int main(){
   ll N;
   cin >> N;
   ll a[3*N];
   for(int i=0;i<3*N;i++){
       cin >> a[i];
   }

   priority_queue<ll, vector<ll>, greater<ll>> que;
   ll current_sum = 0;
   // push the first N elements
   for(int i=0;i<N;i++){
       que.push(a[i]);
       current_sum += a[i];
   }


   ll temp;
   ll sum_left[3*N];
   sum_left[N-1] = current_sum;
   for(int i=N; i<2*N; i++){
       temp = que.top();
       que.pop();
       que.push(a[i]);
       current_sum = current_sum - temp + a[i];

       sum_left[i] = current_sum;
   }


   priority_queue<ll> que2;
   current_sum = 0;
   // push the first N elements
   for(int i=3*N-1;i>2*N-1;i--){
       que2.push(a[i]);
       current_sum += a[i];
   }

   ll sum_right[3*N];
   for(int i=2*N-1; i>=N-1; i--){
       sum_right[i] = current_sum;
       temp = que2.top();
       que2.pop();
       que2.push(a[i]);
       current_sum = current_sum - temp + a[i];
   }

   ll ans = -INF;
   for(int i=N-1;i<2*N;i++){
       ans = max(sum_left[i] - sum_right[i], ans);
   }
   cout << ans << endl;

   return 0;
}

