vector<ll> cum(vector<ll> a, ll N){
    vector<ll> S;
    ll sum = 0;
    priority_queue<ll> que;
    rep(i, N) sum += a[i], que.push(-a[i]);
    S.pb(sum);

    for (ll i = N; i < 2 * N; ++i){
        ll mn = -que.top();
        if(a[i] > mn){
            que.pop();
            que.push(-a[i]);
            sum -= mn;
            sum += a[i];
        }
        S.pb(sum);
    }

    return S;
}

vector<ll> cum2(vector<ll> a, ll N)
{
    vector<ll> S;
    ll sum = 0;
    priority_queue<ll> que;
    rep(i, N) sum += a[i], que.push(a[i]);

    S.pb(sum);
    for (ll i = N; i < 2 * N; ++i)
    {
        ll mx = que.top();
        if (a[i] < mx)
        {
            que.pop();
            que.push(a[i]);
            sum -= mx;
            sum += a[i];
        }
        S.pb(sum);
    }

    return S;
}

