		if(que.size()>n)  //判断队列中的个数有没有超过n个
		{                    //当进到这个循环时队列的个数一定是n+1个
			sumf-=que.top();    //减去队列中最小的那个数
			que.pop();  //最小的出队
			x[i]=sumf;  //   n个数的和 ！！ 
		}
	}
}

void slovee(int n)
{
