ll f0(ll m, ll i, vector<ll> const &a, u_map<ll, ll> &dp) {
  ll n = a.size();
  dump(m, i);
  if (m == 0 && i < n) {
    return 0;
  }
  if (i >= n || m > n - i) {
    return -1e18;
  }
  auto found = dp.find(i);
  if (found != dp.end()) {
    return found->second;
  }
  return dp[i] = max(a[i] + f0(m - 1, i + 1, a, dp), f0(m, i + 1, a, dp));
}
ll f1(ll m, ll i, vector<ll> const &a, u_map<ll, ll> &dp) {
  ll n = a.size();
  dump(m, i);
  if (m == 0 && i < n) {
    return 0;
  }
  if (i >= n || m > n - i) {
    return 1e18;
  }
  auto found = dp.find(i);
  if (found != dp.end()) {
    return found->second;
  }
  return dp[i] = min(a[i] + f1(m - 1, i + 1, a, dp), f1(m, i + 1, a, dp));
}
void solve() {
  ll N;
  input(N);
  vector<ll> a(3 * N);
  input(a);
  dump(a);
  ll ans = -1e18;
  for (auto &&i : range(N, 2 * N + 1)) {

    vector<ll> a0(a.begin(), a.begin() + i);
    sort(a0.rbegin(), a0.rend());
    ll ans0 = accumulate(a0.begin(), a0.begin() + N, 0LL);

    vector<ll> a1(a.begin() + i, a.end());
    sort(a1.begin(), a1.end());
    ll ans1 = accumulate(a1.begin(), a1.begin() + N, 0LL);

    dump(a0, ans0);
    dump(a1, ans1);
    ans = max(ans, ans0 - ans1);
  }
  print(ans);
}

