    if (ai > mi) {
      l[i] = l[i-1]+ai-mi;
      l_q.pop();
      l_q.push(-ai);
    } else {
      l[i] = l[i-1];
    }
  }

  r[N] = r_sum;
  for (int i = N-1; i >= 0; i--) {
    ll ai = A[N+i];
    ll ma = r_q.top();
    if (ai > ma) {
      r[i] = r[i+1];
    } else {
      r[i] = r[i+1]-ma+ai;
      r_q.pop();
      r_q.push(A[i]);
    }
  }

  ll ans = -INF;
  rep(i, 0, N+1) {
    chmax(ans, l[i]-r[i]);
  }

  cout << ans << endl;

  return 0;
};

