using namespace std;

typedef long long ll;
typedef pair<ll,ll> ii;

vector<ll> a;
set<ii> front, back;
vector<ll> maxSum, minSum;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(NULL);
  ll n;
  cin >> n;
  a.resize(3 * n);
  for (ll i = 0; i < 3 * n; i++) cin >> a[i];

  maxSum.resize(3 * n, -100000000000000000LL);
  minSum.assign(3 * n, 100000000000000000LL);

  ll curSum = 0;
  for (int i = 0; i < 3 * n; i++) {
    curSum += a[i];
    front.insert(ii(a[i], i));
    if ((int)front.size() > n) {
      curSum -= front.begin()->first;
      front.erase(front.begin());
    }
    if ((int)front.size() == n) {
      maxSum[i] = curSum;
    }
  }

  curSum = 0;
  for (int i = 3 * n - 1; i >= 0; i--) {
    curSum += a[i];
    back.insert(ii(-a[i], i));
    if ((int)back.size() > n) {
      curSum += back.begin()->first;
      back.erase(back.begin());
    }
    if ((int)back.size() == n) {
      minSum[i] = curSum;
    }
  }

  ll result = -100000000000000000LL;
  for (int i = n - 1; i < 2 * n; i++) {
    result = max(result, maxSum[i] - minSum[i + 1]);
  }
  cout << result << endl;
  return 0;
}

