		le=c-d+b[y];
		ri=c-a[x]-d;
		if(le<ri)
		{
			c-=a[x];
			n--;
			x++;
		}
		else if(ri>le)
		{
			d-=b[y];
			n--;
			y++;
		}
		else
		{
			c-=a[x];
			n--;
			x++;
			if(n==0)
			break;
		}

	}
	prlld(c-d);

	return 0;
}

