const int MAX_N = 1E+05;

int N;

ll A[3 * MAX_N];
ll fds[MAX_N + 1], lds[MAX_N + 1];

ll solve();

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 0; i < 3 * N; i++) {
        cin >> A[i];
    }

    cout << solve() << "\n";

