ll solve()
{
    priority_queue<ll, vector<ll>, greater<ll>> fque;
    priority_queue<ll> lque;
    ll fbs = 0;
    ll lbs = 0;
    for (int i = 0; i < N; i++) {
        fque.push(A[i]);
        fbs += A[i];
    }
    for (int i = 2 * N; i < 3 * N; i++) {
        lque.push(A[i]);
        lbs += A[i];
    }

    ll ffds = 0;
    fds[0] = 0;
    for (int i = N; i < 2 * N; i++) {
        ll fmin = fque.top();
        if (fmin < A[i]) {
            fque.pop();
            fque.push(A[i]);
            fds[i - N + 1] = ffds + A[i] - fmin;
        } else {
            fds[i - N + 1] = ffds;
        }
        ffds = fds[i - N];
    }

    ll llds = 0;
    lds[N] = 0;
    for (int i = 2 * N - 1; i >= N; i--) {
        ll lmax = lque.top();
        if (lmax > A[i]) {
            lque.pop();
            lque.push(A[i]);
            lds[i - N] = llds - A[i] + lmax;
        } else {
            lds[i - N] = llds;
        }
        llds = lds[i - N];
    }

    ll dans = 0;
    for (int i = 0; i <= N; i++) {
        dans = max(dans, lds[i] + fds[i]);
    }

    return fbs - lbs + dans;
}

