      que1.pop();
      que1.push(list[i]);
    } else {
      S[i + 1] = S[i];
    }
  }

  // 右から
  vector<ll> T(2 * N + 1, 0);
  priority_queue<ll> que2;
  for (int i = 0; i < N; i++) {
    T[i + 1] = T[i] + list[3 * N - 1 - i];
    que2.push(list[3 * N - 1 - i]);
  }
  for (int i = N; i < N * 2; i++) {
    ll ma = que2.top();
    if (ma > list[3 * N - 1 - i]) {
      T[i + 1] = T[i] + list[3 * N - 1 - i] - ma;
      que2.pop();
      que2.push(list[3 * N - 1 - i]);
    } else {
      T[i + 1] = T[i];
    }
  }

  // 集計
  ll res = -(1LL << 60);
  for (int i = N; i <= 2 * N; i++) {
    res = max(res, S[i] - T[3 * N - i]);
  }
