using ll = long long;

int N;
int A[300005];

ll maxsum(int k)
{
    vector<ll> v(A, A+k);
    sort(begin(v), end(v), greater<ll>());
    return accumulate(begin(v), begin(v)+N, 0LL);
}

ll minsum(int k)
{
    vector<ll> v(A+k, A+3*N);
    sort(begin(v), end(v));
    return accumulate(begin(v), begin(v)+N, 0LL);
}

/**
 * 区切り位置 k (N <= k <= 2*N) で総当たり
 * 全てのkについて
 *   前半の中からN個選ぶ和の最大値
 *   後半の中からN個選ぶ和の最小値
 * をあらかじめ求めておく。
 */
void solve()
{
    ll lmax_table[300005]; // 前半の中からN個選ぶ和の最大値テーブル
    ll rmin_table[300005]; // 後半の中からN個選ぶ和の最小値テーブル

    /**
     * 優先度付きキューを用いてテーブルを構築
     */
    ll lmax = 0; // 前半の中からN個選ぶ和の最大値
    ll rmin = 0; // 後半の中からN個選ぶ和の最小値
    priority_queue<int, vector<int>, greater<int>> ql; // 前半中最大のN個
    priority_queue<int>                            qr; // 後半中最小のN個

    // 前半初期化
    // 最初のN個をキューに追加し、総和を記録
    FOR(i, 0, N) {
        int a = A[i];
        lmax += a;
        ql.push(a);
    }
    // k == N の場合
    lmax_table[N] = lmax;
    // N+1 <= k <= 2*N の場合
    FOR(k, N+1, 2*N+1) {
        // 新しく得た値をキューに加える
        // その値を総和に加え、キューから取り出した最小値を引く
        int a = A[k-1];
        ql.push(a);
        lmax += a;
        lmax -= ql.top(); ql.pop();
        lmax_table[k] = lmax;
    }

    // 後半初期化
    // 最後のN個をキューに追加し、総和を記録
    for(int i = 3*N-1; i >= 2*N; --i) {
        int a = A[i];
        rmin += a;
        qr.push(a);
    }
    // k == 2*N の場合
    rmin_table[2*N] = rmin;
    // N <= k <= 2*N-1 の場合
    for(int k = 2*N-1; k >= N; --k) {
        // 新しく得た値をキューに加える
        // その値を総和に、キューから取り出した最大値を引く
        int a = A[k];
        qr.push(a);
        rmin += a;
        rmin -= qr.top(); qr.pop();
        rmin_table[k] = rmin;
    }

    ll score_max = numeric_limits<ll>::min();
    FOR(k, N, 2*N+1) {
        score_max = max(score_max, lmax_table[k] - rmin_table[k]);
    }

    cout << score_max << "\n";
}

int main()
{
    cin >> N;
    REP(i, 3*N) {
        cin >> A[i];
    }

    solve();

    return 0;
}

