		if(a[1] < a[2]){
			cout << a[0] - a[1]<< endl;
		}
		else{
			cout << a[0] - a[2]<< endl;
		}

		return 0;
	}



	//初期解
	REP(i,N) {
		left.push(a[i]);
		tl+=a[i];
	}
	kl[N] = tl;
	FOR(i,N,2*N){
		left.push(a[i]);
		tl+=a[i];
		tl-=left.top();
		left.pop();//leftから最小のものをpopする
		kl[i+1] = tl;
	}

	FOR(i,2*N,3*N) {
		right.push(-a[i]);
		tr-=a[i];
	}
	kr[2*N] = tr;
	for(ll i = 2*N-1;i>=N;i--){
		right.push(-a[i]);
		tr-=a[i];
		tr-=right.top();
		right.pop();
		kr[i] = tr;
	}


	long long out = kl[N]+kr[N];
	FOR(i,N+1,2*N){
		if(out < kl[i]+kr[i]){
			out = kl[i]+kr[i];
		}
	}


	cout << out << endl;
}

