const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n;
ll a[MAX_N * 2];
ll a1[MAX_N / 2], a2[MAX_N / 2];

void solve(){
    rep(i, 3 * n) in1(a[i]);
    pql ql; pq qg;
    rep(i, n) a1[i] = a2[i] = 0;
    rep(i, n) ql.push(a[i]), a1[0] += a[i];
    For(i, n, 2 * n){
        ql.push(a[i]);
        a1[i - n + 1] = a1[i - n] + a[i] - ql.top();
        ql.pop();
    }

    For(i, 2 * n, 3 * n) qg.push(a[i]), a2[0] += a[i];
    revFor(i, 2 * n, n){
        qg.push(a[i]);
        a2[2 * n - i] = a2[2 * n - i - 1] + a[i] - qg.top();
        qg.pop();
    }

    answer = -INF;
    rep(i, n + 1)
        chmax(answer, a1[i] - a2[n - i]);
    prl(answer);
    // check negative MOD
    // check index flow
    // check overwrite of the input variables
}

int main(void){
    in1(n);
    // assert(n <= 10000);
    solve();

