template<class T> void gc(T &x)
{
    char c;
    int s = 0;
    x = 0;

    c = getchar();

    if (c == '-') s = 1;
    else if ('0' <= c && c <= '9')  x = c - '0';

    while (true)
    {
        c = getchar();

        if (c < '0' || c > '9') break;
        x = x * 10 + (c - '0');
    }

    if (s) x = -x;
}

struct edge
{
    // (val, index) 要素値 と 要素index
    int val;
    int idx;

    edge() {};
    edge(int val, int idx)
        : val(val), idx(idx) {}

    bool operator== (const edge &edge) const
    {
        return idx == edge.idx && val == edge.val;
    }

    bool operator< (const edge &edge) const
    {
        return val < edge.val;
    }

    bool operator> (const edge &edge) const
    {
        return edge.val < val;
    }
};

int main()
{
    int N;
    if (scanf("%d", &N) < 1) return 0;

    array<int, 300000> ary;

    int sum = 0;

    for (int i = 0; i < 3 * N; i++)
    {
        int tmp = 0;
        gc(tmp);
        ary[i] = tmp;
    }

    priority_queue<edge, vector<edge>, greater<edge> > qg;
    for (int i = 0; i < N; i++)
    {
        qg.push(edge(ary[i], i));
        sum += ary[i];
    }

    set<edge> s;

    // for push
    edge now;

    // for top
    edge cur;

    // unuse
    priority_queue<edge, vector<edge>, greater<edge> > qu;
    for (int i = N; i < 2 * N; i++)
    {
        now = edge(ary[i], i);

        qg.push(now);
        s.insert(now);

        sum += ary[i];

        cur = qg.top();
        s.erase(cur);

        if (N <= cur.idx && cur.idx < 2 * N) qu.push(cur);

        sum -= cur.val;
        qg.pop();
    }

    int max = sum;

    sum = 0;

    // クリア
    qg = priority_queue<edge, vector<edge>, greater<edge> >();

    priority_queue<edge, vector<edge>, less<edge> > ql;
    for (int i = 3 * N - 1; 2 * N <= i; i--)
    {
        ql.push(edge(ary[i], i));
        sum += ary[i];
    }

    edge unuse;
    for (int i = 2 * N - 1; N <= i; i--)
    {
        now = edge(ary[i], i);
        if (s.count(now) == 1)
        {
            // max 側 min 側で使っていないものがある場合
            // 既に max 側で使っているものを min 側で使うようにする為
            // その代替交換できるものが存在することが前提
            if (!qu.empty())
            {
                ql.push(now);
                sum += ary[i];
                cur = ql.top();
                sum -= cur.val;

                if (cur.idx != now.idx)
                {
                    unuse = qu.top();

                    max += unuse.val - ary[i];
                    ql.pop();
                    qu.pop();

                    // max 側でこれまで使わなかったけれども
                    // 使うようになった
                    s.insert(unuse);
                }
            }
        }
        else
        {
            ql.push(now);
            sum += ary[i];
            cur = ql.top();
            sum -= cur.val;
            ql.pop();
            qu.pop();
        }
    }

    // クリア
    ql = priority_queue<edge, vector<edge>, less<edge> >();

    printf("%d\n", max - sum);
    return 0;
}

