signed main() {
  ll n;
    cin>>n;
  ll sum=0;
  ll resum=0;
  vector<ll> A(3*n);
  priority_queue<ll> front;
  priority_queue<ll> back;

  FOR(i,0,3*n){
    cin>>A[i];
    if(i<n){
      front.push(-A[i]);
      sum+=A[i];
    }

    if(2*n-1<i){
      back.push(A[i]);
      resum+=A[i];
    }
  }

  vector<pair<ll,ll>> ans(n+1);
  ans[0].first=sum;
  ans[n].second=resum;

  for(int i=n;i<2*n;i++){
    front.push(-A[i]);
    sum+=A[i];

    ll a=front.top();
    sum+=a;
    front.pop();
    ans[i-n+1].first=sum;
  }

  for(int i=(2*n-1);n<=i;i--){
    back.push(A[i]);
    resum+=A[i];

    ll a=back.top();
    resum-=a;
    back.pop();
    ans[i-n].second=resum;
  }

  ll Ans=-INF;
  FOR(i,0,n+1){
    ll now=ans[i].first-ans[i].second;
    chmax(Ans,now);
  }
  cout<<Ans<<endl;
}

