void solve(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  ll n = 0;
  cin>>n;
  ll a[3*n] = {};
  ll sumf[n+1] = {},sumb[n+1] = {};
  priority_queue<ll,vector<ll>, greater<ll> > front;
  priority_queue<ll> back;
  rep(i, 3* n){
    cin>>a[i];
    if(i < n){
      front.push(a[i]);
      sumf[0] += a[i];
    } else if( i > 2 * n - 1){
      back.push(a[i]);
      sumb[0] += a[i];
    }
  }

  repl(i,n,2*n){
    sumf[i - n + 1] = sumf[i-n] + a[i];
    front.push(a[i]);
    ll t = front.top();
    front.pop();
    sumf[i - n + 1] -= t;
  }

  repr(i, 2 * n, n) {
        sumb[2 * n - i] = sumb[2 * n - 1 - i] + a[i];
        back.push(a[i]);
        ll t = back.top(); back.pop();
        sumb[2 * n - i] -= t;
    }

    ll ans = -INF;
    rep(i, n + 1) maxch(ans, sumf[i] - sumb[n - i]);
    cout << ans << endl;
    return ;
}

