  Memob[0] = accumulate(A.begin()+2*N, A.end(), 0LL);
  for(int i=0; i<N; i++){
    ll tmp = A[2*N-1-i];
    Memob[i+1] = Memob[i];
    if(tmp < Qb.top()){
      Memob[i+1] += - Qb.top() + tmp;
      Qb.pop();
      Qb.push(tmp);
    }
  }
  ll max = Memoa[0] - Memob[N];
  for(int i=0; i<N+1; i++){
    if(max < Memoa[i] - Memob[N-i])
      max = Memoa[i] - Memob[N-i];
  }
  cout << max << endl;
  return 0;
}

