      sum += a[i];
      pql.pop();
      pql.push(a[i]);
    }
    l[i-n+1] = sum;
  }
  priority_queue<ll> pqr;
  sum = 0;
  reverse(ALL(a));
  rep(i, n) {
    sum += a[i];
    pqr.push(a[i]);
  }
  r[0] = sum;
  for(int i = n; i < 2*n; ++i) {
    if(pqr.top() > a[i]) {
      sum -= pqr.top();
      sum += a[i];
      pqr.pop();
      pqr.push(a[i]);
    }
    r[i-n+1] = sum;
  }
  ll ans = -INF64;
  for(int i = 0; i <= n; ++i) chmax(ans, l[i]-r[n-i]);
  cout << ans << endl;
}

