  priority_queue<ll, vector<ll>, greater<ll> > que1;
  for (int i = 0; i < N; i++) {
    S[i + 1] = S[i] + list[i];
    que1.push(list[i]);
  }
  for (int i = N; i < 2 * N; i++) {
    ll mi = que1.top();
    if (list[i] > mi) {
      S[i + 1] = S[i] + list[i] - mi;
      que1.pop();
      que1.push(list[i]);
    } else {
      S[i + 1] = S[i];
    }
  }

  // 右から
  vector<ll> T(2 * N + 1, 0);
  priority_queue<ll> que2;
  for (int i = 0; i < N; i++) {
    T[i + 1] = T[i] + list[3 * N - 1 - i];
    que2.push(list[3 * N - 1 - i]);
  }
  for (int i = N; i < N * 2; i++) {
    ll ma = que2.top();
    if (ma > list[3 * N - 1 - i]) {
      T[i + 1] = T[i] + list[3 * N - 1 - i] - ma;
      que2.pop();
      que2.push(list[3 * N - 1 - i]);
