    {
        return val<rhs.val;
    }
};

struct Rpart
{
    int id;LL val;
    Rpart(int id,LL val):id(id),val(val){}
    Rpart(){}
    bool operator < (const Rpart &rhs) const
    {
        return val>rhs.val;
    }
};

priority_queue<Lpart>Lq;
priority_queue<Rpart>Rq;

LL a[maxn],lsum[maxn],rsum[maxn];

void getlsum()
{
    vis.clear();
    for (int i=1;i<=3*n;i++) Lq.push(Lpart(i,a[i]));
    LL res=0;
    for (int i=1;i<=n;i++)
    {
        LL tmp=Lq.top().val;Lq.pop();
        vis[tmp]++;res+=tmp;
    }
    for (int i=3*n;i>=n+1;i--)
    {
        lsum[i]=res;
        LL tmp=a[i];
        if (vis[tmp]>0)
        {
            res-=tmp;vis[tmp]--;
            while (Lq.top().id>i) Lq.pop();
            LL x=Lq.top().val;Lq.pop();
            res+=x;vis[x]++;
        }
    }
    for (int i=1;i<=n;i++) lsum[i]=lsum[i-1]+a[i];
    //for (int i=1;i<=3*n;i++) printf("%lld ",lsum[i]);puts("");
}

void getrsum()
{
    vis.clear();
    for (int i=1;i<=3*n;i++) Rq.push(Rpart(i,a[i]));
    LL res=0;
    for (int i=1;i<=n;i++)
    {
        LL tmp=Rq.top().val;Rq.pop();
        vis[tmp]++;res+=tmp;
    }
    for (int i=1;i<=2*n;i++)
    {
        rsum[i]=res;
        LL tmp=a[i];
        if (vis[tmp]>0)
        {
            res-=tmp;vis[tmp]--;
            while (Rq.top().id<i) Rq.pop();
            LL x=Rq.top().val;Rq.pop();
            res+=x;vis[x]++;
        }
    }
    for (int i=3*n;i>=2*n+1;i--) rsum[i]=rsum[i+1]+a[i];
    //for (int i=1;i<=3*n;i++) printf("%lld ",rsum[i]);puts("");
}

