int main()
{
	int n, a[300010];
	long long int sum = 0;

	std::cin >> n;
	for (int i = 0; i < 3 * n; ++i)
	{
		std::cin >> a[i];
	}

	int oduzetiDrugih = n / 2;
	int oduzetiPrvih = n - n / 2;

	int granica;
	granica = 3 * n / 2;

	bool flag = false;

	if (3 * n % 2 == 1)
	{
		std::sort(a, a + granica + 1);
		std::sort(a + granica + 1, a + 3 * n);
		flag = true;
	}
	else
	{
		std::sort(a, a + granica);
		std::sort(a + granica, a + n * 3);
	}

	for (int i = 0; i < oduzetiPrvih; ++i)
		a[i] = 0;

	for (int i = 3 * n - 1, k = 0; k < oduzetiDrugih; --i, ++k)
		a[i] = 0;

	if (!flag)
	{
		for (int i = 0, j = 3 * n - 1; i < granica; ++i, --j)
		{
			sum += a[i];
			if (j >= granica)
				sum -= a[j];
		}
	}
	else
	{
		for (int i = 0, j = 3 * n - 1; i < granica + 1; ++i, --j)
		{
			sum += a[i];
			if (j >= granica + 1)
				sum -= a[j];
