using ll = long long;

int N;
int A[300005];

ll maxsum(int k)
{
    vector<ll> v(A, A+k);
    sort(begin(v), end(v), greater<ll>());
    return accumulate(begin(v), begin(v)+N, 0LL);
}

ll minsum(int k)
{
    vector<ll> v(A+k, A+3*N);
    sort(begin(v), end(v));
    return accumulate(begin(v), begin(v)+N, 0LL);
}

void solve()
{
    ll score_max = numeric_limits<ll>::min();

    FOR(k, N, 2*N+1) {
        ll score = maxsum(k) - minsum(k);
        score_max = max(score_max, score);
    }

    cout << score_max << "\n";
}

int main()
{
    cin >> N;
    REP(i, 3*N) {
        cin >> A[i];
    }

    solve();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main()
{
  int N;
  cin >> N;
  vector<int64_t> A(3 * N);
  for (int i = 0; i < 3 * N; i++)
  {
    cin >> A.at(i);
  }
  int64_t lsum = 0, rsum = 0;
  multiset<int64_t> rused, lused, rremoved;
  for (int i = 0; i < N; i++)
  {
    lsum += A.at(i);
    lused.insert(A.at(i));
  }
  for (int i = N; i < 3 * N; i++)
  {
    rsum += A.at(i);
    rused.insert(A.at(i));
  }
  while (rused.size() > N)
  {
    rremoved.insert(*rused.rbegin());
    rsum -= *rused.rbegin();
    rused.erase(*rused.rbegin());
  }
  int64_t ans = lsum - rsum;
  for (int i = N; i < 2 * N; i++)
  {
    lsum += A.at(i);
    lused.insert(A.at(i));
    lsum -= *lused.begin();
    lused.erase(*lused.begin());
    if (rused.count(A.at(i)))
    {
      rused.erase(A.at(i));
      rsum -= A.at(i);
      rused.insert(*rremoved.begin());
      rsum += *rremoved.begin();
      rremoved.erase(*rremoved.begin());
    }
    else
    {
      rremoved.erase(A.at(i));
    }
    ans = max(ans, lsum - rsum);
  }
  cout << ans << endl;
}

