int suf[N];
void solve(){
	int n;
	cin >> n;
	for(int i =1;i<=3*n;i++){
		cin >> a[i];
	}
	priority_queue < ll, std::vector<ll>, std::greater<ll> > mnheap;	// mnheap.push(), mnheap.top(), mnheap.pop()
	priority_queue<int> mxheap;
	for(int i =1;i<=3*n;i++){
		if(i <= n){
			pre[i] = pre[i-1] + a[i];
			mnheap.push(a[i]);
			continue;
		}
		pre[i] = pre[i-1];
		if(a[i] > mnheap.top()){
			pre[i] -= mnheap.top();
			pre[i] += a[i];
			mnheap.pop();
			mnheap.push(a[i]);
		}
	}

	for(int i = 3*n,j = 1;i>=1;i--,j++){
		assert((3*n - i + 1) == j);
		if((3 * n - i + 1) <= n){
			mxheap.push(a[i]);
			suf[i] = suf[i+1] + a[i];
			continue;
		}
		suf[i] = suf[i+1];
		if(a[i] < mxheap.top()){
			suf[i] -= mxheap.top();
			suf[i] += a[i];
			// auto it = se.end();
			// it--;
			// se.erase(it);
			// se.in(a[i]);
			mxheap.pop();
			mxheap.push(a[i]);
		}
	}
	int ans = -INF;
	for(int i =n;i<=2*n;i++){
		ans= max(ans,pre[i]- suf[i+1]);
	}
	assert(ans != -INF);
	cout << ans << endl;

}
