const int dx[] = {1, 0, -1, 0}, dy[] = {0, -1, 0, 1};
int N, M;
vector<int> A;
const int MAX_N = 300010;
ll left_sum,right_sum;
priority_queue<pair<int, int>> left_que,right_que;
bool left_idx[MAX_N];
bool right_idx[MAX_N];
int main() {
  cin >> N;
  M = 3 * N;
  A.resize(M);
  for (auto &val : A) {
    cin >> val;
  }
  //left
  for (int i = 0; i < N; i++){
      left_sum += A[i];
      left_idx[i] = true;
      left_que.emplace(mp(-A[i], i));
  }
  //right
  for (int i = N; i < M; i++){
      right_que.emplace(mp(-A[i], i));
  }
  int cnt = 0;
  while (cnt < N){
      auto p = right_que.top();
      right_que.pop();
      int val = -p.first;
      int idx = p.second;
      right_sum += val;
      right_idx[idx] = true;
      cnt++;
  }
  ll result = left_sum - right_sum;

  for (int i = N; i < M; i++){
      if (left_que.empty() or right_que.empty()){
          break;
      }
      left_sum += A[i];
      left_idx[i] = true;
      left_que.emplace(mp(-A[i], i));
      auto left_min = left_que.top();
      left_que.pop();
      int left_min_val = -left_min.first;
      int left_min_idx = left_min.second;
      left_sum -= left_min_val;
      left_idx[left_min_idx] = false;

      //right
      if (right_idx[i] > 0){
          right_sum -= A[i];
        //   right_idx.erase(i);
          auto right_min = right_que.top();
          right_que.pop();
          int right_min_val = -right_min.first;
          int right_min_idx = right_min.second;
          while (left_idx[right_min_idx]){
              if (right_que.empty()){
                  goto end;
              }
              auto right_min = right_que.top();
              right_que.pop();
              right_min_val = -right_min.first;
              right_min_idx = right_min.second;
          }
          right_sum += right_min_val;
          right_idx[right_min_idx] = true;
      }
      result = max(result, left_sum - right_sum);
  }
  end:;
  cout << result << endl;
  return 0;
}

