// Body
void body() {
    using namespace debug;
    auto N = read<i32>();
    auto as = read<i64>(3 * N);

    i64 result = numeric_limits<i64>::min();

    auto max_sum = V<i64>(N + 1);
    auto min_sum = V<i64>(N + 1);
    {
        auto X = V<i64>();
        X.reserve(N + 1);
        REP (i, N) {
            X.push_back(as[i]);
        }
        make_heap(X.begin(), X.end(), [](i64 &x, i64 &y) { return x > y; });

        max_sum[0] = accumulate(X.begin(), X.end(), 0);
        FOR (k, 1, N + 1) {
            X.push_back(as[k + N - 1]);
            push_heap(X.begin(), X.end(), [](i64 &x, i64 &y) { return x > y; });
            pop_heap(X.begin(), X.end(), [](i64 &x, i64 &y) { return x > y; });
            max_sum[k] = max_sum[k - 1] + as[k + N - 1] - X.back();
            X.pop_back();
        }
    }
    {
        auto X = V<i64>();
        X.reserve(N + 1);
        REPR (i, N) {
            X.push_back(-as[i + 2 * N]);
        }
        make_heap(X.begin(), X.end(), [](i64 &x, i64 &y) { return x > y; });

        min_sum[N] = accumulate(X.begin(), X.end(), 0);
        FOR (k, 1, N + 1) {
            X.push_back(-as[2 * N - k]);
            push_heap(X.begin(), X.end(), [](i64 &x, i64 &y) { return x > y; });
            pop_heap(X.begin(), X.end(), [](i64 &x, i64 &y) { return x > y; });
            min_sum[N - k] = min_sum[N - k + 1] - as[2 * N - k] - X.back();
            X.pop_back();
        }
    }

    REP (k, N + 1) {
        auto score = max_sum[k] + min_sum[k];
        result = max(score, result);
    }
    cout << result << endl;
}

