vector <ll> func(const vector <ll>& a, ll sgn)
{
	const int N = SZ(a) / 3;
	vector <ll> sum(3 * N + 1);

	priority_queue <ll> pq;
	for (int i = 0; i < 3 * N; ++i)
	{
		sum[i + 1] = sum[i] + a[i];
		pq.push(sgn * a[i]);
		if (SZ(pq) >= N + 1)
		{
			ll d = pq.top();
			pq.pop();
			sum[i + 1] -= sgn * d;
		}
	}

	return sum;
}

