// 上位・下位K件の合計
template<typename T> class TopK {
public:
    T high = 0; // 上位k件の合計
    T low = 0;  // 下位k件の合計

private:
    const int k;
    std::priority_queue<T> que_low;
    std::priority_queue<T, std::vector<T>, std::greater<T>> que_high;

public:
    TopK(int k) : k(k) {}

    void insert(T x) {
        insert_low(x);
        insert_high(x);
    }

private:
    void insert_low(T x) {
        this->que_low.emplace(x);
        this->low += x;

        while (this->que_low.size() > this->k) {
            this->low -= this->que_low.top();
            this->que_low.pop();
        }
    }

    void insert_high(T x) {
        this->que_high.emplace(x);
        this->high += x;

        while (this->que_high.size() > this->k) {
            this->high -= this->que_high.top();
            this->que_high.pop();
        }
    }
};

using namespace std;

LL solve(LL N, vector<LL> &A) {
    TopK<LL> h(N), l(N);

    auto high = make_v<LL>(3 * N);
    auto low = make_v<LL>(3 * N);

    FOR(i, 0, 3 * N) {
        h.insert(A[i]);
        high[i] = h.high;
    }
    for (int i = 3 * N - 1; i >= 0; --i) {
        l.insert(A[i]);
        low[i] = l.low;
    }


    LL ans = LONG_LONG_MIN;
    FOR(i, N, 2 * N + 1) {
        chmax(ans, high[i - 1] - low[i]);
    }

    return ans;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    LL N;
    cin >> N;
    auto A = make_v<LL>(3 * N);
    FOR(i, 0, 3 * N) {
        cin >> A[i];
    }
    print(solve(N, A));

    return 0;
}

