constexpr ll INF=1e18;
constexpr int MOD=1e9+7;
constexpr double EPS=1e-9;

template<typename C>
vl calc(int n,vi a,C comp)
{
	map<int,int,C> f;
	ll sum=0;
	rep(i,n){
		f[a[i]]++;
		sum+=a[i];
	}
	vl res={sum};
	rep(i,n){
		if(comp(begin(f)->first,a[n+i])){
			sum=sum+a[n+i]-begin(f)->first;
			if(--begin(f)->second==0)
				f.erase(begin(f));
			f[a[n+i]]++;
		}
		res.push_back(sum);
	}
	return res;
}

int main()
{
	#ifndef _GLIBCXX_DEBUG
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	constexpr char endl='\n';
	#endif

	for(int n;cin>>n&&n;){
		vi a(3*n);
		rep(i,3*n) cin>>a[i];

		vl pre=calc(n,a,less<int>());
		reverse(all(a));
		vl suf=calc(n,a,greater<int>());

		ll res=-INF;
		rep(i,n+1)
			res=max(res,pre[i]-suf[n-i]);
		cout<<res<<endl;
	}
}

