    vector<ll> ls(N * 2);
    vector<ll> la(N + 1);

    ll lc = 0;

    ls[0] = a[0];
    for(int i = 1; i < 2 * N; i++) {
        ls[i] += ls[i - 1] + a[i];
    }

    for(int i = 0; i < N; i++) {
        lq.push(a[i]);
    }

    la[0] = ls[N - 1];
    for(int i = 0; i < N; i++) {
        lq.push(a[i + N]);
        lc += lq.top();
        lq.pop();
        la[i + 1] = ls[N + i] - lc;
    }

    priority_queue<ll> rq;
    vector<ll> rs(N * 2);
    vector<ll> ra(N + 1);

    ll rc = 0;

    rs[0] = a[3 * N - 1];
    for(int i = 1; i < 2 * N; i++) {
        rs[i] += rs[i - 1] + a[3 * N - 1 - i];
    }

    for(int i = 3 * N - 1; i >= 2 * N; i--) {
        rq.push(a[i]);
    }

    ra[0] = rs[N - 1];
    for(int i = 0; i < N; i++) {
        rq.push(a[2 * N - 1 - i]);
