        cin >> a[i];
    }
    for(int i=0; i<N; i++) q_max.push(a[i]);
    for(int i=N*2; i<N*3; i++) q_min.push(a[i]);
    sum_max[0] = 0;
    for(int i=0; i<N; i++) sum_max[0] += a[i];
    // cout << "sum_max : " << sum_max[0] << ',';
    for(int i=1; i<=N; i++) {
        ll min_a = q_max.top();
        if(a[N-1+i] > min_a) {
            q_max.pop();
            q_max.push(a[N-1+i]);
            sum_max[i] = sum_max[i-1] - min_a + a[N-1+i];
        } else {
            sum_max[i] = sum_max[i-1];
        }
        // cout << sum_max[i] << ',';
    }
    // cout << endl;
    sum_min[0] = 0;
    for(int i=N*2; i<N*3; i++) sum_min[0] += a[i];
    // cout << "sum_min : " << sum_min[0] << ',';
    for(int i=1; i<=N; i++) {
        ll max_a = q_min.top();
        if(a[N*2-i] < max_a) {
            q_min.pop();
            q_min.push(a[N*2-i]);
            sum_min[i] = sum_min[i-1] - max_a + a[N*2-i];
        } else {
            sum_min[i] = sum_min[i-1];
        }
