    }
    // cout << endl;
    ll ans = sum_max[0] - sum_min[N];
    for(int i=1; i<=N; i++) {
        if(ans < sum_max[i] - sum_min[N-i]) ans = sum_max[i] - sum_min[N-i];
    }
    cout << ans << endl;
    return 0;
}

