using namespace std;

using ll = long long int;

ll arr[300010] = {};

ll resL[100010] = {};

int main(void){

    cin.tie(0);
    ios::sync_with_stdio(false);

    ll k,sum = 0,result = 0;
    cin >> k;

    priority_queue<ll, vector<ll>, greater<ll> > que;

    for(int i = 0; i < 3*k; i++){
        cin >> arr[i];
    }

    //init

    for(int i = 0; i < k; i++){
        sum += arr[i];
        que.push(arr[i]);
    }

    resL[0] = sum;

    for(int i = 0; i < k; i++){

        que.push(arr[i+k]);
        ll a = que.top();
        que.pop();

        sum += arr[i+k]-a;

        resL[i+1] = sum;
    }

    /// left

    priority_queue<ll> que1;
    sum = 0;

    for(int i = 1; i <= k; i++){
        sum += arr[3*k-i];
        que1.push(arr[3*k-i]);
    }

    result = resL[k] - sum;

    for(int i = 1; i <= k; i++){

        que1.push(arr[2*k-i]);
        ll a = que1.top();
        que1.pop();

        sum += arr[2*k-i]-a;

        result = max(resL[k-i] - sum,result);
    }

    /// right

    cout << result << endl;
}

#include<iostream>
#include<algorithm>
#include<vector>
#include<queue>
using namespace std;
const int BUF = 300005;


int N;
int vList[BUF];

void read() {
    cin >> N;
    for (int i = 0; i < N * 3; ++i) {
        cin >> vList[i];
    }
}


vector<long long> calc() {
    priority_queue<int, vector<int>, greater<int> > aChose;

    long long sum = 0;
    for (int i = 0; i < N; ++i) {
        aChose.push(vList[i]);
        sum += vList[i];
    }

    vector<long long> ret;
    ret.push_back(sum);

    for (int cur = N; cur < N * 2; ++cur) {
        if (aChose.top() < vList[cur]) {
            sum -= aChose.top();
            sum += vList[cur];
            aChose.pop();
            aChose.push(vList[cur]);
        }
        ret.push_back(sum);
    }

    return ret;
}

void work() {
    vector<long long> aVec = calc();

    for (int i = 0; i < N * 3; ++i) {
        vList[i] *= -1;
    }
    reverse(vList, vList + N * 3);

    vector<long long> bVec = calc();

    long long maxV = aVec[0] + bVec.back();
    for (int i = 0; i < aVec.size(); ++i) {
        maxV = max(maxV, aVec[i] + bVec[bVec.size() - i - 1]);
    }
    cout << maxV << endl;
}


int main() {
    read();
    work();
    return 0;
}

