using namespace std;

// T字にカットしたとき
int cutT(int h, int w){
	long long int p,q,s1,s2,s3,res1,res2,res3;
	p = h / 3;
	q = w / 2;
	s1 = p * w;
	s2 = (h-p) * q;
	s3 = (h-p) * (w-q);
	res1 = max(max(s1,s2),s3) - min(min(s1,s2),s3);
	p = p+1;
	s1 = p * w;
	s2 = (h-p) * q;
	s3 = (h-p) * (w-q);
	res2 = max(max(s1,s2),s3) - min(min(s1,s2),s3);
	p = p+1;
	s1 = p * w;
	s2 = (h-p) * q;
	s3 = (h-p) * (w-q);
	res3 = max(max(s1,s2),s3) - min(min(s1,s2),s3);
	return min(res1,min(res2,res3));
}


int main(int argc, char const *argv[]) {
	int h,w,temp;
	std::cin >> h >> w;

	if (h % 3 == 0 || w % 3 == 0) {
		std::cout << 0 << '\n';
		return 0;
	}

	// T字カットと３つに縦割りしたときの比較
	std::cout << min(min(w,cutT(h,w)), min(h,cutT(w,h))) << '\n';
	return 0;
}

