        priority_queue<int> left, right;
        ll tl=0,tr=0;

        for(int i=0;i<=t;i++) {
            left.push(v[i]);
        }
        for(int i=t+1; i<3*N; i++) {
            tr += v[i];
            right.push(v[i]);
        }

        for(int i=0;i<N;i++){
            int x = left.top(); left.pop();
            tl += x;
        }

        for(int i=0;i<N-(t-N+1);i++){
            int x = right.top(); right.pop();
            tr -= x;
        }
        ans = max(ans, tl - tr);
    }
    cout << ans << endl;
    return 0;
}

