int N,a[300001];
ll sl[100001],sr[100001];

void solve(){

	priority_queue<int,vector<int>,greater<int>> lpq;
	priority_queue<int> rpq;

	sl[0] = sr[0] = 0;
	rep(i,N){
		sl[0] += a[i];
		sr[0] += a[N*3-1-i];
		lpq.push(a[i]);
		rpq.push(a[N*3-1-i]);
	}


	rep(i,N){
		int t = lpq.top();
		if(t > a[i+N]) sl[i+1] = sl[i];
		else{
			lpq.pop();
			lpq.push(a[i+N]);
			sl[i+1] = sl[i] + a[i+N] - t;
		}
	}

	rep(i,N){
		int t = rpq.top();
		if(t < a[N*2-1-i]) sr[i+1] = sr[i];
		else{
			rpq.pop();
			rpq.push(a[N*2-i-1]);
			sr[i+1] = sr[i] + a[N*2-i-1] - t;
		}
	}

	ll score = -(1LL << 62);
	rep(i,N) score = max(score, sl[i] - sr[N-i]);
	cout<<score<<endl;

	return;
}

