#include <iostream>
#include <queue>
#include <vector>

using namespace std;
using ll = long long;

int main(){

	// 入力 int N = N, vector a = {a_1, a_2, ... a_N*3} 
	int N;
	cin >> N;
	int N3 = N * 3;

	vector<ll> a(N3);

	for (int i=0; i<N3; ++i){
		cin >> a[i];
	}

	// 優先度つきキューの作成
	// pq_front: 前から N+k 個の要素で常に最大のN要素をもつキュー（降順に取り出す）
	// pq_back: 後ろから N+k　個の要素で常に最小のN要素をもつキュー（昇順に取り出す）
	priority_queue<ll, vector<ll>, greater<ll>> pq_front;
	priority_queue<ll> pq_back;

	// sum_front[k]: あるkに対するpq_front の総和
	// sum_front[k]: あるkに対するpq_back の総和
	vector<ll> sum_front(N+1, 0), sum_back(N+1, 0);

	// pq_front(back)に前から（後ろから）N要素を追加、sum_front(back)を計算
	for (int i=0; i<N; ++i){
		pq_front.push(a[i]);
		pq_back.push(a[N3 - i - 1]);
		sum_front[0] += a[i];
		sum_back[N] += a[N3 - i - 1];
	}

	// k = 0, 1, ... , N-1 に対してsum_front(back)を計算
	for (int k=0; k<N; ++k){
		// a_k+N を pq_front に追加、最小要素をpopして総和を更新。
		pq_front.push(a[N+k]);
		pq_back.push(a[N*2-k-1]);

		sum_front[k+1] = sum_front[k] + a[N+k] - pq_front.top();
		sum_back[N-k-1] = sum_back[N-k] + a[N*2-k-1] - pq_back.top();

		pq_front.pop();
		pq_back.pop();

	}

	// sum_front[k] - sum_back[k] の最大値を計算
	ll max_score = -10000000000000LL;
	for (int k=0; k<=N; ++k){
		ll score = sum_front[k] - sum_back[k];
		if (max_score < score){
			max_score = score;
		}

	}

	// 出力
	cout << max_score << endl;
}

