void solve(){

	priority_queue<int,vector<int>,greater<int>> lpq;
	priority_queue<int> rpq;

	sl[0] = sr[0] = 0;
	rep(i,N){
		sl[0] += a[i];
		sr[0] += a[N*3-1-i];
		lpq.push(a[i]);
		rpq.push(a[N*3-1-i]);
	}


	rep(i,N){
