			left -= pq_left.top();
			pq_left.pop();
		}
		for (int i = 2 * N-1; i > sikiri; i--){
			right += arr[i];
			pq_right.push(arr[i]);
			right -= pq_right.top();
			pq_right.pop();
		}
		if (left - right > ans){
			ans = left - right;
		}
	}
