void body() {
    using namespace debug;
    auto N = read<i32>();
    auto as = read<i64>(3 * N);

    i64 result = numeric_limits<i64>::min();

    auto max_sum = V<i64>(N + 1);
    auto min_sum = V<i64>(N + 1);
    auto tmp = V<i64>(N);
    {
        REP (i, N) {
            tmp[i] = as[i];
        }
        auto X = heap<i64, greater<i64>>(tmp);
        X.reserve(N + 1);

        max_sum[0] = accumulate(X.begin(), X.end(), 0LL);
        FOR (k, 1, N + 1) {
            X.push(as[k + N - 1]);
            max_sum[k] = max_sum[k - 1] + as[k + N - 1] - X.pop();
        }
    }
    {
        REP (i, N) {
            tmp[i] = as[i + 2*N];
        }
        auto X = heap<i64, less<i64>>(tmp);
        X.reserve(N + 1);

        min_sum[N] = accumulate(X.begin(), X.end(), 0LL);
        FOR (k, 1, N + 1) {
            X.push(as[2 * N - k]);
            min_sum[N - k] = min_sum[N - k + 1] + as[2 * N - k] - X.pop();
        }
    }

    REP (k, N + 1) {
        auto score = max_sum[k] - min_sum[k];
        result = max(score, result);
    }
    cout << result << endl;
}

