		que.pop();

		f_table[i + 1] = sum;
	}

	sum = 0;
	que.swap(priority_queue<long long>());
	vector<long long> b_table(N+1);
	for(int i=0; i<N; i++)
	{
		int index = 3*N-1 - i;
		sum += a[index];
		que.push(a[index]);
	}
	b_table[0] = sum;
	for(int i=0; i<N; i++)
	{
		int index = 2*N-1 - i;
		sum += a[index];
		que.push(a[index]);
		sum -= que.top();
		que.pop();

		b_table[i + 1] = sum;
	}

	long long ret = LLONG_MIN;
	for(int i=N; i<=2*N; i++)
	{
		ret = max(ret, f_table[i-N]-b_table[2*N-i]);
	}
	cout << ret << endl;

	return 0;
}

