	bool used_a[1000] = {}, used_b[2000] = {};
	cin >> n;
	for (int i = 0; i < 3*n; i++) {
		ll temp;
		cin >> temp;
		org[i] = temp;
		if (i < 2 * n) {
			a[i].val = temp;
			a[i].id = i;
		}
		if (i >= n) {
			b[3 * n - i - 1].id = 3 * n - i - 1;
			b[3 * n - i - 1].val = temp;
		}
	}
	sort(a, a + 2 * n, greaterN);
	sort(b, b + 2 * n, lessN);
	for (int i = 0; i < n; i++) {
		pr[n] += a[i].val;
		used_a[a[i].id] = true;
		pos[n] += b[i].val;
		used_b[b[i].id] = true;
	}
