			used_b[2 * n - i] = false;
			used_b[b[idx_b].id] = true;
			pos[n - i] = pos[n - i + 1] - org[n + i-1] + b[idx_b++].val;
		}
		else {
			pos[n - i] = pos[n - i + 1];
		}
	}
	ll ans = -1000000000000000000;
	for (int i = 0; i <= n; i++) {
