typedef priority_queue<long> maxp;

int main(void){
	long N,a;
	cin >> N;
	minp af;
	maxp ab;
	VI a_mid(N);
	long sum_f = 0;
	long sum_b = 0;

	REP(i,N) {
		cin >> a;
		af.push(a);
		sum_f += a;
	}
	REP(i,N) {
		cin >> a;
		a_mid[i] = a;
	}
	REP(i,N) {
		cin >> a;
		ab.push(a);
		sum_b += a;
	}

	VI dp_f(N+1,0);
	VI dp_b(N+1,0);
	dp_f[0] = sum_f;
	dp_b[N] = sum_b;

	// 0 ~ 2Nの中で最大を決める dp_l[i]:=左からN+iこ使って最大。
	REP(i,N) {
		long minv = af.top();
		if (minv < a_mid[i]) {
			af.pop();
			af.push(a_mid[i]);
			dp_f[i+1] = dp_f[i] + (a_mid[i] - minv);
		}
		else dp_f[i+1] = dp_f[i];
	}

	RFOR(i,N,1) {
		long maxv = ab.top();
		if (maxv > a_mid[i-1]) {
			ab.pop();
			ab.push(a_mid[i-1]);
			dp_b[i-1] = dp_b[i] + a_mid[i-1] - maxv	;	
		}
		else dp_b[i-1] = dp_b[i];
	}

	#ifdef DEBUG
		dump1d_arr(dp_f);
		dump1d_arr(dp_b);
	#endif

	REP(i,N+1) dp_f[i] -= dp_b[i];
	cout << *max_element(dp_f.begin(),dp_f.end()) << endl;
	return 0;


}

