int main() {

	priority_queue<int, vector<int>, less<int>> pqLow;
	priority_queue<int, vector<int>, greater<int>> pqHigh;
	vector<int> arr;
	int n;

	cin >> n;

	arr.resize(n * 3);

	int sumL = 0, sumH = 0;

	for (int i = 0; i < n * 3; i++) {
		cin >> arr[i];
		if (i < n) {
			pqHigh.push(arr[i]);
			sumH += arr[i];
		} else if (i >= 2 * n) {
			pqLow.push(arr[i]);
			sumL += arr[i];
		}
	}

	vector<ll> highScore(n + 1);
	highScore[0] = sumH;
	for (int k = n; k < 2 * n; k++) {		
		sumH += arr[k];
		pqHigh.push(arr[k]);
		sumH -= pqHigh.top();
		pqHigh.pop();
		highScore[k - n + 1] = sumH;
	}

	vector<ll> lowScore(n + 1);
	lowScore[n] = sumL;
	for (int k = 2 * n - 1; k >= n; k--) {
		sumL += arr[k];
		pqLow.push(arr[k]);
		sumL -= pqLow.top();
		pqLow.pop();
		lowScore[k - n] = sumL;
	}

	ll maxScore = highScore[0] - lowScore[0];
	for (int i = 1; i < n + 1; i++) {
		maxScore = max(maxScore,static_cast<ll>(highScore[i] - lowScore[i]));
	}
