  FOR(i, 1, N+1){
    auto min_it = st.begin();
    ll tmp = *min_it;
    if(a[N-1+i] > tmp){
      st.erase(min_it);
      st.insert(a[N-1+i]);
      former[i] = former[i-1] + a[N-1+i] - tmp;
    }else{
      former[i] = former[i-1];
    }
  }

  multiset<int> st2;

  REP(i, N){
    st2.insert(a[3*N-1-i]);
    latter[0] += a[3*N-1-i];
  }

  FOR(i, 1, N+1){
    auto max_it = st2.rbegin();
    ll tmp = *max_it;
    if(a[2*N-i] < tmp){
      //参考：http://izmiz.hateblo.jp/entry/2014/11/01/140233
      st2.erase(--max_it.base()); 
      st2.insert(a[2*N-i]);
      latter[i] = latter[i-1] + a[2*N-i] - tmp;
    }else{
      latter[i] = latter[i-1];
    }
  }

  ll ans = -INF;

  REP(i, N+1){
    ans = max(ans, former[i] - latter[N-i]);
  }

  cout << ans << endl;
}

