        ll tmp = rmax.top();
        if (a[2 * N - 1 - i] < tmp) {
            dp_min[i+1] = dp_min[i] - tmp + a[2 * N - 1 - i];
            rmax.pop();
            rmax.push(a[2 * N - 1 - i]);
        } else {
            dp_min[i+1] = dp_min[i];
        }
    }

    ll ans = - INF * INF;
    REP(i, N+1) {
        ans = max(ans, dp_max[i] - dp_min[N-i]);
    }
    cout << ans << endl;

    return 0;
}

