void solve() {
    ll N;
    cin >> N;
    ll a[N * 3 + 1];
    FOR(i, 1, N * 3 + 1) {
        cin >> a[i];
    }

    ll red[N * 3 + 1], blue[N * 3 + 1];
    red[0] = 0;
    GPQ<ll> rque;
    FOR(i, 1, N + 1) {
        red[i] = red[i - 1] + a[i];
        rque.push(a[i]);
    }

    FOR(i, N + 1, N * 2 + 1) {
        red[i] = red[i - 1] + a[i];
        rque.push(a[i]);
        red[i] -= rque.top();
        rque.pop();
    }

    blue[N * 3 + 1] = 0;
    PQ<ll> bque;
    RFOR(i, N * 2 + 1, N * 3 + 1) {
        blue[i] = blue[i + 1] + a[i];
        bque.push(a[i]);
    }

    RFOR(i, N + 1, N * 2 + 1) {
        blue[i] = blue[i + 1] + a[i];
        bque.push(a[i]);
        blue[i] -= bque.top();
        bque.pop();
    }

    ll ans = -INF;
    FOR(i, N, N * 2 + 1) {
        // cout << i << ":" << mp(red[i], blue[i + 1]) << endl;
        ans = max(ans, red[i] - blue[i + 1]);
    }

    cout << ans << endl;
    return;
}


