void oneCase () {
    int n;
    cin >> n;
    vector<int> arr(n * 3);
    for (auto& el : arr) {
        cin >> el;
    }
    priority_queue<int> right;
    priority_queue<int,  std::vector<int>, std::greater<int>> left;
    ll ls = 0, rs = 0, best = 0;
    for (int i = 0; i < n; ++i) {
        left.push(arr[i]);
        ls += arr[i];
        right.push(arr[2 * n + i]);
        rs += arr[2 * n + i];
    }


    best = ls - rs;
    int take = n;
    int lp = n;
    int rp = 2 * n - 1;
    while (take > 0 and lp <= rp) {
        if (arr[lp] > left.top()) {
            ls += arr[lp] - left.top();
            left.pop();
            left.push(arr[lp]);
            ++lp;
            --take;
            best = max(best, ls - rs);
            continue;
        }
        if (arr[rp] < right.top()) {
            rs += arr[rp] - right.top();
            right.pop();
            right.push(arr[rp]);
            --rp;
            --take;
            best = max(best, ls - rs);
            continue;
        }
        ++lp;
        --rp;
    }



    cout << best << "\n";
}




