/*
  「3N項の数列から任意のN項を落として、残った2N項の数列の前半N項総和一後半N項総和を最大化せよ。って問題の高速なアルゴリズムが思いつかない。」
*/

/*
 例えば数列が [3 1 4 1 5 9 2 6 5] のとき、
 求めるものは
   [3 1 4] [1 5 9 2 6 5]
   [3 1 4 1] [5 9 2 6 5]
   [3 1 4 1 5] [9 2 6 5]
   [3 1 4 1 5 9] [2 6 5]
 の、(左の集合から大きい順に 3 つとったものの総和) - (右の集合から小さい順に 3 つとったものの総和) の最大値。

 まず、それぞれの (左の集合から大きい順に 3 つとったものの総和) を求める。
 「大きい順に 3 つ」の要素が格納されているような優先度つきキューを考えると順々に求められる。

 最初は 3 つしかないので明らかに、
 [3 1 4]
  キュー: {1, 3, 4}
  キューの総和: 8

 以下順番に、
 [3 1 4 1]
  キューに新たな要素 1 を挿入: {1, 1, 3, 4}
  キューから最小値 1 を削除: {1, 3, 4}
  キューの総和: 8 + 1 - 1 = 8

 [3 1 4 1 5]
  キューに新たな要素 5 を挿入: {1, 3, 4, 5}
  キューから最小値 1 を削除: {3, 4, 5}
  キューの総和: 8 + 5 - 1 = 12

 [3 1 4 1 5 9]
  キューに新たな要素 9 を挿入: {3, 4, 5, 9}
  キューから最小値 3 を削除: {4, 5, 9}
  キューの総和: 12 + 9 - 3 = 18


 右から小さい順に……も同じ要領で求まる。あとは差を取って最大値を探せばよい。


 (キューのデータ構造を適切に選べば) 挿入と削除が O(log N) とかなので全体で O(N log N) のはず。
*/

//↓本体
void f(const std::vector<int> &v){
    const int n = v.size() / 3;

    // 「まず、それぞれの (左の集合から大きい順に N 個とったものの総和) を求める」
    std::vector<int> former_max_n_sum(n + 1); // 「キューの総和」
    std::priority_queue<int, std::vector<int>, std::greater<int>> former_max_n; //「キュー」

    // 「最初は……」
    former_max_n_sum[0] = 0;
    for(int i = 0; i < n; i++){
        former_max_n_sum[0] += v[i];
        former_max_n.push(v[i]);
    }

    // 「以下順番に、……」
    for(int i = n; i < 2 * n; i++){
        former_max_n.push(v[i]); // キューに新たな要素を挿入
        former_max_n_sum[i - n + 1] = former_max_n_sum[i - n] + v[i] - former_max_n.top(); // 総和
        former_max_n.pop(); // キューから最小値を削除
    }


    // 「右から小さい順に……も同じ要領で求まる」
    std::vector<int> latter_min_n_sum(n + 1);
    std::priority_queue<int> latter_min_n;
    latter_min_n_sum[n] = 0;
    for(int i = 2 * n; i < 3 * n; i++){
        latter_min_n_sum[n] += v[i];
        latter_min_n.push(v[i]);
    }
    for(int i = 2 * n - 1; i >= n; i--){
        latter_min_n.push(v[i]);
        latter_min_n_sum[i - n] = latter_min_n_sum[i - n + 1] + v[i] - latter_min_n.top();
        latter_min_n.pop();
    }


    // 「あとは差を取って最大値を探せばよい」
    int diff_max = -INT_MAX, index;
    for(int i = 0; i < n + 1; i++){
        int diff = former_max_n_sum[i] - latter_min_n_sum[i];
        if(diff > diff_max){
            diff_max = diff;
            index = i + n; // 最大値を与える分割の位置
        }
    }

    std::cout << diff_max << std::endl;
}


