int parent(int i){return((i-1)/2);}
int lchild(int i){return(2*i+1);}
int rchild(int i){return(2*i+2);}

void display_queue(int *pq, int *q_max){
  int j = 0;
  int b = 0;
  for (int i=0;i < *q_max;i++) {
    cout << pq[i] << " ";
