long long int sum_left[100005]={0};
long long int sum_right[100005]={0};

int main(){
    int n;
    cin >> n;
    vector<long long int> v;
    for(int i=0;i<3*n;++i){
        long long int a;
        cin >> a;
        v.push_back(a);
    }

    priority_queue<long long int, vector<long long int>, greater<long long int>> que_left;
    priority_queue<long long int> que_right;
    for(int i=0;i<n;++i){
        sum_left[0] += v[i];
        sum_right[0] += v[v.size()-i-1];
        que_left.push(v[i]);
        que_right.push(v[v.size()-i-1]);
    }

    for(int i=0;i<n;++i){
        sum_left[i+1] = sum_left[i] + v[n+i];
        que_left.push(v[n+i]);
        sum_left[i+1] -= que_left.top();
        que_left.pop();

        sum_right[i+1] = sum_right[i] + v[2*n-i-1];
        que_right.push(v[2*n-i-1]);
        sum_right[i+1] -= que_right.top();
        que_right.pop();
    }

    long long int ans = sum_left[0] - sum_right[n];
    for(int i=1;i<=n;++i){
        ans = max(ans, sum_left[i] - sum_right[n-i]);
    }

    cout << ans << endl;

    return 0;
}

