        cin >> a[i];

    vector<long> fh_list(N + 1);
    vector<long> lh_list(N + 1);
    priority_queue<long, vector<long>, greater<long>> first_half; // 降順
    priority_queue<long, vector<long>, less<long>> latter_half;   // 昇順
    long f_sum, l_sum;

    for (int i = 0; i <= N; i++)
    {

        for (int j = 0; j < N + i; j++)
        {
            first_half.push(a[j]);
            latter_half.push(a[3 * N - 1 - j]);
        }
        f_sum = 0;
        l_sum = 0;
        for (int j = 0; j < N; j++)
        {
            f_sum += first_half.top();
            l_sum += latter_half.top();
            first_half.pop();
            latter_half.pop();
        }
        while (!first_half.empty())
        {
            first_half.pop();
        }
        while (!latter_half.empty())
        {
            latter_half.pop();
        }
        fh_list[i] = f_sum;
        lh_list[i] = l_sum;
    }

    long ans_cnd = 0;
    long ans = -1 * pow(10, 10);
    for (int i = 0; i <= N; i++)
    {
        ans_cnd = fh_list[i] - lh_list[N - i];
        if (ans < ans_cnd)
        {
            ans = ans_cnd;
        }
    }

    cout << ans << endl;

    return 0;
}

