    deque<ll> dq;
    priority_queue<ll> lque;
    priority_queue<int, vector<int>, greater<int> > gque;

    ll sf = 0, sb = 0;
    for(int i = 0; i < 3*N; i++) {
        int x;
        cin >> x;
        if(i < N) {gque.push(x); sf += x; }
        else if(i < 2*N) {dq.push_back(x); }
        else {lque.push(x); sb += x; }
    }

    for(int i = 0; i < N; i++) {
        int f = dq.front(), b = dq.back();
        int g = gque.top(), l = lque.top();
        if(sf - g + f > sf && sb - l + b < sb) {
            if(abs(-g+f) > abs(-l+b)) {
                dq.pop_front(); gque.pop();
                sf = sf - g + f;
            }else {
                dq.pop_back(); lque.pop();
                sb = sb - l + b;
            }
        } else if(sf - g + f > sf) {
            dq.pop_front(); gque.pop();
            sf = sf - g + f;            
        } else if(sb - l + b < sb) {
            dq.pop_back(); lque.pop();
            sb = sb - l + b;            
        } else {
            dq.pop_front();
        }
    }

    cout << sf - sb << endl;

