/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, a[MAX_N * 2];
ll ans[2][MAX_N];

void solve(){
    rep(i, 3 * n) in1(a[i]);

    pq qsu; pql qfl;
    rep(j, 2) rep(i, n + 1) ans[j][i] = 0;
    rep(i, n){
        qfl.push(a[i]); qsu.push(a[i + 2 * n]);
        ans[0][0] += a[i]; ans[1][n] += a[i + 2 * n];
    }

    rep(i, n){
        ll fmin = qfl.top(); ll smax = qsu.top();
        ll fnew = a[i + n]; ll snew = a[2 * n - 1 - i];
        ans[0][i + 1] += ans[0][i];
        ans[1][n - i - 1] += ans[1][n - i];

        if (fmin < fnew) {
            qfl.pop(); qfl.push(fnew);
            ans[0][i + 1] += fnew - fmin;
        }
        if (smax > snew) {
            qsu.pop(); qsu.push(snew);
            ans[1][n - i - 1] -= smax - snew;
        }
    }

    answer = -INF;
    rep(i, n + 1) answer = max(answer, ans[0][i] - ans[1][i]);
    prl(answer);

    // check negative MOD
    // check index flow
    // check overwrite of the input variables
}

int main(void){
    in1(n);
    // assert(n <= 999);
    solve();

    return 0;
}

