        que.push(arr[i+k]);
        ll a = que.top();
        que.pop();

        sum += arr[i+k]-a;

        resL[i+1] = sum;
    }

    /// left

    result = resL[k] - sum1;

    for(int i = 1; i <= k; i++){

        que1.push(arr[2*k-i]);
        ll a = que1.top();
        que1.pop();

        sum1 += arr[2*k-i]-a;

        result = max(resL[k-i] - sum1,result);
    }

    /// right

