	}
	REP(i, n) {
		ll gomi; cin >> gomi;
		a2.push_back(gomi);
	}
	REP(i, n) {
		ll gomi; cin >> gomi;
		a3.push(gomi);
		a3goukei += gomi;
	}

	ll left = 0, right = n - 1;
	REP(i, n) {
		ll a1min=a1.top(),a3max=a3.top();
		if (a2[left]<=a1min&&a2[right]>=a3max) {
			break;
		}
		else {
			if (a3max < a2[right] ) {
				a3.pop();
				a3.push(a2[right]);
				a3goukei = a3goukei - a3max + a2[right]; right--;
			}
			else if(a2[left]<a1min){
				a1.pop();
				a1.push(a2[left]);
				a1goukei = a1goukei - a1min + a2[left];
				left++;
			}
			else if (a2[left] - a1min > a3max - a2[right]) {
				a1.pop();
				a1.push(a2[left]);
				a1goukei = a1goukei - a1min + a2[left];
