        priority_queue<int, vector<int>, greater<int>> pq;
        vector<long long> suml(n + 1, 0);
        for (int i = 0; i < n; i ++) { 
                suml[0] += a[i];
                pq.push(a[i]);
        }
        for (int i = n; i < 2 * n; i ++) {
                int nv = a[i];
                int ov = pq.top();
                pq.push(a[i]);
                pq.pop();
                suml[i - n + 1] = suml[i - n] - ov + nv;
        }
