                sumr[n] += a[i];
                pq2.push(a[i]);
        }
        for (int i = 2 * n - 1; i >= n; i --) {
                int nv = a[i];
                int ov = pq2.top();
                pq2.push(a[i]);
                pq2.pop();
                sumr[i - n] = sumr[i - n + 1] - ov + nv;
