			right_min[i] = right_min[i-1] - rpq.top() + a[j];
			rpq.pop();
			rpq.push(a[j]);
		} else {
			right_min[i] = right_min[i-1];
		}

		//cout << "i=" << i << " " << right_min[i] << endl; // **** debug ****
	}

	ll ans = -INF;

	for (int i=N; i<=2*N; i++) {
		ans = max(ans, left_max[i] - right_min[3*N - i]);
	}

	cout << ans << endl;

	return 0;
}

