//添字ごとのTopNの合計の配列を返す(前半部分)
std::valarray<int> DeriveSumArr1()
{
    std::valarray<int> SumArr1(UB+1);

    std::priority_queue<int,std::vector<int>, std::greater<int> > Que;

    int SumVal=0;
    for(int I=0;I<=UB;I++){
        Que.push(AArr[I]);
        SumVal+=AArr[I];

        if((int)Que.size()>N){
            SumVal-=Que.top();
            Que.pop();
        }
        SumArr1[I]=SumVal;
    }
    return SumArr1;
}

//添字ごとのTopNの合計の配列を返す(後半部分)
std::valarray<int> DeriveSumArr2()
{
    std::valarray<int> SumArr2(UB+1);

    std::priority_queue<int> Que;

    int SumVal=0;
    for(int I=UB;0<=I;I--){
        Que.push(AArr[I]);
        SumVal+=AArr[I];

        if((int)Que.size()>N){
            SumVal-=Que.top();
            Que.pop();
        }
        SumArr2[I]=SumVal;
    }
    return SumArr2;
}

