  ll n;
  cin>>n;
  ll a[100005] = {};
  ll sumf[100005] = {},sumb[100005] = {};
  priority_queue<ll,vector<ll>, greater<ll> > front;
  priority_queue<ll> back;
  rep(i, 3* n){
    cin>>a[i];
    if(i < n){
      front.push(a[i]);
      sumf[0] += a[i];
    } else if( i > 2 * n - 1){
      back.push(a[i]);
      sumb[0] += a[i];
    }
  }

  repl(i,n,2*n){
    sumf[i - n + 1] = sumf[i-n] + a[i];
