const int maxn = 1e5 + 10;
const ll INF = 1e16 * -1;
int n;
ll sum[maxn], rig[maxn];
ll a[maxn];
ll dp[maxn];
ll dp2[maxn];

void solve() {
  cin >> n;
  a[0] = sum[0] = 0;
  for (int i = 1; i <= 3 * n; ++i) {
    cin >> a[i];
    sum[i] = a[i] + sum[i - 1];
  }
  rig[3 * n + 1] = 0;
  for (int i = 3 * n; i >= 1; --i) {
    rig[i] = a[i] + rig[i + 1];
  }

//  for (int i = 1; i <= 3 * n; ++i) {
//    printf("%d %d %d\n", a[i], sum[i], rig[i]);
//  }

  priority_queue<ll, vector<ll>, greater<ll> > q;
  dp[0] = INF;
  for (int i = 1; i <= n; ++i) {
    dp[i] = INF;
    q.push(a[i]);
  }

  dp[n] = sum[n];
  for (int i = n + 1; i <= 2 * n; ++i) {
    int mini = q.top();
    if (mini < a[i]) {
      dp[i] = dp[i - 1] - mini + a[i];
      if (!q.empty()) {
        q.pop();
      }
      q.push(a[i]);
    } else {
      dp[i] = dp[i - 1];
    }
  }

  priority_queue<ll> q2;
  dp2[3 * n] = INF * -1; //できるだけ最小に
  for (int i = 3 * n; i >= 2 * n + 1; --i) {
    dp2[i] = INF * -1;
    q2.push(a[i]);
  }
  dp2[2 * n + 1] = rig[2 * n + 1];
  for (int i = 2 * n; i >= n + 1; --i) {
    int maxi = q2.top();
    if (maxi > a[i]) {
      dp2[i] = dp2[i + 1] - maxi + a[i];
      if (!q2.empty()) {
        q2.pop();
      }
      q2.push(a[i]);
    } else {
      dp2[i] = dp2[i + 1];
    }
//    printf("dp2[%2d] = %2d\n", i, dp2[i]);
  }
  ll ans = INF;
  for (int i = n; i <= 2 * n; ++i) {
//    printf("%3d\t%3d\t%3d\n", a[i], dp[i], dp2[i + 1]);
    ans = max(ans, dp[i] - dp2[i + 1]);
  }
  cout << ans << endl;
}

int main() {
  solve();
  return 0;
}

