int  n, ans = -1000000000000000LL, rr=0 ,frst, scond; 
int  a[600015] ; 

bool fun(int x){
    frst=0,scond=0;
    rr=-1;
    int k=n;
    for (int i=3*n;i>0;i--){
        if (x >= a[i]) {
            k--; scond += a[i];
        }
        if (k==0) {
            if (i-1>=n) {
              rr = i-1; 
            }
            break;
        }
    }
    return rr>=n;
}

signed main()
{
    cin >> n ; 
    int N=n*3;
    for (int i=1;i<=N;i++) cin>>a[i];
    int l=1,r=1000000005;
    while (l<=r){
        int m=(l+r)/2;
        if (fun(m)){
            r = m-1 ; 
            int h[rr+1];
            for (int i=1;i<=rr;i++)
                h[i] = a[i];
            sort(h+1,h+rr+1);
            int c=n;
            for (int i=rr;i>0;i--){
                frst += h[i];
                c--;
                if (c==0) break;
            }
            ans = max(ans,frst-scond);
        }
        else {
            l = m+1 ; 
        }
    }
    cout << ans << endl;
    return 0;
}

