int n;

ll calcBig(vector<ll> &arr, int s, int e)
{
	vector<ll> pt(arr.begin() + s, arr.begin() + e);
	sort(pt.begin(), pt.end(), greater<ll>());
	ll ret = 0;
	for (int i = 0; i < n; i++) {
		ret += pt[i];
	}
	/* cout << ret << endl; */
	return ret;
}

ll calcSmall(vector<ll> &arr, int s, int e)
{
	vector<ll> pt(arr.begin() + s, arr.begin() + e);
	sort(pt.begin(), pt.end());
	ll ret = 0;
	for (int i = 0; i < n; i++) {
		ret += pt[i];
	}
	/* cout << ret << endl; */
	return ret;
}

ll value(vector<ll> &arr, int mid)
{
	return calcBig(arr, 0, mid) - calcSmall(arr, mid, 3 * n);
}

ll ternary_search(vector<ll> &arr, int l, int r)
{
	int cnt = 500;
	while (cnt--)
	{
		int l3 = l + (r - l) / 3;
		int r3 = r - (r - l) / 3;
		if (value(arr, l3) > value(arr, r3)) {
			r = r3;
		} else {
			l = l3;
		}
	}
	return max(value(arr, l), value(arr, r));
}

int main()
{
	cin >> n;

	vector<ll> arr(3 * n);
	for (int i = 0; i < 3 * n; i++) {
		cin >> arr[i];
	}
	cout << ternary_search(arr, n, 2 * n);
	return 0;
}

