bool not_used[3*100001];

ll ans = -(1LL << 40);

void solve(int k, int used) {

    if (k >= N*3 and used < N) return;

    if (used >= N) {

        ll s1 = 0, s2 = 0;
        int cnt=0;

        for (int i=0; i<N*3; ++i) {
            if (!not_used[i]) {

                if (cnt < N) s1 += a[i];
                else s2 += a[i];

                ++cnt;
            }
        }

        //cout << s1 << " " << s2 << endl;

        ans = max(ans, s1 - s2);
        return;

    }

    not_used[k] = 1;
    solve(k + 1, used+1);
    not_used[k] = 0;
    solve(k + 1, used);

}

