  for (int i=1; i<=N; i++) {
    l.push(a[2*N-i]);
    sum += a[2*N-i];
    sum -= l.top();
    l.pop();
    lsum[N-i] = sum;
  }
  for (int i=0; i<=N; i++)
    ans = max(ans, fsum[i]-lsum[i]);
