using ll = long long;
int N;
ll f(vector<int> a, int cnt) {
    vector<int> vec1(a.begin(), a.begin() + N + cnt);
    vector<int> vec2(a.begin() + N + cnt, a.end());
    sort(all(vec1));
    sort(all(vec2));
    ll s = 0;
    rep(i, vec1.size()) if (cnt <= i) s += vec1[i];
    // cout << vec1.size() << ", " << vec2.size() << ": " << s << endl;
    rep(i, vec2.size() - (N - cnt)) s -= vec2[i];
    // cout << vec1.size() << ", " << vec2.size() << ": " << s << endl;
    return s;
}
vector<ll> f2(const vector<int> &a, int m) {
    priority_queue<int> que;
    rep(i, N) que.push(m * a[i]);
    vector<ll> s(N + 1);
    rep(i, N) s[0] += a[i];
    rep(i, N) {
        que.push(m * a[i + N]);
        int t = que.top();
        que.pop();
        s[i + 1] = s[i] - m * t + a[i + N];
    }
    return s;
}
int main() {
    vector<int> a;
    cin >> N;
    a.resize(3 * N);
    rep(i, 3 * N) cin >> a[i];
    vector<ll> s1 = f2(a, -1);
    reverse(all(a));
    vector<ll> s2 = f2(a, 1);
    ll ans = -1e18;

    reverse(all(s2));
    // rep(i, s1.size()) cout << s1[i] << ", " << s2[i] << endl;
    rep(i, s1.size()) ans = max(ans, s1[i] - s2[i]);
    cout << ans << endl;
    return 0;
}

