bool fun(int x){
    frst=0,scond=0;
    rr=-1;
    int k=n;
    for (int i=N;i>0;i--){
        if (k>0 and x >= a[i]) {
            k--; scond += a[i];
            if (k==0){
                rr=i-1;
                break;
            }
        }
    }
    return rr>=n;
}

