using namespace std;
const int BUF = 300005;



int N;
int vList[BUF];

void read() {
    cin >> N;
    for (int i = 0; i < N * 3; ++i) {
        cin >> vList[i];
    }
}


void work() {
    priority_queue<int, vector<int>, greater<int> > aChose;
    for (int i = 0; i < N; ++i) {
        aChose.push(vList[i]);
    }


    vector< pair<int, int> > valIdx; // (value, index)
    for (int i = N; i < N * 3; ++i) {
        valIdx.push_back(make_pair(vList[i], i));
    }
    sort(valIdx.begin(), valIdx.end());
    int bCandiCur = N;

    bool isChosenAsB[BUF] = {};
    for (int i = 0; i < N; ++i) {
        isChosenAsB[valIdx[i].second] = true;
    }

    for (int cur = N; cur < N * 3; ++cur) {
        if (isChosenAsB[cur]) {
            while (bCandiCur < valIdx.size() && valIdx[bCandiCur].second <= cur) {
                ++bCandiCur;
            }
            if (bCandiCur == valIdx.size()) {
                break;
            }

            if (vList[cur] - aChose.top() - (valIdx[bCandiCur].first - vList[cur]) >= 0) {
                aChose.pop();
                aChose.push(vList[cur]);
                isChosenAsB[cur] = false;
                isChosenAsB[valIdx[bCandiCur].second] = true;
            } else {
                break;
            }

        } else {
            if (aChose.top() < vList[cur]) {
                aChose.pop();
                aChose.push(vList[cur]);
            }
        }
    }

    long long sum = 0;
    while (!aChose.empty()) {
        sum += aChose.top();
        aChose.pop();
    }

    for (int i = 0; i < N * 3; ++i) {
        if (isChosenAsB[i]) {
            sum -= vList[i];
        }
    }

    cout << sum << endl;
}


int main() {
    read();
    work();
    return 0;
}

