using namespace std;

const int N = 3*1e5 + 10;

struct node{
    int v;
    int index;
};

bool del[N];

struct cmpbig { // big
    bool operator() (const node a, const node b) const {
        return a.v < b.v;
    }
};

struct cmpsmall { // small
    bool operator() (const node a, const node b) const {
        return a.v > b.v;
    }
};

node a[N];

int main() {
    //ios::sync_with_stdio(false);
    int n;
    cin >> n;
    for(int i = 1; i <= 3*n; i++) {
        cin >> a[i].v;
        a[i].index = i;
    }
    long long lsum = 0;
    long long rsum = 0;
    long long ans = -INT_MIN;
    priority_queue<node, vector<node>, cmpsmall> le;
    for(int i = 1; i <= n; i++) le.push(a[i]), lsum += a[i].v;
    priority_queue<node, vector<node>, cmpbig> ri;
    for(int i = n + 1; i <= 3 * n; i++) ri.push(a[i]), rsum += a[i].v;
    priority_queue<node, vector<node>, cmpsmall> rm;
    for(int i = 1; i <= n; i++) {
        node top = ri.top();
        rsum -= top.v;
        del[top.index] = true;
        rm.push(top);
        ri.pop();
    }
    ans = lsum - rsum;
    for(int i = n + 1; i <= 2 * n; i++) {
        le.push(a[i]);
        lsum += a[i].v;
        lsum -= le.top().v;
        if(!del[a[i].index]) {
            rsum -= a[i].v;
            node top = rm.top();
            rm.pop();
            while (!del[top.index]) {
                top = rm.top();
                rm.pop();
            }
            rsum += top.v;
            del[top.index] = false;
        }
        del[a[i].index] = false;
        //printf("lsum=%lld rsum=%lld\n", lsum, rsum);
        ans = max(ans, lsum - rsum);
    }
    cout << ans << endl;
    return 0;
}

