	}
	ss.clear();
	sum = 0LL;
	for (int i = 3*n; i >= 1; --i) {
		ss.insert(make_pair(a[i], i));
		sum += a[i];
		while(ss.size() > n) {
			sum -= (*ss.rbegin()).first;
			ss.erase(*ss.rbegin());
		}
		if (ss.size() == n)rs[i] = sum;
	}
	for (int i = 3*n-1; i >= 1; --i) {
		rs[i] = min(rs[i+1], rs[i]);
		//cout<<i<<" "<<rs[i]<<endl;
	}
	for (int i = 1; i < 3*n; ++i) {
		if (ls[i] > 0LL-1000000000000000000LL && rs[i+1] < 1000000000000000000LL) {
			ans = max(ans, ls[i]-rs[i+1]);
		}
