	// n <= k < 2nの範囲でkを動かし、qlに常に[0,k]の範囲で大きい方からn個の要素が入ってる状態を保つ
	// kを1ずつ右にずらし、その度にqlの最小値を取り出してa[k]を入れ直して差分をsumlに足し、sumをbにしまっておく しゃくとり的な
	// qrには[k,3n)の範囲で小さい方からn個の要素を入れて同様にsumrを求めていき、bから引く
	// これで(kより左n個の総和)-(kより右n個の総和)が全通り求められるので最大値を出力すればいい

	// 前半分
	rep(i,n) {
		suml += a[i];
		ql.push(a[i]);
	}
	b[0] = suml;
	reps(k,n,n*2) {
		// 今厳選してあるn個の最小値よりa[k]の方が更に小さいなら何もしなくていい
		if (ql.top()<a[k]) {
			suml -= ql.top(); ql.pop();
			suml += a[k];
			ql.push(a[k]);
		}
		b[k-n+1] = suml;
	}
	// 後ろ半分
	reps(i,n*2,n*3) {
		sumr += a[i];
		qr.push(a[i]);
	}
	b[n] -= sumr;
	for (int k = n*2-1; k >= n; --k) {
		if (qr.top()>a[k]) {
			sumr -= qr.top(); qr.pop();
			sumr += a[k];
			qr.push(a[k]);
		}
		b[k-n] -= sumr;
	}
	// 最大値探し
	rept(i,n) chmax(ans, b[i]);
	cout << ans << ln;
}

