int main() {
	int num, first_sum, latter_sum, score;
	std::vector<int> v_original, v_first_half, v_latter_half;

	std::cin >> num;								//最初の数値を読み込む
	v_original.resize(num * 3);						//その3倍がvecterの要素数

	for (int i = 0; i < v_original.size(); i++) {	//vectorの要素を読み込む
		std::cin >> v_original[i];
	}

	for (int j = 0; j < v_original.size() / 2; j++) {	//元のvectorの前半分を別のvectorに入れる
		v_first_half[j] = v_original[j];
	}

	for (int k = v_original.size() / 2 + 1; k < v_original.size(); k++) {  //元のvectorの後半分を別のvectorに入れる
		int l = 0;
		v_latter_half[l] = v_original[k];
		l++;
	}

	std::sort(v_first_half.begin(), v_first_half.end());		//前半を昇順ソート
	std::sort(v_latter_half.begin(), v_latter_half.end());		//後半を昇順ソート

	for (int m = 1; m <= num; m++) {						//ここからの方針　最後の問題文を見ると　Score=（前の配列の合計）-（後ろの配列の合計）より前の値を大きく、後ろの値を小さくすればよい
															//よって前の配列から小さい要素を消し、後ろの配列から大きい数値を消す
															//なお、最初の数値が偶数の時、初めに前を削除してから後を削除する　その後　前→後→前→…　と交互に消していく
		if (m % 2 != 0) {
			v_first_half.erase(v_first_half.begin());      //奇数の時、一番小さい要素を消す（昇順ソートしてあるので最初を消す）
		}
		else {
			v_latter_half.erase(v_latter_half.end()+1);    //偶数の時、一番大きい要素を消す（昇順ソートしてあるので最後を消す）
		}
	}

	for (int n = 0; n < v_first_half.size(); n++) {		//前半の合計を出す
		first_sum = v_first_half[n];
	}

	for (int o = 0; o < v_latter_half.size(); o++) {	//後半の合計を出す
		latter_sum = v_latter_half[o];
	}

	score = first_sum - latter_sum;						//score=前半合計-後半合計

	std::cout << score << std::endl;					//出力

	return 0;
}

