int main() {
  ll N;
  scanf("%lld", &N);
  REP(i, N){
    ll temp;
    scanf("%lld", &temp);
    front.push(temp);
    sumf += temp;
  }
  REP(i, N){
    ll temp;
    scanf("%lld", &temp);
    middle.push_back(temp);
  }
  REP(i, N){
    ll temp;
    scanf("%lld", &temp);
    back.push(temp);
    sumb += temp;
  }
  ll l = 0;
  ll r = N-1;
  while(l <= r){
    if(middle[l] <= front.top() && middle[r] >= back.top()){
      if(front.top() - middle[l] < middle[r] - back.top()){
        l++;
      }else r--;
    }else if(middle[l] - front.top() > back.top() - middle[r]){
      sumf -= front.top();
      sumf += middle[l];
      front.pop();
      front.push(middle[l]);
      l++;
    }else{
      sumb -= back.top();
      sumb += middle[r];
      back.pop();
      back.push(middle[r]);
      r--;
    }
  }
  cout << sumf - sumb << endl;
