//添字ごとのTopNの合計の配列を返す(前半部分)
std::valarray<long long> DeriveSumArr1()
{
    std::valarray<long long> SumArr1(UB+1);

    std::priority_queue<long long,std::vector<long long>, std::greater<long long> > Que;

