const int MAXN = (int)3e5 + 777;
ll a[MAXN], pref[MAXN], suff[MAXN];
int n;

void solve() {
	cin >> n;
	n *= 3;

	for(int i = 0; i < n; ++i) {
		cin >> a[i];
	}

	multiset<ll> setik;
	for(int i = 1; i <= n; ++i) {
		pref[i] = pref[i - 1];
		pref[i] += a[i - 1];
		setik.insert(a[i - 1]);

		if(len(setik) > n / 3) {
			auto iter = setik.begin();
			pref[i] -= *iter;
			setik.erase(iter);
		}

		DBG(pref[i]);
	}

	setik.clear();
	for(int i = 1; i <= n; ++i) {
		suff[i] = suff[i - 1];
		suff[i] -= a[n - i];
		setik.insert(-a[n - i]);

		if(len(setik) > n / 3) {
			auto iter = setik.begin();
			suff[i] -= *iter;
			setik.erase(iter);
		}

		DBG(suff[i]);
	}

	ll answ = -LL_INF;

	for(int i = n / 3; i <= 2 * (n / 3); ++i) {
		answ = max(answ, pref[i] + suff[n - i]);
	}

	cout << answ << '\n';
}

