int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int N; cin >> N;
    vector<ll> a(N);
    rep(i, 3*N) cin >> a[i];

    vector<ll> left(2*N, 0), right(2*N, 0);

    priority_queue<ll, vector<ll>, greater<ll>> lpq;
    ll lmax = 0;
    rep(i, N) { lpq.push(a[i]); lmax += a[i]; }
    left[N-1] = lmax;
    repr(i, N, 2*N){
        lmax += a[i];
        lpq.push(a[i]);
        lmax -= lpq.top();
        lpq.pop();
        left[i] = lmax;
    }

    priority_queue<ll> rpq;
    ll rmin = 0;
    repr(i, 2*N, 3*N) { rpq.push(a[i]); rmin += a[i]; }
    right[2*N-1] = rmin;
    reprrev(i, N, 2*N){
        rmin += a[i];
        rpq.push(a[i]);
        rmin -= rpq.top();
        rpq.pop();
        right[i-1] = rmin;
    }

    ll ans = -1e15;
    repr(i, N-1, 2*N) chmax(ans, left[i]-right[i]);
    cout << ans << endl;

    return 0;
}

