#include <ios>
using namespace std;

vector<long long> fill_dp0(int N, vector<long long> &A);
vector<long long> fill_dp1(int N, vector<long long> &A);

int main() {
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    vector<long long> A(3 * N, 0LL);
    for (auto & a : A) cin >> a;

    // dp0[t]: A[:N + t] のうち、上位N個の総和
    auto dp0 = fill_dp0(N, A);

    // dp1[t]: A[N + t:] のうち、下位N個の総和
    auto dp1 = fill_dp1(N, A);

    long long ans = dp0[0] - dp1[0];
    for (int i = 0; i <= N; ++i){
        ans = max(ans, dp0[i] - dp1[i]);
    }
    cout << ans << endl;
    return 0;
}

vector<long long> fill_dp0(int N, vector<long long> &A){
    // dp0[t]: A[:N + t] のうち、上位N個の総和
    vector<long long> dp0(N + 1, 0);
    long long s = 0LL;
    multiset<long long> topN;
    for (int i = 0; i != N; ++i){
        s += A[i];
        topN.insert(-A[i]);
    }
    dp0[0] = s;
    for (int i = N; i != 2 * N; ++i){
        topN.insert(-A[i]);
        auto it_min = topN.end();
        --it_min;
        s += A[i];
        s += *it_min;
        topN.erase(it_min);
        dp0[i - N + 1] = s;
    }
    return dp0;
}


vector<long long> fill_dp1(int N, vector<long long> &A){
    // dp1[t]: A[N + t:] のうち、下位N個の総和
    vector<long long> dp1(N + 1, 0);
    long long s = 0LL;
    multiset<long long> topN;
    for (int i = 2 * N; i != 3 * N; ++i){
        s += A[i];
        topN.insert(A[i]);
    }
    dp1[N] = s;
    for (int i = 2 * N - 1; i >= N; --i){
        topN.insert(A[i]);
        auto it_max = topN.end();
        --it_max;
        s += A[i];
        s -= *it_max;
        topN.erase(it_max);
        dp1[i - N] = s;
    }
    return dp1;
}

