{
	const LL MAX=-10e10;
	LL N;
	cin>>N;
	vector<LL> data(3*N,0);
	LL i,j;
	for (i=0;i<3*N;i++){
		cin>>data[i];
	}
	LL maxV=MAX;
	LL k;

	for (k=0;k<=N;k++){
		vector<LL> A(N+k,0);
		vector<LL> B(2*N-k,0);
		for (i=0;i<N+k;i++){
			A[i]=data[i];
		}
