	rep(i, N * 3) {
		cin >> A[i];
	}

	//左からの走査では小さいものから捨てる
	vll left(N + 1, 0);
	priority_queue<ll, vector<ll>, greater<ll>> pqLeft;
	ll sumLeft = 0;
	rep(i, N) {
		pqLeft.push(A[i]);
		sumLeft += A[i];
	}
	left[0] = sumLeft;
	reps(i, N, N + N - 1) {
		if (pqLeft.top() < A[i]) {
			sumLeft -= pqLeft.top();
			sumLeft += A[i];
			pqLeft.pop();
			pqLeft.push(A[i]);
		}
		left[i - N + 1] = sumLeft;
	}

	eprintf("left:");
	reps(i, 0, N) {
		eprintf("%lld ", left[i]);
	}
	eprintf("\n");

	//右からの走査では大きいさいものから捨てる
	vll right(N + 1, 0);
	priority_queue<ll> pqRight;
	ll sumRight = 0;
	deps(i, N * 3 - 1, N * 2) {
		pqRight.push(A[i]);
		sumRight += A[i];
	}
	right[N] = sumRight;
	deps(i, N * 2 - 1, N) {
		if (pqRight.top() > A[i]) {
			sumRight -= pqRight.top();
			sumRight += A[i];
			pqRight.pop();
			pqRight.push(A[i]);
		}
		right[i - N] = sumRight;
	}

	eprintf("right:");
	reps(i, 0, N) {
		eprintf("%lld ", right[i]);
	}
	eprintf("\n");

	ll result = -INF;

	reps(i, 0, N) {
		ll ans = left[i] - right[i];
		chmax(result, ans);
	}

	cout << result << endl;

	return 0;
}

