	// 右側(初期サイズ 2N) 読み込み
	for(int i=0;i<N2;i++){
		int a;
		cin >> a;
		sum_R+=a;
		pq_R.emplace(a);
		A[N+i]=a;
	}

	ll Max = LLONG_MIN;
	for(int k=0;k<N;k++){

		int oL_sum = 0; // sumL から省く値
		auto L = pqL.cbegin();
		for(int i=0;i<k;i++){ oL_sum += *L; L++; } //小さい方から k 個 の総和

		int oR_sum = 0; // sum_R から省く値
		auto R = pq_R.crbegin();
		for(int i=0;i<(N-k);i++){ oR_sum += *R; R++; } // 大きいさい方から k 個 の総和

		ll m = (sumL-oL_sum) - (sum_R-oR_sum);
		Max = max(Max,m);

		// A[N+k]の値を、左側 <- 右側　に移す。
		sumL += A[N+k];
		sum_R -= A[N+k];
		pqL.emplace(A[N+k]);
		pq_R.erase(A[N+k]);
	}

	printf("%ld\n",Max);

	return 0;
}

