                lque.push(v[i+n]);
                lv.push_back(ltemp);
                ls=ltemp;
                lque.pop();
                sv.push_back(ss);
            }else{
                sque.push(v[i+n]);
                sv.push_back(stemp);
                lv.push_back(ls);
