#define ll long long
#define INF 0x3f3f3f3f3f3f3f3f
using namespace std;

const int N = 1e5+5;
int a[3*N];


int main(){
	//freopen("in","r",stdin);
	ll p1 = 0, p2 = 0;
	auto func = [](const int& l,const int & r) {return a[l] > a[r];};
	priority_queue<int,vector<int>,function<bool(const int&,const int&)> > l(func),r(func);
	int n; scanf("%d",&n);
	for(int i = 1;i <= 3*n;i++){
		scanf("%d",a+i);
		if(i <= n) p1 += a[i];
		if(i > n) p2 += a[i];
	}
	for(int i = 1;i <= n;i++) {
		l.push(i);		
	}
	set<int> record;
	for(int i = n+1;i <= 3*n;i++) r.push(i),record.insert(i);
	ll keep = 0, take = p2;
	for(int i = 1;i <= n;i++){
		int temp = r.top();
		r.pop();
		record.erase(temp);
		take -= a[temp];
		keep += a[temp];
	}
	ll res = -INF;
	for(int i = n+1;i <= 2*n;i++){
		int lt = l.top(),rt = r.top();
		if(a[i]>a[lt]){
			p1 += a[i]-a[lt];
			l.pop(); l.push(i);
		}
		if(record.count(i)==0){
			while(record.count(rt)==0) r.pop(),rt = r.top();
			keep += a[rt]-a[i];
			record.erase(rt);
			r.pop(); 
		}else{
			record.erase(i);
		}
		res = max(res,p1-keep);
	}
	printf("%lld\n", res);

}

#include<bits/stdc++.h>
using namespace std;

int main(){
  int n;
  cin >> n;
  vector<long> a(n),b(2*n),mid(n);
  long suml = 0,sumr = 0,inf = 1000000007;
  multiset<long> left,right,rightrest;
  for(int i = 0;i < n;i++){
    cin >> a.at(i);
    left.insert(a.at(i));
    suml += a.at(i);
  }
  for(int i = 0;i < 2*n;i++){
    cin >> b.at(i);
    if(i < n) mid.at(i) = b.at(i);
  }
  sort(b.begin(),b.end());
  for(int i = 0;i < 2*n;i++){
    if(i < n){
      right.insert(b.at(i));
      sumr += b.at(i);
    }
    else{
      //cout << b.at(i) << endl;
      rightrest.insert(b.at(i));
    }
  }
  long ans = suml - sumr;
  int biter = n;
  //cout << ans << endl;
  for(int i = 0;i < n;i++){
    auto iter = left.lower_bound(mid.at(i));
    auto restiter = rightrest.lower_bound(mid.at(i));
    if(*restiter == mid.at(i)){
      rightrest.erase(restiter);
    }   
    if(iter != begin(left)){
      auto miniter = left.lower_bound(-inf);
      //cout << *miniter << endl;
      suml = suml - *miniter + mid.at(i);
      //cout << suml << endl;
      left.erase(miniter);
      left.insert(mid.at(i));
    }
    iter = right.lower_bound(mid.at(i));
    if(*iter == mid.at(i)){
      auto miniter = rightrest.lower_bound(-inf);
      sumr = sumr - *iter + *miniter;
      //cout << *miniter << endl;
      right.erase(iter);
      right.insert(*miniter);
      rightrest.erase(miniter);
    }
    ans = max(ans,suml-sumr);
    //cout << ans << endl;
  }
  cout << ans << endl;
}

