  priority_queue<int, vector<int>, greater<int>> pq1;
  long long dp1[3*n];
  long long v1 = 0;
  for (int i=0; i<n; i++) {
    pq1.push(a[i]);
    v1 += a[i];
  }
  dp1[n-1] = v1;
  for (int i=n; i<3*n; i++) {
    if (a[i] > pq1.top()) {
      v1 = v1 - pq1.top() + a[i];
      pq1.pop();
      pq1.push(a[i]);
    }
    dp1[i] = v1;
  }
  priority_queue<int> pq2;
  long long dp2[3*n];
