  }
  dp2[2*n] = v2;
  for (int i=2*n-1; i>=0; i--) {
    if (a[i] < pq2.top()) {
      v2 = v2 - pq2.top() + a[i];
      pq2.pop();
      pq2.push(a[i]);
    }
    dp2[i] = v2;
  }
  long long ans = -1e14;
  for (int i=n-1; i<=2*n; i++) {
