const int MAXN = 3e5 + 10;

struct Node {
	int val, idx;
	bool operator < (const Node & obj) {return val < obj.val || val == obj.val && idx > obj.idx;}
} a[MAXN];
int v[MAXN], vis[MAXN];
map<int, int> mp;

int main (void) {
	int n;
	scanf("%d", &n);
	for (int i = 1; i <= 3 * n; i++) {
		scanf("%d", &v[i]);
		a[i].val = v[i];
		a[i].idx = i;
	}
	sort(a+1,a+3*n+1);
	long long sum1 = 0, sum2 = 0;
	for (int i = 1; i <= n; i++) {
		sum1 += v[i];
		mp[v[i]]++;
		vis[i] = 1;
	}
	int cur = 1, cnt = 0;
	for (int i = 1; i <= 3 * n && cnt < n; i++, cur++) {
		if (vis[a[i].idx]) continue;
		sum2 += a[i].val;
		vis[a[i].idx] = 1;
		cnt++;
	}

	long long ans = sum1 - sum2;
	for (int i = n + 1; i <= 2 * n; i++) {
		int val = mp.begin()->first;
		if (v[i] > val) {
			sum1 += v[i] - val;
			mp.begin()->second--;
			if (mp.begin()->second == 0) mp.erase(mp.begin());
			mp[v[i]]++;
		}
		if (vis[i]) {
			sum2 -= v[i];
			for (; cur <= 3 * n; cur++) {
				if (vis[a[cur].idx]) continue;
				sum2 += a[cur].val;
				vis[a[cur].idx] = 1;
				break;
			}
			if (cur == n + 1) break;
		}
		ans = max(sum1 - sum2, ans);
		vis[i] = 1;
	}
	printf("%lld\n", ans);
}

