void solve() {
  inl(N);
  vll a(3 * N);
  rep(i, 3 * N) cin >> a[i];

  vll plus(N + 1, 0);
  plus[0] = accumulate(&a[0], &a[N], 0);
  priority_queue<ll, vll, greater<ll>> que;
  rep(i, N) que.push(a[i]);
  rep(i, N) {
    que.push(a[N + i]);
    auto min = que.top();
    que.pop();
    plus[i + 1] = plus[i] + a[N + i] - min;
  }

  vll minus(N + 1);
  minus[0] = accumulate(&a[2 * N], &a[3 * N], 0);
  priority_queue<ll> que2;
  rep(i, N) que2.push(a[2 * N + i]);
  rep(i, N) {
    que2.push(a[2 * N - i - 1]);
    auto max = que2.top();
    que2.pop();
    minus[i + 1] = minus[i] + a[2 * N - i - 1] - max;
  }

  ll ret = -(1LL << 62);
  rep(i, N + 1) {
    auto diff = plus[i] - minus[N - i];
    if (diff > ret)
      ret = diff;
  }

  out(ret);
}

