long long calc(const int & N, const std::vector<int> & a)
{
        std::unordered_set<int> heads;
        long long sumH = 0;
        for (int i = 0; i < N; i++) {
                heads.insert(a[i]);
                sumH += a[i];
        }
        std::vector<int> backs(a.begin()+N, a.end());
        std::sort(backs.begin(), backs.end());
        std::unordered_set<int> uppers, lowers;
        long long sumL = 0;
        for (int i = 0; i < N; i++) {
                lowers.insert(backs[i]);
                uppers.insert(backs[N+i]);
                sumL += backs[i];
        }
        long long best = sumH - sumL;
        for (int i = 0; i < N; i++) {
                int toBeMoved = a[N+i];
                auto it = uppers.find(toBeMoved);
                if (it != uppers.end()) {
                        uppers.erase(it);
                }
                else {
                        lowers.erase(toBeMoved);
                        sumL -= toBeMoved;
                        auto jt = uppers.begin();
                        lowers.insert(*jt);
                        sumL += *jt;
                        uppers.erase(jt);
                }
                sumH += toBeMoved;
                heads.insert(toBeMoved);
                auto kt = heads.begin();
                sumH -= *kt;
                heads.erase(kt);
                long long d = sumH - sumL;
                if (d > best)
                        best = d;
        }
        return best;
}

