        int q = que.top(); que.pop();
        left -= q;
        l[i] = left;
    }

    int right = 0;
    PQ<int> qqq;
    for(int i=3*n-1;i>=2*n;i--){
        qqq.push(a[i]);
        right += a[i];
        r[i] = right;
    }
    for(int i=2*n-1;i>=n;i--){
        qqq.push(a[i]);
        right += a[i];
        int q = qqq.top(); qqq.pop();
        right -= q;
        r[i] = right;
    }

    int k = -INF;
    FOR(i,n,2*n){
        k = max(k,l[i]-r[i+1]);
    }

