void solve(ll N, vector <ll> a) {
	ll mae[N + 1]	= { };
	ll usiro[N + 1] = { };
	priority_queue <ll, vector <ll>, greater <ll> > que1;
	priority_queue <ll, vector <ll>, less <ll> >	que2;
	rep(i, N) que1.push(a[i]);
	rep(i, N) que2.push(a[i + 2 * N]);
	ll sum;

	sum	   = accumulate(begin(a), begin(a) + N, 0);
	mae[0] = sum;
	FOR(i, 1, N + 1) {
		sum	  += a[N + i];
		que1.push(a[N + i]);
		sum	  -= que1.top();
		que1.pop();
		mae[i] = sum;
	}
	FOR(i, 1, N + 1) {
		sum		+= a[2 * N - i];
		que1.push(a[2 * N - i]);
		sum		-= que1.top();
		que1.pop();
		usiro[i] = sum;
	}

	ll tmp = LLONG_MIN;
	rep(i, N + 1) tmp = max(tmp, mae[i] - usiro[N - i]);

	printf("%lld", tmp);
}

int main() {
