            pref[i] += x-val;

            ms.erase(ms.begin());
            ms.insert(x);
        }
    }

    for(int i = n; i >= 1; i--){
        int x = b[i];
        int val = *mm.begin(); val *= -1;
        suff[i] = suff[i+1];
        if(x < val){
            suff[i] += val-x;
            mm.erase(mm.begin());
            mm.insert(-x);
        }
    }

    // for(int i = 1; i <= n; i++)
