//標準機能のpow(a,n)は整数だとバグるのでこちらを使う
long long POW(long long a, long long n) {
	long long res = 1;
	while(n > 0) {
		if(n & 1) res = res * a;
		a = a * a;
		n >>= 1;
	}
	return res;
}

// 20200423
//エラトステネスのふるいによりn以下の素数を全てベクトルに入れて返す
vector<long long> eratos(long long n) {
	if(n < 2) return {};
	vll v(n - 1);
	rep(i, n - 1) {
		v[i] = i + 2;  // 2からnまで
	}
	ll i = 0;
	while(i < n - 1) {
		ll p = v[i];
		for(ll j = i + 1; j < n - 1; j++) {
			if(v[j] % p == 0) {
				v.erase(v.begin() + j);
				n--;
			}
		}
		i++;
	}
	v.resize(n - 1);
	return v;
}

// n以下の素数を全て詰めたset
set<long long> eraset(long long n) {
	set<long long> s;
	vll v = eratos(n);
	for(auto &t : v) {
		s.insert(t);
	}
	return s;
}

