bool fun(int x){
    frst=0,scond=0;
    rr=-1;
    int k=n;
    for (int i=3*n;i>0;i--){
        if (x >= a[i]) {
            k--; scond += a[i];
        }
        if (k==0) {
            if (i-1>=n) {
              rr = i-1; 
            }
            break;
        }
    }
    return rr>=n;
}

