int main(){
	long long N;
	cin >> N;
	long long a[900000];

	REP(i,3*N) cin >> a[i];
	pq <long long ,vi,greater<long long> > left;
	pq <long long ,vi,greater<long long> > right;

	long long kl[900000];//左のkまでの最大値を記録
	long long kr[900000];	

	long long tl = 0;
	long long tr = 0;


	/* k */
	// k = N ... 2N
	//  left ... i = 0~k-1までの最大値
	// right ... i = k~3N-1 までの最小値


	//初期解
	REP(i,N) {
		left.push(a[i]);
		tl+=a[i];
	}
	kl[N] = tl;
	FOR(i,N,2*N){
		left.push(a[i]);
		tl+=a[i];
		tl-=left.top();
		left.pop();//leftから最小のものをpopする
		kl[i+1] = tl;
	}




	FOR(i,2*N,3*N) {
		right.push(-a[i]);
		tr-=a[i];
	}
	kr[2*N] = tr;
	for(long long i = 2*N-1;i>=N;i--){
		right.push(-a[i]);
		tr-=a[i];
		tr-=right.top();
		right.pop();
		kr[i] = tr;
	}


	long long out = kl[N]+kr[N];
	FOR(i,N+1,2*N){
		out = max(out,kl[i]+kr[i]);
	}


	cout << out << endl;
}

