    REP(i,N,N*2){
      ll ma = que2.top();
      if(a[N * 3 - 1 - i] < ma){
        T[i+1] = T[i] - ma + a[N*3-1 - i];
        que2.pop();
        que2.push(a[N * 3 - 1 - i]);
      }
      else T[i+1] = T[i];
    }

