ll N;
ll A[300001];
ll B[300001];
ll C[300001];
int main() {
	cin >> N;
	rep(i, 0, 3 * N)cin >> A[i];

	priority_queue<ll> pre;
	ll sm = 0;
	rep(i, 0, N * 3) {
		pre.push(-A[i]);
		sm += A[i];
		if (N < pre.size()) {
			ll p = pre.top(); pre.pop();//pop minimum value
			sm += p;
		}
		B[i] = sm;
	}

	priority_queue<ll> post;
	sm = 0;
	for (int i = N * 3 - 1; i >= 0; i--) {
		post.push(A[i]);
		sm += A[i];

		if (N < post.size()) {
			ll p = post.top(); post.pop();
			sm -= p;
		}
		C[i] = sm;
	}

	ll ans = -(ll)(1 << 30);
	rep(c, N, N * 2 + 1) {
		ans = max(ans, B[c - 1] - C[c]);
	}
	cout << ans << endl;
	return 0;
}

