using namespace std;

using ll = long long int;

ll arr[300010] = {};


ll resR[100010] = {};
ll resL[100010] = {};

int main(void){

    ll k,sum = 0,result = 0;
    cin >> k;

    priority_queue<ll, vector<ll>, greater<ll> > que;

    for(int i = 0; i < 3*k; i++){
        cin >> arr[i];
    }

    //init

    for(int i = 0; i < k; i++){
        sum += arr[i];
        que.push(arr[i]);
    }

    resL[0] = sum;

    for(int i = 0; i < k; i++){

        que.push(arr[i+k]);
        ll a = que.top();
        que.pop();

        sum += arr[i+k]-a;

        resL[i+1] = sum;
    }

    /// left

    priority_queue<ll> que1;
    sum = 0;

    for(int i = 1; i <= k; i++){
        sum += arr[3*k-i];
        que1.push(arr[3*k-i]);
    }

    resR[k] = sum;

    for(int i = 1; i <= k; i++){

        que1.push(arr[2*k-i]);
        ll a = que1.top();
        que1.pop();

        sum += arr[2*k-i]-a;

        resR[k-i] = sum;
    }

    /// right

    result = resL[0] - resR[0];

    for(int i = 0; i <= k; i++){
        //cout << resL[i] << " " << resR[i] << endl;
        result = max(resL[i] - resR[i],result);
    }
    cout << result << endl;
}

#include <stdio.h>
#include <set>
#include <vector>
#include <algorithm>

long long calc(const int & N, const std::vector<int> & a)
{
        std::set<int> heads;
        long long sumH = 0;
        for (int i = 0; i < N; i++) {
                heads.insert(a[i]);
                sumH += a[i];
        }
        std::vector<int> backs(a.begin()+N, a.end());
        std::sort(backs.begin(), backs.end());
        std::set<int> uppers, lowers;
        long long sumL = 0;
        for (int i = 0; i < N; i++) {
                lowers.insert(backs[i]);
                uppers.insert(backs[N+i]);
                sumL += backs[i];
        }
        long long best = sumH - sumL;
        for (int i = 0; i < N; i++) {
                int toBeMoved = a[N+i];
                auto it = uppers.find(toBeMoved);
                if (it != uppers.end()) {
                        uppers.erase(it);
                }
                else {
                        lowers.erase(toBeMoved);
                        sumL -= toBeMoved;
                        auto jt = uppers.begin();
                        lowers.insert(*jt);
                        sumL += *jt;
                        uppers.erase(jt);
                }
                sumH += toBeMoved;
                heads.insert(toBeMoved);
                auto kt = heads.begin();
                sumH -= *kt;
                heads.erase(kt);
                long long d = sumH - sumL;
                if (d > best)
                        best = d;
        }
        return best;
}

int main(int argc, char * argv[])
{
        int N;
        scanf("%d", &N);
        std::vector<int> a;
        for (int i = 0; i < N*3; i++) {
                int v;
                scanf("%d", &v);
                a.push_back(v);
        }
        long long r = calc(N, a);
        printf("%lld\n", r);
        return 0;
}

