int main() {
	std::cin >> N;
	std::priority_queue<LL, std::vector<LL>, std::greater<LL>> F;
	for (int i = 0; i < N; i++) {
		LL tmp;
		std::cin >> tmp;
		F.push(tmp);
		sumf[0] += tmp;
	}
	for (int i = 1; i <= N; i++) {
		std::cin >> m[i];
	}

	std::priority_queue<LL> B;
	for (int i = 0; i < N; i++) {
		LL tmp;
		std::cin >> tmp;
		B.push(tmp);
		sumb[0] += tmp;
	}
	for (int i = 1; i <= N; i++) {
		sumf[i] = sumf[i - 1];
		LL l = F.top();
		if (l < m[i]) {
