        for(int i=3*N-1;i>=2*N;i--) q.push(a[i]);

        dp2[2*N] = s;
        for(int i=2*N-1;i>=N;i--){
            ll nxt = a[i];
            ll mx = q.top();
            if(mx > nxt) s = s + nxt - mx;
            dp2[i] = s;
            q.push(nxt);
            q.pop();
        }
    }


    ll ans = numeric_limits<long long>::min();
    for(int i=N-1;i<2*N;i++){
        ans = max(ans,dp1[i]-dp2[i+1]);
    }
    cout << ans << endl;
}

