int main()
{
    int N;
    if (scanf("%d", &N) < 1) return 0;

    array<int, 300000> ary;

    int sum = 0;

    for (int i = 0; i < 3 * N; i++)
    {
        int tmp = 0;
        gc(tmp);
        ary[i] = tmp;
