    // for push
    int now;

    // for top
    int cur;

    priority_queue<int, vector<int>, greater<int> > qg;
    for (int i = 0; i < N; i++)
    {
        now = ary[i];
        qg.push(now);
        sum += now;
    }

    array<int, 100001> aryMax;

    aryMax[0] = sum;

    for (int i = N; i < 2 * N; i++)
    {
        now = ary[i];

        qg.push(now);

        sum += now;

        cur = qg.top();

        sum -= cur;
        qg.pop();

        aryMax[i - N + 1] = sum;
    }

    sum = 0;

    // クリア
    qg = priority_queue<int, vector<int>, greater<int> >();

    priority_queue<int, vector<int>, less<int> > ql;
    for (int i = 3 * N - 1; 2 * N <= i; i--)
