    for (int i = 2 * N - 1; N <= i; i--)
    {
        now = ary[i];

        ql.push(now);

        sum += now;

        cur = ql.top();

        sum -= cur;
        ql.pop();

        aryMin[i - N] = sum;
    }

    int ans = -1000000000;
    for (int i = 0; i <= N; i++)
    {
        ans = max(ans, aryMax[i] - aryMin[i]);
    }

    // クリア
    ql = priority_queue<int, vector<int>, less<int> >();

    printf("%d\n", ans);
    return 0;
}

