int main()
{
    int N;
    if (scanf("%d", &N) < 1) return 0;

    array<int, 300000> ary;

    int64_t sum = 0;

    for (int i = 0; i < 3 * N; i++)
    {
        int tmp = 0;
        gc(tmp);
        ary[i] = tmp;
    }

    // for push
    int now;

    // for top
    int cur;

    priority_queue<int, vector<int>, greater<int> > qg;
    for (int i = 0; i < N; i++)
    {
        now = ary[i];
        qg.push(now);
        sum += now;
    }

    array<int64_t, 100001> aryMax;

    aryMax[0] = sum;

    for (int i = N; i < 2 * N; i++)
    {
        now = ary[i];

        qg.push(now);

        sum += now;

        cur = qg.top();

        sum -= cur;
        qg.pop();

        aryMax[i - N + 1] = sum;
    }

    sum = 0;

    // クリア
    qg = priority_queue<int, vector<int>, greater<int> >();

    priority_queue<int, vector<int>, less<int> > ql;
    for (int i = 3 * N - 1; 2 * N <= i; i--)
    {
        now = ary[i];
        ql.push(now);
        sum += now;
    }

    array<int64_t, 100001> aryMin;

    aryMin.fill(0);

    aryMin[N] = sum;

    for (int i = 2 * N - 1; N <= i; i--)
    {
        now = ary[i];

        ql.push(now);

        sum += now;

        cur = ql.top();

        sum -= cur;
        ql.pop();

        aryMin[i - N] = sum;
    }

    int64_t ans = aryMin[N] - aryMax[0];
    for (int i = 0; i <= N; i++)
    {
        ans = max(ans, aryMax[i] - aryMin[i]);
    }

    // クリア
    ql = priority_queue<int, vector<int>, less<int> >();

    printf("%" PRId64 "\n", ans);
    return 0;
}

