    int sumA = 0, sumB = 0, sumC = 0;
    FOR(n) {
        a.insert({v[i], i});
        sumA += v[i];
    }

    FOR(i, n, 3 * n) {
        b.insert({v[i], i});
        sumB += v[i];
    }

    FOR(n) {
        auto it = *b.begin();
        sumB -= it[0];
        b.erase(it);
        sumC += it[0];
        c.insert(it);
    }

    int ans = sumA - sumC;

    FOR(i, n, 2 * n) {
        int f = (*a.begin())[0];
        if (v[i] > f) {
            a.erase(a.begin());
            a.insert({v[i], i});
            sumA -= f;
            sumA += v[i];
        }

        ar<int, 2> cu = {v[i], i};

        if (b.count(cu)) {
            b.erase(cu);
        }

        if (c.count(cu)) {
            sumC -= v[i];
            c.erase(cu);
            auto fr = *b.begin();
            c.insert(fr);
            sumC += fr[0];
            b.erase(fr);
        }

        umax(ans, sumA - sumC);

    }

    print(ans);


}

