#include <bits/stdc++.h>
using namespace std;

int main() {
  int64_t N;
  cin >> N;
  vector<int64_t> a(3 * N);
  for (auto& x : a) cin >> x;
  vector<int64_t> sum_red(3 * N);
  {
    priority_queue<int64_t, vector<int64_t>, greater<int64_t>> red;
    int64_t sum = 0;
    for (int i = 0; i < N; ++i) {
      red.push(a[i]);
      sum += a[i];
    }
    for (int64_t k = N; k <= 2 * N; ++k) {
      sum_red[k] = sum;
      red.push(a[k]);
      sum += a[k];
      sum -= red.top();   // Removes min.
      red.pop();          // Removes min.
    }
  }
  vector<int64_t> sum_blue(3 * N);
  {
    priority_queue<int64_t, vector<int64_t>, less<int64_t>> blue;
    int64_t sum = 0;
    for (int i = 3 * N - 1; i >= 2 * N; --i) {
      blue.push(a[i]);
      sum += a[i];
    }
    for (int64_t k = 2 * N; k >= N; --k) {
      sum_blue[k] = sum;
      blue.push(a[k - 1]);
      sum += a[k - 1];
      sum -= blue.top();  // Removes max.
      blue.pop();         // Removes max.
    }
  }
  int64_t best = numeric_limits<int64_t>::min();
  for (int64_t k = N; k <= 2 * N; ++k) {
    // printf("%ld %ld\n", sum_red[k], sum_blue[k]);
    best = max(best, sum_red[k] - sum_blue[k]);
  }
  cout << best << endl;
}

