int main(){

	// input
	int N;
	cin >> N;

	int N3 = N * 3;
	vector<long long> v(N3);
	vector<long long *> vp(N3);
	vector<long long> sum(N3 + 1);

	sum[0] = 0;
	for (int i = 0; i< N3; ++i){
		cin >> v[i];
		vp[i] = &v[i];
		sum[i+1] = sum[i] + v[i];
	}

	sort(vp.begin(), vp.end(),[](long long* x, long long* y) -> int {return ( *x < *y );});

	long long int max_score = -1 * sum[3N];
	for (int n = 1; n <= N; ++n){
		long long int S_b = sum[N+n];
		int count = n;
		int j = 0;
		while (count > 0){
			if((long long int)(vp[j] - &v[0]) < N + n){
				S_b -= *vp[j];
				count--;
			}
			++j;
		}

		long long int S_a = sum[N3] - sum[N+n];
		count = N - n;
		j = N3 - 1;
		while (count > 0){
			if((long long int)(vp[j] - &v[0]) >= N + n){
				S_a -= *vp[j];
				count--;
			}
			--j;
		}

		long long score = S_b - S_a;
		if(max_score < score){
			max_score = score;
		}
	}

	cout << max_score << endl;
	return 0;
}

