  srep(i,N,2*N) {
    fir.push(A[i]);
    f += A[i];
    f -= fir.top();
    fir.pop();
    ma[i-N+1] = f;
  }
  priority_queue<int> sec;
  ll s = 0;
  rep(i,N) {
    sec.push(A[i+2*N]);
    s += A[i+2*N];
  }
  vl mi(N+1,0);
  mi[N] = s;
  for(int i = 2*N-1;i >= N;i--) {
    sec.push(A[i]);
    s += A[i];
    s -= sec.top();
    sec.pop();
    mi[i-N] = s;
  }
  ll ans = -LINF;
  rep(i,N+1) {
    ans = max(ans,ma[i]-mi[i]);
  }
  cout << ans << endl;
  return 0;
}

