ll cheak(bool d[300001]){
	ll l=0;
	ll r=0;
	int s=0;
	for(int i=0;i<3*n;++i){
		if(!d[i]){
			if(s<n)l+=a[i];
			else r+=a[i];
			s++;
		}
	}
	return l-r;
}
ll reg(int n1,bool d[300001]){
	if(n1==n)return cheak(d);
	ll res=0;
	for(int i=0;i<n;++i){
		if(!d[i]){
			d[i]=true;
			res=max(res,reg(n1+1,d));
			d[i]=false;
		}
	}
	return res;
}
