int main(){
	long N;
	cin >> N;
	long a[300000];

	REP(i,3*N) cin >> a[i];
	pq <long,vi,greater<long> > left;
	pq <long,vi,greater<long> > right;

	long long kl[300000];//左のkまでの最大値を記録
	long long kr[300000];	

	long long tl = 0;
	long long tr = 0;


	/* k */
	// k = N ... 2N
	//  left ... i = 0~k-1までの最大値
	// right ... i = k~3N-1 までの最小値


	//初期解
	REP(i,N) {
		left.push(a[i]);
		tl+=a[i];
	}
