int main() {
	scanf("%lld", &n);
	for(LL i = 1; i <= 3 * n; i++) scanf("%lld", &num[i]);
	priority_queue<LL, vector<LL>, greater<LL> > q1;
	priority_queue<LL> q2;
	for(LL i = 1; i <= n; i++) {
		sum1 += num[i];
		q1.push(num[i]);
	}
	sum_max[n] = sum1;
	for(LL i = n + 1; i <= 2 * n; i++){
		if(num[i] > q1.top()){
			sum1 -= q1.top();
			q1.pop();
			q1.push(num[i]);
			sum1 += num[i];
		}
		sum_max[i] = sum1;
	}
	for(LL i = 3 * n; i >= 2 * n + 1; i--){
		sum2 += num[i];
		q2.push(num[i]);
	}
	sum_min[2 * n + 1] = sum2;
	for(LL i = 2 * n; i > n; i--){
		if(num[i] < q2.top()) {
			sum2 -= q2.top();
			q2.pop();
			q2.push(num[i]);
			sum2 += num[i];
		}
		sum_min[i] = sum2;
	}
	sum = -(1LL << 60);
	for(LL i = n ; i <= 2 * n; i++)
		sum = max(sum, sum_max[i] - sum_min[i + 1]);
	printf("%lld\n", sum);
