const int N = (int) 3e5 + 5;
const long long INF = (long long) 1e18;

int n;
int a[N];
long long dpLeft[N], dpRight[N];

void solveLeft() {
	multiset <int> myset;
	multiset <int> :: iterator it;
	long long res = 0;
	for (int i = 1; i <= n; i++) {
		myset.insert(a[i]);
		res += a[i];
	}	
	dpLeft[n] = res;
	for (int i = n + 1; i <= 2 * n; i++) {
		it = myset.begin();
		if (*it >= a[i]) {
			dpLeft[i] = res;
			continue;
		} else {
			res = res - *it + a[i];
			myset.erase(it);
			myset.insert(a[i]);
			dpLeft[i] = res;
		}
	}
}

void solveRight() {
	multiset <int> myset;
	multiset <int> :: iterator it;
	long long res = 0;
	for (int i = 3 * n; i > 2 * n; i--) {
		myset.insert(a[i]);
		res += a[i];
	}	
	dpRight[2 * n + 1] = res;
	for (int i = 2 * n; i > n; i--) {
		it = myset.end();
		it--;
		if (*it <= a[i]) {
			dpRight[i] = res;
			continue;
		} else {
			res = res - *it + a[i];
			myset.erase(it);
			myset.insert(a[i]);
			dpRight[i] = res;
		}
	}
}

