    sum_min[0] = 0;
    for(int i=N*2; i<N*3; i++) sum_min[0] += a[i];
    // cout << "sum_min : " << sum_min[0] << ',';
    for(int i=1; i<=N; i++) {
        int max_a = q_min.top();
        if(a[N*2-i] < max_a) {
            q_min.pop();
            q_min.push(a[N*2-i]);
            sum_min[i] = sum_min[i-1] - max_a + a[N*2-i];
        } else {
            sum_min[i] = sum_min[i-1];
        }
        // cout << sum_min[i] << ',';
    }
    // cout << endl;
    int ans = sum_max[0] - sum_min[N];
    for(int i=1; i<=N; i++) {
        if(ans < sum_max[i] - sum_min[N-i]) ans = sum_max[i] - sum_min[N-i];
    }
    cout << ans << endl;
    return 0;
}

