//{2, 5,2,3,4, 1,  0}にする
void press(vector<long long> &v) {
	long long n = v.size();
	vector<long long> w(n);
	map<long long, long long> m;
	for(auto &p : v) {
		m[p] = 0;
	}
	long long i = 0;
	for(auto &p : m) {
		p.second = i;
		i++;
	}
	for(long long i = 0; i < n; i++) {
		w.at(i) = m[v.at(i)];
	}
	v = w;
	return;
}

