LL max_score()
{
	LL firstsum = 0, secondsum = 0, ret = 0;	

	int cnt = n;
	if(cnt % 2 == 0){
		while(cnt -= 2 && !one.empty() && !two.empty())
		{
			one.pop();
			two.pop();
		}
		while(one.empty() == false)
			firstsum += -one.top(), one.pop();
		while(two.empty() == false)
			secondsum += two.top(), two.pop();
		ret = firstsum - secondsum;
	}
	else{
		while(cnt > 1)
		{
			one.pop();
			two.pop();
			cnt -= 2;
		}

		if(sz(one) > sz(two))
			one.pop();
		else
			two.pop();

		while(one.empty() == false)
			firstsum += -one.top(), one.pop();
		while(two.empty() == false)
			secondsum += two.top(), two.pop();

		ret = firstsum - secondsum;
	}

	return ret;
}

