void heapIncrease(ll i,ll k)
{
	biggest_queue[i] = k;
	while(i>1&&biggest_queue[i/2]<biggest_queue[i])
	{
		swap(biggest_queue[i],biggest_queue[i/2]);
		i = i/2;
	}
}

void binsert(ll k)
{
	Hb++;
	biggest_queue[Hb] = INT_MIN;
	heapIncrease(Hb,k);
}

void bheapify(ll i)
{
	//cout<<biggest_queue[i]<<endl;
	ll l = i*2,r = i*2+1,biggest;
	if(l <= Hb && biggest_queue[l] > biggest_queue[i]) biggest = l;
	else biggest = i;
	if(r<=Hb&&biggest_queue[r]>biggest_queue[biggest])biggest = r;
	//cout<<' '<<biggest_queue[l]<<biggest_queue[r]<<endl;
	if(i!=biggest)
	{
		//cout<<biggest_queue[biggest]<<';'<<biggest_queue[i]<<endl;
		swap(biggest_queue[i],biggest_queue[biggest]);
		bheapify(biggest);
	}
}

void bextract()
{
	swap(biggest_queue[1],biggest_queue[Hb]);
	biggest_queue[Hb]=INT_MIN;
	Hb--;
	bheapify(1);
}

void heapDecrease(ll i,ll k)
{
	smallest_queue[i] = k;
	while(i>1&&smallest_queue[i/2]>smallest_queue[i])
	{
		swap(smallest_queue[i],smallest_queue[i/2]);
		i = i/2;
	}
}

void ainsert(ll k)
{
	Ha++;
	smallest_queue[Ha] = INT_MAX;
	heapDecrease(Ha,k);
}

void aheapify(ll i)
{
	ll l = i*2,r = i*2+1,smallest;
	if(l<=Ha&&smallest_queue[l]<smallest_queue[i])smallest=l;
	else smallest = i;
	if(r<=Ha&&smallest_queue[r]<smallest_queue[smallest])smallest = r;
	if(i!=smallest)
	{
		swap(smallest_queue[i],smallest_queue[smallest]);
		aheapify(smallest);
	}
}

void aextract()
{
	swap(smallest_queue[1],smallest_queue[Ha]);
	smallest_queue[Ha] = INT_MAX;
	Ha--;
	aheapify(1);
}

