int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n * 3);
    vector<ll> sum(n * 3 + 1);
    sum[0] = 0;
    for(int i = 0; i < n * 3; ++i){
        cin >> a[i];
        sum[i + 1] = sum[i] + a[i];
    }
    ll lsum = sum[n], rsum = sum[n * 3] - sum[n];
    priority_queue<int, vector<int>, greater<int>> left;
    for(int i = 0; i < n; ++i)  left.push(a[i]);
    priority_queue<P> right;
    for(int i = n; i < n * 3; ++i){
        right.push(P(a[i], i));
        used[i] = true;
    }
    priority_queue<P, vector<P>, greater<P>> stock;
    for(int i = 0; i < n; ++i){
        P p = right.top();
        right.pop();
        rsum -= p.first;
        used[p.second] = false;
        stock.push(p);
    }
    ll ans = lsum - rsum;
    for(int i = n; i < n * 2; ++i){
        if(!used[i]){
            used[i] = true;
            if(a[i] > left.top()){
                lsum -= left.top();
                lsum += a[i];
                left.pop();
                left.push(a[i]);
            }
        }
        else{
            bool ok = false;
            P p;
            while(!ok){
                p = stock.top();
                stock.pop();
                if(!used[p.second]) ok = true;
            }
            rsum -= a[i];
            rsum += p.first;
            used[p.second] = true;
            if(a[i] > left.top()){
                lsum -= left.top();
                lsum += a[i];
                left.pop();
                left.push(a[i]);
            }
        }
        chmax(ans, lsum - rsum);
    }
    cout << ans << endl;
}

