template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return true; } return false; }

int main() {
  int N;
  cin >> N;
  vector<int> a(N*3);
  rep(i, N*3) cin >> a[i];
  priority_queue<int, vector<int>, greater<int>> mx;
  ll mxsum = 0;
  rep(i, N) {
    mx.push(a[i]);
    mxsum += a[i];
  }
  vector<ll> l(N+1);
  l[0] = mxsum;
  rep(i, N) {
    if (a[N+i] > mx.top()) {
      mxsum += a[N+i]-mx.top();
      mx.pop();
      mx.push(a[N+i]);
    }
    l[i+1] = mxsum;
  }
  priority_queue<int> mn;
  ll mnsum = 0;
