    mn.push(a[N*2+i]);
    mnsum += a[N*2+i];
  }
  vector<ll> r(N+1);
  r[N] = mnsum;
  for (int i=N-1; i>=0; i--) {
    if (a[N+i] < mn.top()) {
      mnsum += a[N+i]-mn.top();
      mn.pop();
      mn.push(a[N+i]);
    }
    r[i] = mnsum;
  }
