        qR.push(push);
        ll pop = qR.top();
        qR.pop();
        sumR[N-1-i] = sumR[N-i] + push - pop;
    }
    ll ans = -1000000000000000000;
    REP(i,N) chmax(ans, sumL[i] - sumR[i]);
    cout << ans << endl;
