    if(-q_f.top() < a[i + N]){
      s_f[i + 1] += q_f.top();
      s_f[i + 1] += a[i + N];
      q_f.pop();
      q_f.push(-a[i + N]);
    }
  }

  priority_queue<int> q_b;
  for(int i = 0; i < N; i++){
    s_b[0] += a[3 * N - i - 1];
    q_b.push(a[3 * N - i - 1]);
  }

  for(int i = 0; i < N; i++){
