  }
  long l = accumulate(A.begin(), A.begin() + N / 3, 0L);
  long r = accumulate(A.end() - N / 3, A.end(), 0L);
  long ans = l - r;
  vector<long> L, R;
  L.push_back(l);
  R.push_back(r);
  for (int i = N / 3; i < N / 3 * 2; i++) {
    long tmp = LQ.top();
    if (tmp >= A.at(i)) {
      L.push_back(l);
      continue;
    }
    l += A.at(i) - tmp;
    L.push_back(l);
    LQ.pop();
    LQ.push(A.at(i));
  }
  for (int i = N / 3 * 2 - 1; i >= N / 3; i--) {
    long tmp = RQ.top();
    if (tmp <= A.at(i)) {
      R.push_back(r);
      continue;
    }
    r -= tmp - A.at(i);
    R.push_back(r);
    RQ.pop();
    RQ.push(A.at(i));
  }
  reverse(R.begin(), R.end());
  for (int i = 0; i < (long) L.size(); i++) {
    ans = max(ans, L.at(i) - R.at(i));
  }
  cout << ans << "\n";
}

