            r_set.erase(r_set.find(*ite));
        }

        r_min[i] = r_sum;
    }

    long long res = l_max[n - 1] - r_min[n];
    for (int i = n; i < 2 * n; i++) {
        res = max(res, l_max[i] - r_min[i + 1]);
    }

    cout << res << endl;
