void solve(int N, vi a) {
  vi lv(N + 1), rv(N + 1);
  priority_queue<int, vi, greater<int>> lq;
  priority_queue<int> rq;
  rep(i, N) {
    lq.push(a[i]);
    lv[0] += a[i];
    rq.push(a[N * 3 - i - 1]);
    rv[0] += a[N * 3 - i - 1];
  }
  rep(i, N) {
    lq.push(a[N + i]);
    lv[i + 1] = lv[i] - lq.top() + a[N + i];
    lq.pop();
    rq.push(a[N * 2 - i - 1]);
    rv[i + 1] = rv[i] - rq.top() + a[N * 2 - i - 1];
    rq.pop();
  }
  int ans = -INF;
  rep(i, N + 1)amax(ans, lv[i] - rv[N - i]);
  COUT(ans);
}


