using namespace std;
const int BUF = 300005;
const long long INF = 1LL << 60;

class State {
public:
    int index;
    int nChoosePre;
    int nChoosePost;

    State(){}
    State(int index, int nChoosePre, int nChoosePost) :
        index(index), nChoosePre(nChoosePre), nChoosePost(nChoosePost) {}

    bool operator< (const State &opp) const {
        if (index != opp.index) return index < opp.index;
        if (nChoosePre != opp.nChoosePre) return nChoosePre < opp.nChoosePre;
        return nChoosePost < opp.nChoosePost;
    }
};


int N;
int vList[BUF];

void read() {
    cin >> N;
    for (int i = 0; i < N * 3; ++i) {
        cin >> vList[i];
    }
}

long long rec(State &st, map<State, long long> &dp) {
    if (st.nChoosePre == N && st.nChoosePost == N) {
        return dp[st] = 0;
    }

    if (dp.count(st)) {
        return dp[st];
    }

    long long ret = -INF;

    int val = vList[st.index];

    if (st.nChoosePre == N) {
        if (st.nChoosePost + (3 * N - st.index) == N) {
            st.index++;
            st.nChoosePost++;
            ret = max(ret, rec(st, dp) - val);
            st.index--;
            st.nChoosePost--;
        } else {
            st.index++;
            ret = max(ret, rec(st, dp));
            st.index--;

            st.index++;
            st.nChoosePost++;
            ret = max(ret, rec(st, dp) - val);
            st.index--;
            st.nChoosePost--;
        }
    } else {
        if (st.index - st.nChoosePre == N) {
            st.index++;
            st.nChoosePre++;
            ret = max(ret, rec(st, dp) + val);
            st.index--;
            st.nChoosePre--;
        } else {
            st.index++;
            ret = max(ret, rec(st, dp));
            st.index--;

            st.index++;
            st.nChoosePre++;
            ret = max(ret, rec(st, dp) + val);
            st.index--;
            st.nChoosePre--;
        }
    }

    return dp[st] = ret;
}


void work() {
    map<State, long long> dp;
    State init = State(0, 0, 0);
    cout << rec(init, dp) << endl;
}


int main() {
    read();
    work();
    return 0;
}

