					temp.push_back( plus[i] );
			}

			plus = temp;
			++lp;
		}
	}

	long long total = 0;
	for( int i = 0; i < plus.size(); ++i ) total -= minus[i];
	for( int i = 0; i < minus.size(); ++i ) total += plus[i];
	cout << total << endl;
	return 0;	

}

