            rsum[i - 1] = rsum[i];
        }
    }

    ll ans = -LINF;
    for (int i = n; i <= 2 * n; ++i)
    {
        ans = max(ans, lsum[i] - rsum[i]);
    }
    cout << ans << endl;
}

