    int n;
    cin>>n;
    int arr[3*n];
    for0(i,3*n) cin>>arr[i];
    priority_queue<int, vi, greater<int>> pq;
    priority_queue<int> pq1;
    int sum = 0, pre[3*n], suf[3*n];
    for0(i,n) {
        sum += arr[i];
        pq.push(arr[i]);
    }
    pre[n-1] = sum;
    for(int i=n; i<2*n; i++) {
        if(arr[i] > pq.top()) {
            sum -= pq.top();
            pq.pop();
            sum += arr[i];
            pq.push(arr[i]);
        }
        pre[i] = sum;
    }
    sum = 0;
    for(int i=3*n-1; i>=2*n; i--) {
        sum += arr[i];
        pq1.push(arr[i]);
    }
    suf[2*n] = sum;
    for(int i=2*n-1; i>=n; i--) {
        if(arr[i] < pq1.top()) {
            sum -= pq1.top();
            pq1.pop();
            sum += arr[i];
            pq1.push(arr[i]);
        }
        suf[i] = sum;
    }
    int mx = -1*MOD;
    for(int i=n-1; i<2*n; i++) {
