int main(){
	long long N;
	cin >> N;
	long long a[300001];

	REP(i,3*N) cin >> a[i];
	pq <long long ,vl,greater<long long> > left;
	pq <long long ,vl,greater<long long> > right;

	long long kl[300001];//左のkまでの最大値を記録
	long long kr[300001];	

	long long tl = 0;
	long long tr = 0;


	/* k */
	// k = N ... 2N
	//  left ... i = 0~k-1までの最大値
	// right ... i = k~3N-1 までの最小値

