    priority_queue<int> greater_pq;
    priority_queue<int, vector<int>, greater<int>> less_pq;
    vector<ll> fdp(n + 1), ldp(n + 1);
    ll fsum = 0, lsum = 0;

    rep(i, n) fsum += a[i];
