int main(){
  int N=0;
  cin>>N;
  int head=0;
  int tail=N-1;
  long sumLeft=0;
  long sumRight=0;
  long res=0;

  for(int i=0;i<N;i++){
    int tmp;
    cin>>tmp;
    leftN.push(tmp);
    sumLeft+=tmp;
  }

  for(int i=0;i<N;i++)
    cin>>a[i];

  for(int i=0;i<N;i++){
    int tmp;
    cin>>tmp;
    rightN.push(tmp);
    sumRight+=tmp;
  }

  res=sumLeft-sumRight;

  while(head<=tail){
    int opA=a[head]-leftN.top();
    int opB=rightN.top()-a[tail];
    if(opA>0 && opA>=opB){
      leftN.pop();
      leftN.push(a[head++]);
      res+=opA;
    }else if(opB>0 && opB>opA){
      rightN.pop();
      rightN.push(a[tail--]);
      res+=opB;
    }else{
      if(opA<=0)
	head++;
      if(opB<=0)
	tail++;
    }
  }

  cout<<res<<endl;

  return 0;
}

