int main() {
    int N;
    cin>>N;
    priority_queue<long, vector<long>, greater<long> > que1;
    priority_queue<long> que2;
    long middle[N];
    long tmp;
    for(int i=0;i<3*N;++i){
        cin>>tmp;
        if(i<N){
            que1.push(tmp);
        }
        else if(i<2*N){
            middle[i-N] = tmp;
        }
        else{
            que2.push(tmp);
        }
    }
    int l = 0, r = N-1;
    while(l<=r){
        if(middle[l] - que1.top() >= que2.top() - middle[r]){
            if(middle[l] < que1.top()){
                l++;
                continue;
            }
            que1.pop();
            que1.push(middle[l]);
            l++;
        }
        else{
            if(que2.top() < middle[r]){
                r--;
                continue;
            }
            que2.pop();
            que2.push(middle[r]);
            r--;
        }
    }
    long ans1 = 0, ans2 = 0;
    while(!que1.empty()){
        ans1 += que1.top();
        que1.pop();
    }
    while(!que2.empty()){
        ans2 += que2.top();
        que2.pop();
    }
    cout<<ans1-ans2<<endl;
}

