int main() {
  int n; cin >> n;
  vector<llong> a;

  REP(i, 3*n) {
    llong j; cin >> j;
    a.push_back(j);
  }

  llong best_score = -123456789;
  REP(i, n+1) {
    // [0, n+i)までが左側
    // [n+i, 3n)までが右側
    priority_queue<llong, vector<llong>, greater<llong>> left;
    priority_queue<llong> right;
    FOR(j, 0, n+i) left.push(a.at(j));
    FOR(j, n+i, 3*n) right.push(a.at(j));

    REP(j, i) left.pop();
    REP(j, n-i) right.pop();

    llong left_score = 0, right_score = 0;
    while(true) {
      left_score += left.top();
      left.pop();
      if(left.empty()) break;
    }
    while(true) {
      right_score += right.top();
      right.pop();
      if(right.empty()) break;
    }
    llong score = left_score - right_score;
    if(best_score < score) best_score = score;
  }

  cout << best_score << endl;
  return 0;
}

