typedef long long ll;


int main() {
    int N; cin >> N;
    vector<ll> a(3*N);
    REP(i,3*N) cin >> a[i];

    priority_queue<ll, vector<ll>, greater<ll>> L;
    priority_queue<ll> R;
    vector<ll> l_sum(N+1,0);
    vector<ll> r_sum(N+1,0);

    REP(i,N){
        L.push(a[i]);
        l_sum[0] += a[i];
    }
    REP(i,N){
        if(L.top() < a[N+i]){
            l_sum[i+1] = l_sum[i] + a[N+i] - L.top();
            L.pop();
            L.push(a[N+i]);
        }else{
            l_sum[i+1] = l_sum[i];
        }
    }

    REP(i,N){
        R.push(a[3*N-1-i]);
        r_sum[0] += a[3*N-1-i];
    }
    REP(i,N){
        if(R.top() > a[2*N-1-i]){
            r_sum[i+1] = r_sum[i] + a[2*N-1-i] - R.top();
            R.pop();
            R.push(a[2*N-1-i]);
        }else{
            r_sum[i+1] = r_sum[i];
