struct IO {
#ifdef _WIN32
  inline char getchar_unlocked() { return getchar(); }
  inline void putchar_unlocked(char c) { putchar(c); }
#endif
  string separator = " ";
  template <class T>
  inline void read(T& x) {
    char c;
    do {
      c = getchar_unlocked();
    } while (c != '-' && (c < '0' || '9' < c));
    bool minus = 0;
    if (c == '-') {
      minus = 1;
      c = getchar_unlocked();
    }
    x = 0;
    while ('0' <= c && c <= '9') {
      x *= 10;
      x += c - '0';
      c = getchar_unlocked();
    }
    if (minus) x = -x;
  }
  inline void read(string& x) {
    char c;
    do {
      c = getchar_unlocked();
    } while (c == ' ' || c == '\n');
    x.clear();
    do {
      x += c;
      c = getchar_unlocked();
    } while (c != ' ' && c != '\n' && c != EOF);
  }
  template <class T>
  inline void read(vector<T>& v) {
    for (auto& x : v) read(x);
  }
  template <class Head, class... Tail>
  inline void read(Head& head, Tail&... tail) {
    read(head);
    read(tail...);
  }
  template <class T>
  inline void write(T x) {
    char buf[32];
    int p = 0;
    if (x < 0) {
      x = -x;
      putchar_unlocked('-');
    }
    if (x == 0) putchar_unlocked('0');
    while (x > 0) {
      buf[p++] = (x % 10) + '0';
      x /= 10;
    }
    while (p) {
      putchar_unlocked(buf[--p]);
    }
  }
  inline void write(string x) {
    for (char c : x) putchar_unlocked(c);
  }
  inline void write(const char s[]) {
    for (int i = 0; s[i] != 0; ++i) putchar_unlocked(s[i]);
  }
  template <class T>
  inline void write(vector<T> v) {
    for (auto itr = v.begin(); itr + 1 != v.end(); ++itr) {
      write(*itr);
      write(separator);
    }
    write(v.back());
  }
  template <class Head, class... Tail>
  inline void write(Head head, Tail... tail) {
    write(head);
    write(separator);
    write(tail...);
  }
  template <class Head, class... Tail>
  inline void writeln(Head head, Tail... tail) {
    write(head, tail...);
    write("\n");
  }
  void set_separator(string s) { separator = s; }
} io;

int main() {
  int N;
  io.read(N);
  vector<ll> a(3 * N);
  io.read(a);
  set<ll> mn, mx;
  vector<ll> mns(3 * N), mxs(3 * N);
  REP(i, N) mn.insert(a[i]);
  ll acc = accumulate(a.begin(), a.begin() + N, 0LL);
  FOR(i, N - 1, 2 * N) {
    mns[i] = acc;
    mn.insert(a[i + 1]);
    acc += a[i + 1] - *mn.begin();
    mn.erase(mn.begin());
  }
  for (int i = 3 * N - 1; i >= 2 * N; --i) mx.insert(-a[i]);
  acc = accumulate(a.begin() + 2 * N, a.begin() + 3 * N, 0LL);
  for (int i = 2 * N; i >= N; --i) {
    mxs[i] = acc;
    mx.insert(-a[i - 1]);
    acc += a[i - 1] + *mx.begin();
    mx.erase(mx.begin());
  }
  ll ans = -LLINF;
  FOR(i, N - 1, 2 * N) { ans = max(ans, mns[i] - mxs[i + 1]); }
  io.writeln(ans);
  return 0;
}

