void preCompute() {
    priority_queue<ll> pQ;
    ll sum = 0;
    for (int i = (3 * n) - 1 ; i >= 0 ; i--) {
        pQ.push(v[i]);
        sum += v[i];
        if ((int)pQ.size() > n) {
            sum -= pQ.top();
            pQ.pop();
        }
        minim[i] = sum;
    }
    while (!pQ.empty()) pQ.pop();
    sum = 0;
    for (int i = 0 ; i < 3 * n ; i++) {
        pQ.push(-v[i]);
        sum += v[i];
        if ((int)pQ.size() > n) {
            sum += pQ.top();
            pQ.pop();
        }
        maxim[i] = sum;
    }
}

