			smaller_hidden.erase(smaller_hidden.begin());
		}
		//smallerにA[i]が入ってないなら
		else{
			smaller_hidden.erase(smaller_hidden.find(A[i]));
		}

		ans = max(ans,bigger_accum-smaller_accum);
	}
}

