typedef long long LL;
int main(int argc, char* argv[])
{
	int N;
	cin>>N;
	vector<LL> data(3*N,0);
	LL i;
	for (i=0;i<3*N;i++){
		cin>>data[i];
	}
	priority_queue<LL,vector<LL>,greater<LL>> before;
	priority_queue<LL,vector<LL>,less<LL>> after;
	vector<LL> sum1(N+1,0),sum2(N+1,0);
	int k=0;
	LL maxV=-10e10;
	LL Sum=0;
	int j=0;
	for (i=0;i<2*N;i++){
		before.push(data[i]);
		Sum+=data[i];
		if (i>=N-1){
			if (j>0){
				Sum-=before.top();
				before.pop();
			}
			sum1[j]=Sum;
			j++;
		}
	}
	Sum=0;
	j=0;
	for (i=3*N-1;i>=N;i--){
		after.push(data[i]);
		Sum+=data[i];
		if (i<=2*N){
			if (j>0){
				Sum-=after.top();
				after.pop();
			}
			sum2[j]=Sum;
			j++;
		}
	}
	for (i=0;i<N;i++){
		LL v=sum1[i]-sum2[N-i];
		if (maxV<v){
			maxV=v;
		}
	}

	cout<<maxV<<endl;
	return 0;
}

