using namespace std;

int main() {
    int n;
    cin >> n;

    vector<long long> a(3 * n);
    for (int i = 0; i < 3 * n; i++) {
        cin >> a[i];
    }

    vector<long long> l_max(3 * n, 0);
    multiset<long long> l_set;
    long long l_sum = 0;
    for (int i = 0; i < n; i++) {
        l_sum += a[i];
        l_set.insert(a[i]);
        l_max[i] = l_sum;
    }
    for (int i = n; i <= 2 * n; i++) {
        multiset<long long>::iterator ite = l_set.begin();
        if (a[i] > *ite) {
            l_sum += a[i] - *ite;
            l_set.insert(a[i]);
            l_set.erase(*ite);
        }

        l_max[i] = l_sum;
    }

    vector<long long> r_min(3 * n, 0);
    multiset<long long> r_set;
    long long r_sum = 0;
    for (int i = 3 * n - 1; i >= 2 * n; i--) {
        r_sum += a[i];
        r_set.insert(a[i]);
        r_min[i] = r_sum;
    }
    for (int i = 2 * n; i >= n - 1; i--) {
        multiset<long long>::reverse_iterator ite = r_set.rbegin();
        if (a[i] < *ite) {
            r_sum += a[i] - *ite;
            r_set.insert(a[i]);
            r_set.erase(*ite);
        }

        r_min[i] = r_sum;
    }

    long long res = l_max[n - 1] - r_min[n];
    for (int i = n; i < 2 * n; i++) {
        res = max(res, l_max[i] - r_min[i + 1]);
    }

    cout << res << endl;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
	int N;
	cin >> N;
	vector<ll> A(N), B(N), C(N);
	priority_queue<ll, vector<ll>, greater<ll>> qa;
	priority_queue<ll> qc;

	for(auto &a : A) {
		cin >> a;
		qa.push(a);
	}
	for(auto &b : B) cin >> b;
	for(auto &c : C) {
		cin >> c;
		qc.push(c);
	}

	sort(A.begin(), A.end());
	sort(C.begin(), C.end());

	vector<ll> suml(N+1), sumr(N+1);
	suml[0] = accumulate(A.begin(), A.end(), 0LL);
	sumr[0] = accumulate(C.begin(), C.end(), 0LL);

	for(int i=0;i<N;i++) {
		// 和を大きく
		ll amin = qa.top();
		if (amin < B[i]) {
			suml[i+1] = suml[i] - amin + B[i];
			qa.pop();
			qa.push(B[i]);
		} else {
			suml[i+1] = suml[i];
		}
		// 和を小さく
		ll cmax = qc.top();
		if (cmax > B[N-1-i]) {
			sumr[i+1] = sumr[i] - cmax + B[N-1-i];
			qc.pop();
			qc.push(B[N-1-i]);
		} else {
			sumr[i+1] = sumr[i];
		}
	}

  	ll ans = LLONG_MIN;
	for(int i=0;i<=N;i++) {
		ans = max(ans, suml[i] - sumr[N-i]);
	}
	cout << ans << endl;
}

