    for(int i = 0; i < k; i++){
        sum += arr[i];
        que.push(arr[i]);
    }

    resL[0] = sum;

    for(int i = 0; i < k; i++){

        sum1 += arr[3*k-(i+1)];
        que1.push(arr[3*k-(i+1)]);

        que.push(arr[i+k]);
