using namespace std;
typedef long long LL;
int main(int argc, char* argv[])
{
	int N;
	cin>>N;
	vector<LL> data(3*N,0);
	LL i;
	for (i=0;i<3*N;i++){
		cin>>data[i];
	}
	priority_queue<LL,vector<LL>,greater<LL>> before;
	priority_queue<LL,vector<LL>,less<LL>> after;
	int k=0;
	LL maxV=-10e10;
	for (k=0;k<=N;k++){
		for (i=0;i<N+k;i++){
			before.push(data[i]);
		}
		for (;i<3*N;i++){
			after.push(data[i]);
		}
		for (int j=0;j<k;j++){
			before.pop();
		}
		for (int j=0;j<N-k;j++){
			after.pop();
		}
		LL vB=0;
		while (!before.empty()){
			vB+=before.top();
			before.pop();
		}
		LL vA=0;
		while (!after.empty()){
			vA+=after.top();
			after.pop();
		}
		LL v=vB-vA;
		if (maxV<v){
			maxV=v;
		}
	}
	cout<<maxV<<endl;
	return 0;
}

