	S[0] += sumL;

	for(int i=0;i<N;i++){
		int ad = N+i;
		pqL.emplace( A[ad] );
		sumL += A[N+i];
		auto p = pqL.begin();
		sumL -= *p;
		pqL.erase(p);
		S[i+1] += sumL;
	}


	// 右側(数列末尾側) : Que に追加する度に Que内の最大値をpop する
	S[N] -= sum_R;
	for(int i=0; i<N; i++){
		int ad = N+N-i-1;
		pq_R.emplace(A[ad] );
		sum_R += A[ad];
		auto p=pq_R.begin();
		sum_R -= *p;
		pq_R.erase(p);
		S[N-i-1] -= sum_R;
	}

	stable_sort(S.begin(),S.end() ,greater<int>());
	printf("%d\n",S[0]);

	return 0;
}

