    constexpr ll inf = 100000000000000;

    void solve()
    {
        using namespace std;

        int n;
        cin >> n;

        vec<int> A(n * 3);
            for (auto & x : A)
                cin >> x;

        priority_queue<int, vec<int>, greater<int>> q1;
        // v1[i] 左からN + i番目まででN個使ったときの最大値
        vec<ll> v1(n + 1);
        for (int i = 0; i < n; ++i)
            q1.push(A[i]);
        v1[0] = accumulate(A.cbegin(), A.cbegin() + n, 0ll);

        for (int i = 1; i <= n; ++i)
        {
            auto in = A[n - 1 + i];
            q1.push(in);
            auto out = q1.top(); q1.pop();
            v1[i] = v1[i - 1] + in - out;
        }

        priority_queue<int, vec<int>, less<int>> q2;
        // v2[i] N + 1 + i番目から右まででN個使ったときの最小値
        vec<ll> v2(n + 1);
        for (int i = 0; i < n; ++i)
            q2.push(A[2 * n + i]);
        v2[n] = accumulate(A.cbegin() + 2 * n, A.cend(), 0ll);

        for (int i = n; i > 0; --i)
        {
            auto in = A[n - 1 + i];
            q2.push(in);
            auto out = q2.top(); q2.pop();
            v2[i - 1] = v2[i] + in - out;
        }

        ll ans = -inf;

        for (int i = 0; i <= n; ++i)
        {
            ans = max(ans, v1[i] - v2[i]);
        }

        cout << ans << endl;
    }
