            red_q.push(ai);
            red_sum += ai - red_t;
        } else if (ai < blue_t) {
            blue_q.pop();
            blue_q.push(ai);
            blue_sum += ai - blue_t;
        }
    }

    printf("%ld\n", red_sum - blue_sum);

