signed main() {
    int n;
    cin>>n;
    vi a(3*n);
    cin>>a;
    priority_queue<int,vector<int>,greater<int>> g;
    priority_queue<int> l;
    vector<int> x(3*n,0),y(3*n,0);
    int sum=0;
    REP(i,n) {
        g.push(a[i]);
        sum+=a[i];
    }
    REPF(i,n,2*n+1) {
        x[i]=sum;
        if(g.top()<a[i]) {
            sum-=g.top();
            sum+=a[i];
            g.pop();
            g.push(a[i]);
        }
    }

    sum=0;
    REP(i,n) {
        l.push(a[3*n-i-1]);
        sum+=a[3*n-i-1];
    }
    y[2*n]=sum;
    REPF(i,n,2*n+1) {
        if(l.top()>a[3*n-i-1]) {
            sum-=l.top();
            sum+=a[3*n-i-1];
            l.pop();
            l.push(a[3*n-i-1]);
        }
        y[3*n-i-1]=sum;
    }

    int ans=-2*INF;
    REPF(i,n,2*n+1) {
        chmax(ans,x[i]-y[i]);
    }
    cout<<ans<<endl;
    return 0;
}

