int main()
{
	cin >> N;
	for( int i = 0; i < N * 3; i++ ) {
		cin >> a[i];
	}

	for( int i = 0; i < N; i++ ) {
		queL.push( a[i] );
		sumL[0] += a[i];
	}
	for( int i = 0; i < N; i++ ) {
		int n = N + i;
		queL.push( a[n] );
		long long s = queL.top();
		queL.pop();
		sumL[i + 1] = sumL[i] + a[n] - s;
	}
	for( int i = 0; i < N; i++ ) {
		int n = N * 2 + i;
		queR.push( a[n] );
		sumR[0] += a[n];
	}
	for( int i = 0; i < N; i++ ) {
		int n = N * 2 - i - 1;
		queR.push( a[n] );
		long long s = queR.top();
