	}
	for (int i = 0; i < N; i++) {
		int x;
		cin >> x;
		neg.push(-x);
		neg_sum[N] -= x;
	}

	for (int i = 1; i <= N; i++) {
		long x = pos.top(); pos.pop();
		pos.push(mid[i-1]);
		pos_sum[i] = pos_sum[i-1] + mid[i-1] - x;
