/*
 例えば数列が [3 1 4 1 5 9 2 6 5] のとき、
 求めるものは
   [3 1 4] [1 5 9 2 6 5]
   [3 1 4 1] [5 9 2 6 5]
   [3 1 4 1 5] [9 2 6 5]
   [3 1 4 1 5 9] [2 6 5]
 の、(左の集合から大きい順に 3 つとったものの総和) - (右の集合から小さい順に 3 つとったものの総和) の最大値。

 まず、それぞれの (左の集合から大きい順に 3 つとったものの総和) を求める。
 「大きい順に 3 つ」の要素が格納されているような優先度つきキューを考えると順々に求められる。

 最初は 3 つしかないので明らかに、
 [3 1 4]
  キュー: {1, 3, 4}
  キューの総和: 8

 以下順番に、
 [3 1 4 1]
  キューに新たな要素 1 を挿入: {1, 1, 3, 4}
  キューから最小値 1 を削除: {1, 3, 4}
  キューの総和: 8 + 1 - 1 = 8

 [3 1 4 1 5]
  キューに新たな要素 5 を挿入: {1, 3, 4, 5}
  キューから最小値 1 を削除: {3, 4, 5}
  キューの総和: 8 + 5 - 1 = 12

 [3 1 4 1 5 9]
  キューに新たな要素 9 を挿入: {3, 4, 5, 9}
  キューから最小値 3 を削除: {4, 5, 9}
  キューの総和: 12 + 9 - 3 = 18


 右から小さい順に……も同じ要領で求まる。あとは差を取って最大値を探せばよい。


 (キューのデータ構造を適切に選べば) 挿入と削除が O(log N) とかなので全体で O(N log N) のはず。
*/

//↓本体
void f(const std::vector<int> &v){
    const int n = v.size() / 3;

    // 「まず、それぞれの (左の集合から大きい順に N 個とったものの総和) を求める」
    std::vector<int> former_max_n_sum(n + 1); // 「キューの総和」
    std::priority_queue<int, std::vector<int>, std::greater<int>> former_max_n; //「キュー」

    // 「最初は……」
    former_max_n_sum[0] = 0;
    for(int i = 0; i < n; i++){
        former_max_n_sum[0] += v[i];
        former_max_n.push(v[i]);
    }

    // 「以下順番に、……」
    for(int i = n; i < 2 * n; i++){
        former_max_n.push(v[i]); // キューに新たな要素を挿入
        former_max_n_sum[i - n + 1] = former_max_n_sum[i - n] + v[i] - former_max_n.top(); // 総和
        former_max_n.pop(); // キューから最小値を削除
    }


    // 「右から小さい順に……も同じ要領で求まる」
    std::vector<int> latter_min_n_sum(n + 1);
    std::priority_queue<int> latter_min_n;
    latter_min_n_sum[n] = 0;
    for(int i = 2 * n; i < 3 * n; i++){
        latter_min_n_sum[n] += v[i];
        latter_min_n.push(v[i]);
    }
    for(int i = 2 * n - 1; i >= n; i--){
        latter_min_n.push(v[i]);
        latter_min_n_sum[i - n] = latter_min_n_sum[i - n + 1] + v[i] - latter_min_n.top();
        latter_min_n.pop();
    }


    // 「あとは差を取って最大値を探せばよい」
    int diff_max = -INT_MAX, index;
    for(int i = 0; i < n + 1; i++){
        int diff = former_max_n_sum[i] - latter_min_n_sum[i];
        if(diff > diff_max){
            diff_max = diff;
            index = i + n; // 最大値を与える分割の位置
        }
    }

    std::cout << diff_max << std::endl;
}


int main(void){
    int len;
    std::vector<int> v;

    std::cin >> len;
    if(len % 3 != 0){
        std::cerr << "length must be multiple of 3" << std::endl;
        exit(1);
    }

    v.resize(len);
    for(int i = 0; i < len; i++) std::cin >> v[i];

    f(v);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int maxx = 3e5 + 7;
const int Inf = 1 << 30;
const ll INF = 1ll << 60;
int n;
ll a[maxx];
ll suml[maxx], sumr[maxx];
ll s1, s2;
priority_queue <ll, vector<ll>, less<ll> > qua; //降序, 队头大
priority_queue <ll, vector<ll>, greater<ll> > que; //升序, 队头小

int main() {
	scanf("%d", &n);
	for(int i = 1; i <= n * 3; i++) {
		scanf("%lld", &a[i]);
		if(i <= n) {
			s1 += a[i];
			que.push(a[i]);
		}
		else if(i >= 2 * n + 1) {
			s2 += a[i];
			qua.push(a[i]);
		}
	}
	suml[n] = s1; //前n项和
	sumr[n * 2 + 1] = s2; //后n项和
	int l = n + 1, r = 2 * n;
	//只能精确删除n项, 无论怎么删, 后n项都不可能进到前n项去
	//故让中间的n项去往两边置换(相当于在两边删除)
	//中间的n项必然是前x个置换到前n项内, 后n-x个置换到后n项内(或者不发生置换)
	//故分别维护前缀和、后缀和, 前缀和与后缀和的差维护一个最大值
	while(l <= r) {
		if(a[l] > que.top()) { //每次置换出最小的队头
			s1 += a[l];
			s1 -= que.top();
			que.pop();
			que.push(a[l]);
		}
		suml[l] = s1; //维护前缀和
		l++;
	}
	l = n + 1, r = 2 * n;
	while(l <= r) {
		if(a[r] < qua.top()) { //每次置换出最大的队头
			s2 += a[r];
			s2 -= qua.top();
			qua.pop();
			qua.push(a[r]);
		}
		sumr[r] = s2; //维护后缀和
		r--;
	}
	ll ans = -INF;
	for(int i = n; i <= n * 2; i++) ans = max(ans, suml[i] - sumr[i + 1]);
	printf("%lld\n", ans);
}

