			ans = max( ans , Head[i] - Tail[i+1] );
		}
		cout << ans << endl;
		memset( MID , 0 , sizeof(MID) );
		memset( Head , 0 , sizeof(Head) );
		memset( Tail , 0 , sizeof(Tail) );
		while(!T1.empty())	T1.pop();
		while(!T2.empty())	T2.pop();
	}
