int main(int argc, char *argv[]) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    vector<LL> v(3 * N, 0), leftMax(3 * N, 0), rightMin(3 * N, 0);

    cin >> N;
    LL x;
    FOR(i, 0, 3 * N) {
        cin >> x;
        v[i] = x;
    }

    {
        priority_queue<LL, vector<LL>, greater<LL>> left;
        LL total = 0;
        FOR(i, 0, N) {
            left.push(v[i]);
            total += v[i];
        }
        leftMax[N - 1] = total;
        FOR(i, N, v.size()) {
            total += v[i] - left.top();
            leftMax[i] = total;
            left.pop();
            left.push(v[i]);
        }
    }

    priority_queue<LL> right;
    {
        LL total = 0;
        for(int i = v.size() - 1; i >= 2 * N; --i) {
            right.push(v[i]);
            total += v[i];
        }
        rightMin[2 * N] = total;
        for(int i = 2 * N - 1; i >= 0; --i) {
            total += v[i] - right.top();
            rightMin[i] = total;
            right.pop();
            right.push(v[i]);
        }
    }

    LL ans = LLONG_MIN;
    FOR(i, N - 1, 2 * N) {
        ans = max(ans, leftMax[i] - rightMin[i + 1]);
    }
    std::cout << ans << std::endl;

    return 0;
}

