int main(int argc, char* argv[]) {
  ll n;
  cin >> n;
  vec<ll> a(3 * n);
  scan(a);

  priority_queue<ll, vec<ll>, greater<ll>> left;
  priority_queue<ll> right;
  deque<ll> q;

  rep(i, 0, n) {
    left.push(a[i]);
    right.push(a[3 * n - 1 - i]);
    q.push_back(a[n + i]);
  }

  rep(i, 0, n) {
    ll l = left.top(), r = right.top();
    ll next_l = q.front(), next_r = q.back();

    ll diff_l = next_l - l;
    ll diff_r = r - next_r;

    if (diff_l < 0 && diff_r < 0) {
      (diff_l <= diff_r) ? q.pop_front() : q.pop_back();
      continue;
    }

    if (diff_l >= diff_r) {
      left.pop();
      left.push(next_l);
      q.pop_front();
    } else {
      right.pop();
      right.push(next_r);
      q.pop_back();
    }
  }

  ll ans = 0;
  while (!left.empty()) {
    ans += left.top();
    left.pop();
  }
  while (!right.empty()) {
    ans -= right.top();
    right.pop();
  }

  cout << ans << endl;
  return 0;
}

