	FOR(i,0,N){
		ll mi=INF,mii,ma=0,mai;
		FOR(i,0,a.size()/2){
			if(mi>a[i]){
				mi = a[i];
				mii = i;
			}
		}
		ll k=0;
		if(a.size()&1)k++;
		FOR(i,a.size()/2+k,N){
			if(ma<a[i]){
				ma = a[i];
				mai = i;
			}
		}
		ll p = a[a.size()/2];
		ll q = a[a.size()/2-1];
		if(k==1){

			if((p-mi)>(ma-p)){
				a.erase(a.begin()+mai);
			}else{
				a.erase(a.begin()+mii);
			}
		}else{
			if((p-mi)>(ma-q)){
				a.erase(a.begin()+mai);
			}else{
				a.erase(a.begin()+mii);
			}
		}
	}
	ll ans = 0;
	FOR(i,0,a.size()/2){
		ans += a[i];
	}
	FOR(i,a.size()/2,a.size()){
		ans -= a[i];
	}
	cout << ans << endl;
}

