int main() {

    priority_queue<int, vector<int>, greater<int>> que1;
    priority_queue<int> que2;

    int N;
    cin >> N;
    vector<int> a(N*3+1);

    rep(i, N*3) cin >> a[i];

    ll p[N+1], b[N+1];

    ll sum=0;
    int id=0;
    rep(i, N) {
        que1.push(a[i]);
        sum += a[i];
    }
    p[id++] = sum;

    for (int i=N; i<2*N; ++i) {
        sum += a[i];
        que1.push(a[i]);
        int t = que1.top(); que1.pop();
        p[id++] = sum - t;
        sum -= t;
    }

    ll sum2 = 0;
    id=0;
    for (int i=3*N-1; i>=2*N; --i) {
        que2.push(a[i]);
        sum2 += a[i];
    }
    b[id++] = sum2;

    for (int i=2*N-1; i>=N; --i) {
        sum2 += a[i];
        que2.push(a[i]);
        ll t = que2.top(); que2.pop();
        b[id++] = sum2 - t;
        sum2 -= t;
    }

    reverse(b, b+(2*N-(N-1)));

    ll ma = -(1LL << 50);
    rep(i, N+1) {
        ma = max(ma, (ll)p[i] - (ll)b[i]);
    }

    cout << ma << endl;

}

