    reps(i,2*n,3*n){
        mpq.push(a[i]);
        m += a[i];
    }
    R[2*n-1] = m;//2*n-1
    for(int k = 2*n-1; k >= n; k--){
        mpq.push(a[k]);
        m += a[k];
        num = mpq.top();

        m -= num;
        mpq.pop();
        R[k-1] = m;
    }
    Max = L[0]-R[(n)-1];

    for(int i = 1; i < 2*n-1;i++){
        if(Max < L[i]-R[i+(n)-1]){
            Max = L[i]-R[i+(n)-1];
        }
