};
Data aib1[MAXN+1],aib2[MAXN+1];
inline void update1(int poz,int val,int cnt){
    for(int i=poz;i<=MAXN;i+=zeros(i)){
       aib1[i].cnt+=cnt;
       aib1[i].sum+=val;
    }
}
inline void update2(int poz,int val,int cnt){
    for(int i=poz;i>0;i-=zeros(i)){
       aib2[i].cnt+=cnt;
       aib2[i].sum+=val;
    }
}
long long anssum=0;
int anscnt=0;
inline long long query1(int poz){
    anssum=anscnt=0;
    for(int i=poz;i>0;i-=zeros(i)){
      anssum+=aib1[i].sum;
      anscnt+=aib1[i].cnt;
    }
}
inline long long query2(int poz){
    anssum=anscnt=0;
    for(int i=poz;i<=MAXN;i+=zeros(i)){
      anssum+=aib2[i].sum;
      anscnt+=aib2[i].cnt;
    }
}
long long sp1[MAXN+1];
long long sp2[MAXN+1];
int main(){
    FILE*fi,*fout;
    int i,n;
    //fi=fopen("A.in" ,"r");
    //fout=fopen("A.out" ,"w");
    fi=stdin;
    fout=stdout;
    fscanf(fi,"%d" ,&n);
    for(i=1;i<=3*n;i++){
       fscanf(fi,"%d" ,&v[i].val);
       sp1[i]=sp1[i-1]+v[i].val;
       real[i]=v[i].val;
       v[i].poz=i;
    }
    for(i=3*n;i>=1;i--)
       sp2[i]=sp2[i+1]+v[i].val;
    std::sort(v+1,v+3*n+1);
    int val=0;
    for(i=1;i<=3*n;i++){
       if(v[i].val!=v[i-1].val)
          val++;
       vec[v[i].poz]=val;
       mp[val]=v[i].val;
    }
    for(i=1;i<=n;i++)
       update1(vec[i],real[i],1);
    for(i=n+1;i<=3*n;i++)
       update2(vec[i],real[i],1);
    long long ans=-(1LL<<62);
    for(i=n;i<=2*n;i++){
       int sz1,sz2;
       sz1=i-n;
       sz2=(3*n-i)-n;
       int rez=0,pas;
       for(pas=1<<18;pas;pas>>=1){
         if(rez+pas<=MAXN)
            query1(rez+pas);
         if(rez+pas<=MAXN&&anscnt<sz1)
           rez+=pas;
       }
       long long a,b;
       query1(rez);
       a=anssum+1LL*mp[rez+1]*(sz1-anscnt);
       rez=0;
       for(pas=1<<18;pas;pas>>=1){
         if(MAXN>rez+pas)
           query2(MAXN-rez-pas);
         if(MAXN-rez-pas>0&&anscnt<sz2)
           rez+=pas;
       }
       query2(MAXN-rez);
       b=anssum+1LL*mp[MAXN-rez-1]*(sz2-anscnt);
       ans=std::max(ans,sp1[i]-a-(sp2[i+1]-b));
       update1(vec[i+1],real[i+1],1);
       update2(vec[i+1],-real[i+1],-1);
    }
    fprintf(fout,"%lld\n" ,ans);
    //fclose(fi);
    //fclose(fout);
}

