LL add(int v, LL ans, multiset<LL> &s) {
    if(v > *s.rbegin()) s.find(s.erase(v));
    else {
        ans -= *s.rbegin();
        s.erase(s.find(*s.rbegin()));
        ans += v;
        s.insert(v);
    }
    return ans;
}

LL rem(int v, LL ans, multiset<LL> &s) {
    if(s.find(v) != s.end()) s.erase(s.find(v));
    else ans -= v, ans += *s.rbegin(), s.erase(s.find(*s.rbegin()));
    return ans;
}

