constexpr std::int64_t LINF = 1001001001001001001;

void Main()
{
    ll n = in();
    vll a = in(3 * n);

    vll lsum(3 * n), rsum(3 * n);
    multiset<ll> l, r;

    rep(i, n)
    {
        l.insert(a[i]);
        r.insert(a[2 * n + i]);
    }

    lsum[n] = accumulate(ALL(l), 0LL);
    rsum[2 * n] = accumulate(ALL(r), 0LL);

    for (int i = n; i < 2 * n; ++i)
    {
        ll lmin = *l.begin();
        ll ml = a[i];
        if (lmin < ml)
        {
            l.erase(l.begin());
            l.insert(ml);
            lsum[i + 1] = lsum[i] - lmin + ml;
        }
        else
        {
            lsum[i + 1] = lsum[i];
        }
    }

    for (int i = 2 * n; i >= n; --i)
    {
        ll rmax = *r.rbegin();
        DUMP(rmax);
        ll mr = a[i - 1];
        if (rmax > mr)
        {
            r.erase(rmax);
            r.insert(mr);
            rsum[i - 1] = rsum[i] - rmax + mr;
        }
        else
        {
            rsum[i - 1] = rsum[i];
        }
    }

    ll ans = -LINF;
    for (int i = n; i <= 2 * n; ++i)
    {
        ans = max(ans, lsum[i] - rsum[i]);
    }
    cout << ans << endl;
}

