void solveSingleCase(int caseNo)
{
    int N;
    cin >> N;
    VEC(int) A(3 * N);
    READVEC(A);

    VEC(lint) L(3 * N);

    multiset<int> bag1, bag2;
    lint total = 0;
    FOR(i, 0, 3 * N) {
        bag1.insert(A[i]);
        total += A[i];
        if (SZ(bag1) > N) {
            auto it = bag1.begin();
            total -= *it;
            bag1.erase(it);
        }

        L[i] = total;
    }

    total = 0;
    lint ret = -(1LL << 55);
    FORD(i, 3 * N - 1, -1) {
        total += A[i];
        bag2.insert(A[i]);
        if (SZ(bag2) > N) {
            auto it = bag2.end();
            it--;
            total -= *it;
            bag2.erase(it);
        }

        if (3 * N - i >= N && i >= N) {
            ret = max(ret, L[i - 1] - total);
        }
    }

    cout << ret << endl;
};

