	reverse(A.begin(), A.begin()+N3);
	f(B, 1L);

	ll maxfb = LLONG_MIN;
	rp(i, 0, N+1){
		int f = N - 1 + i;
		int b = N3 - 1 - N - i;
		maxfb = max(maxfb, F[f]-B[b]);
	}
	cout<< maxfb <<endl;
}

