  rep(i, n) {
    sum += as[3*n - 1 - i];
    pqr.emplace(as[3*n - 1 - i]);
  }
  rig[n] = sum;
  rrepLRE(i, 2 * n - 1, n) {
    ll t = pqr.top();
    if (t > as[i]) {
      pqr.push(as[i]);
      pqr.pop();
      sum += as[i] - t;
    }
    rig[i - n] = sum;
  }
  ll ans = LONG_LONG_MIN;
