int main(int argc, char** argv) {
	sint(N);
	vint(a, 3 * N);

	vector<int> left(N), right(2 * N);
	copy(a.begin(), a.begin() + N, left.begin());
	copy(a.begin() + N, a.end(), right.begin());
	sort(all(left));
	sort(all(right));

	ll leftSum = accumulate(all(left), (ll)0);
	ll rightSum = accumulate(right.begin(), right.begin() + N, (ll)0);
	ll max = leftSum - rightSum;
	int leftOffset = 0;
	int rightOffset = 0;
	rep(i, N) {
		int m = a[N + i];
		if (m > left[leftOffset]) {
			leftSum = leftSum - left[leftOffset] + m;
			left.insert(lower_bound(left.begin() + leftOffset, left.end(), m), m);
			leftOffset++;
		}
		if (m < right[N + rightOffset]) {
			rightSum = rightSum - m + right[N + rightOffset];
			rightOffset++;
		}
		else {
			right.erase(lower_bound(right.begin() + N + rightOffset, right.end(), m));
		}
		ll score = leftSum - rightSum;
		if (max < score) {
			max = score;
		}
	}
	printf("%lld\n", max);
}

