void solve()
{
    heap<int> rgt;
    minheap<int> lft;

    for(int i=1; i<=n*3; i++)
    {
        if(i>n)
        {
            l[i]=l[i-1];
            if(lft.top()<a[i])
            {
                l[i]+=a[i]-lft.top();
                lft.pop();
                lft.emplace(a[i]);
            }
        }
        else
        {
            lft.emplace(a[i]);
            l[i]=l[i-1]+a[i];
        }
    }

    reverse(a+1,a+n*3+1);

    for(int i=1; i<=n*3; i++)
    {
        if(i>n)
        {
            r[i]=r[i-1];
            if(lft.top()>a[i])
            {
                r[i]+=a[i]-rgt.top();
                rgt.pop();
                rgt.emplace(a[i]);
            }
        }
        else
        {
            rgt.emplace(a[i]);
            r[i]=r[i-1]+a[i];
        }
    }

    i64 ans=-inf<i64>;

    for(int i=n; i<=n*2; i++)
    {
        chmax(ans,l[i]-r[n*3-i]);    
    }

    cout << ans << "\n";
}

