		vector<int> left(N + i), right(2 * N - i), left2(N), right2(N);
		copy(a.begin(), a.begin() + N + i, left.begin());
		sort(all(left));
		copy(a.begin() + N + i, a.end(), right.begin());
		sort(all(right));

		copy(left.begin() + i, left.begin() + i + N, left2.begin());
		copy(right.begin(), right.begin() + N, right2.begin());
		ll score = accumulate(all(left2), (ll)0) - accumulate(all(right2), (ll)0);
		if (min < score) {
			min = score;
		}
	}
	printf("%d\n", min);
}

