int lowbit(int x) {
	return x & (-x);
}

int get_sum(int x) {
	int sum = 0;
	while(x > 0) {
		sum += tree[x];
		x -= lowbit(x);
	}
	return sum;
}

void update(int x, int t) {
	while(x <= n) {
		tree[x] += t;
		x += lowbit(x);
	}
}

