#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
using namespace std;

typedef long long ll;

int n;
ll vs[300000+10];
ll memo1[300000+10];
ll memo2[300000+10];

void calcMemo1(void) {
  memo1[0] = 0;
  priority_queue<ll> q; // negate
  ll sum = 0;
  REP(i, n*2) {
    q.push(-vs[i]);
    sum += vs[i];
    if(q.size() > n) {
      sum += q.top(); q.pop();
    }
    memo1[i+1] = sum;
  }
}

void calcMemo2(void) {
  memo2[3*n] = 0;
  priority_queue<ll> q;
  ll sum = 0;
  REP(i, n*2) {
    q.push(vs[3*n-1-i]);
    sum += vs[3*n-1-i];
    if(q.size() > n) {
      sum -= q.top(); q.pop();
    }
    memo2[3*n-1-i] = sum;
  }
}

int main(void) {
  scanf("%d", &n);
  REP(i, 3*n) {
    scanf("%lld", &vs[i]);
  }
  calcMemo1();
  calcMemo2();
  ll res = -1e18;
  for(int i = n; i <= 2*n; ++i) {
    res = max(res, memo1[i] - memo2[i]);
  }
  printf("%lld\n", res);
  return 0;
}

