  priority_queue<ll> front;
  priority_queue<ll> back;

  for(int i=0;i<3*n;++i){
    cin>>A[i];
    if(i<n){
      front.push(-A[i]);
      sum+=A[i];
    }

    if(2*n-1<i){
      back.push(A[i]);
      resum+=A[i];
    }
  }

  vector<pair<ll,ll>> ans(n+1);
  ans[0].first=sum;
  ans[n].second=resum;

  for(int i=n;i<2*n;i++){
