    back.push(A[i]);
    resum+=A[i];

    ll a=back.top();
    resum-=a;
    back.pop();
    ans[i-n].second=resum;
  }

  ll Ans=-INF;
  FOR(i,0,n+1){
    ll now=ans[i].first-ans[i].second;
    chmax(Ans,now);
  }
