// 数列aに対して、以下の2つのクエリをO(log n)で実現する
// (1) 数列aにxを追加する
// (1) 数列aをソートしたとき、小さい方からK個の和を求める
//
// 初期化: 長さKの数列aを入力
class IncrementalOrderSumK {
public:
    ll r = 0;
    priority_queue<ll, vector<ll>, std::greater<ll>> q;
    IncrementalOrderSumK(vll a_) {
        for (auto x : a_) {
            r += x;
            q.push(x);
        }
    }
    ll get(void) {
        return r;
    }
    ll push(ll x) {
        auto minVal = q.top();
        if (minVal < x) {
            q.pop();
            r = r + x - minVal;
            q.push(x);
        }
        return r;
    }
};

int main(void) {
    ll n; cin >> n;
    vll a(3ll*n); cin >> a;

    vll r(n+1);
    vll tmp; 
    rep(i, n) tmp.pb(a[i]);
    IncrementalOrderSumK iosk(tmp);
    r[0] = iosk.get();
    repi(i, 1, n+1) {
        r[i] = iosk.push(a[i+n-1]);
    }

    vll r_rev(n+1);
    reverse(all(a));
    for (auto&& x : a) x *= -1;
    tmp.clear();
    rep(i, n) tmp.pb(a[i]);
    IncrementalOrderSumK iosk_rev(tmp);
    r_rev[0] = -iosk_rev.get();
    repi(i, 1, n+1) {
        r_rev[i] = -iosk_rev.push(a[n+i-1]);
    }
    rep(i, n+1) {
        r[i] -= r_rev[n-i];
    }
    cout << *max_element(all(r)) << endl;;

    return 0;
}

