bool cmp(int a,int b)
{
	return a>b;
}

void de(int x)
{
	int k=a[x+n]-a[x+n-1];
	for(int i=x;i<=n*2;i++)
	{
	if(m[i]==k)m[i]=0;
	break;
	}

	sort(m+1,m+n*2+1,cmp);
}

int solve(int x)
{
	de(x);

	int ann1=a[n+x],ann2=a[n*3]-a[n+x];
	qs.push(a[n+x]-a[n+x-1]);

	int tmp;
	for(int i=1;i<=x;i++)
	{
		tmp=qs.top();
		tem.push(tmp);
		qs.pop();
		ann1-=tmp;
	}

	for(int i=1;i<=x;i++)
	{
		qs.push(tem.front());
		tem.pop();
	}

	for(int i=1;i<=n-x;i++)
	{
		ann2-=m[i];
	}
	return ann1-ann2;
}

void scan()
{
	n=read();
	for(int i=1;i<=n-1;i++)
	{
		k=read();
		qs.push(k);
		a[i]=a[i-1]+k;
	}

	for(int i=n;i<=n*2;i++)
	{
		k=read();
		a[i]=a[i-1]+k;
		m[i-n]=k;
	}

	for(int i=n*2+1;i<=n*3;i++)
	{
		k=read();
		m[i-n]=k;
		a[i]=a[i-1]+k;
	}
}

