int main() {
    cin >> N;
    for (int i = 0; i < 3*N; i++) cin >> a[i];

    priority_queue<ll> pq_front;
    priority_queue<ll> pq_back;

    for (int i = 0; i < N; i++) {
        pq_front.push(-a[i]);
        pq_back.push(a[3*N - 1 - i]);
    }

    int l = N, r = 2*N-1;
    while (l <= r) {
        ll fr_min = -pq_front.top();
        ll bc_max = pq_back.top();

        if (a[l] - fr_min > bc_max - a[r]) {
            if (a[l] - fr_min > 0) {
                pq_front.pop();
                pq_front.push(-a[l]);
            }
            l++;
        }
        else {
            if (bc_max - a[r] > 0) {
                pq_back.pop();
                pq_back.push(a[r]);
            }
            r--;
        }
    }

    ll ans = 0;
    for (int i = 0; i < N; i++) {
        ans -= pq_front.top();
        pq_front.pop();

        ans -= pq_back.top();
        pq_back.pop();
    }


    cout << ans << endl;


    return 0;
