int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    priority_queue<int, vector<int>, greater<int>> first;   // 前半部
    priority_queue<int> latter;     // 後半部
    deque<int> middle;              // 中間部
    ll score = 0;       // (前半部) - (後半部)
    for(int i = 0; i < n; ++i){
        int temp;
        cin >> temp;
        first.push(temp);
        score += temp;
    }
    for(int i = 0; i < n; ++i){
        int temp;
        cin >> temp;
        middle.push_back(temp);
    }
    for(int i = 0; i < n; ++i){
        int temp;
        cin >> temp;
        latter.push(temp);
        score -= temp;
    }

    while(!middle.empty()){
        ll score1, score2;
        score1 = score - first.top() + middle.front();
        score2 = score + latter.top() - middle.back();

        if(score >= score1 && score >= score2){
            if(middle.size() == 1){
                middle.pop_front();
            }
            else{
                middle.pop_front();
                middle.pop_back();
            }
        }
        else if(score >= score2){       // score1が最大値       
            score = score1;
            first.pop();
            first.push(middle.front());
            middle.pop_front();
        }
        else if(score >= score1){       // score2が最大値
            score = score2;
            latter.pop();
            latter.push(middle.back());
            middle.pop_back();
        }
        else{       // score1, score2ともに現時点のscoreより小さい時
            if(score1 >= score2){       // score1が最大値
                score = score1;
                first.pop();
                first.push(middle.front());
                middle.pop_front();
            }
            else{                       // score2が最大値
                score = score2;
                latter.pop();
                latter.push(middle.back());
                middle.pop_back();
            }
        }
    }

    cout << score << endl;
}

