        sum1 += a1[i].first;
        ub = max(ub, -a1[i].second);
    }

    ll sum2 = 0, n2 = 0;
    for (int i = 0; i < ub; ++i)
        if (!used[i]) {
            sum2 += a[i];
            ++n2;
        }

    vector<ll> a2;
    for (int i = ub + 1; i < 3 * n; ++i)
        a2.push_back(a[i]);
    sort(a2.begin(), a2.end(), greater<ll>());

    for (int i = 0; n2 < n; ++i) {
        sum2 += a2[i];
        ++n2;
    }

    cout << 2 * sum1 + sum2 - accumulate(a.begin(), a.end(), 0ll) << endl;

