    {
        cin >> a[i];
    }

    priority_queue<int64_t, vector<int64_t>, greater<int64_t>> lQ;
    priority_queue<int64_t, vector<int64_t>, less<int64_t>> rQ;
    int64_t lSum = 0;
    int64_t rSum = 0;

    for (int i = 0; i < N; i++)
    {
        lQ.push(a[i]);
        rQ.push(a[i + 2 * N]);

        lSum += a[i];
        rSum += a[i + 2 * N];
    }

    for (int i = 0; i <= N; i++)
    {
        if (i != 0)
        {
            lSum += a[i - 1 + N];
            lQ.push(a[i - 1 + N]);
            lSum -= lQ.top();
            lQ.pop();

            rSum += a[2 * N - i];
            rQ.push(a[2 * N - i]);
            rSum -= rQ.top();
            rQ.pop();
        }
        lScore[i] = lSum;
        rScore[N - i] = rSum;
    }

    int64_t mScore = numeric_limits<int64_t>::min();
    for (int i = 0; i <= N; i++)
    {
        mScore = max(mScore, lScore[i] - rScore[i]);
