using namespace std;

long long parent(long long i){return((i-1)/2);}
long long lchild(long long i){return(2*i+1);}
long long rchild(long long i){return(2*i+2);}

bool gt(long long x, long long y){
  return(x > y);
}

bool lt(long long x, long long y){
  return(x < y);
}

void push(long long x, long long *pq, long long *q_max, function<bool(long long, long long)> f){
  pq[*q_max] = x;
  long long idx = *q_max;
  (*q_max)++;
  while (idx > 0) {
    if (f(pq[idx], pq[parent(idx)])) {
      long long tmp = pq[parent(idx)];
      pq[parent(idx)] = pq[idx];
      pq[idx] = tmp;
      idx = parent(idx);
    } else {
      return;
    }
  }
}

long long pop(long long *pq, long long *q_max, function<bool(long long, long long)> f){
  if (*q_max < 0) {
    cerr << "queue is empty." << endl;
    return 0;
  }
  long long result = pq[0];
  pq[0] = pq[--(*q_max)];
  long long idx = 0;
  while (lchild(idx) < *q_max) {
    if (f(pq[idx], pq[lchild(idx)]) && f(pq[idx], pq[rchild(idx)])) {
      return(result);
    }
    if (f(pq[lchild(idx)], pq[rchild(idx)])) {
      long long tmp = pq[lchild(idx)];
      pq[lchild(idx)] = pq[idx];
      pq[idx] = tmp;
      idx = lchild(idx);
    } else {
      long long tmp = pq[rchild(idx)];
      pq[rchild(idx)] = pq[idx];
      pq[idx] = tmp;
      idx = rchild(idx);
    } 
  }
  return(result);
}


