ll f0(ll m, ll i, vector<ll> const &a, u_map<ll, ll> &dp) {
  ll n = a.size();
  dump(m, i);
  if (m == 0 && i < n) {
    return 0;
  }
  if (i >= n || m > n - i) {
    return -1e18;
  }
  auto found = dp.find(i);
  if (found != dp.end()) {
    return found->second;
  }
  return dp[i] = max(a[i] + f0(m - 1, i + 1, a, dp), f0(m, i + 1, a, dp));
}
ll f1(ll m, ll i, vector<ll> const &a, u_map<ll, ll> &dp) {
  ll n = a.size();
  dump(m, i);
  if (m == 0 && i < n) {
    return 0;
  }
  if (i >= n || m > n - i) {
    return 1e18;
  }
  auto found = dp.find(i);
  if (found != dp.end()) {
