void solve() {
  ll N;
  input(N);
  vector<ll> a(3 * N);
  input(a);
  dump(a);
  multiset<ll> X0(a.begin(), a.begin() + N);
  vector<ll> ans0(N + 1, accumulate(X0.begin(), X0.end(), 0LL));
  for (auto &&i : range(1, N + 1)) {
    ll ai = a[i + N - 1];
    X0.insert(ai);
    auto x0 = X0.begin();
    ans0[i] = ans0[i - 1] + ai - *x0;
    X0.erase(x0);
  }
  multiset<ll> X1(a.begin() + 2 * N, a.end());
  vector<ll> ans1(N + 1, accumulate(X1.begin(), X1.end(), 0LL));
  dump(0, X1);
  for (auto &&i : range(1, N + 1)) {
    ll ai = a[2 * N - i];
    X1.insert(ai);
    auto xn = --X1.end();
    ans1[N - i] = ans1[N - i + 1] + ai - *xn;
    X1.erase(xn);
    dump(i, X1);
  }

  dump(ans0, ans1);
  ll ans = -1e18;
  for (auto &&i : range(N + 1)) {
    ans = max(ans, ans0[i] - ans1[i]);
  }
  print(ans);
}

