int main() {

    int N;
    cin >> N;

    vector<LL> a(3 * N);
    for (int i = 0; i < 3 * N; i++) cin >> a[i];

    vector<LL> d1, d2;

    LL sum = 0;
    priority_queue<LL, vector<LL>, greater<LL>> Q_min;
    for (int i = 0; i < N; i++) {
        sum += a[i];
        Q_min.push(a[i]);
    }
    d1.push_back(sum);
    for (int i = 0; i < N; i++) {
        sum += a[i + N];
        Q_min.push(a[i + N]);
        LL minV = Q_min.top();
        Q_min.pop();
        sum -= minV;
        d1.push_back(sum);
    }

    reverse(a.begin(), a.end());
    sum = 0;
    priority_queue<LL> Q_max;
    for (int i = 0; i < N; i++) {
        sum += a[i];
        Q_max.push(a[i]);
    }
    d2.push_back(sum);
    for (int i = 0; i < N; i++) {
        sum += a[i + N];
        Q_max.push(a[i + N]);
        LL maxV = Q_max.top();
        Q_max.pop();
        sum -= maxV;
        d2.push_back(sum);
    }
    reverse(d2.begin(), d2.end());

    LL ans = LONG_LONG_MIN;
    for (int i = 0; i < d1.size(); i++) {
        ans = max(ans, d1[i] - d2[i]);
    }
    cout << ans << endl;

    return 0;
}

