	for(int i=1;i<=n*3;i++) scanf("%lld",&a[i]);
	for(int i=1;i<=n;i++) q2.push(a[i]);
	for(int i=n*3;i>=2*n+1;i--) q1.push(a[i]);
	int l=n+1,r=2*n;
	while(l<=r){
		if(a[l]-q2.top()>q1.top()-a[r]){
			if(q1.top()-a[r]<=0){
				if(a[l]-q2.top()<=0){
					if(a[l]-q2.top()>q1.top()-a[r]) r--;
					else l++;;
				}
				else{
					if(a[l]-q2.top()>=q1.top()-a[l]){
						q2.pop();
						q2.push(a[l]);
						l++;
					}
					else r--;
				}
			}
			else{
				q2.pop();
				q2.push(a[l]);
				l++;
			}
		}
		else{
			if(a[l]-q2.top()<=0){
				if(q1.top()-a[r]>0){
					if(q1.top()-a[r]>a[r]-q2.top()){
						q1.pop();
						q1.push(a[r]);
						r--;
					}
					else l++;
				}
				else{
					if(q1.top()-a[r]>a[l]-q2.top()) l++;
					else r--;
				}
			}
			else{
				q1.pop();
				q1.push(a[r]);
				r--;
			}
		}
	}
	sum1=0;
	sum2=0;
	while(!q2.empty()){
		sum1+=q2.top();
		q2.pop();
	}
	while(!q1.empty()){
		sum2+=q1.top();
		q1.pop();
	}
	printf("%lld\n",sum1-sum2);

}

