    dpq.push(a[N + i - 1]);
    dsum[i] -= dpq.top(); dpq.pop();
  }

  vector<ll> lsum(N + 1, 0);
  priority_queue<int> lpq;
  for (int i = 0; i < N; i++) {
    lsum[0] += a[2 * N + i];
    lpq.push(a[2 * N + i]);
  }
  for (int i = 1; i <= N; i++) {
    lsum[i] = lsum[i - 1] + a[2 * N - i];
    lpq.push(a[2 * N - i]);
    lsum[i] -= lpq.top(); lpq.pop();
  }


  ll ans = -110000000000000;
  for(int i = 0; i <= N; i++) {
    ans = max(ans, dsum[i] - lsum[N - i]);
  }
  cout << ans << endl;

  return 0;
}

