/* -----  2018/02/27  Problem: 074_arc_b / Link: https://abc062.contest.atcoder.jp/tasks/arc074_b?lang=en  ----- */
/* ------問題------

N を 1 以上の整数とします。
長さ 3N の数列 a=(a1,a2,…,a3N) があります。 すぬけ君は、a からちょうど N 個の要素を取り除き、残った 2N 個の要素を元の順序で並べ、長さ 2N の数列 a' を作ろうとしています。 このとき、a' のスコアを (a'の前半N要素の総和)−(a'の後半N要素の総和) と定義します。
a' のスコアの最大値を求めてください。

-----問題ここまで----- */
/* -----解説等-----



----解説ここまで---- */

LL N;

LL ans = 0LL;

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	cin >> N;
	VI a(3 * N);
	FOR(i, 0, 3 * N) {
		cin >> a[i];
	}

	VL dp1(3 * N, 0);
	{
		priority_queue<int, VI, greater<int>>pq;
		LL sum = 0;
		FOR(i, 0, 3 * N) {

			sum += a[i];
			pq.push(a[i]);
			if (SZ(pq)== (N + 1)) {
				LL val = pq.top(); pq.pop();
				sum -= val;
			}
			dp1[i] = sum;
		}
		//FOR(i, 0, 3 * N) {
		//	cout << dp1[i] << " ";
		//}cout << endl;
	}
	VL dp2(3 * N, 0);
	{
		priority_queue<int>pq;
		LL sum = 0;
		FORR(i, 3*N-1, 0-1) {

			sum += a[i];
			pq.push(a[i]);
			if (SZ(pq) ==(N + 1)) {
				LL val = pq.top(); pq.pop();

				sum -= val;
			}
			dp2[i] = sum;
		}
		//FOR(i, 0, 3 * N) {
		//	cout << dp2[i] << " ";
		//}cout << endl;
	}
	ans = -LINF;
	FOR(i, N-1, 2 * N) {
		ans = max(ans, dp1[i] - dp2[i+1]);
	}
	cout << ans << "\n";

	return 0;
}

