ll solve(ll* nums, int n){
  priority_queue<int, vector<int>, greater<int> > a;  //前半の要素を小さいものからポップ
  priority_queue<int> b;  //後半の要素を大きいものからポップ
  ll asum[n+1], bsum[n+1];
  ll atemp=0, btemp=0;

  for(int i=1; i<=n; i++) {
    //aに関しては1~nの要素を入れておく
    a.push(nums[i]);
    atemp += nums[i];

    //bに関しては2*n+1~3*nの要素を入れておく
    b.push(nums[2*n+i]);
    btemp += nums[2*n+i];
  }

  asum[0] = atemp; bsum[n] = btemp;

  //とりあえずasumの様子を更新
  for(int k=1; k<=n; k++){
    a.push(nums[n+k]);
    atemp += nums[n+k];
    atemp -= a.top(); a.pop();
    asum[k] = atemp;

    b.push(nums[2*n+1-k]);
    btemp += nums[2*n+1-k];
    btemp -= b.top(); b.pop();
    bsum[n-k] = btemp;
  }

  //次にbsumの様子を更新
  ll ans = LLONG_MIN;
  for(int k=0; k<=n; k++){
    ans = max(ans, asum[k] - bsum[k]);
  }

  return ans;
}

