void func()
{
	priority_queue<int> pq;
	int s = 0;
	rrep(i, 0, 3 * N)
	{
		int t = INF;
		if (SZ(pq) == N)
		{
			t = pq.top();
		}

		if (A[i] < t)
		{
			if (SZ(pq) == N)
			{
				pq.pop();
				s -= t;
			}
			s += A[i];
			pq.push(A[i]);
		}

		if (SZ(pq) == N)
		{
			SUM[i] = s;
		}
		else
		{
			SUM[i] = INF;
		}
	}
}

int solve()
{
	int ans = -INF;
	priority_queue<int, vector<int>, greater<int>> pq;
	int s = 0;
	rep(i, 0, 3 * N - 1)
	{
		int t = 0;
