			t = pq.top();
		}

		if (A[i] > t)
		{
			if (SZ(pq) == N)
			{
				pq.pop();
				s -= t;
			}
			s += A[i];
			pq.push(A[i]);
		}

		if (SZ(pq) == N)
		{
			t = s;
		}
		else
		{
			t = 0;
		}

		chmax(ans, t - SUM[i + 1]);
	}

	return ans;
}

