int main()
{
  int n = 0;
  std::cin >> n;

  std::vector<int> a_front;
  std::deque<int> a_middle;
  std::vector<int> a_back;
  for(int i = 0; i < n; ++i)
  {
    int element = 0;
    std::cin >> element;
    a_front.push_back(element);
  }
  for(int i = 0; i < n; ++i)
  {
    int element = 0;
    std::cin >> element;
    a_middle.push_back(element);
  }
  for(int i = 0; i < n; ++i)
  {
    int element = 0;
    std::cin >> element;
    a_back.push_back(element);
  }

  std::sort(a_front.begin(), a_front.end(), std::greater<int>());
  std::sort(a_back.begin(), a_back.end());

  for(int i = 0; i < n; ++i)
  {
    // check front
    bool replace = false;
    int point_diff = 0;
    if(a_front.back() < a_middle.front())
    {
      point_diff += a_middle.front() - a_front.back();
      replace = true;
    }

    // check back
    if(a_back.back() > a_middle.back())
    {
      point_diff += a_middle.back() - a_back.back();
      replace = true;
    }

    if(replace)
    {
      if(point_diff >= 0)
      {
        auto itr_insert = std::upper_bound(a_front.begin(), a_front.end(), a_middle.front(), std::greater<int>());
        a_front.insert(itr_insert, a_middle.front());
        a_middle.pop_front();
        a_front.pop_back();
      }
      else
      {
        auto itr_insert = std::upper_bound(a_back.begin(), a_back.end(), a_middle.back());
        a_back.insert(itr_insert, a_middle.back());
        a_middle.pop_back();
        a_front.pop_back();
      }
    }
    else
    {
      if((a_front.back() - a_middle.back()) + (a_back.back() - a_middle.front()) > 0)
      {
        a_middle.pop_front();
      }
      else
      {
        a_middle.pop_back();
      }
    }
  }

  int point = 0;
  for(int i = 0; i < n; ++i)
  {
    point += a_front[i];
    point -= a_back[i];
  }
  std::cout << point;

  return 0;
}

