int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int N; cin >> N;
  vl A(3*N);
  rep(i, 0, 3*N) {
    cin >> A[i];
  }

  priority_queue<ll> l_q, r_q;

  ll l_sum = 0;

  rep(i, 0, N) {
    l_sum += A[i];
    l_q.push(-A[i]);
  }

  ll r_sum = 0;
  rep(i, 2*N, 3*N) {
    r_sum += A[i];
    r_q.push(A[i]);
  }


  vl r(N+1), l(N+1);
  l[0] = l_sum;

  rep(i, 1, N+1) {
    ll ai = A[N-1+i];
    ll mi = -l_q.top();
    if (ai > mi) {
      l[i] = l[i-1]+ai-mi;
      l_q.pop();
      l_q.push(-ai);
    } else {
      l[i] = l[i-1];
    }
  }

  r[N] = r_sum;
  for (int i = N-1; i >= 0; i--) {
    ll ai = A[N+i];
    ll ma = r_q.top();
    if (ai > ma) {
      r[i] = r[i+1];
    } else {
      r[i] = r[i+1]-ma+ai;
      r_q.pop();
      r_q.push(ai);
    }
  }

  ll ans = -INF;
  rep(i, 0, N+1) {
    chmax(ans, l[i]-r[i]);
  }

  cout << ans << endl;

  return 0;
};

