        r--;
      }
    }else if(middle[l] - front.top() > back.top() - middle[r]){
      sumf -= front.top();
      sumf += middle[l];
      front.pop();
      front.push(middle[l]);
      l++;
    }else{
      sumb -= back.top();
      sumb += middle[r];
      back.pop();
      back.push(middle[r]);
      r--;
    }
  }
  cout << sumf - sumb << endl;
}

