    for (int i = 0; i < n; i++) {
        l_sum += a[i];
        l_set.insert(a[i]);
        l_max[i] = l_sum;
    }
    for (int i = n; i <= 2 * n; i++) {
        multiset<long long>::iterator ite = l_set.begin();
