    //co(pl[i+1]<<" "<<pl[i]<<" "<<ql.top()<<" "<<A[n+i]);
    ql.pop();
    qr.push(A[2*n-1-i]);
    mi[i+1]+=mi[i]-qr.top()+A[2*n-1-i];
    qr.pop();
  }
  ll ans=-MOD;
  FOR(i,0,n+1){
    ans=max(ans,pl[i]-mi[n-i]);
    //co(ans<<" "<<pl[i]<<" "<<mi[n-i]);
  }
  co(ans);
}

