const ll INF = LLONG_MAX;
const ll N =(3e5+5); // TODO : change value as per problem
const ll MOD = 1e9+7;

int a[N];
int pre[N];
int suf[N];
void solve(){
	int n;
	cin >> n;
	for(int i =1;i<=3*n;i++){
		cin >> a[i];
	}
	set<int> se;
	for(int i =1;i<=3*n;i++){
		if(i <= n){
			pre[i] = pre[i-1] + a[i];
			se.in(a[i]);
			continue;
		}
		pre[i] = pre[i-1];
		if(a[i] > *(se.begin())){
			pre[i] -= *(se.begin());
			pre[i] += a[i];
			se.erase(se.begin());
			se.in(a[i]);
		}
	}

	se.clear();
	for(int i = 3*n,j = 1;i>=1;i--,j++){
		assert((3*n - i + 1) == j);
		if((3 * n - i + 1) <= n){
			se.in(a[i]);
			suf[i] = suf[i+1] + a[i];
			continue;
		}
		suf[i] = suf[i+1];
		if(a[i] < *(se.rbegin())){
			suf[i] -= *(se.rbegin());
			suf[i] += a[i];
			auto it = se.end();
			it--;
			se.erase(it);
			se.in(a[i]);
		}
	}
	int ans = -INF;
	for(int i =n;i<=2*n;i++){
		ans= max(ans,pre[i]- suf[i+1]);
	}
	assert(ans != -INF);
	cout << ans << endl;

}
signed main(){

    ios_base::sync_with_stdio(0);
    cin.tie(NULL);
     // freopen(".in","r",stdin);freopen(".out","w",stdout);

     ll tt=1;   
     // cin >> tt;
    while(tt--){    
        solve();
    }    
}

