            sum0-=(it->first);
            zz.erase( it );
            s0[i+1-n]=sum0;
        }
    }

    vector<ll> s1(n+1);
    {
        reverse(a.begin(), a.end());
        ll sum0=0;
        set<pair<long,long> > zz;
        for(i=0; i<n; i++) {
            zz.insert( make_pair( a[i], i) );
            sum0+=a[i];
        }
        s1[0]=sum0;
        for(i=n; i<n*2; i++) {
            zz.insert( make_pair( a[i], i) );
            sum0+=a[i];

            auto it=zz.end();
            it--;
            sum0-=(it->first);
            zz.erase( it );
            s1[i+1-n]=sum0;
        }
    }

    ll max=-LINF;
    for(i=0; i<=n; i++) {
