	REP(i, N) {
		left += a[i];
		minpq.push(a[i]);
	}
	Left[N-1] = left;
	FOR(i, N, 2*N) {
		minpq.push(a[i]);
		Left[i] =Left[i-1]+ a[i];
		ll c = minpq.top();
		minpq.pop();
		Left[i]-= c;
	}


	ll right = 0;
	priority_queue<ll> maxpq;
	FORR(i, 3*N - 1, 2*N) {
		right += a[i];
		maxpq.push(a[i]);
	}
