#define int long long

using namespace std;

int N;
int a[300010];
int sum_arr[300010];
int min_sum_arr[300010];

signed main()
{
#ifdef LOCAL
    ifstream in("input.txt");
    cin.rdbuf(in.rdbuf());
#endif

    cin >> N;
    rep(i,3*N) cin >> a[i];

    priority_queue<int, vector<int>, greater<int> > minpq;

    int sum = 0;
    rep(i,N) {
        minpq.push(a[i]);
        sum += a[i];
    }
    sum_arr[N-1] = sum;

    for (int i=N; i<2*N+1; i++) {
        minpq.push(a[i]);
        sum += a[i];
        sum -= minpq.top();
        minpq.pop();
        sum_arr[i] = sum;
    }

    priority_queue<int> maxpq;

    sum = 0;

    for (int i=3*N-1; i>=2*N; i--) {
        maxpq.push(a[i]);
        sum += a[i];
    }
    min_sum_arr[2*N] = sum;

    for (int i=2*N-1; i>=N-1; i--) {
        maxpq.push(a[i]);
        sum += a[i];
        sum -= maxpq.top();
        maxpq.pop();
        min_sum_arr[i] = sum;
    }

    int ans = INT_MIN;
    for (int i=N-1; i<=2*N-1; i++) {
        ans = max(ans, sum_arr[i] - min_sum_arr[i+1]);
    }

    cout << ans << endl;
}

