ll N;
ll A[300001];
ll B[300001];
ll C[300001];
int main() {
	cin >> N;
	rep(i, 0, 3 * N)cin >> A[i];

	priority_queue<ll> pre;
	ll sm = 0;
	rep(i, 0, N * 3) {
		pre.push(-A[i]);
		sm += A[i];
		if (N < pre.size()) {
			ll p = pre.top(); pre.pop();//pop minimum value
			sm += p;
		}
		B[i] = sm;
	}

	priority_queue<ll> post;
	sm = 0;
	for (int i = N * 3 - 1; i >= 0; i--) {
		post.push(A[i]);
		sm += A[i];

		if (N < post.size()) {
			ll p = post.top(); post.pop();
			sm -= p;
		}
		C[i] = sm;
	}

	ll ans = -(ll)(1 << 30);
	rep(c, N, N * 2 + 1) {
		ans = max(ans, B[c - 1] - C[c]);
	}
	cout << ans << endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main(){
    int n;
    cin >> n;
    vector<int> a(3*n);
    for(int i = 0; i < 3*n; i++){
        cin >> a[i];
    }

    priority_queue<int,vector<int>,greater<int>> bigger_remain;
    priority_queue<int> smaller_remain;

    vector<ll> bigger_sum(n+1);
    vector<ll> smaller_sum(n+1);
    ll tmp_bigger_sum = 0;
    ll tmp_smaller_sum = 0;
    for(int i = 0; i < n; i++){
        bigger_remain.push(a[i]);
        tmp_bigger_sum += a[i];
        smaller_remain.push(a[3*n-1-i]);
        tmp_smaller_sum += a[3*n-1-i];
    }
    bigger_sum[0] = tmp_bigger_sum;
    smaller_sum[0] = tmp_smaller_sum;
    int tmp_pop;
    for(int i = 0; i < n; i++){
        tmp_bigger_sum += a[n+i];
        bigger_remain.push(a[n+i]);
        tmp_pop = bigger_remain.top();
        bigger_remain.pop();
        tmp_bigger_sum -= tmp_pop;
        bigger_sum[1+i] = tmp_bigger_sum;
        tmp_smaller_sum += a[2*n-1-i];
        smaller_remain.push(a[2*n-1-i]);
        tmp_pop = smaller_remain.top();
        smaller_remain.pop();
        tmp_smaller_sum -= tmp_pop;
        smaller_sum[1+i] = tmp_smaller_sum;
    }
    ll ans = -9999999999999999;
    for(int i = 0; i < n+1; i++){
        ans = max(ans,bigger_sum[i]-smaller_sum[n-i]);
    }

    cout << ans << endl;
    return 0;
}

