typedef long long int LLI;

LLI ans(LLI & n, LLI arr[], int even_odd)
{
	LLI tmp = (3*n)/2, left[tmp], right[tmp];
	LLI sum_left = 0, sum_right = 0, answer;

	for(int i = 0; i < tmp; i++)
	{
		left[i] = arr[i];
		sum_left += left[i];
	}

	sort(left,left+tmp);

	for(int i = 0; i < n/2; i++)
		sum_left -= left[i];

	for(int i = tmp+even_odd; i < 3*n; i++)
	{
		right[i-tmp-even_odd] = arr[i];
		sum_right += right[i-tmp-even_odd];
	}

	sort(right,right+tmp);

	for(int i = tmp - n/2; i < tmp; i++)
		sum_right -= right[i];

	answer = sum_left - sum_right;

	if( even_odd == 0 )
		return answer;
	else{
		if( answer < ( sum_left - left[n/2]) + arr[tmp] - sum_right )
			answer = ( sum_left - left[n/2] ) + arr[tmp] - sum_right;
		if( answer < sum_left - ( arr[tmp] + ( sum_right - right[tmp - n/2 - 1] ) ) )
			answer = sum_left - ( arr[tmp] + ( sum_right - right[tmp - n/2 - 1] ) );
	}
	return answer;
}
