    vector<ll> a(3*n);
    for(int i = 0; i < 3*n; i++) {
        cin >> a[i];
    }
    priority_queue<ll> q2;
    priority_queue<ll, vector<ll>, greater<ll>> q1;
    ll sumA = 0, sumB = 0;
    for(int i = 0; i < n; i++) q1.push(a[i]), sumA += a[i];
    for(int i = 2*n; i < 3*n; i++) q2.push(a[i]), sumB += a[i];
    vector<ll> A(3*n,0), B(3*n,0);
    A[n-1] = sumA;
    B[2*n] = sumB;
    for(int i = n; i < 2*n; i++) {
        ll now = q1.top();
        if(now < a[i]){
            sumA = sumA + a[i] - now;
            q1.pop();
            A[i] = sumA;
        }else{
            A[i] = sumA;
        }
    }
    for(int i = 2*n-1; i >= n; i--) {
        ll now = q2.top();
        if(now > a[i]) {
            sumB = sumB - now + a[i];
            q2.pop();
            B[i] = sumB;
        }else{
            B[i] = sumB;
        }
    }
    ll ans = -1e18;
    for(int i = n-1; i < 2*n; i++) {
        ll now = A[i] - B[i+1];
        chmax(ans, now);
    }
    cout << ans << endl;
}

