const int N = 1e5+5;
int a[3*N];


int main(){
	//freopen("in","r",stdin);
	ll p1 = 0, p2 = 0;
	auto func = [](const int& l,const int & r) {return a[l] > a[r];};
	priority_queue<int,vector<int>,function<bool(const int&,const int&)> > l(func),r(func);
	int n; scanf("%d",&n);
	for(int i = 1;i <= 3*n;i++){
		scanf("%d",a+i);
		if(i <= n) p1 += a[i];
		if(i > n) p2 += a[i];
	}
	for(int i = 1;i <= n;i++) {
		l.push(i);		
	}
	set<int> record;
	for(int i = n+1;i <= 3*n;i++) r.push(i),record.insert(i);
	ll keep = 0, take = p2;
	for(int i = 1;i <= n;i++){
		int temp = r.top();
		r.pop();
		record.erase(temp);
		take -= a[temp];
		keep += a[temp];
	}
	ll res = -INF;
	for(int i = n+1;i <= 2*n;i++){
		int lt = l.top(),rt = r.top();
		if(a[i]>a[lt]){
			p1 += a[i]-a[lt];
			l.pop(); l.push(i);
		}
		if(record.count(i)==0){
			while(record.count(rt)==0) r.pop(),rt = r.top();
			keep += a[rt]-a[i];
			record.erase(rt);
			r.pop(); 
		}else{
			record.erase(i);
		}
		res = max(res,p1-keep);
	}
	printf("%lld\n", res);

}

