using namespace std;

int main()
{

	long long num_count;
	cin >> num_count;

	vector<long long> nums( num_count*3 );

	for( long long i = 0; i < nums.size(); ++i )
		cin >> nums[i];

	long long answer = numeric_limits<long long>::min();

	map< int,long long > plus_total, minus_total;
	priority_queue< long long, vector<long long>, greater<long long> > q_plus;
	priority_queue< long long, vector<long long>, less<long long> > q_minus;

	long long total = 0;

	for( long long i = 0; i < num_count; ++i )
	{
		q_plus.push( nums[i] );
		total += nums[i];
	}

	plus_total[0] = total;

	for( long long k = 0; k < num_count; ++k )
	{

		total += nums[k+num_count];
		q_plus.push(nums[k+num_count]);
		total -= q_plus.top();
		q_plus.pop();

		plus_total[k+1] = total;

	}

	total = 0;
	for( long long i = 2*num_count; i < 3*num_count; ++i )
	{
		q_minus.push(nums[i]);
		total += nums[i];
	}

	minus_total[num_count] = total;

	for( long long k = num_count-1; k >= 0; --k )
	{
		total += nums[k+num_count];
		q_minus.push(nums[k+num_count]);
		total -= q_minus.top();
		q_minus.pop();
		minus_total[k] = total;
	}

	for( long long i = 0; i <= num_count; ++i )
	{
		answer = max( answer, plus_total[i] - minus_total[i] );
	}

	cout << answer << endl;

	return 0;	

}

