#include <climits>
using namespace std;

int main() {
  int n;
  cin >> n;
  int a[n * 3];
  for (int i = 0; i < n * 3; i++) {
    cin >> a[i];
  }

  long long ans = LONG_LONG_MAX * (-1);
  for (int i = n; i < 2 * n; i++) {
    int b[i], c[3 * n - i];
    for (int j = 0; j < i; j++) {
      b[j] = a[j];
    }
    for (int j = 0; j < 3 * n - i; j++) {
      c[j] = a[i + j];
    }

    sort(b, b + i);
    sort(c, c + (3  *n - i));

    long long maxi = 0, mini = 0;
    for (int j = i - n; j < i; j++) {
      maxi += b[j];
    }
    for (int j = 0; j < n; j++) {
      mini += c[j];
    }

    ans = max(ans, (maxi - mini));
  }

  cout << ans << endl;

  return 0;
}

