int main(int argc, char** argv) {
	sint(N);
	vint(a, 3 * N);

	vector<int> left(N), right(2 * N);
	copy(a.begin(), a.begin() + N, left.begin());
	copy(a.begin() + N, a.end(), right.begin());
	sort(all(left));
	sort(all(right));

	ll leftSum = accumulate(all(left), (ll)0);
	ll rightSum = accumulate(right.begin(), right.begin() + N, (ll)0);
	ll max = leftSum - rightSum;
	int offset = 0;
	rep(i, N) {
		int m = a[N + i];
		if (m > left[offset]) {
			leftSum = leftSum - left[offset] + m;
			left.insert(lower_bound(left.begin() + offset, left.end(), m), m);
			offset++;
		}
		right.erase(lower_bound(all(right), m));
		if (m < right[N - 1]) {
			rightSum = rightSum - m + right[N - 1];
		}
		ll score = leftSum - rightSum;
		if (max < score) {
			max = score;
		}
	}
	printf("%lld\n", max);
}

