int main() {
  ll n;
  cin >> n;
  vector<ll> m(n), sl(n + 1, 0), sr(n + 1, 0);
  priority_queue<ll> qr;
  priority_queue<ll, vector<ll>, greater<ll>> ql;
  REP(i, n) {
    ll l;
