using namespace std;
typedef long long ll;
const ll INF = 1LL << 60;
/* テンプレートここまで */

int main() {
  int N; cin >> N;
  vector<ll> a(3*N); REP(i, 3*N) cin >> a[i];

  multiset<ll> st;

  //i=0,1,...,Nに対し，
  //a[0], a[1], ..., a[N-1+i]のうち，上位N個の和を記録
  vector<ll> former(N+1, 0); 
  //a[3N-1], a[3N-2], ..., a[2N-i]のうち，下位N個の和を記録
  vector<ll> latter(N+1, 0);

  REP(i, N){
    st.insert(a[i]);
    former[0] += a[i];
  }

  FOR(i, 1, N+1){
    auto min_it = min_element(ALL(st));
    ll tmp = *min_it;
    if(a[N-1+i] > tmp){
      st.erase(min_it);
      st.insert(a[N-1+i]);
      former[i] = former[i-1] + a[N-1+i] - tmp;
    }else{
      former[i] = former[i-1];
    }
  }

  multiset<ll> st2;

  REP(i, N){
    st2.insert(a[3*N-1-i]);
    latter[0] += a[3*N-1-i];
  }

  FOR(i, 1, N+1){
    auto max_it = max_element(ALL(st2));
    ll tmp = *max_it;
    if(a[2*N-i] < tmp){
      st2.erase(max_it);
      st2.insert(a[2*N-i]);
      latter[i] = latter[i-1] + a[2*N-i] - tmp;
    }else{
      latter[i] = latter[i-1];
    }
  }

  ll ans = -INF;

  REP(i, N+1){
    ans = max(ans, former[i] - latter[N-i]);
  }

  cout << ans << endl;
}

