long long n, m;
long long a[maxn];
vector<long long> p, q;
long long s=0, t=0, res;

void enter()
{
    fi >> n;
    m=(n*3)/2;
    fort(i, 1, m)
    {
        fi >> a[i];
        p.push_back(-a[i]);
    }
    fort(i, m+1, n*3)
    {
        fi >> a[i];
        q.push_back(a[i]);
    }
}

void solve()
{
    sort(p.begin(), p.end());
    sort(q.begin(), q.end());
    fort(i, 0, n-1)
    {
        s-=p[i];
        t+=q[i];
    }
    res=s-t;
    fo << res;
}

int main()
{
    enter();
    solve();
}

