int main()
{
    int n;
    cin >> n;
    vl a(n*3);
    rep(i,n*3) cin >> a[i];

    vl l(n*2+1,0);
    priority_queue<ll, vector<ll>, greater<ll>> que1;
    for(int i = 0; i < n; ++i) {
        l[i+1] = l[i+1] + a[i];
        que1.push(a[i]);
    }
    for(int i = n; i < n*2; ++i) {
        ll m = que1.top();
        if(a[i] > m) {
            l[i+1] = l[i] - m + a[i];
            que1.pop();
            que1.push(a[i]);
        } else l[i+1] = l[i];
    }

    vl r(n*2+1,0);
    priority_queue<ll> que2;
    for(int i = 0; i < n; ++i) {
        r[i+1] = r[i] + a[n*3-1 - i];
        que2.push(a[n*3-1 - i]);
    }
    for(int i = n; i < n*2; ++i) {
        ll M = que2.top();
        if(a[n*3-1 - i] < M) {
            r[i+1] = r[i] - M + a[n*3-1 - i];
            que2.pop();
            que2.push(a[n*3-1 - i]);
        } else r[i+1] = r[i];
    }

