int main(void) {
  int n;
  cin >> n;
  priority_queue<int, vector<int>, greater<int> > gq;
  priority_queue<int> lq;
  vector<int> mid(n), sumf(n + 1), sums(n + 1);
  int sum1 = 0, sum2 = 0;
  for (int i = 0; i < n; i++) {
    int a;
    cin >> a;
    gq.push(a);
    sum1 += a;
  }
  for (int i = 0; i < n; i++) {
    cin >> mid[i];
  }
  for (int i = 0; i < n; i++) {
    int a;
    cin >> a;
    lq.push(a);
    sum2 += a;
  }
  sumf[0] = sum1;
  for (int i = 0; i < n; i++) {
    gq.push(mid[i]);
    sumf[i + 1] = sumf[i] + mid[i] - gq.top();
    gq.pop();
  }
  sums[n] = sum2;
  for (int i = n - 1; i >= 0; i--) {
    lq.push(mid[i]);
    sums[i] = sums[i + 1] + mid[i] - lq.top();
    lq.pop();
  }
  int answer = sumf[n] - sums[n];
  for (int i = 0; i < n; i++) {
    if (answer <= sumf[i] - sums[i]) {
      answer = sumf[i] - sums[i];
    }
  }
  cout << answer << endl;
  return 0;
}

