  repe(i, 1, N) {
    ll mi = que.top();
    ll na = a[N + i];
    if (na > mi) {
      csum[i] = csum[i - 1] + na - mi;
      que.pop();
      que.push(na);
    } else {
      csum[i] = csum[i - 1];
    }
  }

  priority_queue<int> rque;
  ll rsum = 0;
  rep(i, 0, N) {
    rque.push(a[3 * N - i]);
    rsum += a[3 * N - i];
  }

  rcsum[N] = rsum;
  repe(i, 1, N) {
    ll ma = rque.top();
    ll na = a[2 * N + 1 - i];
    if (na < ma) {
      rcsum[N - i] = rcsum[N - i + 1] - ma + na;
      rque.pop();
      rque.push(na);
    } else {
      rcsum[N - i] = rcsum[N - i + 1];
    }
  }

  ll ans = MINF;
  repe(i, 0, N) { chmax(ans, csum[i] - rcsum[i]); }
  cout << ans;
}

