using namespace std;

int main()
{

	int num_count;
	cin >> num_count;

	vector<int> nums( num_count*3 );

	for( int i = 0; i < nums.size(); ++i )
		cin >> nums[i];

	vector<long long> plus(num_count), minus(num_count);	
	int lp, rp;

	for( lp = 0; lp < num_count; ++lp ) plus[lp] = nums[lp];
	for( rp = nums.size()-1; rp > nums.size()-num_count-1; --rp ) minus[nums.size()-rp-1] = nums[rp];

	long long answer = numeric_limits<long long>::min();
	stack < vector<long long> > st_plus, st_minus;
	stack < long long > st_count;
	stack < int > st_lp, st_rp;
	st_plus.push( plus );
	st_minus.push( minus );
	st_count.push( num_count );
	st_lp.push( lp );
	st_rp.push( rp );

	while( st_plus.size() != 0 )
	{

		long long num = st_count.top(); st_count.pop();
		vector< long long > plus = st_plus.top(); st_plus.pop();
		vector< long long > minus = st_minus.top(); st_minus.pop();
		int left_position = st_lp.top(); st_lp.pop();
		int right_position = st_rp.top(); st_rp.pop();

		while( num-- > 0 )
		{

			long long min_num = numeric_limits<long long>::max();
			int min_pos; 
			for( int i = 0; i < plus.size(); ++i )
			{
				if( min_num > plus[i] )
				{
					min_pos = i;
					min_num = plus[i];
				}
			}

			long long max_num = numeric_limits<long long>::min();
			int max_pos;
			for( int i = 0; i < minus.size(); ++i )
			{
				if( max_num < minus[i] )
				{
					max_pos = i;
					max_num = minus[i];
				}
			}

			if( nums[left_position] - min_num < max_num - nums[right_position] )
				minus[max_pos] = nums[right_position--];
			else if( nums[left_position] - min_num > max_num - nums[right_position] )
				plus[min_pos] = nums[left_position++];
			else
			{
				{
					vector < long long > temp = minus;
					temp[max_pos] = nums[right_position];
					st_count.push( num - 1 );
					st_plus.push( plus );
					st_minus.push( temp );
					st_lp.push( left_position - 1 );
					st_rp.push( right_position );
				}

				plus[min_pos] = nums[left_position++];

			}

		}
		long long total = 0;
		for( int i = 0; i < plus.size(); ++i ) total -= minus[i];
		for( int i = 0; i < minus.size(); ++i ) total += plus[i];
		if( answer < total ) answer = total;
	}


	cout << answer << endl;
	return 0;	

}

