int main(){

	int N;
	std::cin >> N;

	std::vector<int> buf(3*N, 0);

	for (int i = 0; i < 3*N; ++i) {
		std::cin >> buf[i];
	}

	int64_t topsum = 0;
	std::multiset<int> topset{};
	for (int i = 0; i < N; ++i) {
		topsum += buf[i];
		topset.insert(buf[i]);
	}

	std::multiset<int> botsetSub{}; // 末尾範囲で末尾最小和に含まれないもの
	for (int i = N; i < 3*N; ++i) {
		botsetSub.insert(buf[i]);
	}

	int64_t botsum = 0;
	std::multiset<int> botset{};
	{
		auto itSub = botsetSub.begin();
		for (int i = 0; i < N; ++i) {
			botsum += *itSub;
			botset.insert(*itSub);
			++itSub;
		}
		botsetSub.erase(botsetSub.begin(), itSub);
	} // itSub

	int64_t maxans = topsum - botsum; // 初期状態の答え

	for (int i = 0; i < N; ++i) {
		int val = buf[N + i];

		auto itTop = topset.begin();
		int topmin = *itTop;
		if(val > topmin){
			topsum += val - topmin;
			topset.erase(topset.begin());
			topset.insert(val);
		}

		auto itBot = botset.find(val);
		if (itBot != botset.end()) {
			botset.erase(itBot);

			auto itBotSub = botsetSub.begin();
			int newval = *itBotSub;
			botsetSub.erase(itBotSub);
			botset.insert(newval);

			botsum += newval - val;
		}
		else {
			botsetSub.erase(botsetSub.find(val));
		}

		maxans = (std::max)(maxans, topsum - botsum); // N+i番目までとそれ以降を範囲とした時の答え
	}

	std::cout << maxans << std::endl;

	return 0;
}

