using namespace std;
const int BUF = 300005;
const long long INF = 1LL << 60;

class State {
public:
    int nChoosePre;
    int nChoosePost;

    State(){}
    State(int nChoosePre, int nChoosePost) :
        nChoosePre(nChoosePre), nChoosePost(nChoosePost) {}

    bool operator< (const State &opp) const {
        if (nChoosePre != opp.nChoosePre) return nChoosePre < opp.nChoosePre;
        return nChoosePost < opp.nChoosePost;
    }
};


int N;
int vList[BUF];

void read() {
    cin >> N;
    for (int i = 0; i < N * 3; ++i) {
        cin >> vList[i];
    }
}

long long rec(int index, State &st, map<State, long long> dp[BUF]) {
    if (st.nChoosePre == N && st.nChoosePost == N) {
        return dp[index][st] = 0;
    }

    if (dp[index].count(st)) {
        return dp[index][st];
    }

    long long ret = -INF;

    int val = vList[index];

    if (st.nChoosePre == N) {
        if (st.nChoosePost + (3 * N - index) == N) {
            st.nChoosePost++;
            ret = max(ret, rec(index + 1, st, dp) - val);
            st.nChoosePost--;
        } else {
            ret = max(ret, rec(index + 1, st, dp));

            st.nChoosePost++;
            ret = max(ret, rec(index + 1, st, dp) - val);
            st.nChoosePost--;
        }
    } else {
        if (index - st.nChoosePre == N) {
            st.nChoosePre++;
            ret = max(ret, rec(index + 1, st, dp) + val);
            st.nChoosePre--;
        } else {
            ret = max(ret, rec(index + 1, st, dp));

            st.nChoosePre++;
            ret = max(ret, rec(index + 1, st, dp) + val);
            st.nChoosePre--;
        }
    }

    return dp[index][st] = ret;
}


void work() {
    static map<State, long long> dp[BUF];
    State init = State(0, 0);
    cout << rec(0, init, dp) << endl;
}


int main() {
    read();
    work();
    return 0;
}

