            fque.push(A[i]);
            int r = fque.top();
            fque.pop();
            fsum -= r;
        }
        priority_queue<int> sque;
        int ssum = 0;
        FOR(i, k, k + N) {
            sque.push(A[i]);
            ssum += A[i];
        }
        FOR(i, k + N, 3 * N) {
            ssum += A[i];
            sque.push(A[i]);
            int r = sque.top();
            sque.pop();
            ssum += r;
        }
        ans = max(ans, fsum - ssum);
    }

    return 0;
}

