int main() {
	priority_queue <int> pq_right,pqr_def; // default 大きい順
	priority_queue<int, vector<int>, greater<int> > pq_left,pql_def; // 小さい順
	int N;
	cin >> N;
	vector<int> arr;
	for (int i = 0; i < 3*N; i++){
		int tmp;
		cin >> tmp;
		arr.push_back(tmp);
	}
	//int sikiri = N-1;	//leftはsikiriまで含む。
	int left=0;
	int right=0;
	for (int i = 0; i < N; i++){
		left += arr[i];
		pq_left.push(arr[i]);
		right += arr[3*N - 1 - i];
		pq_right.push(arr[3*N - 1 - i]);
	}
	//leftを更新
	int left_def = left;
	int right_def = right;
	pqr_def = pq_right;
	pql_def = pq_left;
	int ans = (1<<15)*-1;
	for (int sikiri = N - 1; sikiri < 2*N; sikiri++){
		left = left_def;
		right = right_def;
		pq_left = pql_def;
		pq_right = pqr_def;
		for (int i = N ; i <= sikiri; i++){
			left += arr[i];
			pq_left.push(arr[i]);
			left -= pq_left.top();
			pq_left.pop();
		}
		for (int i = 2 * N-1; i > sikiri; i--){
			right += arr[i];
			pq_right.push(arr[i]);
			right -= pq_right.top();
			pq_right.pop();
		}
		if (left - right > ans){
			ans = left - right;
		}
	}
	cout << ans << endl;


	return 0;
}

