        partial_sort(Y.begin() + N + n, Y.begin() + 2 * N, Y.end(), greater<i64>());
        if (n == 0) {
            REP (i, N) {
                score += X[i + n];
            }
            REP (i, N) {
                score -= Y[i + 2 * N - n];
            }
        } else {
            // move v (Y -> X)
            auto v = as[n + N - 1];
            if (X[n - 1] < v) {
                score -= X[n -1];
                score += v;
            }

            if (Y[2 * N - 1] > v) {
                score += v;
                score -= Y[2 * N - 1];
            }
        }
        result = max(result, score);
    }
    cout << result << endl;
}

