	for (int i = 1; i <= 3 * N; i++) {
		da[i] += da[i - 1] + a[i];
	}

	vector<ll> tl;
	tl.assign(&a[1], &a[N + 1]);
	sort(tl.begin(), tl.end());
	vector<ll> dl(N + 1, 0);
	for (int i = 1; i <= N; i++) {
		int it = upper_bound(tl.begin(), tl.end(), a[i + N]) - tl.begin();
		if ((it == tl.size()) || (it >= i)) {
			dl[i] += dl[i - 1] + tl[i - 1];
		} else if (it < i) {
			dl[i] += dl[i - 1] + a[i + N];
		}
		tl.push_back(a[i + N]);
		sort(tl.begin(), tl.end());
	}

	vector<ll> tr;
	tr.assign(&a[2 * N + 1], &a[3 * N + 1]);
