// Data Structure
template <class T, class Compare = std::less<T>>
struct heap {
    heap () : m_heap(), m_cmp() {
    }
    heap (const V<T> &v) : m_heap(v), m_cmp() {
        make_heap(this->m_heap.begin(), this->m_heap.end(), this->m_cmp);
    }
    heap (const Compare &cmp) : m_heap(), m_cmp(cmp) {
    }
    heap (const V<T> &v, const Compare &cmp) : m_heap(v), m_cmp(cmp) {
        make_heap(this->m_heap.begin(), this->m_heap.end(), this->m_cmp);
    }

    void reserve(size_t size) {
        this->m_heap.reserve(size);
    }

    const T &top() const {
        return this->m_heap.front();
    }
    T pop() {
        pop_heap(this->m_heap.begin(), this->m_heap.end(), this->m_cmp);
        auto retval = this->m_heap.back();
        this->m_heap.pop_back();
        return retval;
    }
    void push(const T &v) {
        this->m_heap.push_back(v);
        push_heap(this->m_heap.begin(), this->m_heap.end(), this->m_cmp);
    }

    auto begin() const {
        return this->m_heap.cbegin();
    }
    auto cbegin() const {
        return this->m_heap.cbegin();
    }
    auto end() const {
        return this->m_heap.cend();
    }
    auto cend() const {
        return this->m_heap.cend();
    }
private:
    V<T> m_heap;
    Compare m_cmp;
};

// Body
void body() {
    using namespace debug;
    auto N = read<i32>();
    auto as = read<i64>(3 * N);

    i64 result = numeric_limits<i64>::min();

    auto max_sum = V<i64>(N + 1);
    auto min_sum = V<i64>(N + 1);
    auto tmp = V<i64>(N);
    {
        REP (i, N) {
            tmp[i] = as[i];
        }
        auto X = heap<i64, greater<i64>>(tmp);
        X.reserve(N + 1);

        max_sum[0] = accumulate(X.begin(), X.end(), 0);
        FOR (k, 1, N + 1) {
            X.push(as[k + N - 1]);
            max_sum[k] = max_sum[k - 1] + as[k + N - 1] - X.pop();
        }
    }
    {
        REP (i, N) {
            tmp[i] = -as[i + 2*N];
        }
        auto X = heap<i64, greater<i64>>(tmp);
        X.reserve(N + 1);

        min_sum[N] = accumulate(X.begin(), X.end(), 0);
        FOR (k, 1, N + 1) {
            X.push(-as[2 * N - k]);
            min_sum[N - k] = min_sum[N - k + 1] - as[2 * N - k] - X.pop();

        }
    }

    REP (k, N + 1) {
        auto score = max_sum[k] + min_sum[k];
        result = max(score, result);
    }
    cout << result << endl;
}

