const ll N = 300003;
ll n,a[N],ans=0;
ll hi[N],mi[N];
priority_queue<ll> hiq,miq;
int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin>>n;
	FOR(i,0,3*n)cin>>a[i];

	FOR(i,0,3*n){
		hi[i]=-INF;
		mi[i]=INF;
	}
	ll w=0;
	FOR(i,0,n){
		hiq.push(-a[i]);
		w+=a[i];
		hi[i]=-INF;
	}
	hi[n-1]=w;
	FOR(i,n,2*n){
		ll k=-hiq.top();
		if(k<a[i]){
			hiq.pop();
			w-=k;
			w+=a[i];
			hiq.push(-a[i]);
		}
		hi[i]=w;
	}


	w=0;
	FOR(i,0,n){
		ll j=3*n-i-1;
		w+=a[j];
		miq.push(a[j]);
		mi[3*n-1-i]=INF;
	}
	for(ll i=2*n-1;i>=n-1;i--){
		ll k=miq.top();
		if(k>a[i]){
			miq.pop();
			w+=a[i];
			w-=k;
			miq.push(a[i]);
		}
		mi[i]=w;
	}


	ans=hi[n]-mi[n+1];
	FOR(i,n-1,2*n-1){
		ans=max(ans,hi[i]-mi[i+1]);
	}
	cout<<ans<<endl;
	return 0;
}

