  }
  ll ans = INF;
  for (int i = n; i <= 2 * n; ++i) {
//    printf("%3d\t%3d\t%3d\n", a[i], dp[i], dp2[i + 1]);
    ans = max(ans, dp[i] - dp2[i + 1]);
  }
