// main function
int main()
{
	ll N = 0;
	ll ans = 0;
	ll cnt = 0;
	multiset<ll> head_set;
	multiset<ll> tail_set;
	multiset<ll>::iterator head_set_itr = head_set.begin();
	multiset<ll>::iterator tail_set_itr = tail_set.begin();

	cin >> N;
	vector< ll > A(3 * N, 0);
	Rep(i, 3 * N){
		cin >> A[i];
		if (i < N) {
			head_set.insert(A[i]);
		}
		else if (i >= 2 * N) {
			tail_set.insert(A[i]);
		}
	}

	// min{a0, a1, ...aN-1}とaN
	// a2N-1とMAX{a2N, a2N+1, ..., a3N-1}を比較
	// N回繰り返す
	ll head_ptr = N;
	ll tail_ptr = 2 * N - 1;
	ll discard_index = 0;
	while ( cnt < N ) {
		// scoreがどれだけ上がるか比較
		head_set_itr = head_set.begin();
		multiset<ll>::reverse_iterator tail_set_revitr = tail_set.rbegin();
		ll head_up_score = A[head_ptr] - *head_set_itr;
		ll tail_up_score = *tail_set_revitr - A[tail_ptr];

		if (head_up_score < 0 && tail_up_score < 0) {
			if (head_up_score >= tail_up_score) {
				// discard head_ptr
				head_ptr++;
			}
			else {
				// discard tail_ptr
				tail_ptr--;
			}
		}
		else{
			if (head_up_score >= tail_up_score) {
				// discard head
				head_set.erase(head_set_itr);
				head_set.insert(A[head_ptr]);
				head_ptr++;
			}
			else {
				// discard tail
				tail_set.erase( (++tail_set_revitr).base() );
				tail_set.insert(A[tail_ptr]);
				tail_ptr--;
			}
		}
		cnt++;
	}

	// calculate ans
	for (head_set_itr = head_set.begin(); head_set_itr != head_set.end(); head_set_itr++) {
		ans += *head_set_itr;
	}
	for (tail_set_itr = tail_set.begin(); tail_set_itr != tail_set.end(); tail_set_itr++) {
		ans -= *tail_set_itr;
	}

	cout << ans << endl;

	return 0;
}

