    lq.push(mid[i]);
    sums[i] = sums[i + 1] + mid[i] - lq.top();
    lq.pop();
  }
  ll answer = sumf[n] - sums[n];
  for (int i = 0; i < n; i++) {
    if (answer < sumf[i] - sums[i]) {
      answer = sumf[i] - sums[i];
    }
  }
  cout << answer << endl;
  return 0;
}

