  long N;
  cin >> N;
  vector<long> A(N * 3);
  priority_queue<long, vector<long>, greater<long>> LQ;
  priority_queue<long> RQ;
  long l = 0, r = 0;
  for (int i = 0, a; i < N * 3 && cin >> a; i++) {
    A.at(i) = a;
    if (i < N) {
      LQ.push(a);
      l += a;
    }
    if (i >= N * 2) {
      RQ.push(a);
      r += a;
    }
  }
  vector<long> L = { l };
  for (int i = N; i < N * 2; i++) {
    long t = LQ.top();
    if (t >= A.at(i)) {
      L.push_back(l);
      continue;
    }
    l += A.at(i) - t;
    L.push_back(l);
    LQ.pop();
    LQ.push(A.at(i));
  }
  vector<long> R = { r };
  for (int i = N * 2 - 1; i >= N; i--) {
    long t = RQ.top();
    if (t <= A.at(i)) {
      R.push_back(r);
      continue;
    }
    r -= t - A.at(i);
    R.push_back(r);
    RQ.pop();
    RQ.push(A.at(i));
  }
  reverse(R.begin(), R.end());
  long ans = -2e18;
  for (int i = 0; i < N + 1; i++) {
    ans = max(ans, L.at(i) - R.at(i));
  }
  cout << ans << "\n";
}

