void solve(){
    priority_queue<long> ba;
    priority_queue<long, vector<long>, greater<long> > fo;
    for(int i=0 ; i<n ; i++){
        fo.push(v[i]);
    }
    for(int i=2*n ; i<3*n ; i++){
        ba.push(v[i]);
