    while(l<r){
        int x = fo.top();   int y = ba.top();
        if(x<v[l]){
            fo.pop();
            fo.push(v[l]);
            v[l] = x;
        }
        l++;

        if(y>v[r]){
            ba.pop();
            ba.push(v[r]);
            v[r] = y;
        }
        r--;
    }
    if(l == r){
        if(fo.top()<v[l] && ba.top()>v[l]){
            if(v[l]-ba.top()<fo.top()-v[l]){
                ba.pop();
                ba.push(v[l]);
