void add(multiset<int> & s, ll & sum, int x)
{
	s.insert(x);
	sum += x;
	if (s.size() > n)
	{
		sum -= *s.begin();
		s.erase(s.begin());
	}
}
void addm(multiset<int>& s, ll& sum, int x)
{
	s.insert(x);
	sum += x;
	if (s.size() > n)
	{
		sum -= *s.rbegin();
		s.erase(s.find(*s.rbegin()));
	}
}
