int main()
{
    cin >> N;
    vector<ll> nums(3*N);
    for (auto &n : nums)
        cin >> n;

    vector<ll> formers(N+1);
    vector<ll> former(nums.begin(), nums.begin() + N);
    ll fSum = accumulate(former.begin(), former.end(), 0);
    formers[0] = fSum; cerr << fSum << endl;
    priority_queue< ll, vector<ll>, greater<ll> > fpq;
    for (auto f : former)
        fpq.push(f);
    for (int i = N; i < 2*N; ++i) {
        ll current = nums[i];
        fpq.push(current);
        fSum += current - fpq.top();
        fpq.pop();
        formers[i-N+1] = fSum;
        cerr << i << " : " << fSum << endl;
    }
    cerr << endl;
    vector<ll> latters(N+1);
    vector<ll> latter(nums.rbegin(), nums.rbegin() + N);
    ll lSum = accumulate(latter.begin(), latter.end(), 0);
    latters[0] = lSum; cerr << lSum << endl;
    priority_queue<ll> lpq;
    for (auto f : latter)
        lpq.push(f);
    for (int i = N; i < 2*N; ++i) {
        ll current = *(nums.rbegin() + i);
        lpq.push(current);
        lSum += current - lpq.top();
        lpq.pop();
        latters[i-N+1] = lSum;
        cerr << i << " : " << lSum << endl;
    }
    cerr << endl;
    auto fitr = formers.begin();
    auto litr = latters.rbegin();
    ll maximum = INT64_MIN;
    for (int i = 0; i < N; ++i) {
        //cerr << *(fitr++) << " " << *(litr++) << endl;
        maximum = max(maximum, *(fitr++) - *(litr++));
    }

    cout << maximum << endl;

    return 0;
}

