void solve() {
  pqasc<int> fr;
  pqdesc<int> ba;

  int N; cin >> N;
  vi32 a(3 * N); cin >> a;

  i64 fsum = 0, bsum = 0;
  rep(i, N) fr.push(a[i]), fsum += a[i];
  rep(i, N) ba.push(a[i + 2 * N]), bsum += a[i + 2 * N];

  vi64 fsums(N + 1), bsums(N + 1);
  fsums[0] = fsum, bsums[N] = bsum;

  for (int i = N; i < 2 * N; i++) {
    if (fr.top() < a[i]) {
      fsum = fsum - fr.top() + a[i];
      fr.pop(), fr.push(a[i]);
    }
    fsums[i - N + 1] = fsum;
  }
  for (int i = 2 * N - 1; i >= N; i--) {
    if (ba.top() > a[i]) {
      bsum = bsum - ba.top() + a[i];
      ba.pop(), ba.push(a[i]);
    }
    bsums[i - N] = bsum;
  }

  i64 ans = -1e18;
  rep(i, N + 1) amax(ans, fsums[i] - bsums[i]);
  cout << ans << '\n';
}

