        sum += arr[i];
        que.push(arr[i]);
    }

    for(int i = 0; i < k; i++){

        que.push(arr[i+k]);
        int a = que.top();
        que.pop();

        sum += arr[i+k]-a;

        resL[i] = sum;
    }

    /// left

    priority_queue<int> que1;
    sum = 0;

    for(int i = 1; i <= k; i++){
        sum += arr[3*k-i];
        que1.push(arr[3*k-i]);
