void solve(void)
{
  int N;
  cin>>N;
  vector<int> vec(3*N);
  for (int i = 0; i < 3*N; i++)
  {
    cin>>vec[i];
  }
  priority_queue<int, vector<int>, greater<int> >que;
  int SUM = 0;
  vector<int> data1(N+1),data2(N+1);

  for (int i = 0; i < N; i++)
  {
    que.push(vec[i]);
    SUM += vec[i];
  }
  data1[0] = SUM;


  for (int i = 0; i < N; i++)
  {
    SUM += vec[N+i];
    que.push(vec[N+i]);
    int A = que.top();
    que.pop();
    SUM -= A;
    data1[i+1] = SUM;
  }
  SUM = 0;

  priority_queue<int> que1;

  for (int i = 0; i < N; i++)
  {
    SUM += vec[3*N-1-i];
    que1.push(vec[3*N -1 - i]);
  }

  data2[0] = SUM;



  for (int i = 0; i < N; i++)
  {
    SUM += vec[2*N-i-1];
    que1.push(vec[2*N-i-1]);
    int A = que1.top();
    que1.pop();
    SUM -= A;
    data2[i+1] = SUM;
  }

  int ANS = -1*INF;
  for (int i = 0; i < N+1; i++)
  {
    chmax(ANS,data1[i] - data2[N-i]);
  }
  // DEBUG(data1);DEBUG(data2);
  cout<<ANS<<endl;





  return; 
}


