int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;

	vector<int> a(3 * N);
	for (int i = 0; i < 3 * N; i++) cin >> a[i];

	vector<lint> smax(3 * N, -LINF), smin(3 * N, LINF);

	// Max
	{
		priority_queue<int, vector<int>, greater<int>> pqmax;
		lint Mtmp = 0;
		for (int i = 0; i < N; i++) {
			pqmax.emplace(a[i]);
			Mtmp += a[i];
		}
		smax[N - 1] = Mtmp;
		for (int i = N; i < 2 * N; i++) {

			if (pqmax.top() < a[i]) {
				Mtmp += a[i] - pqmax.top();
				pqmax.pop();
				pqmax.emplace(a[i]);
			}

			smax[i] = Mtmp;
		}
	}

	// min
	{
		priority_queue<int> pqmin;
		lint mtmp = 0;
		for (int i = 3 * N - 1; i >= 2 * N; i--) {
			pqmin.emplace(a[i]);
			mtmp += a[i];
		}
		smin[2 * N] = mtmp;
		for (int i = 2 * N - 1; i >= N; i--) {

			if (pqmin.top() > a[i]) {
				mtmp += a[i] - pqmin.top();
				pqmin.pop();
				pqmin.emplace(a[i]);
			}

			smin[i] = mtmp;
		}
	}

	DMP(smax, smin);

	lint ans = -LINF;
	for (int i = N; i < 2 * N; i++) {
		ans = max(ans, smax[i - 1] - smin[i]);
	}

	cout << ans << "\n";

	return 0;
}

