using namespace std;


LL solve(int N, vector<LL> v) {
    vector<LL> leftMax(3 * N, 0);
    vector<LL> rightMin(3 * N, 0);

    {
        priority_queue<LL, vector<LL>, greater<LL>> left;
        LL total = 0;
        FOR(i, 0, N) {
            left.push(v[i]);
            total += v[i];
        }
        leftMax[N - 1] = total;
        FOR(i, N, v.size()) {
            left.push(v[i]);
            total += v[i] - left.top();
            leftMax[i] = total;
            left.pop();
        }
    }

    priority_queue<LL> right;
    {
        LL total = 0;
        for(int i = v.size() - 1; i >= 2 * N; --i) {
            right.push(v[i]);
            total += v[i];
        }
        rightMin[2 * N] = total;
        for(int i = 2 * N - 1; i >= 0; --i) {
            right.push(v[i]);
            total += v[i] - right.top();
            rightMin[i] = total;
            right.pop();
        }
    }

    LL ans = LLONG_MIN;
    FOR(i, N - 1, 2 * N) {
        ans = max(ans, leftMax[i] - rightMin[i + 1]);
    }

    return ans;
}


int main(int argc, char *argv[]) {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    vector<LL> v(3 * N, 0);
    LL x;
    FOR(i, 0, 3 * N) {
        cin >> x;
        v[i] = x;
    }
    std::cout << solve(N, v) << endl;

    return 0;
}

