void preCompute() {
    priority_queue<ll> pQ;
    ll sum = 0;
    for (int i = (3 * n) - 1 ; i >= 0 ; i--) {
        if ((int)pQ.size() >= n) {
            sum -= pQ.top();
            pQ.pop();
        }
        pQ.push(v[i]);
        sum += v[i];
        minim[i] = sum;
    }
    while (!pQ.empty()) pQ.pop();
    sum = 0;
    for (int i = 0 ; i < 3 * n ; i++) {
        if ((int)pQ.size() >= n) {
            sum -= abs(pQ.top());
            pQ.pop();
        }
        pQ.push(-v[i]);
        sum += v[i];
        maxim[i] = sum;
    }
}

