const int MAX_N = 100000;
int A[3 * MAX_N + 10];
signed main() {
    int N; cin >> N;
    for(int i=0; i<3*N; i++) {
        cin >> A[i];
    }

    priority_queue< int, vector<int>, greater<int> > que_l;
    priority_queue< pii, vector<pii>, greater<pii> > que_r;
    set<pii> topN_r;

    int sum_l = 0, sum_r = 0;
    for(int i=0; i<N; i++) {
        sum_l += A[i];
        que_l.push(A[i]);
    }
    for(int i=N; i<3*N; i++) {
        que_r.push(make_pair(A[i], i));
    }
    for(int i=0; i<N; i++) {
        pii val = que_r.top(); que_r.pop();
        // printf("add: index = %lld, val = %lld\n", val.second, val.first);
        topN_r.insert(val);
        sum_r += val.first;
    }

    int ans = sum_l - sum_r;
    // printf("initial: sum_l = %lld, sum_r = %lld, ans = %lld\n", sum_l, sum_r, ans);
    for(int i=N; i<2*N; i++) {
        // 動く要素
        int val = A[i];
        // printf("val = %lld\n", val);

        // 左側
        sum_l += val;
        que_l.push(val);
        int erase_l = que_l.top(); que_l.pop();
        // printf("insert %lld, erase %lld\n", val, erase_l);
        sum_l -= erase_l;

        // 右側
        pii elem = make_pair(A[i], i);
        if(topN_r.count(elem)) {
            sum_r -= A[i];
            topN_r.erase(elem);
            while(que_r.size()) {
                pii cur = que_r.top(); que_r.pop();
                if(cur.second <= i) continue;
                topN_r.insert(cur);
                sum_r += cur.first;
                break;
            }
        }
        // printf("end: index = %lld, sum_l = %lld, sum_r = %lld\n", i, sum_l, sum_r);
        chmax(ans, sum_l - sum_r);
    }
    cout << ans << endl;
    return 0;
}

