class CumulativeMax {
    vector<ll> numbers;
    vector<ll> maximum;
public:
    CumulativeMax(ll n) {
        numbers.resize(n);
        maximum.resize(n);
    }

    void set(ll i, ll n) {
        numbers[i] = n;
    }

    void calculate() {
        maximum[numbers.size() - 1] = numbers.back();
        for (ll i = numbers.size() - 2; i >= 0; i--) {
            maximum[i] = max(maximum[i + 1], numbers[i]);
        }
    }

    ll getMax(ll i) {
        return maximum[i];
    }

};

class Right {

    vector<ll> initial;
    multiset<ll> used;
    multiset<ll> ignore;
    queue<ll> all;

    ll score = 0;

public:
    Right(ll n) {
        initial.resize(n * 2);
    }

    void set(ll i, ll n) {
        initial[i] = n;
        all.push(n);
    }

    void calculate(ll n) {
        sort(initial.rbegin(), initial.rend());
        for (ll i = 0; i < n; i++) {
            ignore.insert(initial[i]);
        }
        for (int i = n; i < 2 * n; i++) {
            used.insert(initial[i]);
            score += initial[i];
        }
    }

    ll pop() {
        ll f = all.front();
        auto it = used.find(f);
        if (it != used.end()) {
            score -= f;
            auto ignore_it = ignore.begin();
            ll t = *ignore_it;
            ignore.erase(ignore_it);
            score += t;
            used.erase(it);
            used.insert(t);
        } else {
            auto ignore_it = ignore.find(f);
            ignore.erase(ignore_it);
        }
        all.pop();
        return f;
    }

    ll getScore() {
        return score;
    }

};


