int main() {
    int N;
    cin >> N;

    vector<ll> a(3 * N);
    for (int i = 0; i < 3 * N; i++) {
        cin >> a[i];
    }

    priority_queue<ll, vector<ll>, greater<ll>> pre_q;
    priority_queue<ll> suf_q;

    vector<ll> pre_sum(3 * N, 0),
               suf_sum(3 * N, 0);
    ll sum = 0;
    for (int i = 0; i < 3 * N; i++) {
        if (pre_q.size() < N) {
            pre_q.push(a[i]);
            sum += a[i];
        } else if (pre_q.top() < a[i]) {
            sum -= pre_q.top(); pre_q.pop();
            pre_q.push(a[i]);
            sum += a[i];
        }
        if (pre_q.size() == N) pre_sum[i] = sum;
        else pre_sum[i] = -INF;
    }

    sum = 0;
    for (int i = 3 * N - 1; i >= 0; i--) {
        if (suf_q.size() < N) {
            suf_q.push(a[i]);
            sum += a[i];
        } else if (suf_q.top() > a[i]){
            sum -= suf_q.top(); suf_q.pop();
            suf_q.push(a[i]);
            sum += a[i];
            suf_sum[i] = sum;
        }
        if (suf_q.size() == N) suf_sum[i] = sum;
        else suf_sum[i] = INF;
    }

    ll ans = -INF;
    for (int i = 0; i < 3 * N - 1; i++) {
        ans = max(ans, pre_sum[i] - suf_sum[i + 1]);
    }
    cout << ans << endl;

    return 0;
}

