vector<int> a;
void solve () {
    int n;
    cin >> n;
    vector<vector<long long>> m (3, vector<long long>(n));
    vector<long long> ans(3);
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < n; j++) {
            cin >> m[i][j];
            ans[i] += m[i][j];
        }
    }
    sort(m[0].begin(), m[0].end());
    sort (m[2].begin(), m[2].end());
    int end = 0;
    long long f = ans[0];
    for (int i = n - 1, j = n - 1; i >= 0; i--) {
        if (m[2][i] >= m[1][j]) {
            f -= m[2][i] - m[1][j];
            end = j;
            j--;
        }
    }
    long long s = ans[2];
    for (int i = 0, j = 0; i < n && j < end; i++) {
        if (m[1][i] <= m[2][j]) {
            s += m[2][j] - m[1][i];
            j++;
        }
    }
    long long mx = f - s;
    end = 0;
    for (int i = 0, j = 0; i < n; i++) {
        if (m[0][i] <= m[1][j]) {
            ans[0] += m[1][j] - m[0][i];
            end = j;
            j++;
        }
    }
    for (int i = n - 1, j = n - 1; j > end && i >= 0; i--) {
        if (m[2][i] >= m[1][j]) {
            ans[2] -= m[2][i] - m[1][j];
            j--;
        }
    }
    //cout << ans[0] << " " << ans[2] << endl;
    cout << max(mx, ans[0] - ans[2]);
}

