using namespace std;
typedef long long ll;
typedef vector<ll> vec;

ll sum_max(vec v, long st, long en, long n){
  sort(v.begin()+st, v.begin()+en);
  ll sum=0;
  for(long i=en-1; i>=en-n; i--)
    sum+=v[i];
  return sum;
}

ll sum_min(vec v, long st, long en, long n){
  sort(v.begin()+st, v.begin()+en);
  ll sum=0;
  for(long i=st; i<st+n; i++)
    sum+=v[i];
  return sum;
}

int main(){
  long n;
  cin >> n;
  long size=3*n;
  vec v;
  for(long i=0; i<size; i++){
    ll a;
    cin >> a;
    v.push_back(a);
  }
  ll ans=-1;
  for(long i=n; i<=2*n; i++){
    ll max_=sum_max(v,0,i,n)-sum_min(v,i,size,n);
    ans=ans>max_?ans:max_;
  }
  cout << ans << endl;
}

