	freopen("input.in", "r", stdin);
	freopen("output.o", "w", stdout);
	int n;
	scanf("%d", &n);
	for (int i = 1; i <= 3 * n; i++) scanf("%d", &a[i]);
	int cs = 0;
	for (int i = 1; i <= n; i++) {
		pq.push(a[i]);
		cs += a[i];
	}
	dp1[n] = cs;
	for (int i = n + 1; i <= 2 * n; i++) {
		int smallest = pq.top();
		if (a[i] > smallest) {
			cs += a[i];
			cs -= smallest;
			dp1[i] = cs;
			pq.pop();
			pq.push(a[i]);
		} else {
			dp1[i] = cs;
		}
	}
	cs = 0;
	while (!pq.empty()) pq.pop();
	for (int i = 3 * n; i >= 2 * n + 1; i--) {
		cs += a[i];
		pq2.push(a[i]);
	}
	dp2[2*n+1] = cs;
	for(int i=2*n;i>=n+1;i--){
		int largest = pq2.top();
		if (a[i] < largest) {
			cs += a[i];
			cs -= largest;
			dp2[i]=cs;
			pq2.pop();
			pq2.push(a[i]);
		} else {
			dp2[i] = cs;
		}
