priority_queue<ll> pq2;                           // max heap
ll a[333333], prefix1[333333], prefix2[333333];

int main(void)
{
    ll n, i;

	scanf("%lld" ,&n);
	for (i = 1; i <= 3 * n; i++)
		scanf("%lld" ,&a[i]);

	for (i = 1; i <= 2 * n; i++)
		if (i <= n)
		{
			prefix1[i] = prefix1[i - 1] + a[i];
			pq1.push(a[i]);
		}
		else
		{
            ll tp = pq1.top();

            if (a[i] > tp)
			{
				prefix1[i] = prefix1[i - 1] + a[i] - tp;
				pq1.pop();

				pq1.push(a[i]);
			}
			else
				prefix1[i] = prefix1[i - 1];
		}

    for (i = 3 * n; i >= n + 1; i--)
		if (i >= 2 * n + 1)
		{
			prefix2[i] = prefix2[i + 1] + a[i];
			pq2.push(a[i]);
		}
		else
		{
            ll tp = pq2.top();

			if (a[i] < tp)
			{
                prefix2[i] = prefix2[i + 1] + a[i] - tp;
                pq2.pop();

                pq2.push(a[i]);
			}
			else
				prefix2[i] = prefix2[i + 1];
		}

	ll ans = -1e18;
    for (i = n; i <= 2 * n; i++)
        ans = max(ans, prefix1[i] - prefix2[i + 1]);

	printf("%d" ,ans);
	return 0;
