#define REP(i,k,n) for(int(i)=(k);(i)<(n);++(i))
using namespace std;
typedef long long ll;

const ll INF = 1e10;
const int MAX_N = int(1e5) + 10;
int N;
ll a[3 * MAX_N];

int main()
{
  cin >> N;
  REP(i,0, 3*N) cin >> a[i];

  ll max_score = -INF;
  // [N,2N] の間で k を探す
  REP(k,N,2*N+1) {
    // [0,k) のうちで，大きい方からN個の和 s1
    priority_queue<ll> q1;
    REP(i,0,k) q1.push(a[i]);
    ll s1 = 0;
    REP(i,0,N) {
      s1 += q1.top();
      q1.pop();
    }

    // [k,3N) のうちで，小さい方からN個の和 s2
    // 小さい方から取り出したいので，greater
    priority_queue<ll, vector<ll>, greater<ll> > q2;
    REP(i,k,3*N) q2.push(a[i]);
    ll s2 = 0;
    REP(i,0,N) {
      s2 += q2.top(); q2.pop();
    }

    // update max
    max_score = max(max_score, s1 - s2);
  }

  cout << max_score << endl;

  return 0;
}

