#define int long long int
int function(int arr[],int index,int n,int memo[])
{
	if(memo[index]!=-1)
	{
		return memo[index];
	}
	else
	{
		int j;
		bool result=false;
		int val=arr[index];
		for(j=index+val;j<=n;j+=val)
		{
			if(arr[j]>arr[index])
			{
				int here=function(arr,j,n,memo);
				if(here==0)
				{
					result=true;
					break;
				}
			}
		}
		for(j=index-val;j>=1;j-=val)
		{
			if(arr[j]>arr[index])
			{
				int here=function(arr,j,n,memo);
				if(here==0)
				{
					result=true;
				}
			}
		}
		if(result)
		{
			memo[index]=1;
			return 1;
		}
		else
		{
			memo[index]=0;
			return 0;
		}
	}
}
