	 int n;
	 cin>>n;
	 int arr[3*n+1];
	 int j;
	 for(j=1;j<=3*n;j++)
	 {
		 cin>>arr[j];
	 }
	 int prefix[3*n+1]={0};
	 int sum=0;
	 multiset<int> st;
	 for(j=1;j<=n;j++)
	 {
		 sum+=arr[j];
		 st.insert(arr[j]);
	 }
	 prefix[n]=sum;
	 for(j=n+1;j<=2*n;j++)
	 {
		 int x=arr[j];
		 int y=*st.begin();
		 if(x>y)
		 {
			 st.erase(st.begin());
			 st.insert(x);
			 sum+=(x-y);
		 }
		 prefix[j]=sum;
	 }
	 int suffix[3*n+1];
	 multiset<int> st2;
	 int sum2=0;
	 for(j=3*n;j>2*n;j--)
	 {
		 sum2+=arr[j];
		 st2.insert(arr[j]);
	 }
	 suffix[2*n+1]=sum2;
	 for(j=2*n;j>n;j--)
	 {
		 int x=arr[j];
		 int y=*st2.rbegin();
		 if(x<y)
		 {
			 auto it=st2.end();
			 it--;
			 st2.erase(it);
			 st2.insert(x);
			 sum2+=(x-y);
		 }
		 suffix[j]=sum2;
	 }
	 int answer=-1000000000000000000;
	 for(j=n;j<=2*n;j++)
	 {
		 int here=prefix[j]-suffix[j+1];
		 answer=max(answer,here);
	 }
	 cout<<answer<<endl;
}

