int main(void){
    ll N, A[300100], ans=-1e15;
    in(N);
    rep(i,3*N) in(A[i]);

    ll score[2][100100];//0行目に a'の前半N要素　1行目に後半N要素　0～Nまで
    //kをN～2Nまでインクリメント。各kでのscoreをmaxにしたい
    //queueの最小値をpopしたい
    score[0][0] = 0;
    rep(i, N){           //O(N*logN)
        PQ_push2(A[i]);
        score[0][0] += A[i];
    }
    rep(k, N){           //O(N*logN)
        score[0][1+k] = score[0][k];//最適な結果を引き継ぐ
        score[0][1+k] += A[N+k];
        PQ_push2(A[k+N]);
        score[0][1+k] -= PQ_pop2();
    }

    //queueをリセット
    heap_idx = -1;

    //各kでのscoreをminにしたい
    //queueの最大値をpopしたい
    ll end = 3*N-1;
    score[1][N] = 0;
    rep(i, N){
        score[1][N] += A[end - i];
        PQ_push(A[end - i]);
    }
    rep(k, N){
        score[1][N-1-k] = score[1][N-k];
        score[1][N-1-k] += A[end-N-k];
        PQ_push(A[end-N-k]);
        score[1][N-1-k] -= PQ_pop();
    }

    //最大値を見つける
    rep(i, N+1) chmax(ans, score[0][i]-score[1][i]);
    put(ans);
    return 0;
}

