int32_t N;
int64_t a[334334];

int64_t kohan_sum_cache[334334];

struct heap_t {
	int32_t count;
	int64_t data[334334];
};

struct heap_t zenhan, kohan;

void heap_adjust(int64_t heap[], int64_t heap_count, int32_t pos) {
	for (;;) {
		int32_t next_idx = pos;
		int64_t next_value = heap[pos];
		if (pos * 2 + 1 < heap_count && heap[pos * 2 + 1] < next_value) {
			next_value = heap[next_idx = pos * 2 + 1];
		}
		if (pos * 2 + 2 < heap_count && heap[pos * 2 + 2] < next_value) {
			next_value = heap[next_idx = pos * 2 + 2];
		}
		if (next_idx == pos) {
			if (pos == 0) break;
			pos = (pos - 1) / 2;
		} else {
			int64_t t = heap[pos];
			heap[pos] = heap[next_idx];
			heap[next_idx] = t;
			pos = next_idx;
		}
	}
}

void heap_add(struct heap_t* heap, int64_t num) {
	heap->data[heap->count++] = num;
	heap_adjust(heap->data, heap->count, heap->count - 1);
}

int64_t heap_top(const struct heap_t* heap) {
	return heap->count <= 0 ? 0 : heap->data[0];
}

void heap_pop(struct heap_t* heap) {
	if (heap->count > 1) heap->data[0] = heap->data[heap->count - 1];
	if (heap->count > 0) {
		heap->count--;
		heap_adjust(heap->data, heap->count, 0);
	}
}

int main(void) {
	int32_t i;
	int64_t zenhan_sum = 0, kohan_sum = 0;
	int64_t answer;
	if (scanf("%" SCNd32, &N) != 1) return 1;
	for (i = 0; i < 3 * N; i++) {
		if (scanf("%" SCNd64, &a[i]) != 1) return 1;
	}
	for (i = 0; i < N; i++) {
		heap_add(&zenhan, a[i]);
		heap_add(&kohan, -a[3 * N - 1 - i]);
		zenhan_sum += a[i];
		kohan_sum -= a[3 * N - 1 - i];
	}
	kohan_sum_cache[N] = kohan_sum;
	for (i = 0; i < N; i++) {
		heap_add(&kohan, -a[2 * N - 1 - i]);
		kohan_sum = kohan_sum - a[2 * N - 1 - i] - heap_top(&kohan);
		heap_pop(&kohan);
		kohan_sum_cache[N - 1 - i] = kohan_sum;
	}
	answer = zenhan_sum + kohan_sum_cache[0];
	for (i = 0; i < N; i++) {
		heap_add(&zenhan, a[N + i]);
		zenhan_sum = zenhan_sum + a[N + i] - heap_top(&zenhan);
		heap_pop(&zenhan);
		if (zenhan_sum + kohan_sum_cache[i + 1] > answer) answer = zenhan_sum + kohan_sum_cache[i + 1];
	}
	printf("%" PRId64 "\n", answer);
	return 0;
}

