void swap(long long a[], int k, int i)
{
  int tmp;
  tmp = a[k];
  a[k] = a[i];
  a[i] = tmp;
}

void downheap1(long long a[], int k, int j)
{
  int i;
  i = k * 2 + 1;
  while(i <= j){
    if(i < j && a[i+1] > a[i]) i++;
    if(a[k] >= a[i]) break;
    swap(a, k, i);
    k = i;
    i = k * 2 + 1;
  }
}

void sort1(long long a[], int n)
{
  int j = n-1;
  int k = (n-1)/2;
  int i;
  while(k >= 0){
    downheap1(a, k, j);
    k--;
  }
}

void downheap2(long long a[], int k, int j)
{
  int i;
  i = k * 2 + 1;
  while(i <= j){
    if(i < j && a[i+1] < a[i]) i++;
    if(a[k] <= a[i]) break;
    swap(a, k, i);
    k = i;
    i = k * 2 + 1;
  }
}

void sort2(long long a[], int n)
{
  int j = n-1;
  int k = (n-1)/2;

  while(k >= 0){
    downheap2(a, k, j);
    k--;
  }
}


