// ヒープ - 親子関係チェック
// 戻り値：[>=0]:変更した子の配列番号 [-1]:変更なし
int
fHeapChk(
	int piMode					// <I> 昇順 or 降順
	, int piPNo					// <I> 親の配列番号 0～
)
{
	// 最小値 or 最大値
	int liMNo = piPNo;

	// 左の子と比較
	int liCNo = piPNo * 2 + 1;
	if (liCNo < siHCnt) {
		if (si1Heap[liMNo] * piMode > si1Heap[liCNo] * piMode) {
			liMNo = liCNo;
		}
	}

	// 右の子と比較
	liCNo = piPNo * 2 + 2;
	if (liCNo < siHCnt) {
		if (si1Heap[liMNo] * piMode > si1Heap[liCNo] * piMode) {
			liMNo = liCNo;
		}
	}

	// 自分が最小値(最大値)であるかチェック
	if (piPNo == liMNo) {
		return -1;
	}

	// 値の交換
	int liWork;
	liWork = si1Heap[liMNo];
	si1Heap[liMNo] = si1Heap[piPNo];
	si1Heap[piPNo] = liWork;

	return liMNo;
}

