fHeapEnqueue(
	int piMode					// <I> 昇順 or 降順
	, int piVal					// <I> 値
)
{
	int liRet;

	// 末尾に追加
	si1Heap[siHCnt] = piVal;
	siHCnt++;

	// 親子関係チェック
	int liNo = siHCnt - 1;
	while (1) {

		// 親の配列番号
		liNo = (liNo - 1) / 2;

		// 親子関係チェック
		liRet = fHeapChk(piMode, liNo);
		if (liRet < 0) {
			break;
		}
	}

	return 0;
}

// ヒープ - キュー取得
int
fHeapDequeue(
	int piMode					// <I> 昇順 or 降順
	, int *pipRet				// <O> 取得値
)
{
	// データ数
	if (siHCnt < 1) {
		return -1;
	}

	// 取得
	*pipRet = si1Heap[0];
	siHCnt--;

	// データ数
	if (siHCnt < 1) {
		return 0;
	}

	// 末尾を先頭へ
	si1Heap[0] = si1Heap[siHCnt];

	// 親子関係チェック
	int liNo = 0;
	while (liNo >= 0) {
		liNo = fHeapChk(piMode, liNo);
	}

	return 0;
}

// 合計リストの作成
int
fMakeSum(
	int piMode					// <I> 昇順 or 降順
)
{
	int i;

	// ヒープ数
	siHCnt = 0;

	// 配列開始位置・対象配列
	int liNo;
	long long *llpSum;
	if (piMode == D_HEAP_UP) {
		liNo = 0;
		llpSum = sl1SumF;
	}
	else {
		liNo = siACnt * 3 - 1;
		llpSum = sl1SumS;
	}

	// １つ目の合計値作成・ヒープ作成
	llpSum[0] = 0;
	for (i = 0; i < siACnt; i++) {

		// 合計値
		llpSum[0] += (long long)si1Array[liNo];

		// ヒープに追加
		fHeapEnqueue(piMode, si1Array[liNo]);

		// 次の位置
		liNo += piMode;
	}

	// ２つ目以降の合計値作成
	for (i = 1; i <= siACnt; i++) {

		// ヒープに追加
		fHeapEnqueue(piMode, si1Array[liNo]);

		// ヒープ - キュー取得
		int liVal;
		fHeapDequeue(piMode, &liVal);

		// 合計値 = 差を加算
		llpSum[i] = llpSum[i - 1] + (long long)si1Array[liNo] - (long long)liVal;

		// 次の位置
		liNo += piMode;
	}

	return 0;
}

