    a[i+1]+=a[i];
  }
  //for(i=0;i<3*n;i++)printf("%4lld %4lld\n",a[i],b[i]);printf("\n");
  for(i=n;i<2*n;i++){
    hin(d[i]);
    a[i]+=d[i];
    a[i]-=N[hout()];
    a[i+1]+=a[i];
  }
  R=C=1;
  for(i=0;i<n;i++){
    hin(-d[m-i]);
    b[m-i]+=d[m-i];
    b[m-i-1]+=b[m-i];
  }
  for(i=n;i<2*n;i++){
    hin(-d[m-i]);
    b[m-i]+=d[m-i];
    b[m-i]+=N[hout()];
    b[m-i-1]+=b[m-i];
  }
  //for(i=0;i<3*n;i++)printf("%4lld %4lld\n",a[i],b[i]);
  for(i=0;i<n;i++){
