long long swfl=0;

long long ininf(long long x){
    if((x+swfl)%2){return -llinf;}else{return llinf;}
}

typedef struct{
long long node;
long long cost;
}data;

data heap[524288];
long long hsize=0;

void resheap(){
    hsize=0;
    long long i;
    heap[0].node=-1;
    heap[0].cost=ininf(1);
    for(i=1;i<262144;i++){
        heap[i].node=-1;
        heap[i].cost=ininf(0);
    }
}

long long swjud(data high,data low){
    if(swfl==0){
        if(high.cost > low.cost){return 1;}else{return -1;}
    }
    else{
        if(high.cost < low.cost){return 1;}else{return -1;}
    }
}

void pqpush(data x){
    long long a,b;
    data m;
    hsize++;
    heap[hsize]=x;
    a=hsize;
    while(1){
        b=a/2;
        if(swjud(heap[b],heap[a]) == 1){
            m=heap[a];heap[a]=heap[b];heap[b]=m;
        }
        else{break;}
        a=b;
    }
}

data pqpop(){
    long long a,b,c;
    data m,sw;
    m=heap[1];
    heap[1]=heap[hsize];
    heap[hsize].node=-1;
    heap[hsize].cost=ininf(0);
    hsize--;
    a=1;
    while(1){
        b=a*2;c=a*2+1;
        if(swjud(heap[a],heap[b])==-1 && swjud(heap[a],heap[c])==-1){break;}
        if(swjud(heap[b],heap[c])==-1){
            sw=heap[a];heap[a]=heap[b];heap[b]=sw;
            a=b;
        }
        else{
            sw=heap[a];heap[a]=heap[c];heap[c]=sw;
            a=c;
        }
    }
    return m;
}

int main(void){
    long long res,rw,i,j,n,zh[131072],kh[131072],a[524288];
    data x;
    resheap();
    scanf("%lld",&n);
    for(i=1;i<=3*n;i++){scanf("%lld",&a[i]);}
    rw=0;
    for(i=1;i<=n;i++){
        x.node=i;x.cost=a[i];
        pqpush(x);
        rw+=a[i];
    }
    zh[0]=rw;
    for(i=n+1;i<=2*n;i++){
        x.node=i;x.cost=a[i];
        pqpush(x);
        rw+=a[i];
        x=pqpop();
        rw-=x.cost;
        zh[i-n]=rw;
    }
    swfl=1;
    resheap();
    rw=0;
    for(i=2*n+1;i<=3*n;i++){
        x.node=i;x.cost=a[i];
        pqpush(x);
        rw+=a[i];
    }
    kh[n]=rw;
    for(i=2*n;i>=n+1;i--){
        x.node=i;x.cost=a[i];
        pqpush(x);
        rw+=a[i];
        x=pqpop();
        rw-=x.cost;
        kh[i-n-1]=rw;
    }
    res=-llinf;
    for(i=0;i<=n;i++){
        res=max(res,zh[i]-kh[i]);
    }
    printf("%lld\n",res);
    return 0;
}

