fun main(args: Array<String>) {
	val n = readLine()!!.toInt()
	val arr = readLine()!!.split(" ").map{ it.toLong() }.toLongArray()
	val comparator = compareBy(Pair<Long, Int>::first, Pair<Long, Int>::second)
	val fstSet = arr.sliceArray(0..(n - 1)).mapIndexed({i, v -> Pair(v, i)}).toSortedSet(comparator)
	val sndSet = arr.sliceArray(n..(3 * n - 1)).mapIndexed({i, v -> Pair(v, i + n)}).toSortedSet(comparator)
	val sndUnused = sortedSetOf<Pair<Long, Int>>(comparator)
	for (i in 1..n) {
		val p = sndSet.last()
		sndSet.remove(p)
		sndUnused.add(p)
	}
	var score = fstSet.fold(0L, {acc, p -> acc + p!!.first}) - sndSet.fold(0L, {acc, p -> acc + p!!.first})
	var ans = score
	for (i in n..(2 * n - 1)) {
		val p = fstSet.first()
		fstSet.remove(p)
		fstSet.add(Pair(arr[i], i))
		score -= p.first
		score += arr[i]
		if (sndSet.remove(Pair(arr[i], i))) {
			val p = sndUnused.first()
			sndUnused.remove(p)
			sndSet.add(p)
			score += arr[i]
			score -= p.first
		} else {
			sndUnused.remove(Pair(arr[i], i))
		}
		ans = Math.max(score, ans)
	}
	println(ans)	

}

import java.util.TreeMap

/**
 * (a'の前半N要素) first、取り除かれたN 個の要素 removed、(a'の後半N要素) last の3つに分かれる。
 * 仮にfirstが、aのm番目までに存在することがわかっているとすると、
 * (a'の前半N要素の総和)−(a'の後半N要素の総和)の最大値は
 * (aのm番目までのうち小さい方からm-N個を除いたものの総和) - (aのm番目よりも後の3N-m個のうち、大きい方から2N-m個を除いたものの総和)
 * となる。
 *
 * mが1増えると、
 *
 * (firstの総和)は、
 * aのm+1番目の要素分だけ増え、
 * firstに、aのm+1番目の要素を加えた集合の中の最小のものの分だけ、減少する。
 *
 * (lastの総和)は、
 * aのm+1番目の要素が、除かれる2N-m個に入っていた場合は、変化せず、
 * そうでない場合は、
 * aのm+1番目の要素の分だけ減り、
 * 除かれる2N-m個のうち最小のものの分だけ増える。
 *
 * mはNから2Nまで変化するので繰り返しはN+1回
 * 大小の探索は、木構造を使えばlogNで可能と思われ、
 * O(N logN)で可能か。
 */
fun main(args: Array<String>) {
    val n = readLine()!!.toInt()    // 1≤N≤10^5
    val a = readLine()!!.split(" ").map(String::toInt)      // 1≤ai≤10^9

    val first = a.take(n)//.sorted()
    val remain = a.takeLast(2 * n).sorted()
    val removed = remain.takeLast(n)       // 大きい方から2N-m個を除いた

    // mがNのときで初期化
    val firstPart = FirstPart(first)
    val removedPart = RemovedPart(removed, remain.take(n))
    var result = firstPart.targetSum - removedPart.targetSum

    for (m in n .. n * 2 - 1) {     // コード上のmは0オリジン
        val e = a[m]
        firstPart.add(e)
        removedPart.remove(e)
        val score = firstPart.targetSum - removedPart.targetSum

        result = listOf(result, score).max()!!

    }
    println(result)
}


abstract internal class Part (list: List<Int>) {
    /** 値をkeyとして値がlistに含まれる回数を記録する。*/
    protected val data = TreeMap<Int, Int>()
    init {
        for (e in list) {
            this.data.increment(e)
        }
    }
    /** 目標とするものの総和。継承先により異なる。 */
    abstract var targetSum: Long      // intの上限を超えることあり。
        protected set

    /** dataにeの分を加える(+1する)*/
    protected fun MutableMap<Int, Int>.increment(e: Int) {
        this[e] = this.getOrElse(e, { 0 }) + 1
    }
    /**
     * dataからeの分を除く(-1する)
     * @param e 除く要素。dataのkeyに存在することは外部で保証すること。
     */
    protected fun MutableMap<Int, Int>.decrement(e: Int) {
        val count = this[e]!!   // 存在することは保証されている。

        if (count > 1) {
            this[e] = count - 1
        } else if (count == 1) {
            this.remove(e)
        } else {
            throw Exception("0個の要素をさらに除外しようとしました。")
        }
    }
}

/**
 * (aのm番目までのうち小さい方からm-N個を除いたものの総和)は、
 * aのm+1番目の要素分だけ増え、
 * aのm番目までのうち小さい方からm-N個を除いたもののに、aのm+1番目の要素を加えた集合の中の最小のものの分だけ、減少する。
 */
internal class FirstPart(list: List<Int>): Part(list) {
    override var targetSum = list.map { it.toLong() }.sum()

    /** first部分の処理 */
    fun add(e: Int) {
        if (data.firstKey() == e) {
            // eが最小(の一つ)であれば変化しない
            return
        } else {
            // eを加え、最小を除く
            val min = data.firstKey()

            this.data.decrement(min)
            this.data.increment(e)

            // 総和も調整
            this.targetSum += e - min
        }
    }
}

import java.util.PriorityQueue
import kotlin.comparisons.compareByDescending
fun main(args: Array<String>) {
    val N = nextInt()
    val A = listOfLong()
    //前半
    val first = LongArray(N + 1)
    val fQ = PriorityQueue<Long>(N)
    fQ.addAll(A.subList(0, N))
    var fS = A.subList(0, N).SUM()
    for (n in 0 .. N) {
        first[n] = fS
        fS += A[n + N]
        fQ.add(A[n + N])
        fS -= fQ.poll()!! //一番小さい引く
    }
    //後半
    val latter = LongArray(N + 1)
    val lQ = PriorityQueue<Long>(N, compareByDescending { it })
    lQ.addAll(A.subList(2 * N, 3 * N))
    var lS = A.subList(2 * N, 3 * N).SUM()
    for (n in 0 .. N) {
        latter[N - n] = lS
        lS += A[2 * N - n - 1]
        lQ.add(A[2 * N - n - 1])
        lS -= lQ.poll()!! // 一番大きい引く
    }
    var ans = (0 .. N).map { first[it] - latter[it] }.max()!!
    println(ans)
}

