 * 除かれる2N-m個のうち最小のものの分だけ増える。
 *
 * @param list: 取り除かれる要素のList
 * @param lastPart: 取り除かれない方のList
 */
internal class RemovedPart(list: List<Int>, lastPart: List<Int>): Part(list) {
    val last = lastPart.groupBy { it }.mapValuesTo(mutableMapOf()) { it.value.size }
    /** ここではlastPart側の総和になる。 */
    override var targetSum = lastPart.map { it.toLong() }.sum()

    /** removed部分の処理 */
    fun remove(e: Int) {
        if (e in this.data) {
            // aのm+1番目の要素が、除かれる2N-m個に入っていた場合は、変化せず
            // だが、dataからeは除かれる。
            this.data.decrement(e)
            return
        } else {
            // それ以外とはaのm番目よりも後の3N-m個のうち、大きい方から2N-m個を除いたものにeが入っているということ。
            // lastからeを除き、dataの最小を1つlastに移す。総和も変更する。
            this.last.decrement(e)

            val min = this.data.firstKey()
            this.data.decrement(min)
            this.last.increment(min)

            this.targetSum += min - e
        }
    }
}

