fun main(args: Array<String>) {
    Program().solve()
}

class Program {
    fun solve() {
        val sc = FastScanner()
        val n = sc.nextInt()
        val a = Array(3 * n) { sc.nextLong() }

        // [1,i+n]までの要素でN個使う
        // 最大の総和
        val f = Array(n + 1) { -1L }

        var fSum = 0L
        val fPq = PriorityQueue<Long>(n)

        // 前N個足す
        for (i in 0 until n) {
            fSum += a[i]
            fPq.add(a[i])
        }

        for (i in 0..n) {
            f[i] = fSum
            fSum += a[i + n]
            fPq.add(a[i + n])

            // 一番小さい奴引く
            fSum -= fPq.poll()!!
        }

        // [i+n,3*n)でn個使う
        // 最小
        val b = Array(n + 1) { -1L }
        var bSum = 0L
        val bPq = PriorityQueue<Long>(n, Comparator { l, r -> r.compareTo(l) })
        // 後ろn個足す
        for (i in 1..n) {
            bSum += a[3 * n - i]
            bPq.add(a[3 * n - i])
        }

        for (i in 0..n) {
            b[n - i] = bSum
            bSum += a[2 * n - i - 1]
            bPq.add(a[2 * n - i - 1])
            // 一番大きい奴引く
            bSum -= bPq.poll()
        }
        var ans = Long.MIN_VALUE
        for (i in 0..n) {
            ans = Math.max(ans, f[i] - b[i])
        }
        println(ans)
    }
}


class FastScanner {
    companion object {
        val input: InputStream = System.`in`
        val buffer = ByteArray(1024) { 0 }
        fun isPrintableChar(c: Int): Boolean = c in 33..126
    }

    var ptr = 0
    var buflen = 0
    private fun hasNextByte(): Boolean {
        if (ptr < buflen) {
            return true
        } else {
            ptr = 0
            buflen = input.read(buffer)
            if (buflen <= 0) {
                return false
            }
        }
        return true
    }

    private fun readByte(): Int = if (hasNextByte()) buffer[ptr++].toInt() else -1

    private fun skipUnprintable() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr].toInt())) ptr++
    }

    fun hasNext(): Boolean {
        skipUnprintable()
        return hasNextByte()
    }

    fun next(): String {
        if (!hasNext()) throw NoSuchElementException()
        val sb = StringBuilder()
        var b = readByte()
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b)
            b = readByte()
        }
        return sb.toString()
    }

    fun nextInt(): Int {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0
        var b = readByte()
        // '-' = 45
        val minus = b == 45
        if (minus) {
            b = readByte()
        }

        // '0' = 48 '9' = 57
        if (b !in 48..57) {
            throw NumberFormatException()
        }

        while (true) {
            if (b in 48..57) {
                n *= 10
                n += b - 48
            } else if (b == -1 || !isPrintableChar(b)) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }

    fun nextLong(): Long {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0L
        var b = readByte()
        // '-' = 45
        val minus = b == 45
        if (minus) {
            b = readByte()
        }

        // '0' = 48 '9' = 57
        if (b !in 48..57) {
            throw NumberFormatException()
        }

        while (true) {
            if (b in 48..57) {
                n *= 10
                n += b - 48
            } else if (b == -1 || !isPrintableChar(b)) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }

    fun nextDouble(): Double = next().toDouble()
}

import java.util.*

fun main(args: Array<String>) {
	val n = readLine()!!.toInt()
	val arr = readLine()!!.split(" ").map{ it.toLong() }.toLongArray()
	val comparator = Comparator<Pair<Long, Int>>{ a, b -> a.first.compareTo(b.first) }
	val fstSet = arr.sliceArray(0..(n - 1)).mapIndexed({i, v -> Pair(v, i)}).toSortedSet(comparator)
	val sndSet = arr.sliceArray(n..(3 * n - 1)).mapIndexed({i, v -> Pair(v, i + n)}).toSortedSet(comparator)
	val sndUnused = sortedSetOf<Pair<Long, Int>>(comparator)
	for (i in 1..n) {
		val p = sndSet.last()
		sndSet.remove(p)
		sndUnused.add(p)
	}
	var score = fstSet.fold(0L, {acc, p -> acc + p!!.first}) - sndSet.fold(0L, {acc, p -> acc + p!!.first})
	var ans = score
	for (i in n..(2 * n - 1)) {
		val p = fstSet.first()
		fstSet.remove(p)
		fstSet.add(Pair(arr[i], i))
		score -= p.first
		score += arr[i]
		if (sndSet.remove(Pair(arr[i], i))) {
			val p = sndUnused.first()
			sndUnused.remove(p)
			sndSet.add(p)
			score += arr[i]
			score -= p.first
		} else {
			sndUnused.remove(Pair(arr[i], i))
		}
		ans = Math.max(score, ans)
	}
	println(ans)	

}

