    	for (n in 0 .. N) {
        	array[n] = fS
        	fS += A[N + n]
        	fQ.add(A[N + n])
        	fS -= fQ.poll()!! //一番小さい引く
    	}
    	return array
	}()
    //後半
    val latter = fun(): LongArray {
	    val array = LongArray(N + 1)
    	val lQ = PriorityQueue<Long>(N, compareByDescending { it })
    	lQ.addAll(A.subList(2 * N, 3 * N))
    	var lS = lQ.toList().sum()
    	for (n in 0 .. N) {
        	array[N - n] = lS
        	lS += A[2 * N - n - 1]
        	lQ.add(A[2 * N - n - 1])
        	lS -= lQ.poll()!! // 一番大きい引く
    	}
    	return array
    }()
    var ans = (0 .. N).map { first[it] - latter[it] }.max()!!
    println(ans)
}

