public class Main {
    static InputStream is;
    static PrintWriter out;
    static String INPUT = "";

    static void solve()
    {
        int n = ni();
        int[] a = new int[3*n];
        for(int i = 0; i < 3*n; i++){
            a[i] = ni();
        }
        long res = 0;
        long ans = Long.MIN_VALUE;
        for(int k = 0; k <= n; k++){
            int[] b = new int[n+k];
            int[] c = new int[2*n-k];
            for(int i = 0; i < n + k; i++){
                b[i] = a[i];
            }
            Arrays.sort(b);
            for(int i = 0; i < 2*n-k; i++){
                c[i] = a[i+n+k];
            }
            Arrays.sort(c);
            for(int i = 0; i < n; i++){
                res += b[n+k-i-1] - c[i];
            }
            ans = Math.max(ans, res);
            res = 0;
        }
        out.println(ans);
    }


    public static void main(String[] args) throws Exception
    {
        long S = System.currentTimeMillis();
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);

        solve();
        out.flush();
        long G = System.currentTimeMillis();
        tr(G-S+"ms");
    }


    private static boolean eof()
    {
        if(lenbuf == -1)return true;
        int lptr = ptrbuf;
        while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

        try {
            is.mark(1000);
            while(true){
                int b = is.read();
                if(b == -1){
                    is.reset();
                    return true;
                }else if(!isSpaceChar(b)){
                    is.reset();
                    return false;
                }
            }
        } catch (IOException e) {
            return true;
        }
    }

    private static byte[] inbuf = new byte[1024];
    static int lenbuf = 0, ptrbuf = 0;

    private static int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//  private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
    private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private static double nd() { return Double.parseDouble(ns()); }
    private static char nc() { return (char)skip(); }

    private static String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b))){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private static char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private static char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private static int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private static int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }

    private static int[] nsi(){
        char[] s = ns().toCharArray();
        int[] a = new int[s.length];
        for(int j = 0; j < s.length; j++){
           a[j] = s[j] - '0';
        }
        return a;
    }
}

import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Scanner;
import java.util.Stack;

class Main {

    public static void main(String[] args) {
        new Main().compute();
    }

    void compute() {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] aMid = new int[N];
        Queue<Integer> zenhan = new PriorityQueue<>();
        Queue<Integer> kouhan = new PriorityQueue<>((o1, o2) -> o2 - o1);
        long[] zenhanSums = new long[N + 1];
        long[] kouhanSums = new long[N + 1];
        for (int i = 0; i < N; i++) {
            int a = sc.nextInt();
            zenhan.add(a);
            zenhanSums[0] += a;
        }
        for (int i = 0; i < N; i++) {
            aMid[i] = sc.nextInt();
        }
        for (int i = 0; i < N; i++) {
            int a = sc.nextInt();
            kouhan.add(a);
            kouhanSums[N] += a;
        }
        for (int i = 0; i < N; i++) {
            int min = zenhan.poll();
            int added = Math.max(min, aMid[i]);
            zenhan.add(added);
            zenhanSums[i + 1] = zenhanSums[i] - min + added;
        }
        for (int i = 0; i < N; i++) {
            int max = kouhan.poll();
            int added = Math.min(max, aMid[N - i - 1]);
            kouhan.add(added);
            kouhanSums[N - i - 1] = kouhanSums[N - i] - max + added;
        }
        long ans = Long.MIN_VALUE;
        for (int i = 0; i < N + 1; i++) {
            ans = Math.max(ans, zenhanSums[i] - kouhanSums[i]);
        }
        System.out.println(ans);
    }
}

