			pq.add(nums[i]);
			sum += nums[i];
		}

		long[] maxInLeft = new long[N + 1];
		maxInLeft[0] = sum;

		for (int i = N; i < 2 * N; i++) {
			pq.add(nums[i]);
			sum += nums[i];
			sum -= pq.poll();
			maxInLeft[i - N + 1] = sum;
		}


		// Do right
		long[] minInRight = new long[N + 1];
		sum = 0;
		pq = new PriorityQueue<Integer>(Collections.reverseOrder());
		for (int i = 3 * N - 1; i >= 2 * N; i--) {
			sum += nums[i];
			pq.add(nums[i]);
		}

