                r -= a[i]-right_unused.peek();
                right_used.remove(a[i]);
                right_used.add(right_unused.poll());
            }
            if (left.peek()<a[i]) {
                l += a[i]-left.peek();
                left.remove();
                left.add(a[i]);
            }
            ans = Math.max(ans, l-r);
        }
        System.out.println(ans);
