    // ======================================================================
    static class Solver {
    	MyInput in;
    	PrintWriter out;
        public Solver(MyInput in, PrintWriter out) {
        	this.in = in;
        	this.out = out;
        }

        // -----------------------------------------
        int[] A;
        long[] Mae, Ato;
        MapCounter mcnt = new MapCounter();
        public void solve() {
        	int N = ni();
        	A = ndi(3*N);
        	Mae = new long[N + 1];					// 前半の指定位置での最大合計値
        	Ato = new long[N + 1];					// 後半の指定位置での最小合計値
        	// 前半の計算
        	long sum = 0;
        	for (int i = 0; i < N; i++) {
				sum += A[i];
				mcnt.add(A[i]);
			}
        	Mae[0] = sum;							// 前半の先頭の最大合計値
        	int min;
        	for (int i = N; i < 2*N; i++) {
				sum += A[i];						// 次の値を足す
				mcnt.add(A[i]);
				min = mcnt.getFirstKey();
				sum -= min;							// １番小さい値を引く
				Mae[i - N + 1] = sum;
				mcnt.remove(min);					// １番小さい値をマップから消す
			}
        	// 後半の計算
        	sum = 0;
        	mcnt.clear();
        	for (int i = 3*N - 1; i > 2*N - 1; i--) {
				sum += A[i];
				mcnt.add(A[i]);
			}
        	Ato[N] = sum;							// 後半の先頭の最小合計値
        	int max;
        	for (int i = 2*N - 1; i > N - 1; i--) {
				sum += A[i];						// 次の値を足す
				mcnt.add(A[i]);
				max = mcnt.getLastKey();
				sum -= max;							// １番大きい値を引く
				Ato[i - N] = sum;
				mcnt.remove(max);					// １番大きい値をマップから消す
			}
        	// 差分の計算
        	long ans = -1000000000000000L;
        	for (int i = 0; i <= N; i++) {
				ans = Math.max(ans, Mae[i] - Ato[i]);
			}
        	prn(ans);
        }

        // -----------------------------------------
        // Integer のキーに対して、Integer のカウントを管理する（カウントを足したり、引いたりする）
        static class MapCounter {
        	private TreeMap<Integer, Integer> map;
        	// 昇順のマップ
        	public MapCounter() {
        		map = new TreeMap<>();
        	}
        	// reverse = tree なら降順のマップ
        	public MapCounter(boolean reverse) {
        		if(reverse) {
        			map = new TreeMap<Integer, Integer>(Collections.reverseOrder());
        		} else {
            		map = new TreeMap<>();
        		}
        	}
        	// キーを追加する（キーが存在すれば、カウントに１足す）
        	public void add(Integer key) {
        		add(key, 1);
        	}
           	public void add(Integer key, int cnt) {
           		Integer val = map.get(key);
        		if(val == null) {
        			map.put(key, cnt);
        		} else {
        			map.put(key,  val + cnt);
        		}
        	}
        	// キーを消す（キーが存在すれば、カウントを１減らす）
        	public void remove(Integer key) {
        		sub(key, 1, false);
        	}
           	// キーのカウントを減らす
        	public void sub(Integer key) {
        		sub(key, 1);
        	}
        	// キーのカウントから値を引く（マイナスのカウントを許す）
        	public void sub(Integer key, int cnt) {
        		sub(key, cnt, true);
        	}
        	// キーのカウントから値を引く
        	// 　→　マイナスを許可しない場合で、カウントがマイナスになったら消す
           	public void sub(Integer key, int cnt, boolean minus) {
        		Integer val = map.get(key);
        		if(val == null) {
        			if(minus) {
        				map.put(key, -cnt);				// カウントのマイナスを許す
        			}
        		} else if(val > cnt || minus){
       				map.put(key, val - cnt);
        		} else {
        			map.remove(key);
        		}
        	}
        	// キーのカウントを取得する（なければ　ＮＵＬＬを返す）
        	public Integer getCountwithNull(Integer key) {
        		return map.get(key);
        	}
        	// キーのカウントを取得する（なければ　０　を返す）
        	public Integer getCount(Integer key) {
        		Integer val = map.get(key);
        		if(val == null)		return 0;
        		else 				return val;
        	}
        	public Set<Integer> getKey() {
        		return map.keySet();
        	}
        	// 登録されているキーの数を返す
        	public int getKeyCount() {
        		return map.keySet().size();
        	}
        	// 先頭キーを返す
        	public Integer getFirstKey() {
        		return map.firstKey();
        	}
        	// 最終キーを返す
        	public Integer getLastKey() {
        		return map.lastKey();
        	}
