	static class TaskX {

		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			long[] a = in.nextLongArray(3*n);
			PriorityQueue<Long> b = new PriorityQueue<Long>();
			PriorityQueue<Long> r = new PriorityQueue<Long>(Comparator.reverseOrder());
			long b_sum = 0, r_sum = 0;
			for (int i = 0; i < n; i++) {
				b_sum += a[i];
				b.add(a[i]);

				r_sum += a[3*n-i-1];
				r.add(a[3*n-i-1]);
			}

			long[] b_max = new long[n+1];
			long[] r_max = new long[n+1];
			b_max[0] = b_sum;
			r_max[0] = r_sum;

			for (int i = 1; i <= n; i++) {
				b.add(a[n+i-1]);
				b_max[i] += b_max[i-1] + a[n+i-1] - b.remove();
			}

			for (int i = 1; i <= n; i++) {
				r.add(a[2*n-i]);
				r_max[i] += r_max[i-1] + a[2*n-i] - r.remove();
			}

			long ans = -LINF;
			for (int i = 0; i <= n; i++) {
				ans = Math.max(ans, b_max[i] - r_max[n-i]);
			}

			out.println(ans);
		}
	}

