    void solve() {
        int n = in.nextInt();
        int[] a = new int[3 * n + 1];
        for (int i = 1; i <= 3 * n; i++) {
            a[i] = in.nextInt();
        }
        long[] left = new long[3 * n + 1];
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int i = 1; i <= 2 * n; i++) {
            pq.add(a[i]);
            left[i] = left[i - 1] + a[i];
            if (pq.size() > n) {
                left[i] -= pq.poll();
            }
        }
        pq.clear();
        pq = new PriorityQueue<>(Collections.reverseOrder());
        long right = 0, ans = -ML;
        for (int i = 3 * n; i > n; i--) {
            pq.add(a[i]);
            right += a[i];
            if (i == 2 * n + 1) {
                ans = Math.max(ans, left[i - 1] - right);
            }
            if (pq.size() > n) {
                right -= pq.poll();
                ans = Math.max(ans, left[i - 1] - right);
            }
        }
        printf(ans);
    }

