		int sume=0;

		for(int i=0;i<N;i++){
			sumf+=front.get(i);
			sume+=end.get(i);
		}
		System.out.println(sumf-sume);
	}
}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean elapsed = false;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private void solve(Scanner sc) {
        int N = sc.nextInt();
        int[] a = new int[3 * N];
        for (int i = 0; i < 3 * N; ++i) {
            a[i] = sc.nextInt();
        }

        Queue<Integer> q1 = new PriorityQueue<>();
        long[] sum1 = new long[N + 1];
        for (int i = 0; i < N; ++i) {
            q1.offer(a[i]);
            sum1[0] += a[i];
        }

        Queue<Integer> q2 = new PriorityQueue<>(Collections.reverseOrder());
        long[] sum2 = new long[N + 1];
        for (int i = 2 * N; i < 3 * N; ++i) {
            q2.offer(a[i]);
            sum2[0] += a[i];
        }

        for (int k = N; k < 2 * N; ++k) {
            q1.offer(a[k]);
            int t1 = q1.poll();
            sum1[k - N + 1] = sum1[k - N] + a[k] - t1;

            q2.offer(a[3 * N - k - 1]);
            int t2 = q2.poll();
            sum2[k - N + 1] = sum2[k - N] + a[3 * N - k - 1] - t2;
        }

        long max = Long.MIN_VALUE;
        for (int i = 0; i <= N; ++i) {
            max = Math.max(max, sum1[i] - sum2[N - i]);
        }
        _out.println(max);
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sc = new Scanner(System.in);
        new Main().solve(sc);
        _out.flush();

        long G = System.currentTimeMillis();
        if (elapsed) {
            _err.println((G - S) + "ms");
        }
        _err.flush();
    }
}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Main main = new Main();
		main.run();
	}

	public void run() {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		long a[] = new long[3*n];
		for(int i=0; i<3*n; i++) {
			a[i]=sc.nextLong();
		}

		PriorityQueue<Long> pq1 = new PriorityQueue<Long>();
		long sum1 = 0;
		for(int i=0; i<n; i++) {
			pq1.add(a[i]);
			sum1 += a[i];
		}

		PriorityQueue<Long> pq2 = new PriorityQueue<Long>((x,y)->Long.compare(y, x));
		long sum2 = 0;
		for(int i=3*n-1; i>=2*n; i--) {
			pq2.add(a[i]);
			sum2 += a[i];
		}

		long tmp1[] = new long[n+1];
		tmp1[0]=sum1;
		long tmp2[] = new long[n+1];
		tmp2[0]=sum2;

		for(int k=n; k<2*n; k++) {
			pq1.add(a[k]);
			sum1 += a[k];
			long sub1 = pq1.poll();
			sum1 -= sub1;
			tmp1[k-(n-1)] = sum1;

			pq2.add(a[3*n-k-1]);
			sum2 += a[3*n-k-1];
			long sub2 = pq2.poll();
			sum2 -= sub2;
			tmp2[k-(n-1)] = sum2;
		}
		long ans = -Long.MAX_VALUE;
		for(int i=0; i<=n; i++) {
			ans = Math.max(ans, tmp1[i] - tmp2[n-i]);
		}
		System.out.println(ans);
		sc.close();
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

	public static void main(String args[]) {
		FastScanner cin = new FastScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	private static void solve(FastScanner cin, PrintWriter cout) {
		assert solve(2, new long[] { 3, 1, 4, 1, 5, 9 }) == 1;
		assert solve(1, new long[] { 1, 2, 3 }) == -1;
		assert solve(3, new long[] { 8, 2, 2, 7, 4, 6, 5, 3, 8 }) == 5;
		int n = cin.nextInt();
		long[] a = new long[3 * n];
		for (int i = 0; i < a.length; i++)
			a[i] = cin.nextLong();
		long ans = solve(n, a);
		cout.println(ans);
	}

	private static long solve(int n, long[] a) {
		// n == 1e5では時間が無理では？
		long ans = Long.MIN_VALUE;
		long[] c = new long[a.length];
		for (int i = n; i < 2 * n; i++) {
			System.arraycopy(a, 0, c, 0, a.length);
			Arrays.sort(c, 0, i);
			Arrays.sort(c, i, 3 * n);
			long left = 0;
			long right = 0;
			for (int j = 0; j < n; j++) {
				left += c[i - 1 - j];
				right += c[i + j];
			}
			ans = Math.max(ans, left - right);
		}
		return ans;
	}

	/**
	 * How to read input in Java — tutorial <br />
	 * By Flatfoot<br />
	 * http://codeforces.com/blog/entry/7018
	 */
	static class FastScanner {
		private BufferedReader br;
		private StringTokenizer st;

		FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements())
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new IllegalStateException(e);
				}
			return st.nextToken();
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				throw new IllegalStateException(e);
			}
			return str;
		}

		long nextLong() {
			return Long.parseLong(next());
		}
	}

}

