/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author acesine
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        D solver = new D();
        solver.solve(1, in, out);
        out.close();
    }

    static class D {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int N = in.nextInt();
            List<Long> a = new ArrayList<>();
            for (int i = 0; i < 3 * N; i++) {
                a.add(in.nextLong());
            }
            Queue<Long> head = new PriorityQueue<>(Comparator.naturalOrder());
            Queue<Long> tail = new PriorityQueue<>(Comparator.reverseOrder());
            for (int i = 0; i < N; i++) {
                head.add(a.get(i));
                tail.add(a.get(a.size() - 1 - i));
            }
            assert head.size() == N;
            assert tail.size() == N;
            long[] l = new long[N + 1];
            long[] r = new long[N + 1];
            l[0] = head.stream().mapToLong(Long::longValue).sum();
            r[N] = tail.stream().mapToLong(Long::longValue).sum();
            for (int i = 1; i <= N; i++) {
                if (a.get(N + i - 1) > head.peek()) {
                    long t = head.poll();
                    head.add(a.get(N + i - 1));
                    l[i] = l[i - 1] + a.get(N + i - 1) - t;
                } else {
                    l[i] = l[i - 1];
                }
                if (a.get(2 * N - i) < tail.peek()) {
                    long t = tail.poll();
                    tail.add(a.get(2 * N - i));
                    r[N - i] = r[N - i + 1] + a.get(2 * N - i) - t;
                } else {
                    r[N - i] = r[N - i + 1];
                }
                assert tail.size() == head.size();
            }
            long max = l[0] - r[0];
            for (int i = 1; i <= N; i++) {
                if (l[i] - r[i] > max) max = l[i] - r[i];
            }
            out.println(max);
        }

    }
}

import java.util.*;
import java.io.*;

class Main{
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        int n=fsc.nextInt();
        long[] a=new long[3*n];
        for(int i=0;i<3*n;i++){
            a[i]=fsc.nextLong();
        }
        fsc.close();
        long[] fmax=new long[n+1];
        PriorityQueue<Long> pq=new PriorityQueue<>();
        for(int i=0;i<n;i++){
            pq.add(a[i]);
            fmax[0]+=a[i];
        }
        for(int i=n;i<2*n;i++){
            if(a[i]>pq.peek()){
                fmax[i-n+1]=fmax[i-n]+a[i]-pq.poll();
                pq.add(a[i]);
            }
            else fmax[i-n+1]=fmax[i-n];
        }
        long[] bmin=new long[n+1];
        PriorityQueue<Long> revpq=new PriorityQueue<>((u, v)->u<v?1:u>v?-1:0);
        for(int i=2*n;i<3*n;i++){
            revpq.add(a[i]);
            bmin[n]+=a[i];
        }
        for(int i=2*n-1;i>=n;i--){
            if(a[i]<revpq.peek()){
                bmin[i-n]=bmin[i-n+1]+a[i]-revpq.poll();
                revpq.add(a[i]);
            }
            else bmin[i-n]=bmin[i-n+1];
        }
        long max=Long.MIN_VALUE;
        for(int i=0;i<=n;i++){
            max=Math.max(max, fmax[i]-bmin[i]);
        }
        System.out.println(max);
    }
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

import java.util.Comparator;
