		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			Long[] an = new Long[3*n];
			for (int i = 0; i < 3*n; i++) {
				an[i] = in.nextLong();
			}


			long ans = Long.MIN_VALUE;
			for (int k = n-1; k < 3*n-n; k++) {
				Long[] a = new Long[3*n];
				for (int i = 0; i < 3*n; i++) {
					a[i] = 0L;
				}
				Long[] b = new Long[3*n];
				for (int i = 0; i < 3*n; i++) {
					b[i] = Long.MAX_VALUE;
				}
				long tmp = 0;
				for (int i = 0; i <= k; i++) {
					a[i] = an[i];
				}
				for (int i = k+1; i < 3*n; i++) {
					b[i] = an[i];
				}
				Arrays.sort(a, Comparator.reverseOrder());
				Arrays.sort(b, Comparator.naturalOrder());

				for (int i = 0; i < n; i++) {
					tmp += a[i];
					tmp -= b[i];
				}

				ans = Math.max(ans, tmp);
			}

			out.println(ans);

		}
	}

