        sumL[N-1]=sum1+a[N-1];
        for(int i=N;i<=2*N-1;i++){// sumL[i]表示取a[i]为最后一个元素时的first-half的和
            if(a[i-1]>pq1.peek()){
                long temp = pq1.poll();
                pq1.add(a[i-1]);
                sumL[i]=sumL[i-1]+a[i]-temp;
            }
            else{
                sumL[i]=sumL[i-1]+a[i]-a[i-1];
            }
        }
