        for (int i = 0; i < n; i++) {
            frontSum += arr[i];
            front.add(arr[i]);
            frontSum -= front.poll();
            values[i + 1] += frontSum;
            backSum += arr[n - i - 1];
            back.add(- arr[n - i - 1]);
            backSum += back.poll();
            values[n - i - 1] -= backSum;
        }
        long max = Long.MIN_VALUE;
        for (int i = 0; i <= n; i++) {
            max = Math.max(max, values[i]);
        }
        System.out.println(max);
