/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author toshif
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyReader in = new MyReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, MyReader in, PrintWriter out) {
            int N0 = in.nextInt();
            int N = N0 * 3;
            long[] a = new long[N];
            for (int i = 0; i < N; i++) {
                a[i] = in.nextLong();
            }

            PriorityQueue<Long> lp = new PriorityQueue<>();
            PriorityQueue<Long> rp = new PriorityQueue<>();
            long[] ls = new long[N];
            long[] rs = new long[N];
            Arrays.fill(ls, (long) 1E18);
            Arrays.fill(rs, (long) -1E18);
            long l = 0;
            for (int i = 0; i < N; i++) {
                lp.add(a[i]);
                l += a[i];

                if (lp.size() > N0) {
                    l -= lp.poll();
                }
                ls[i] = l;
            }
            long r = 0;
            for (int i = N - 1; i >= 0; i--) {
                rp.add(-a[i]);
                r += a[i];

                if (rp.size() > N0) {
                    r -= -rp.poll();
                }
                rs[i] = r;
            }

            long ma = (long) -1E18;
            for (int i = N0 - 1; i < 2 * N0; i++) {
                ma = Math.max(ma, ls[i] - rs[i + 1]);
            }

            out.println(ma);
        }

    }

    static class MyReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public MyReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    static int N;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N*3);

        System.out.println( solve() );
    }

    private static long solve() {
        // LOからは小さいもの、HIからはおおきいものを優先的に取り除きたい
        Comparator<Integer> c = Comparator.naturalOrder();
        PriorityQueue<Integer> left = new PriorityQueue<>(N, c);
        PriorityQueue<Integer> right = new PriorityQueue<>(N, c.reversed());

        for (int i = 0; i < N; i++) {
            left.add(A[i]);
            right.add(A[i+2*N]);
        }

        List<Integer> mid = new ArrayList<>(N);
        for (int i = 0; i < N; i++) {
            mid.add(A[i+N]);
        }
        int ml = 0;
        int mr = N-1;

        for (int i = 0; i < N; i++) {
            int l = left.peek();
            int r = right.peek();

            int l_kaizen = mid.get(ml) - l;
            int r_kaizen = r - mid.get(mr);

            if( l_kaizen > 0 && r_kaizen > 0) {
                if( l_kaizen >= r_kaizen ) {
                    left.poll();
                    left.add(mid.get(ml));
                    ml++;
                } else {
                    right.poll();
                    right.add(mid.get(mr));
                    mr--;
                }
            } else if( l_kaizen > 0 ) {
                left.poll();
                left.add(mid.get(ml));
                ml++;
            } else if( r_kaizen > 0 ) {
                right.poll();
                right.add(mid.get(mr));
                mr--;

            } else {
                int l_kaizen_ex = l - mid.get(mr);
                int r_kaizen_ex = r - mid.get(ml);

                if( l_kaizen_ex > r_kaizen_ex ) {
                    ml++;
                } else {
                    mr--;
                }
            }
        }

        long lo_sum = 0;
        for (int i : left) {
            lo_sum += i;
        }
        long hi_sum = 0;
        for (int i : right) {
            hi_sum += i;
        }
        return lo_sum - hi_sum;
    }

    static class FastScanner {

        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

import java.util.Scanner;

public class Main {

    private static Scanner scan = new Scanner(System.in);

    public static void main(String[] args) {
	int N = Integer.parseInt(scan.next());
	long[] first = new long[N];
	long[] second = new long[N];
	long[] third = new long[N];

	for (int i = 0; i < N; i++) {
	    first[i] = -Long.parseLong(scan.next());
	    upHeap(first, i);
	}
	for (int i = 0; i < N; i++) {
	    second[i] = Long.parseLong(scan.next());
	}
	for (int i = 0; i < N; i++) {
	    third[i] = Long.parseLong(scan.next());
	    upHeap(third, i);
	}

	long[] firstScore = new long[N+1];
	for (int i = 0; i < N; i++) firstScore[0] += (-first[i]);
	for (int i = 1; i <= N; i++) {
	    firstScore[i] = firstScore[i-1];
	    long dif = second[i-1] + first[0];
	    if(dif > 0) {
		firstScore[i] += dif;
		first[0] = -second[i-1];
		downHeap(first, 0);
	    }		    
	}

	long[] thirdScore = new long[N+1];
	for (int i = 0; i < N; i++) thirdScore[0] += third[i];
	for (int i = 1; i <= N; i++) {
	    thirdScore[i] = thirdScore[i-1];
	    long dif = third[0] - second[N-i];
	    if(dif > 0) {
		thirdScore[i] -= dif;
		third[0] = second[N-i];
		downHeap(third, 0);
	    }
	}

	long ans = firstScore[0] - thirdScore[N];
	for (int i = 1; i <= N; i++) {
	    long tmp = firstScore[i] - thirdScore[N-i];
	    ans = tmp > ans ? tmp : ans;
	}

	System.out.println(ans);
	scan.close();
    }

    private static void downHeap(long[] heap, int index) {
	int left = 2*index+1;
	int right = left+1;

	if(left < heap.length) {
	    if(right < heap.length) {
		int biggerIndex = (heap[left] > heap[right] ? left : right);
		if(heap[index] < heap[biggerIndex]) {
		    swap(heap, index, biggerIndex);
		    downHeap(heap, biggerIndex);
		}
	    } else {
		if(heap[index] < heap[left]) {
		    swap(heap, index, left);
		    downHeap(heap, left);
		}
	    }
	}
    }

    private static void upHeap(long[] heap, int index) {
	if(index == 0) return;

	int parent = (index-1) / 2;
	if(heap[index] > heap[parent]) {
	    swap(heap, index, parent);
	    upHeap(heap, parent);
	}
    }

    private static void swap(long[] heap, int index1, int index2) {
	long tmp = heap[index1];
	heap[index1] = heap[index2];
	heap[index2] = tmp;
    }
}

import java.util.*;

public class Main{
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);

        int n = Integer.parseInt(sc.next());
        int[] a = new int[n*3];
        for(int i=0; i<n*3; i++){
            a[i] = Integer.parseInt(sc.next());
        }

        //前N個をプライオリティキューに突っ込む
        long fsum = 0L;
        PriorityQueue<Integer> fq = new PriorityQueue<>();
        for(int i=0; i<n; i++){
            fsum += a[i];
            fq.add(a[i]);
        }

        long[] fk = new long[n+1];
        fk[0] = fsum;
        //前2N個のうちK個捨てる。
        for(int k=1; k<=n; k++){
            fq.add(a[n+k-1]);
            fsum += a[n+k-1];
            fsum -= fq.poll();
            fk[k] = fsum;
        }

        //後ろN個をプライオリティキューに突っ込む
        long rsum = 0L;
        PriorityQueue<Integer> rq = new PriorityQueue<>(Comparator.reverseOrder());
        for(int i=n*3-1; i>=n*2; i--){
            rsum += a[i];
            rq.add(a[i]);
        }

        long[] rk = new long[n+1];
        rk[0] = rsum;
        //後ろ2N個のうちK個捨てる。
        for(int k=1; k<=n; k++){
            rq.add(a[n*2-k]);
            rsum += a[n*2-k];
            rsum -= rq.poll();
            rk[k] = rsum;
        }

        long max = -(1L<<60);
        //前K個+後ろK個が丁度N個になるモノで最大を取る
        for(int i=0; i<=n; i++){
            long tmp = fk[i] - rk[n-i];
            max = Math.max(max, tmp);
        }

        System.out.println(max);

    }
}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		final Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();

		PriorityQueue<Long> left = new PriorityQueue<>();
		long[] center = new long[n];
		PriorityQueue<Long> right = new PriorityQueue<>((l1, l2)-> {
			return l2.compareTo(l1);
		});

		for (int i = 0; i < n; i++) {
			left.add(sc.nextLong());
		}
		for (int i = 0; i < n; i++) {
			center[i] = sc.nextLong();
		}
		for (int i = 0; i < n; i++) {
			right.add(sc.nextLong());
		}

		long[] lmove = new long[n + 1];
		lmove[0] = left.stream().mapToLong(i -> i).sum();
		long[] rmove = new long[n + 1];
		rmove[0] = right.stream().mapToLong(i -> i).sum();

		for (int i = 0; i < n; i++) {
			lmove[i + 1] = lmove[i] - left.poll() + center[i];
			left.add(center[i]);
		}
		for (int i = 0; i < n; i++) {
			rmove[i + 1] = rmove[i] - right.poll() + center[n - 1 - i];
			right.add(center[n - 1 - i]);
		}

		long a = Long.MIN_VALUE;
		for (int i = 0; i <= n; i++) {
			long ans = lmove[i] - rmove[n - i];
			a = Math.max(a, ans);
		}
		System.out.println(a);
	}
}

