        PriorityQueue<Long> right=new PriorityQueue<>(Comparator.reverseOrder());
        int n=sc.nextInt();
        long[] a=new long[1+n*3];
        for (int i = 1; i <= 3*n; i++) {
            a[i]=sc.nextLong();
        }
        long[] tL=new long[3*n+1];
        long[] tR=new long[3*n+2];
