	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			Long[] an = new Long[3*n];
			for (int i = 0; i < 3*n; i++) {
				an[i] = in.nextLong();
			}

			long ans = Long.MIN_VALUE;
			Queue<Long> q1 = new PriorityQueue<>((a, b) -> (int)(a-b));
			Queue<Long> q2 = new PriorityQueue<>((a, b) -> (int)-(a-b));

			long[] sum1 = new long[n+1];
			long[] sum2 = new long[n+1];

			for (int i = 0; i < n; i++) {
				q1.add(an[i]);
				sum1[0] += an[i];
			}

			for (int k = n; k < 2*n; k++) {
				q1.add(an[k]);
				sum1[k-n+1] += sum1[k-n]+an[k];
				sum1[k-n+1] -= q1.remove();
			}


			for (int i = 3*n-1; i >= 2*n; i--) {
				q2.add(an[i]);
				sum2[0] += an[i];
			}

			for (int k = 2*n-1; k >= n; k--) {
				q2.add(an[k]);
				sum2[2*n-k] += sum2[2*n-k-1]+an[k];
				sum2[2*n-k] -= q2.remove();
			}

			for (int i = 0; i <= n; i++) {
				ans = Math.max(ans, sum1[i]-sum2[n-i]);
			}

			out.println(ans);

		}
	}

