	static void solve(int N, long[] a) {
		PriorityQueue<Long> first = new PriorityQueue<>();
		PriorityQueue<Long> second = new PriorityQueue<>(Comparator.reverseOrder());
		long fsum = 0;
		long ssum = 0;
		for (int i = 0; i < N; i++) {
			first.offer(a[i]);
			fsum += a[i];
			second.offer(a[3 * N - i - 1]);
			ssum += a[3 * N - i - 1];
		}

		long[] f = new long[N + 1];
		long[] s = new long[N + 1];

		f[0] = fsum;
		s[N] = ssum;
