			int r = 2 * N - 1 - k;

			first.offer(a[l]);
			fsum += a[l];
			fsum -= first.poll();
			f[k + 1] = fsum;

			second.offer(a[r]);
			ssum += a[r];
			ssum -= second.poll();
			s[N - 1 - k] = ssum;
		}

		long answer = Long.MIN_VALUE;
