/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author acesine
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        D solver = new D();
        solver.solve(1, in, out);
        out.close();
    }

    static class D {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int N = in.nextInt();
            List<Integer> a = new ArrayList<>();
            for (int i = 0; i < 3 * N; i++) {
                a.add(in.nextInt());
            }
            Queue<Integer> head = new PriorityQueue<>(Comparator.naturalOrder());
            Queue<Integer> tail = new PriorityQueue<>(Comparator.reverseOrder());
            for (int i = 0; i < N; i++) {
                head.add(a.get(i));
                tail.add(a.get(a.size() - 1 - i));
            }
            int[] l = new int[N + 1];
            int[] r = new int[N + 1];
            l[0] = head.stream().mapToInt(Integer::intValue).sum();
            r[N] = tail.stream().mapToInt(Integer::intValue).sum();
            for (int i = 1; i <= N; i++) {
                if (a.get(N + i - 1) > head.peek()) {
                    int t = head.poll();
                    head.add(a.get(N + i - 1));
                    l[i] = l[i - 1] + a.get(N + i - 1) - t;
                } else {
                    l[i] = l[i - 1];
                }
                if (a.get(2 * N - i) < tail.peek()) {
                    int t = tail.poll();
                    tail.add(a.get(2 * N - i));
                    r[N - i] = r[N - i + 1] + a.get(2 * N - i) - t;
                } else {
                    r[N - i] = r[N - i + 1];
                }
            }
            int max = l[0] - r[0];
            for (int i = 1; i <= N; i++) {
                if (l[i] - r[i] > max) max = l[i] - r[i];
            }
            out.println(max);
        }

    }
}

