public class Main{
	public static void main(String[] args)throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		String[] strs = br.readLine().split(" ");

		LinkedList<Integer> left = new LinkedList<Integer>();
		ArrayList<Integer> mid = new ArrayList<Integer>();
		LinkedList<Integer> right = new LinkedList<Integer>();


		for(int i = 0 ; i < n*3 ; i++){
			if(i < n){
				insert(left,Integer.parseInt(strs[i]));
			}else
			if(i < n*2){
				mid.add(Integer.parseInt(strs[i]));
			}else{
				insert(right,Integer.parseInt(strs[i]));
			}
		}

		int stBig = 0;
		for(int d : left){
			stBig += d;
		}
		int stLit = 0;
		for(int d : right){
			stLit += d;
		}

		int[] map = new int[n+1];
		for(int i = 0 ;i < map.length ; i++){
			map[i] = 0;
		}

		int plus = 0;
		for(int i = 0 ; i < mid.size() ; i++){
			if(left.getFirst() < mid.get(i) ){
				plus += mid.get(i) - left.getFirst();
				insert(left,mid.get(i));
				left.removeFirst();
			}
			map[i+1] += plus;
		}

		plus = 0;
		for(int j = 0 ; j < mid.size() ; j++){
			int i = mid.size() - j -1;
			if(right.getLast() > mid.get(i) ){
				plus += right.getLast() - mid.get(i);
				insert(right,mid.get(i));
				right.removeLast();
			}
			map[i] += plus;
		}

		int max = Integer.MIN_VALUE;
		for(int i = 0 ; i < map.length ; i++){
			max = (max < map[i])? map[i] : max;
		}
		System.out.println((stBig-stLit)+max);

	}

	public static void insert(LinkedList<Integer> list , int num){
		int i = 0;
		for(i = 0 ; i < list.size() ; i++){
			if(list.get(i) > num)
				break;
		}
		list.add(i,num);
	}
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Arrays;
import java.util.Collections;

public class Main {

    static int N;
    static long[] a;

    static List<Long> left;
    static List<Long> right;

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        N = sc.nextInt();

        a = new long[3 * N];
        left = new ArrayList<Long>();
        right = new ArrayList<Long>();

        for (int i = 0; i < a.length; i++) {
            a[i] = sc.nextLong();
            if (i < N) {
                left.add(a[i]);
            }
            else if (2 * N <= i) {
                right.add(a[i]);
            }
        }

        sc.close();

        Collections.sort(left);
        Collections.sort(right);
        //System.out.println(left);
        //System.out.println(right);
        removeNumber(left, right, N, 2*N - 1);

        System.out.println(sum(left) - sum(right));
    }

    private static void removeNumber(List<Long> left, List<Long> right, int l, int r) {

        long leftMin = left.get(0);
        long rightMax = right.get(right.size() - 1);

        long leftDiff = a[l] - leftMin; 
        long rightDiff = rightMax - a[r];

        if (leftDiff >= rightDiff) {
            left.remove(0);
            left = addNumber(left, a[l]);
            l++;
        } else {
            right.remove(right.size() - 1);
            right = addNumber(right, a[r]);
            r--;
        }

        if (l > r) {
            return;
        }

        //System.out.println(left);
        //System.out.println(right);
        removeNumber(left, right, l, r);
    }

    private static long sum(List<Long> list) {
        return list.stream().mapToLong(x -> (long)x).sum();
    }

    private static long min(List<Long> list) {
        return Collections.min(list);
    }

    private static long max(List<Long> list) {
        return Collections.max(list);
    }

    private static List<Long> addNumber(List<Long> list, long num) {
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i) > num) {
                list.add(i, num);
                return list;
            }
        }
        list.add(num);
        return list;
    }
}

