class J
{
	const int Mod = 1000000007;
	int F() => int.Parse(ReadLine());
	int[] G() => ReadLine().Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).ToArray();
	public J()
	{
		SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
		Solve();
		Out.Flush();
	}
	int N;
	int[] a;
	void Solve()
	{
		N = F();
		a = G();
		Init();
		var max = new long[3 * N];
		for (var i = 0; i < N; i++)
		{
			max[N - 1] += a[i];
			Add(a[i]);
		}
		for (var i = N; i < 3 * N; i++)
		{
			max[i] = max[i - 1];
			if (a[i] > Min())
			{
				max[i] += a[i] - Min();
				Add(a[i]);
				Remove(Min());
			}
		}
		var b = new int[3 * N];
		for (var i = 0; i < 3 * N; i++) b[i] = a[3 * N - i - 1];
		Init();
		var min = new long[3 * N];
		for (var i = 0; i < N; i++)
		{
			min[N - 1] += b[i];
			Add(b[i]);
		}
		for (var i = N; i < 3 * N; i++)
		{
			min[i] = min[i - 1];
			if (b[i] < Max())
			{
				min[i] += b[i] - Max();
				Add(b[i]);
				Remove(Max());
			}
		}
		var ans = max[N - 1] - min[2 * N - 1];
		for (var i = N + 1; i <= 2 * N; i++) ans = Math.Max(ans, max[i - 1] - min[3 * N - i - 1]);
		WriteLine(ans);
	}
	SortedSet<int> key;
	SortedDictionary<int, int> good;
	void Init()
	{
		key = new SortedSet<int>();
		good = new SortedDictionary<int, int>();
	}
	int Max() => key.Max;
	int Min() => key.Min;
	void Add(int x)
	{
		if (!key.Contains(x)) { key.Add(x); good[x] = 1; }
		else good[x]++;
	}
	void Remove(int x)
	{
		if (good[x] == 1) { key.Remove(x); good.Remove(x); }
		else good[x]--;
	}
}

