class D
{
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var l = Console.ReadLine().Split();
		var a = new int[3 * n];
		for (var i = 0; i < a.Length; i++) a[i] = int.Parse(l[i]);

		var x1 = new PQ<int>();
		var x2 = new List<int>(n);
		var s1 = new long[n + 1];
		var s2 = new long[n + 1];
		for (int i = 0, j = 3 * n - 1; i < n; i++, j--)
		{
			x1.Push(a[i]);
			x2.Add(a[j]);
			s1[0] += a[i];
			s2[n] += a[j];
		}
		x2.Sort();

		for (int i = 0, j = n - 1; i < n; i++, j--)
		{
			var v1 = a[n + i];
			if (v1 > x1.Current)
			{
				s1[i + 1] = s1[i] + v1 - x1.Pop();
				x1.Push(v1);
			}
			else s1[i + 1] = s1[i];

			var v2 = a[n + j];
			if (v2 < x2[n - 1])
			{
				s2[j] = s2[j + 1] + v2 - x2[n - 1];
				x2.Insert(Search(x2, v2), v2);
			}
			else s2[j] = s2[j + 1];
		}
		Console.WriteLine(Enumerable.Range(0, n + 1).Max(i => s1[i] - s2[i]));
	}

	static int Search(IList<int> l, int v) => l.Count > 0 ? Search(l, v, 0, l.Count) : 0;
	static int Search(IList<int> l, int v, int s, int c)
	{
		if (c == 1) return v <= l[s] ? s : s + 1;
		int c2 = c / 2, s2 = s + c2;
		return v <= l[s2] ? Search(l, v, s, c2) : Search(l, v, s2, c - c2);
	}
}

class PQ<T> : List<T>
{
	Comparison<T> _c;
	public T Current => this[0];

	public PQ() : this(Comparer<T>.Default.Compare) { }
	public PQ(Comparison<T> c) { _c = c; }

	void Swap(int i, int j)
	{
		var t = this[i];
		this[i] = this[j];
		this[j] = t;
	}

	void UpHeap(int i) { for (var j = (i - 1) / 2; i > 0 && _c(this[j], this[i]) > 0; Swap(i, j), i = j, j = (i - 1) / 2) ; }
	void DownHeap(int i)
	{
		for (var j = 2 * i + 1; j < Count; i = j, j = 2 * i + 1)
		{
			if (j + 1 < Count && _c(this[j], this[j + 1]) > 0) j++;
			if (_c(this[i], this[j]) > 0) Swap(i, j); else break;
		}
	}

	public void Push(T v) { Add(v); UpHeap(Count - 1); }
	public T Pop()
	{
		var r = this[0];
		this[0] = this[Count - 1];
		RemoveAt(Count - 1);
		DownHeap(0);
		return r;
	}
}

