class D
{
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var a = Console.ReadLine().Split().Select(long.Parse).ToArray();

		var a1 = new long[n];
		var a2 = new long[n];
		Array.Copy(a, a1, n);
		Array.Copy(a, 2 * n, a2, 0, n);
		Array.Sort(a1);
		Array.Sort(a2);
		var x1 = a1.ToList();
		var x2 = a2.ToList();
		var s1 = new long[n + 1];
		var s2 = new long[n + 1];
		s1[0] = x1.Sum();
		s2[n] = x2.Sum();
		for (var i = 0; i < n; i++)
		{
			var v1 = a[n + i];
			if (v1 > x1[x1.Count - n])
			{
				s1[i + 1] = s1[i] + v1 - x1[x1.Count - n];
				var xi = x1.BinarySearch(v1);
				x1.Insert(xi < 0 ? ~xi : xi, v1);
			}
			else s1[i + 1] = s1[i];

			var j = n - 1 - i;
			var v2 = a[n + j];
			if (v2 < x2[n - 1])
			{
				s2[j] = s2[j + 1] + v2 - x2[n - 1];
				var xi = x2.BinarySearch(v2);
				x2.Insert(xi < 0 ? ~xi : xi, v2);
			}
			else s2[j] = s2[j + 1];
		}
		Console.WriteLine(Enumerable.Range(0, n + 1).Max(i => s1[i] - s2[i]));
	}
}

