public class PriorityQueue<T> where T:IComparable<T>
{
	public long Size { get; private set; } = 0;
	public long MaxSize { get; private set; } = 0;
	private T[] m_heap;
	public int Type { get; private set; } = 0;  // 0: ascending

	public PriorityQueue(long maxSize, int type)
	{
		if(maxSize <= 0)
			throw new Exception();
		MaxSize = maxSize;
		m_heap = new T[maxSize];

		Type = type;
	}

	private int Compare(T x, T y)
	{
		return (Type == 0) ? x.CompareTo(y) : y.CompareTo(x);
	}

	public void Push(T x)
	{
		if(Size == MaxSize)
			throw new Exception("Queue is full.");

		long i = Size++;
		while(i > 0)
		{
			long p = (i - 1)/2;
			if(Compare(m_heap[p],x) <= 0)
				break;
			m_heap[i] = m_heap[p];
			i = p;			
		}
		m_heap[i] = x;		
	}

	public T Pop()
	{
		if(Size == 0)
			throw new Exception("Queue is empty.");

		T result = m_heap[0];
		T x = m_heap[--Size];
		long i = 0;
		while(i * 2 + 1 < Size)
		{
			long c1 = i * 2 + 1, c2 = i * 2 + 2;
			if(c2 < Size && Compare(m_heap[c2], m_heap[c1]) < 0)
				c1 = c2;
			if(Compare(m_heap[c1], x) >= 0)
				break;
			m_heap[i] = m_heap[c1];
			i = c1;
		}
		m_heap[i] = x;

		return result;		
	}	
}


