public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Alice" : "Brown"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        var arr = cr.Repeat(3 * N).Long;
        var dpL = (long[])arr.Clone();
        var dpR = (long[])arr.Clone();
        var pqL = new PriorityQueue<long, int>();
        var pqR = new PriorityQueue<long, int>(ComparerReverse<long>());
        pqL.Add(arr[0], 0);
        pqR.Add(arr[arr.Length - 1], arr.Length - 1);
        for (int i = 1; i < N; i++)
        {
            dpL[i] += dpL[i - 1];
            pqL.Add(arr[i], i);
            dpR[arr.Length - i - 1] += dpR[arr.Length - i];
            pqR.Add(arr[arr.Length - i - 1], arr.Length - i - 1);
        }
        for (int i = N; i < 2 * N; i++)
        {
            pqL.Add(arr[i], i);
            pqR.Add(arr[arr.Length - i - 1], arr.Length - i - 1);
            dpL[i] = dpL[i - 1] + arr[i] - pqL.Dequeue().Key;
            dpR[arr.Length - i - 1] = dpR[arr.Length - i] + arr[arr.Length - i - 1] - pqR.Dequeue().Key;
        }
        for (int i = N; i < 2 * N; i++)
        {
            UpdateMax(ref dpL[i], dpL[i - 1]);
            UpdateMin(ref dpR[arr.Length - i - 1], dpR[arr.Length - i]);
        }
        long max = long.MinValue;
        for (int i = N - 1; i < 2 * N; i++)
        {
            UpdateMax(ref max, dpL[i] - dpR[i + 1]);
        }

        return max;
    }
}

