class D
{
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var a = Console.ReadLine().Split().Select(int.Parse).ToArray();

		var x1 = a.Take(n).OrderBy(x => x).ToList();
		var x2 = a.Skip(2 * n).OrderBy(x => x).ToList();
		var s1 = new long[n + 1];
		var s2 = new long[n + 1];
		s1[0] = x1.Sum();
		s2[n] = x2.Sum();
		for (var i = 0; i < n; i++)
		{
			var v = a[n + i];
			if (v > x1[0])
			{
				s1[i + 1] = s1[i] + v - x1[0];
				x1.RemoveAt(0);
				var j = x1.BinarySearch(v);
				x1.Insert(j < 0 ? ~j : j, v);
			}
			else s1[i + 1] = s1[i];
		}
		for (var i = n - 1; i >= 0; i--)
		{
			var v = a[n + i];
			if (v < x2[n - 1])
			{
				s2[i] = s2[i + 1] + v - x2[n - 1];
				x2.RemoveAt(n - 1);
				var j = x2.BinarySearch(v);
				x2.Insert(j < 0 ? ~j : j, v);
			}
			else s2[i] = s2[i + 1];
		}
		Console.WriteLine(Enumerable.Range(0, n + 1).Max(i => s1[i] - s2[i]));
	}
