namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            PriorityQueue<int> maxAry = new PriorityQueue<int>(0);
            PriorityQueue<int> minAry = new PriorityQueue<int>(1);
            int[] ary = new int[N];

            long smax = 0;
            long smin = 0;

            string[] lines = Console.ReadLine().Split(' ');
            for (int i = 0; i < 3 * N; i++)
            {
                int a = int.Parse(lines[i]);

                if (i < N)
                {
                    maxAry.Push(a);
                    smax += a;
                }
                else if (2 * N <= i)
                {
                    minAry.Push(a);
                    smin += a;
                }
                else
                {
                    ary[i - N] = a;
                }
            }

            long res = smax - smin;
            long[] ans = new long[N];
            PriorityQueue<int> maxpq = new PriorityQueue<int>(0);
            long[] max = new long[N];
            PriorityQueue<int> minpq = new PriorityQueue<int>(1);
            long[] min = new long[N];;
            for (int i = N; i < 2 * N; i++)
            {
                ans[i - N] = long.MinValue;
                max[i - N] = smax;
                min[i - N] = smin;
                maxpq = PriorityQueue<int>.CloneDeep(maxAry);
                minpq = PriorityQueue<int>.CloneDeep(minAry);

                for (int j = N; j < i + 1; j++)
                {
                    maxpq.Push(ary[j - N]);
                    max[i - N] += ary[j - N];
                    max[i - N] -= maxpq.Pop();
                }
                for (int j = i + 1; j < 2 * N; j++)
                {
                    minpq.Push(ary[j - N]);
                    min[i - N] += ary[j - N];
                    min[i - N] -= minpq.Pop();
                }
                ans[i - N] = max[i - N] - min[i - N];
                res = Math.Max(res, ans[i - N]);
            }

            Console.WriteLine(res);
        }
    }


    [Serializable]
    public class PriorityQueue<T> where T : IComparable
    {
        private IComparer<T> _comparer = null;
        private int _type = 0;

        private T[] _heap;
        private int _sz = 0;

        private int _count = 0;

        /// <summary>
        /// Priority Queue with custom comparer
        /// </summary>
        public PriorityQueue(IComparer<T> comparer)
        {
            _heap = new T[128];
            _comparer = comparer;
        }

        /// <summary>
        /// Priority queue
        /// </summary>
        /// <param name="type">0: asc, 1:desc</param>
        public PriorityQueue(int type = 0)
        {
            _heap = new T[128];
            _type = type;
        }

        private int Compare(T x, T y)
        {
            if (_comparer != null) return _comparer.Compare(x, y);
            return _type == 0 ? x.CompareTo(y) : y.CompareTo(x);
        }

        public void Push(T x)
        {
            _count++;
            if (_count > _heap.Length)
            {
                var newheap = new T[_heap.Length * 2];
                for (int n = 0; n < _heap.Length; n++) newheap[n] = _heap[n];
                _heap = newheap;
            }

            //node number
            var i = _sz++;

            while (i > 0)
            {
                //parent node number
                var p = (i - 1) / 2;

                if (Compare(_heap[p], x) <= 0) break;

                _heap[i] = _heap[p];
                i = p;
            }

            _heap[i] = x;
        }

        public T Pop()
        {
            _count--;

            T ret = _heap[0];
            T x = _heap[--_sz];

            int i = 0;
            while (i * 2 + 1 < _sz)
            {
                //children
                int a = i * 2 + 1;
                int b = i * 2 + 2;

                if (b < _sz && Compare(_heap[b], _heap[a]) < 0) a = b;

                if (Compare(_heap[a], x) >= 0) break;

                _heap[i] = _heap[a];
                i = a;
            }

            _heap[i] = x;

            return ret;
        }

        public int Count()
        {
            return _count;
        }

        public T Peek()
        {
            return _heap[0];
        }

        public bool Contains(T x)
        {
            for (int i = 0; i < _sz; i++) if (x.Equals(_heap[i])) return true;
            return false;
        }

        public void Clear()
        {
            while (this.Count() > 0) this.Pop();
        }

        public IEnumerator<T> GetEnumerator()
        {
            var ret = new List<T>();

            while (this.Count() > 0)
            {
                ret.Add(this.Pop());
            }

            foreach (var r in ret)
            {
                this.Push(r);
                yield return r;
            }
        }

        public T[] ToArray()
        {
            T[] array = new T[_sz];
            int i = 0;

            foreach (var r in this)
            {
                array[i++] = r;
            }

            return array;
        }

        public static PriorityQueue<T> CloneDeep(PriorityQueue<T> target)
        {
            PriorityQueue<T> clone = default(PriorityQueue<T>);
            using (MemoryStream stream = new MemoryStream())
            {
                BinaryFormatter formatter = new BinaryFormatter();
                formatter.Serialize(stream, target);
                stream.Position = 0;
                clone = (PriorityQueue<T>)formatter.Deserialize(stream);
            }
            return clone;
        }
    }
}

