class D
{
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var l = Console.ReadLine().Split();
		var a = new int[3 * n];
		for (var i = 0; i < a.Length; i++) a[i] = int.Parse(l[i]);

		var x1 = new List<int>(n);
		var x2 = new List<int>(n);
		var s1 = new long[n + 1];
		var s2 = new long[n + 1];
		for (int i = 0, j = 3 * n - 1; i < n; i++, j--)
		{
			x1.Add(a[i]);
			x2.Add(a[j]);
			s1[0] += a[i];
			s2[n] += a[j];
		}
		x1.Sort();
		x2.Sort();

		for (int i = 0, j = n - 1; i < n; i++, j--)
		{
			var v1 = a[n + i];
			if (v1 > x1[x1.Count - n])
			{
				s1[i + 1] = s1[i] + v1 - x1[x1.Count - n];
				x1.Insert(Search(x1, v1), v1);
			}
			else s1[i + 1] = s1[i];

			var v2 = a[n + j];
			if (v2 < x2[n - 1])
			{
				s2[j] = s2[j + 1] + v2 - x2[n - 1];
				x2.Insert(Search(x2, v2), v2);
			}
			else s2[j] = s2[j + 1];
		}
		var M = long.MinValue;
		for (var i = 0; i <= n; i++) M = Math.Max(M, s1[i] - s2[i]);
		Console.WriteLine(M);
	}

	static int Search(IList<int> l, int v) => l.Count > 0 ? Search(l, v, 0, l.Count) : 0;
	static int Search(IList<int> l, int v, int s, int c)
	{
		if (c == 1) return v <= l[s] ? s : s + 1;
		int c2 = c / 2, s2 = s + c2;
		return v <= l[s2] ? Search(l, v, s, c2) : Search(l, v, s2, c - c2);
	}
}

