public class Program
{

    public void Proc()
    {
        int inputCount = int.Parse(Reader.ReadLine());
        int[] items = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();

        PriorityList list = new PriorityList();
        items.Take(inputCount).ToList().ForEach(a=>list.Push(a));

        Dictionary<int, long> zenhan = new Dictionary<int, long>();
		Dictionary<int, long> kouhan = new Dictionary<int, long>();
		zenhan.Add(inputCount-1, list.GetTotal());
        for (int i = inputCount; i < inputCount * 2;i++) {
            list.Push(items[i]);
            list.Pop();
            zenhan.Add(i, list.GetTotal());
        }
        list = new PriorityList();
        long max = long.MinValue;
        items.Skip(inputCount * 2).ToList().ForEach(a=>list.Push(a*-1));
        kouhan.Add(inputCount*2-1, list.GetTotal());
        max = zenhan[inputCount * 2 - 1] + kouhan[inputCount * 2 - 1];

		for (int i = inputCount * 2 - 1; i >= inputCount; i--) {
            list.Push(items[i]*-1);
            list.Pop();
            kouhan.Add(i-1, list.GetTotal());
            max = Math.Max(max, zenhan[i-1] + kouhan[i-1]);
        }
        Console.WriteLine(max);

    }


    private class PriorityList {
        public long GetTotal() {
            return this.Total;
        }
        private long Total = 0;
        private List<int> Items = new List<int>();
        public void Push(int num) {
            int idx = GetInsertIndex(num, 0, this.Items.Count-1);
            this.Items.Insert(idx, num);
            Total += num;
		}
        public int Pop() {
            int num = this.Items[0];
            this.Items.RemoveAt(0);
            Total -= num;
            return num;
        }

        private int GetInsertIndex(int num, int min, int max) {
            if(this.Items.Count == 0) {
                return 0;
            }
            if(num <= this.Items[min]) {
                return min;
            }
            if(num>this.Items[max]) {
                return max + 1;
            }
            if(max-min<=1) {
                return max;
            }
            int mid = (max + min) / 2;
            if(this.Items[mid] == num) {
                return mid;
            }
            if(this.Items[mid]<num) {
                return GetInsertIndex(num, mid, max);
            } else {
                return GetInsertIndex(num, min, mid);
            }
        }

    }

