public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Calc());

    #endregion
    public object Calc()
    {
        var N = cr.Int;
        var arr = cr.Repeat(3 * N).Long;
        var hidari = NewArray(3 * N, -(long)1e16);
        var migi = NewArray(3 * N, (long)1e16);

        {
            var pq = new PriorityQueue<long, long>(N + 1);
            hidari[N] = 0;
            for (int i = 0; i < N; i++)
            {
                pq.Add(arr[i], arr[i]);
                hidari[N] += arr[i];
            }
            for (int i = N; i < 2 * N; i++)
            {
                hidari[i + 1] = hidari[i];
                if (pq.Peek.Value < arr[i])
                {
                    pq.Add(arr[i], arr[i]);
                    hidari[i + 1] += arr[i] - pq.Dequeue().Value;
                }
            }
        }
        {
            var pq = new PriorityQueue<long, long>(N + 1);
            migi[2 * N] = 0;
            for (int i = 2 * N; i < 3 * N; i++)
            {
                pq.Add(-arr[i], arr[i]);
                migi[2 * N] += arr[i];
            }
            for (int i = 2 * N - 1; i >= N; i--)
            {
                migi[i] = migi[i + 1];
                if (pq.Peek.Value > arr[i])
                {
                    pq.Add(-arr[i], arr[i]);
                    migi[i] += arr[i] - pq.Dequeue().Value;
                }
            }
        }

        return hidari.Zip(migi, (h, m) => h - m).Max();
    }
}
