            var large = new SortedCollection<long>(a.Take(N));

            var small = new SortedCollection<long>(a.Skip(2 * N), Comparer<long>.Create((l, r) => r.CompareTo(l)));

            dpLarge[0] = large.Sum();
            dpSmall[N] = small.Sum();

            for (int i = 0; i < N; i++)
            {
                var nextL = a[N + i];
                long min = large.First;
                if (min < nextL)
                {
                    large.Add(nextL);
                    large.Remove(min);
                    dpLarge[i + 1] = dpLarge[i] + nextL - min;
                }
                else
                    dpLarge[i + 1] = dpLarge[i];

                var nextR = a[2 * N - i - 1];
                var max = small.First;
                if (nextR < max)
                {
                    small.Add(nextR);
