                    dpSmall[N - i - 1] = dpSmall[N - i] + nextR - max;
                }
                else
                    dpSmall[N - i - 1] = dpSmall[N - i];
            }
            return Enumerable.Zip(dpLarge, dpSmall, (l, s) => l - s).Max();
