class D
{
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var a = Console.ReadLine().Split().Select(int.Parse).ToArray();

		var a1 = new int[n];
		var a2 = new int[n];
		Array.Copy(a, a1, n);
		Array.Copy(a, 2 * n, a2, 0, n);
		Array.Sort(a1);
		Array.Sort(a2);
		var x1 = a1.ToList();
		var x2 = a2.ToList();
		var s1 = new long[n + 1];
		var s2 = new long[n + 1];
		s1[0] = a1.Sum(i => (long)i);
		s2[n] = a2.Sum(i => (long)i);
		for (var i = 0; i < n; i++)
		{
			var v1 = a[n + i];
			if (v1 > x1[x1.Count - n])
			{
				s1[i + 1] = s1[i] + v1 - x1[x1.Count - n];
				x1.Insert(Search(x1, v1), v1);
			}
			else s1[i + 1] = s1[i];

			var j = n - 1 - i;
			var v2 = a[n + j];
			if (v2 < x2[n - 1])
			{
				s2[j] = s2[j + 1] + v2 - x2[n - 1];
				x2.Insert(Search(x2, v2), v2);
			}
			else s2[j] = s2[j + 1];
		}
		var M = long.MinValue;
		for (var i = 0; i <= n; i++) M = Math.Max(M, s1[i] - s2[i]);
		Console.WriteLine(M);
	}

	static int Search(IList<int> l, int v) => l.Count > 0 ? Search(l, v, 0, l.Count) : 0;
	static int Search(IList<int> l, int v, int s, int c)
	{
		if (c == 1) return v <= l[s] ? s : s + 1;
		int c2 = c / 2, s2 = s + c2;
		return v <= l[s2] ? Search(l, v, s, c2) : Search(l, v, s2, c - c2);
	}
}

