                ans = Math.Max(ans, sumA - sumC);
            }
            Console.WriteLine(ans);
        }

        static public long kanA(int[] b, int[] a, int i, int N)
        {
            int[] mat = new int[N + i];
            for (int j = 0; j < N; j++)
            {
                mat[j] = a[j];
            }
            for (int j = 0; j < i; j++)
            {
                mat[j + N] = b[j];
            }
            Array.Sort(mat);
            Array.Reverse(mat);
            long sumA = 0;
            for (int j = 0; j < N; j++)
            {
                sumA += mat[j];
            }
            return sumA;
        }

        static public long kanC(int[] b, int[] c, int i, int N)
        {
            int[] mat = new int[2 * N - i];
            for (int j = 0; j < N; j++)
            {
                mat[j] = c[j];
            }
            for (int j = i; j < N; j++)
            {
                mat[j + N - i] = b[j];
            }
            Array.Sort(mat);
            long sumC = 0;
            for (int j = 0; j < N; j++)
            {
                sumC += mat[j];
            }
            return sumC;
        }
    }
