public class Hello
{

    public static void Main()
    {
        int N = int.Parse(Console.ReadLine());
        string[] s = Console.ReadLine().Split(' ');
        int[] nums = s_to_i(s);
        int[] box = new int[N];

        int[] select = new int[N];
        for (int i = 0; i < N; i++) select[i] = 0;
        int fin_flag = 0;
        int count = 0;

        int first_harf = 0;
        int later_harf = 0;
        int num = 0;
        int max = -1000000000;

        while (true)
        {
            //消去パターン生成
            while (true)
            {
                select = Select_set(select, N);
                if (select[0] == -1) { fin_flag = 1; break; }
                if (judge(select)) break;
            }
            if (fin_flag == 1) break;
            //前半計算
            count = 0;
            first_harf = 0;
            later_harf = 0;
            for (int i = 0; i < nums.Length; i++)
            {
                if (select.Count(n => n == i) == 0)
                {
                    first_harf += nums[i];
                    count++;
                    if (count == N) break;
                }
            }
            //後半
            count = 0;
            for (int i = nums.Length - 1; i != 0; i--)
            {
                if (select.Count(n => n == i) == 0)
                {
                    later_harf += nums[i];
                    count++;
                    if (count == N) break;
                }
            }
            //比較
            num = first_harf - later_harf;
            if (num > max) max = num;
        }
        Console.WriteLine(max);
    }

    static int[] Select_set(int[] num, int N)
    {
        int stok = 0;
        int next_add = 1;
        for (int i = 0; i < N; i++)
        {
            stok = num[i] + next_add;
            //仮に最大を超える場合に0にしnextを1
            if (stok >= N * 3)
            {
                if (i == N - 1) { num[0] = -1; break; }
                num[i] = 0;
                next_add = 1;
            }
            else
            {
                num[i] = stok;
                next_add = 0;
                break;
            }
        }

        return num;
    }

    static bool judge(int[] num)
    {
        bool jg = true;

        int[] box = new int[num.Length];
        num.CopyTo(box, 0);
        Array.Sort(box);
        Array.Reverse(box);
        if (!box.SequenceEqual(num)) return false;
        for (int i = 0; i < num.Length; i++)
        {
            if (num.Count(n => n == num[i]) > 1)
            {
                jg = false;
                break;
            }
        }
        return jg;
    }

    static int[] s_to_i(string[] s)
    {
        int[] ret = Array.ConvertAll<string, int>(s, delegate (string value) { return int.Parse(value); });
        return ret;
    }
}

