class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }


    Scanner cin;

    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        int[] A = cin.ArrayInt(3 * N);
        Heap<long> h = new Heap<long>();
        long[] dp1 = new long[3 * N + 1];
        long sum = 0;
        for (int i = 0; i < 3 * N; i++)
        {
            sum += A[i];
            h.push(A[i]);
            if (i >= N) sum -= h.pop();
            dp1[i + 1] = sum;
        }
        Array.Reverse(A);
        h = new Heap<long>();
        long[] dp2 = new long[3 * N + 1];
        sum = 0;
        for (int i = 0; i < 3 * N; i++)
        {
            sum += A[i];
            h.push(-A[i]);
            if (i >= N) sum -= -h.pop();
            dp2[i + 1] = sum;
        }

        long ans = long.MinValue;

        for (int i = 0; i < 3 * N; i++)
        {
            int j = 3 * N - i;
            if (i < N || j < N) continue;
            ans = Math.Max(ans, dp1[i] - dp2[j]);
        }

        Console.WriteLine(ans);
    }

    class Heap<T> where T : IComparable
    {
        public HeapNode<T> top;

        public Heap() { }

        public void push(T val)
        {
            top = HeapNode<T>.meld(top, new HeapNode<T>(val));
        }

        public T pop()
        {
            T ret = top.val;
            top = HeapNode<T>.meld(top.r, top.l);
            return ret;
        }

        public void merge(Heap<T> h2)
        {
            top = HeapNode<T>.meld(top, h2.top);
        }

        public class HeapNode<NT> where NT : IComparable
        {
            public HeapNode<NT> l, r;
            public NT val;

            public HeapNode(NT _val)
            {
                val = _val;
            }

            public static HeapNode<NT> meld(HeapNode<NT> a, HeapNode<NT> b)
            {
                if (a == null) return b;
                if (b == null) return a;
                if (a.val.CompareTo(b.val) > 0)
                {
                    HeapNode<NT> temp = a;
                    a = b;
                    b = temp;
                }
                a.r = meld(a.r, b);
                HeapNode<NT> temph = a.l;
                a.l = a.r;
                a.r = temph;
                return a;
            }
        }
    }

}



