    class Program
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            PriorityQueue<int> maxPq = new PriorityQueue<int>(N);
            PriorityQueue<int> minPq = new PriorityQueue<int>(N);
            ArrayList<int> al = new ArrayList<int>(N);

            long smax = 0;
            long smin = 0;

            string[] lines = Console.ReadLine().Split(' ');
            for (int i = 0; i < 3 * N; i++)
            {
                int a = int.Parse(lines[i]);

                if (i < N)
                {
                    maxPq.Push(-a);
                    smax += a;
                }
                else if (2 * N <= i)
                {
                    minPq.Push(a);
                    smin += a;
                }
                else
                {
                    al.InsertLast(a);
                }
            }

            long ans = long.MinValue;
            for (int i = N; i < 2 * N; i++)
            {
                PriorityQueue<int> maxpq = new PriorityQueue<int>(N);
                long max = smax;
                PriorityQueue<int> minpq = new PriorityQueue<int>(N);
                long min = smin;
                for (int j = 0; j < N; j++)
                {
                    maxpq.Push(maxPq[j]);
                    minpq.Push(minPq[j]);
                }

                int top = 0;
                for (int j = N; j < i + 1; j++)
                {
                    maxpq.Push(-al[j - N]);
                    max += al[j - N];
                    top = -maxpq.Top;
                    maxpq.Pop();
                    max -= top;
                }
                for (int j = i + 1; j < 2 * N; j++)
                {
                    minpq.Push(al[j - N]);
                    min += al[j - N];
                    top = minpq.Top;
                    minpq.Pop();
                    min -= top;
                }
                ans = Math.Max(ans, max - min);
            }

            Console.WriteLine(ans);
        }
    }




    /// <summary>
    /// 優先度付き待ち行列
    /// </summary>
    /// <typeparam name="T">要素の型</typeparam>
    public class PriorityQueue<T> where T : IComparable<T>
    {
        #region フィールド

        ArrayList<T> buffer;

        #endregion
        #region プロパティ

        /// <summary>
        /// i 番目の要素を読み書き。
        /// </summary>
        /// <param name="i">読み書き位置</param>
        /// <returns>読み出した要素</returns>
        public T this[int i]
        {
            get { return this.buffer[i]; }
            set { this.buffer[i] = value; }
        }

        #endregion
        #region 初期化

        public PriorityQueue() { this.buffer = new ArrayList<T>(); }
        public PriorityQueue(int capacity) { this.buffer = new ArrayList<T>(capacity); }

        #endregion
        #region ヒープ操作

        /// <summary>
        /// ヒープ化されている配列リストに新しい要素を追加する。
        /// </summary>
        /// <param name="array">対象の配列リスト</param>
        public static void PushHeap(ArrayList<T> array, T elem)
        {
            int n = array.Count;
            array.InsertLast(elem);

            while (n != 0)
            {
                int i = (n - 1) / 2;
                if (array[n].CompareTo(array[i]) > 0)
                {
                    T tmp = array[n]; array[n] = array[i]; array[i] = tmp;
                }
                n = i;
            }
        }

        /// <summary>
        /// ヒープから最大値を削除する。
        /// </summary>
        /// <param name="array">対象の配列リスト</param>
        public static void PopHeap(ArrayList<T> array)
        {
            int n = array.Count - 1;
            array[0] = array[n];
            array.EraseLast();

            for (int i = 0, j; (j = 2 * i + 1) < n;)
            {
                if ((j != n - 1) && (array[j].CompareTo(array[j + 1]) < 0))
                    j++;
                if (array[i].CompareTo(array[j]) < 0)
                {
                    T tmp = array[j]; array[j] = array[i]; array[i] = tmp;
                }
                i = j;
            }
        }

        #endregion
        #region 要素の挿入・削除

        /// <summary>
        /// 要素のプッシュ。
        /// </summary>
        /// <param name="elem">挿入したい要素</param>
        public void Push(T elem)
        {
            PushHeap(this.buffer, elem);
        }

        /// <summary>
        /// 要素を1つポップ。
        /// </summary>
        /// <remarks>
        /// 今回の実装では、先頭要素の読み出しと削除は別に行う。
        /// この Pop では削除のみ。
        /// 読み出しには Top プロパティを使う。
        /// </remarks>
        public void Pop()
        {
            PopHeap(this.buffer);
        }

        /// <summary>
        /// 先頭要素の読み出し。
        /// </summary>
        public T Top
        {
            get { return this.buffer[0]; }
        }

        public int Count
        {
            get { return this.buffer.Count; }
        }

        #endregion
    }

    /// <summary>
    /// 配列リスト。
    /// </summary>
    /// <typeparam name="T">要素の型</typeparam>
    public class ArrayList<T> : IEnumerable<T>
    {
        #region フィールド

        T[] data;
        int count;

        #endregion
        #region 初期化

        public ArrayList() : this(256) { }

        /// <summary>
        /// 初期最大容量を指定して初期化。
        /// </summary>
        /// <param name="capacity">初期載大容量</param>
        public ArrayList(int capacity)
        {
            this.data = new T[capacity];
            this.count = 0;
        }

        #endregion
        #region プロパティ

        /// <summary>
        /// 格納されている要素数。
        /// </summary>
        public int Count
        {
            get { return this.count; }
        }

        /// <summary>
        /// i 番目の要素を読み書き。
        /// </summary>
        /// <param name="i">読み書き位置</param>
        /// <returns>読み出した要素</returns>
        public T this[int i]
        {
            get { return this.data[i]; }
            set { this.data[i] = value; }
        }

        #endregion
        #region 挿入・削除

        /// <summary>
        /// 配列を確保しなおす。
        /// </summary>
        /// <remarks>
        /// 配列長は2倍ずつ拡張していきます。
        /// </remarks>
        void Extend()
        {
            T[] data = new T[this.data.Length * 2];
            for (int i = 0; i < this.data.Length; ++i) data[i] = this.data[i];
            this.data = data;
        }

        /// <summary>
        /// i 番目の位置に新しい要素を追加。
        /// </summary>
        /// <param name="i">追加位置</param>
        /// <param name="elem">追加する要素</param>
        public void Insert(int i, T elem)
        {
            if (this.count >= this.data.Length)
                this.Extend();

            for (int n = this.count; n > i; --n)
            {
                this.data[n] = this.data[n - 1];
            }
            this.data[i] = elem;
            ++this.count;
        }

        /// <summary>
        /// 末尾に新しい要素を追加。
        /// </summary>
        /// <param name="elem">追加する要素</param>
        public void InsertLast(T elem)
        {
            if (this.count >= this.data.Length)
                this.Extend();

            this.data[this.count] = elem;
            ++this.count;
        }

        /// <summary>
        /// i 番目の要素を削除。
        /// </summary>
        /// <param name="i">削除位置</param>
        public void Erase(int i)
        {
            for (int n = i; n < this.count - 1; ++n)
            {
                this.data[n] = this.data[n + 1];
            }
            --this.count;
        }

        /// <summary>
        /// 末尾の要素を削除。
        /// </summary>
        public void EraseLast()
        {
            --this.count;
        }

        #endregion
        #region IEnumerable<T> メンバ

        public IEnumerator<T> GetEnumerator()
        {
            for (int i = 0; i < this.count; ++i)
                yield return this.data[i];
        }

        System.Collections.IEnumerator
          System.Collections.IEnumerable.GetEnumerator()
        {
            return this.GetEnumerator();
        }

        #endregion
    }
}

