            {
                tailSums[0] += array[3 * n - i - 1];
                sDictT.Add(-array[3 * n - i - 1], i);
            }
            for (int i = 1; i <= n; i++)
            {
                tailSums[i] = tailSums[i - 1] + array[2 * n - i];
                sDictT.Add(-array[2 * n - i], i+n);
                KeyValuePair<long, int> pair = sDictT.Dequeue();
                tailSums[i] += pair.Key;
            }

            long res = long.MinValue;
