        public static void Main(string[] args)
        {
            // 前半は1-2Nから大きいものをN個選ぶ
            // 後半は前半の最後+1から3Nまでの間で小さいものをN個選ぶ

            long N = long.Parse(Console.ReadLine());
            long[] a = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();

            long score = long.MinValue;
            // 前半の最後はN - 2Nまでの間
            for (long i = N; i <= 2*N ; i++)
            {
                long[] aryw = new long[i];
                Array.Copy(a, 0, aryw,0,i);
                long max = aryw.OrderBy(x=>x).Where((n,index)=>index>=i-N).Sum();
                long[] aryw2 = new long[3*N - i];
                Array.Copy(a, i, aryw2, 0, 3*N-i);
                long min = aryw2.OrderBy(x => x).Where((n, index) => index < N).Sum();
                long w = max - min;
                if (score < w) score = w;
            }
            Console.WriteLine(score);
        }
    }
