using System;
using System.Collections;
public class MainApp
{
    static public void Main(string[] args)
    {
        var read = Console.ReadLine();
        int N = int.Parse(read);
        int[] a = new int[3 * N];
        read = Console.ReadLine();
        var split = read.Split(' ');
        for(int c = 0; c < 3*N;c++)
        {
            a[c] = int.Parse(split[c]);
        }
        int[] leftscore = new int[N];
        int[] rightscore = new int[N];

        int[] leftnumbers = new int[N];
        int[] rightnumbers = new int[N];
        for (int c = 0; c < N; c++)
        {
            leftnumbers[c] = a[c];
            rightnumbers[c] = a[3*N - c-1];

        }
        long firstscore = sum(leftnumbers) - sum(rightnumbers);
        for (int c = 0; c < N; c++)
        {
            int minimum_soeji = minimum(leftnumbers);

            leftscore[c] = a[c + N]-leftnumbers[minimum_soeji];
            leftnumbers[minimum_soeji] = a[c + N];

        }
        for (int c = 0; c < N; c++)
        {
            int maximum_soeji = maximum(rightnumbers);
            rightscore[c] =  rightnumbers[maximum_soeji]- a[2 * N - c - 1] ;
            rightnumbers[maximum_soeji] = a[2 * N - c-1];
        }
        for (int c = 0; c < N-1; c++)
        {
            leftscore[c + 1] += leftscore[c];
            rightscore[c + 1] += rightscore[c];

        }
        long maxscore = Math.Max(leftscore[N - 1], rightscore[N - 1]);
        for (int c = 0; c < N - 1; c++)
        {
            if (leftscore[c] + rightscore[N - 2 - c] > maxscore)
                maxscore = leftscore[c] + rightscore[N - 2 - c];

        }
        Console.WriteLine(maxscore + firstscore);
    }

    static public long sum(int[] a)
    {
        long output = 0;
        for (int c = 0; c < a.Length; c++)
        {
            output += a[c];
        }
        return output;
    }

    static public int maximum(int[] a)
    {
        int output_number = 0;
        int max = a[0];

        for (int c = 0; c < a.Length; c++)
        {
            if (max< a[c])
            {
                output_number = c;
                max = a[c];
            }
        }
        return output_number;
    }

    static public int minimum(int[] a)
    {
        int output_number = 0;
        int min = a[0];
        for (int c = 0; c < a.Length; c++)
        {
            if (min > a[c])
            {
                output_number = c;
                min = a[c];
            }
        }
        return output_number;
    }

}

