            var rights = new PriorityQueue<long>((a, b) => a < b ? 1 : a == b ? 0 : -1);
            var l = N;
            var r = 2 * N - 1;

            foreach (var item in list.Take(N)) {
                lefts.Enqueue(item);
            }
            foreach (var item in list.Skip(N * 2)) {
                rights.Enqueue(item);
            }

            while (l != r + 1) {
                if (list[l] - lefts.Peek() <= 0 && rights.Peek() - list[r] <= 0) {
                    l++;
                } else if (list[l] - lefts.Peek() >= Math.Max(0, rights.Peek() - list[r])) {
                    lefts.Dequeue();
                    lefts.Enqueue(list[l++]);
                } else {
                    rights.Dequeue();
                    rights.Enqueue(list[r--]);
                }
            }

            Console.WriteLine(lefts.Data.Sum() - rights.Data.Sum());
        }
    }

