        static long Ans(int N, List<long> a1, List<long> a2, List<long> a3)
        {
            List<long> a1sum = new List<long>();
            List<long> a3sum = new List<long>();

            a1.Sort();
            a1sum.Add(a1.Sum());
            for (int i = 0; i < N; ++i)
            {
                a1sum.Add(a1sum[i] - a1[0] + a2[i]);
                a1.RemoveAt(0);
                a1.Add(a2[i]);
                a1.Sort();
            }

            a3.Sort();
            a3sum.Add(a3.Sum());
            for (int i = 0; i < N; ++i)
            {
                a3sum.Add(a3sum[i] - a3[N - i - 1] + a2[N - i - 1]);
                a3.RemoveAt(N - i - 1);
                a3.Add(a2[N - i - 1]);
                a3.Sort();
            }

            long max = long.MinValue;
            for (int i = 0; i <= N; ++i)
            {
                max = Math.Max(max, a1sum[i] - a3sum[N - i]);
            }
            return max;

        }
    }
