        public class PriorityQueueNum
        {
            SortedDictionary<long, Queue<long>> dict
                = new SortedDictionary<long, Queue<long>>();

            public int Count { get; private set; } = 0;
            bool reverse = false;

            public PriorityQueueNum(bool reverse = false)
            {
                this.reverse = reverse;
            }

            public void Add(long key, long value)
            {
                if (reverse) key = -key;
                if (!dict.ContainsKey(key))
                {
                    dict[key] = new Queue<long>();
                }
                dict[key].Enqueue(value);
                Count++;
            }

            public KeyValuePair<long, long> Dequeue()
            {
                KeyValuePair<long, Queue<long>> queue = dict.First();
                if (queue.Value.Count <= 1)
                {
                    dict.Remove(queue.Key);
                }
                Count--;
                long key = queue.Key;
                if (reverse) key = -key;
                return new KeyValuePair<long, long>(
                    key, queue.Value.Dequeue());
            }
        }
    }
