			{
				s1[i + 1] = s1[i] + v1 - x1[0];
				x1.RemoveAt(0);
				x1.Insert(Search(x1, v1), v1);
			}
			else s1[i + 1] = s1[i];

			var j = n_ - i;
			var v2 = a[n + j];
			if (v2 < x2[n_])
			{
				s2[j] = s2[j + 1] + v2 - x2[n_];
				x2.RemoveAt(n_);
				x2.Insert(Search(x2, v2), v2);
			}
			else s2[j] = s2[j + 1];
		}
		Console.WriteLine(Enumerable.Range(0, n + 1).Max(i => s1[i] - s2[i]));
	}

	static int Search(IList<int> l, int v) => l.Count > 0 ? Search(l, v, 0, l.Count) : 0;
	static int Search(IList<int> l, int v, int s, int c)
	{
		if (c == 1) return v <= l[s] ? s : s + 1;
		int c2 = c / 2, s2 = s + c2;
		return v <= l[s2] ? Search(l, v, s, c2) : Search(l, v, s2, c - c2);
	}
}

