        void Solve() {
            io.i(out N);
            io.ini(out A, 3 * N);

            //前について
            var fq = new PQueue<int>();
            var fqSum = 0L;
            var fqSums = new long[N+1];
            N.REP(i => { fq.Enqueue(A[i]); fqSum += A[i]; });
            fqSums[0] = fqSum;
            N.REP(i => {
                fq.Enqueue(A[i+N]);fqSum += A[i + N];
                fqSum -= fq.Dequeue();
                fqSums[i + 1] = fqSum;
            });
            //後について
            var eq = new PQueue<int>(1);
            var eqSum = 0L;
            var eqSums = new long[N + 1];
            N.REP(i => { eq.Enqueue(A[i + 2 * N]); eqSum += A[i + 2 * N]; });
            eqSums[N] = eqSum;
            N.REPR(i => {
                eq.Enqueue(A[i+N]);eqSum += A[i + N];
                eqSum -= eq.Dequeue();
                eqSums[i] = eqSum;
            });

            long ans = long.MinValue;
            fqSums.Length.REP(i => {
                ans = Math.Max(ans,fqSums[i] - eqSums[i]);
            });

            io.o(ans);

        }
