class PQ<T> : List<T>
{
	Comparison<T> _c;
	public T Current => this[0];

	public PQ() : this(Comparer<T>.Default.Compare) { }
	public PQ(Comparison<T> c) { _c = c; }

	void Swap(int i, int j)
	{
		var t = this[i];
		this[i] = this[j];
		this[j] = t;
	}

	void UpHeap(int i) { for (var j = (i - 1) / 2; i > 0 && _c(this[j], this[i]) > 0; Swap(i, j), i = j, j = (i - 1) / 2) ; }
	void DownHeap(int i)
	{
		for (var j = 2 * i + 1; j < Count; i = j, j = 2 * i + 1)
		{
			if (j + 1 < Count && _c(this[j], this[j + 1]) > 0) j++;
			if (_c(this[i], this[j]) > 0) Swap(i, j); else break;
		}
	}

	public void Push(T v) { Add(v); UpHeap(Count - 1); }
	public T Pop()
	{
		var r = this[0];
		this[0] = this[Count - 1];
		RemoveAt(Count - 1);
		DownHeap(0);
		return r;
	}
}

