            //var ret = Math.Min(GetAns(h, w), GetAns(w, h));

            //IO.Printer.Out.WriteLine(ret);


            var n = scanner.Integer();
            var a = scanner.ScanLine().Split().Select(v => int.Parse(v)).ToList();

            var ret = int.MinValue;
            for (var i = n; i < 2 * n; i++)
            {
                var left = a.Take(i).OrderByDescending(v => v).Take(n).Sum();
                var right = a.Skip(i).OrderBy(v => v).Take(n).Sum();
                ret = Math.Max(ret, left - right);
            }

            IO.Printer.Out.WriteLine(ret);
            IO.Printer.Out.Flush();
        }

        static int GetAns(int w, int h)
        {
            if (w % 3 == 0 || h % 3 == 0) return 0;

            var ret = int.MaxValue;

            for (int i = 1; i <= w - 1; i++)
            {
                var s1 = h * i;
                var val = int.MaxValue;

                // hori
                if (h >= 2)
                {
                    var mid = h / 2;
                    var s2 = (h - i) * mid;
                    var s3 = (h - i) * (h - mid);
                    val = Math.Min(val, GetAns(s1, s2, s3));
                }

                // vertical
                if (w - i >= 2)
                {
                    var mid = (w - i) / 2;
                    var s2 = h * mid;
                    var s3 = h * (w - i - mid);
                    val = Math.Min(val, GetAns(s1, s2, s3));
                }

                ret = Math.Min(ret, val);
            }

            return ret;
        }

        static int GetAns(int s1, int s2, int s3)
        {
            var ss = new int[] { s1, s2, s3 }.OrderBy(s => s).ToArray();
            return Math.Abs(ss[0] - ss[2]);
        }
    }


