        var psum = 0L;
        for (int i = 0; i < n; i++) { pq.Push(a[i]); psum += a[i]; }
        ret[0] = psum;
        for (int i = 0; i < n; i++)
        {
            pq.Push(a[n + i]);
            var w = pq.Pop();
            psum += (a[n + i] - w);
            ret[i + 1] = psum;
        }
        return ret;
    }
}

