            for (int i = 0; i < N; ++i)
            {
                a1sum.Add(a1sum[i] - a1[0] + a2[i]);
                a1.RemoveAt(0);
                a1.Add(a2[i]);
                a1.Sort();
            }

            a3.Sort();
            a3.Reverse();
            a3sum.Add(a3.Sum());
            for (int i = 0; i < N; ++i)
            {
                a3sum.Add(a3sum[i] - a3[0] + a2[N - i - 1]);
                a3.RemoveAt(0);
                a3.Add(a2[N - i - 1]);
                a3.Sort();
            }

