    class Program
    {
        static void Main(string[] args)
        {
            int N = Int32.Parse(Console.ReadLine());

            string[] bufs = Console.ReadLine().Split(' ');
            int[] front = new int[N];
            int[] center = new int[N];
            int[] rear = new int[N];

            for (int i = 0; i < N; i++)
            {
                front[i] = Int32.Parse(bufs[i]);
                center[i] = Int32.Parse(bufs[N + i]);
                rear[i] = Int32.Parse(bufs[2 * N + i]);
            }

            Array.Sort(front);
            Array.Sort(rear);

            int curL = 0;
            int curR = N - 1;

            while (curL <= curR)
            {
                int left = center[curL] - front[0];
                int right = rear[N - 1] - center[curR];

                if (left < 0 && right < 0)
                {
                    curL++;
                }
                else if (left >= right)
                {
                    // sort
                    int i = 1;
                    while(i < N)
                    {
                        if (center[curL] <= front[i])
                        {
                            front[i - 1] = center[curL];
                            break;
                        }
                        front[i - 1] = front[i];
                        i++;
                    }

                    if (i == N)
                    {
                        front[N - 1] = center[curL];
                    }

                    curL++;
                }
                else
                {
                    // sort
                    int i = N - 2;
                    while (i >= 0)
                    {
                        if (center[curR] >= rear[i])
                        {
                            rear[i + 1] = center[curR];
                            break;
                        }
                        rear[i + 1] = rear[i];
                        i--;
                    }

                    if (i < 0)
                    {
                        rear[0] = center[curR];
                    }

                    curR--;
                }
            }

            long sum = 0;
            for (int i = 0; i < N; i++)
            {
                sum = sum + front[i] - rear[i];
            }

            Console.WriteLine(sum);
        }
    }
}

