    static class Solver
    {
        static IO io = new IO();

        public static void Solve()
        {
            io.Read();
            int N = io.Int();

            List<long> a1 = new List<long>();
            List<long> a2 = new List<long>();
            List<long> a3 = new List<long>();
            io.ReadSplit();
            for (int i = 0; i < N; ++i)
            {
                a1.Add(io.Int());
            }
            for (int i = 0; i < N; ++i)
            {
                a2.Add(io.Int());
            }
            for (int i = 0; i < N; ++i)
            {
                a3.Add(io.Int());
            }

            io.WriteLine(Ans(N, a1, a2, a3).ToString());
        }
        static long Ans(int N, List<long> a1, List<long> a2, List<long> a3)
        {
            List<long> a1sum = new List<long>();
            List<long> a3sum = new List<long>();

            a1.Sort();
            a1sum.Add(a1.Sum());
            for (int i = 0; i < N; ++i)
            {
                long aa1 = a1[0];
                long aa2 = a2[i];
                if (aa1 < aa2)
                {
                    a1sum.Add(a1sum[i] - aa1 + aa2);
                    a1.RemoveAt(0);
                    a1.Add(aa2);
                    a1.Sort();
                }
                else
                {
                    a1sum.Add(a1sum[i]);
                }
            }

            a3.Sort();
            a3sum.Add(a3.Sum());
            for (int i = 0; i < N; ++i)
            {
                long aa3 = a3[N - 1];
                long aa2 = a2[N - i - 1];
                if (aa2 < aa3)
                {
                    a3sum.Add(a3sum[i] - aa3 + aa2);
                    a3.RemoveAt(N - 1);
                    a3.Add(aa2);
                    a3.Sort();
                }
                else
                {
                    a3sum.Add(a3sum[i]);
                }
            }

            long max = long.MinValue;
            for (int i = 0; i <= N; ++i)
            {
                max = Math.Max(max, a1sum[i] - a3sum[N - i]);
            }
            return max;

        }
    }
}
