class PriorityQueue
  attr :s

  def initialize
    @q = [nil]
    @s = 0
  end

  def bubble_up(i)
    p = i / 2
    return if i <= 1 || @q[p] <= @q[i]
    @q[i], @q[p] = @q[p], @q[i]
    bubble_up(p)
  end

  def add(e)
    @q << e
    @s += e
    bubble_up(@q.size - 1)
  end

  def bubble_down(i)
    c = i * 2
    return if c >= @q.size
    c += 1 if c != @q.size - 1 && @q[c] > @q[c + 1]
    return if @q[i] <= @q[c]
    @q[i], @q[c] = @q[c], @q[i]
    bubble_down(c)
  end

  def pop
    @q[1], @q[-1] = @q[-1], @q[1]
    ret = @q.pop
    @s -= ret
    bubble_down(1)
    ret
  end

  def push_pop(e)
    self.add(e)
    self.pop
  end
end

