int main() {
  ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
  cout << fixed << setprecision(15);

  ll n;
  cin >> n;

  ll frs = 0;
  multiset<ll> bkq;
  multiset<ll> frms;
  vll as(3*n);
  rep(i, 3*n) {
    ll a;
    cin >> a;
    as[i] = a;
    if (i < n) {
      frs += a;
      frms.insert(a);
    } else {
      bkq.insert(a);
    }
  }
  multiset<ll> bkms;
  ll bks = 0;
  rep(i, n) {
    ll a = *bkq.begin();
    bks += a;
    bkms.insert(a);
    bkq.erase(bkq.begin());
  }

  ll ans = frs - bks;
  ll tmp = ans;
  repLRE(i, n, 2 * n - 1) {
    ll a = as[i];
    // fr
    auto itrf = frms.upper_bound(a);
    if(itrf != frms.begin()){
      auto ifb = frms.begin();
      tmp += a - *ifb;
      frms.insert(a);
      frms.erase(ifb);
    }
    // bk
    auto itrb = bkms.lower_bound(a);
    if(itrb != bkms.end()){
      bkms.erase(a);
      ll inst = *bkq.begin();
      bkq.erase(bkq.begin());
      bkms.insert(inst);
      tmp -= inst - a;
    } else {
      bkq.erase(bkq.lower_bound(a));
    }
    chmax(ans, tmp);
  }

  cout << ans << endl;

  return 0;
}

