// W固定のサイズ
func sizeW(x int) int {
	h := H - x
	c1 := W * x
	c2 := W / 2 * h
	c3 := (W/2 + W%2) * h
	if c1 == 0 || c2 == 0 || c3 == 0 {
		return H * W
	}
	maxChoco := max(c1, max(c2, c3))
	minChoco := min(c1, min(c2, c3))
	// log.Println(x, h, c1, c2, c3, maxChoco, minChoco)
	return maxChoco - minChoco
}

// W固定のサイズ
func sizeH(x int) int {
	h := W - x
	c1 := H * x
	c2 := H / 2 * h
	c3 := (H/2 + H%2) * h
	if c1 == 0 || c2 == 0 || c3 == 0 {
		return H * W
	}
	maxChoco := max(c1, max(c2, c3))
	minChoco := min(c1, min(c2, c3))
	// log.Println(c1, c2, c3, maxChoco, minChoco)
	return maxChoco - minChoco
}

