type pqe struct {
	v interface{}
	p int
}
type Pq []pqe

func NewPq(c int) Pq { ; p := make(Pq, 1, c); p[0] = pqe{v: -1, p: -1}; return p }
func (pq *Pq) Push(v interface{}, p int) {
	*pq = append(*pq, pqe{v, p})
	for i := len(*pq) - 1; i > 1 && (*pq)[i].p > (*pq)[i/2].p; i = i / 2 {
		(*pq)[i], (*pq)[i/2] = (*pq)[i/2], (*pq)[i]
	}
}
func (pq *Pq) Pop() interface{} {
	if len(*pq) <= 1 {
		return nil
	}
	me := (*pq)[1]
	(*pq)[1] = (*pq)[len(*pq)-1]
	*pq = (*pq)[:len(*pq)-1]
	for i := 1; ; {
		lc, rc := 2*i, 2*i+1
		var lrg int
		if lc < len(*pq) && (*pq)[lc].p > (*pq)[i].p {
			lrg = lc
		} else {
			lrg = i
		}
		if rc < len(*pq) && (*pq)[rc].p > (*pq)[lrg].p {
			lrg = rc
		}
		if lrg == i {
			break
		}
		(*pq)[i], (*pq)[lrg] = (*pq)[lrg], (*pq)[i]
		i = lrg
	}
	return me.v
}
func (pq *Pq) Peek() interface{} {
	if len(*pq) <= 1 {
		return nil
	}
	return (*pq)[1].v
}

func solve() {
	n := ri()
	as := ris(3 * n)

	lSum := 0
	lPq := NewPq(n)
	for _, a := range as[:n] {
		lSum += a
		lPq.Push(a, -a)
	}

	lSums := make([]int, n+1)
	lSums[0] = lSum
	for i, a := range as[n : 2*n] {
		if a > lPq.Peek().(int) {
			lSum -= lPq.Pop().(int)
			lSum += a
			lPq.Push(a, -a)
		}
		lSums[i+1] = lSum
	}

	rSum := 0
	rPq := NewPq(n)
	for _, a := range as[2*n : 3*n] {
		rSum += a
		rPq.Push(a, a)
	}

	rSums := make([]int, n+1)
	rSums[n] = rSum
	for i := n - 1; i >= 0; i-- {
		a := as[n : 2*n][i]
		if a < rPq.Peek().(int) {
			rSum -= rPq.Pop().(int)
			rSum += a
			rPq.Push(a, a)
		}
		rSums[i] = rSum
	}

	mxScore := -inf
	for i := 0; i < n+1; i++ {
		chmax(&mxScore, lSums[i]-rSums[i])
	}
	pln(mxScore)
}

