func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)
	aa := make([]int64, n*3)
	var hl, hr IntHeap
	var suml, sumr int64
	heap.Init(&hl)
	heap.Init(&hr)
	for i := 0; i < n*3; i++ {
		aa[i] = getNextInt64(scanner)
	}

	sum := make([]int64, n+1)
	for i := 0; i < n; i++ {
		suml += aa[i]
		heap.Push(&hl, aa[i])
		sumr += -aa[i+n*2]
		heap.Push(&hr, -aa[i+n*2])
	}

	sum[0] = suml
	sum[n] = sumr
	for i := 0; i < n; i++ {
		heap.Push(&hl, aa[i+n])
		pl := heap.Pop(&hl).(int64)
		suml = suml + aa[i+n] - pl
		sum[i+1] += suml
		heap.Push(&hr, -aa[n*2-1-i])
		pr := heap.Pop(&hr).(int64)
		sumr = sumr - aa[n*2-1-i] - pr
		sum[n-i-1] += sumr
	}

	var ans int64
	ans = int64(1e15+1) * -1
	for i := 0; i < n+1; i++ {
		if ans < sum[i] {
			ans = sum[i]
		}
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

