	for i := 0; i < n; i++ {
		heap.Push(First, A[i])
	}
	for i := 2 * n; i < 3*n; i++ {
		heap.Push(Last, A[i])
	}

	var firstSums, lasSums [100001]int
	sum := 0
	for i := 0; i < n; i++ {
		sum += (*First)[i]
	}
	firstSums[0] = sum
	for i := n; i < 2*n; i++ {
		pushed := A[i]
		heap.Push(First, pushed)
		popped := heap.Pop(First).(int)
		sum += (pushed - popped)
		firstSums[i-n+1] = sum
	}

	sum = 0
	for i := 0; i < n; i++ {
		sum += (*Last)[i]
	}
	lasSums[n] = sum
	for i := 2*n - 1; i >= n; i-- {
		pushed := A[i]
		heap.Push(Last, pushed)
		popped := heap.Pop(Last).(int)
		sum += (pushed - popped)
		lasSums[i-n] = sum
	}

	ans := -math.MaxInt64
	for i := 0; i <= n; i++ {
