type intList []int

func (a intList) Len() int           { return len(a) }
func (a intList) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a intList) Less(i, j int) bool { return a[i] < a[j] }
func (a *intList) Push(x interface{}) {
	*a = append(*a, x.(int))
}
func (a *intList) Pop() interface{} {
	old := *a
	n := len(old)
	x := old[n-1]
	*a = old[0 : n-1]

	return x
}

func makeFormer(A *intList) (intList, int) {
	M := len(*A)
	N := M / 3

	B, sum := make(intList, N), 0
	copy(B, (*A)[:N])
	for i, b := range B {
		sum += b
		B[i] = -b
	}

	return B, sum
}

func makeLatter(A *intList) (intList, int) {
	M := len(*A)
	N := M / 3

	C := make(intList, N)
	copy(C, (*A)[2*N:])

	sum := 0
	for _, c := range C {
		sum += c
	}

	return C, sum
}

func intMax(x, y int) int {
	return int(math.Max(float64(x), float64(y)))
}

func main() {
	sc.Split(bufio.ScanWords)

	N := scanInt()
	A := make(intList, 3*N)
	for i := 0; i < 3*N; i++ {
		A[i] = scanInt()
	}

	Former, Fsum := makeFormer(&A)
	heap.Init(&Former)
	FsumList := make(intList, N+1) // FsumList[i] = 0~N-1+i
	FsumList[0] = Fsum
	for i := 1; i <= N; i++ {
		poped := -Former.Pop().(int)
		Former.Push(-A[N-1+i])

		Fsum = Fsum + A[N-1+i] - poped
		FsumList[i] = Fsum
	}

	Latter, Lsum := makeLatter(&A)
	heap.Init(&Latter)
	LsumList := make(intList, N+1) // LsumList[i] = N+i~3N-1
	LsumList[N] = Lsum
	for i := N - 1; i >= 0; i-- {
		poped := Latter.Pop().(int)
		Latter.Push(A[N+i])

		Lsum = Lsum + A[N+i] - poped
		LsumList[i] = Lsum
	}

	ans := FsumList[0] - LsumList[0]
	for i := 0; i <= N; i++ {
		if p := FsumList[i] - LsumList[i]; p < ans {
			ans = p
		}
		//ans = intMax(ans, FsumList[i]-LsumList[i])
	}

	fmt.Println(ans)
}

