		var sz1, sz2 int
		h := make([]int, 2*N)
		for i := 0; i < k; i++ {
			firsrSum += a[i]
			push(h, a[i], sz1)
			sz1++
			if sz1 > N {
				firsrSum -= pop(h, sz1)
				sz1--
			}
		}
		h2 := make([]int, 2*N)
		for i := k; i < 3*N; i++ {
			push(h2, a[i], sz2)
			sz2++
			if sz2 > 2*N-k {
				secondSum += pop(h2, sz2)
				sz2--
			}
		}
