func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func push(heap []int, x, sz int) {
	i := sz
	sz++
	for i > 0 {
		p := (i - 1) / 2
		if heap[p] <= x {
			break
		}
		heap[i] = heap[p]
		i = p
	}
	// log.Println(heap, i)
	heap[i] = x
}

func pop(heap []int, sz int) (ret int) {
	ret = heap[0]
	sz--
	x := heap[sz]
	i := 0
	for i*2+1 < sz {
		a := i*2 + 1
		b := i*2 + 2
		if b < sz && heap[b] < heap[a] {
			a = b
		}
		if heap[a] >= x {
			break
		}
		heap[i] = heap[a]
		i = a
	}
	heap[i] = x
	return
}

func sum(a []int) (r int) {
	for i := range a {
		r += a[i]
	}
	return
}

type scanner struct {
	r   *bufio.Reader
	buf []byte
	p   int
}

func newScanner() *scanner {
	rdr := bufio.NewReaderSize(os.Stdin, 1000)
	return &scanner{r: rdr}
}
func (s *scanner) next() string {
	s.pre()
	start := s.p
	for ; s.p < len(s.buf); s.p++ {
		if s.buf[s.p] == ' ' {
			break
		}
	}
	result := string(s.buf[start:s.p])
	s.p++
	return result
}
func (s *scanner) nextLine() string {
	s.pre()
	start := s.p
	s.p = len(s.buf)
	return string(s.buf[start:])
}
func (s *scanner) nextInt() int {
	v, _ := strconv.Atoi(s.next())
	return v
}

func (s *scanner) pre() {
	if s.p >= len(s.buf) {
		s.readLine()
		s.p = 0
	}
}
func (s *scanner) readLine() {
	s.buf = make([]byte, 0)
	for {
		l, p, e := s.r.ReadLine()
		if e != nil {
			panic(e)
		}
		s.buf = append(s.buf, l...)
		if !p {
			break
		}
	}
}

