func main() {
	tmp := NextIntsLine()
	n = tmp[0]
	A = NextIntsLine()

	First, Second, Third := &IntHeap{}, []int{}, &IntReverseHeap{}
	heap.Init(First)
	heap.Init(Third)
	for i := 0; i < n; i++ {
		heap.Push(First, A[i])
	}
	for i := n; i < 2*n; i++ {
		Second = append(Second, A[i])
	}
	for i := 2 * n; i < 3*n; i++ {
		heap.Push(Third, A[i])
	}

	for len(Second) > 0 {
		a := (*First)[0]
		btop := Second[0]
		btail := Second[len(Second)-1]
		c := (*Third)[0]

		leftCase := btop - a
		rightCase := -1 * (btail - c)
		which := Max(leftCase, 0, rightCase)
		if which == leftCase {
			heap.Pop(First)
			Second = Second[1:]
			heap.Push(First, btop)
		} else if which == rightCase {
			heap.Pop(Third)
			Second = Second[:len(Second)-1]
			heap.Push(Third, btail)
		} else {
			Second = Second[1:]
		}
	}

	firstSum, lastSum := 0, 0
	for First.Len() > 0 {
		firstSum += First.Pop().(int)
	}
	for Third.Len() > 0 {
		lastSum += Third.Pop().(int)
	}
	fmt.Println(firstSum - lastSum)
}

