var sc = bufio.NewScanner(os.Stdin)

func readInt() int {
    sc.Scan()
    n, _ := strconv.Atoi(sc.Text())
    return n
}

func main() {
    sc.Split(bufio.ScanWords)
    comp := func(p, q interface{}) int {
        if p.(int) < q.(int) {
            return -1
        } else if p.(int) == q.(int) {
            return 0
        } else {
            return 1
        }
    }
    n := readInt()
    preQue := new(PriorityQueue)
    preQue.comps = append(preQue.comps, comp)
    sufQue := new(PriorityQueue)
    sufQue.comps = append(sufQue.comps, comp)
    mid := make([]int, n)
    var preScore, sufScore int
    preScores := make([]int, n + 1)
    sufScores := make([]int, n + 1)
    for i := 0; i < n; i++ {
        v := readInt()
        preScore += v
        heap.Push(preQue, v)
    }
    for i := 0; i < n; i++ {
        mid[i] = readInt()
    }
    for i := 0; i < n; i++ {
        v := -readInt()
        sufScore += v
        heap.Push(sufQue, v)
    }

    preScores[0] = preScore
    for i, m := range mid {
        v := heap.Pop(preQue).(int)
        if v < m {
            preScore += (m - v)
            heap.Push(preQue, m)
        } else {
            heap.Push(preQue, v)
        }
        preScores[i + 1] = preScore
    }

    sufScores[0] = sufScore
    for i := n - 1; i >= 0; i-- {
        m := mid[i]
        v := heap.Pop(sufQue).(int)
        if -v > m {
            sufScore += -v - m
            heap.Push(sufQue, -m)
        } else {
            heap.Push(sufQue, v)
        }
        sufScores[n - i] = sufScore
    }
    ans := -10000000000000000
    for i := 0; i <= n; i++ {
        score := preScores[i] + sufScores[n - i]
        if ans < score {
            ans = score
        }
    }
    fmt.Println(ans)
}

