func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func push(heap []int, x, sz int) {
	i := sz
	sz++
	for i > 0 {
		p := (i - 1) / 2
		if heap[p] <= x {
			break
		}
		heap[i] = heap[p]
		i = p
	}
	// log.Println(heap, i)
	heap[i] = x
}

func pop(heap []int, sz int) (ret int) {
	ret = heap[0]
	sz--
	x := heap[sz]
	i := 0
	for i*2+1 < sz {
		a := i*2 + 1
		b := i*2 + 2
		if b < sz && heap[b] < heap[a] {
			a = b
		}
		if heap[a] >= x {
			break
		}
		heap[i] = heap[a]
		i = a
	}
	heap[i] = x
	return
}

