int N;
void main() {
    N = readln.chomp.to!int;
    long[] ary = readln.split.to!(long[]);

    long[] as = ary[0..2*N];
    long[] bs = ary[N..3*N].retro.array;

    long[] xs = as.po!((a, b) => a<b);
    long[] ys = bs.po!((a, b) => a>b);

    long ans = 0;
    foreach(i; 0..N+1) {
        ans = max(ans, xs[i]-ys[N-i]);
    }
    ans.writeln;
}

long[] po(alias pred)(long[] as) {
    long[] xs = new long[N+1];
    xs[0] = as[0..N].sum;
    foreach(i; 0..N) {
        xs[i+1] = xs[i] + as[N+i];
    }

    auto tree = as.enumerate.array.redBlackTree!(
        (a, b) => a.value!=b.value ? pred(a.value, b.value) : a.index>b.index
    );

    long[] ys = new long[N];
    foreach(i; 0..N) {
        foreach(a; tree) {
            if (a.index.to!int-N <= i) {
                ys[i] = a.value;
                tree.removeKey(a);
                break;
            }
        }
    }

    foreach(i; 0..N-1) {
        ys[i+1] += ys[i];
    }

    foreach(i; 0..N) {
        xs[i+1] -= ys[i];
    }

    return xs;
}


