void readA(T)(size_t n,ref T[]t){t=new T[](n);auto r=rdsp;foreach(ref v;t)pick(r,v);}

void main()
{
  int n; readV(n);
  long[] a; readA(n*3, a);

  auto t1 = new long[](n+1);
  t1[0] = a[0..n].sum;
  auto rb1 = redBlackTree!"a<b"(a[0..n]);
  foreach (i; 1..n+1) {
    auto ai = a[n+i-1];
    if (rb1.front >= ai) {
      t1[i] = t1[i-1];
    } else {
      t1[i] = t1[i-1] - rb1.front + ai;
      rb1.removeFront();
      rb1.insert(ai);
    }
  }

  auto t2 = new long[](n+1);
  t2[0] = a[n*2..n*3].sum;
  auto rb2 = redBlackTree!"a>b"(a[n*2..n*3]);
  foreach (i; 1..n+1) {
