      t2[i] = t2[i-1] - rb2.front + ai;
      rb2.removeFront();
      rb2.insert(ai);
    }
  }

  auto r = -10L^^18;
  foreach (i; 0..n+1)
    r = max(r, t1[i] - t2[n-i]);

  writeln(r);
}

