	LL sum = 0;
	for(int i = 1; i <= 3 * n; i++) {
		pre_que.push(a[i]);
		sum += a[i];
		pre_sum[i] = sum;
		if(pre_que.size() > n) {
			sum -= pre_que.top();
			pre_que.pop();
			pre_sum[i] = sum;
		}
	}
}

void solve2() {
	LL sum = 0;
	for(int i = 3 * n; i >= 1; i--) {
		pos_que.push(a[i]);
		sum += a[i];
		pos_sum[i] = sum;
		if(pos_que.size() > n) {
			sum -= pos_que.top();
			pos_que.pop();
			pos_sum[i] = sum;
		}
	}
}
