  let cmped = heap.cmp(
      heap.values[parent], heap.values[child]
    ) 

  return cmped >= 0

proc check_and_replace[T](heap: BinaryHeap[T], parent: int, child: int): bool =
  if heap.exists(child):
    result = not heap.cmp_node(parent, child)
    if result:
      heap.swap_node(parent, child)
  else:
