    if heap.exists(left_pos):
      if heap.exists(right_pos):
        left = heap.cmp_node(left_pos, right_pos)
      else:
        left = true
    else:
      left = false

    let replace = if left: left_pos else: right_pos
    if heap.check_and_replace(position, replace):
      heap.fix_node(replace)

