        ushiro.push(a[curr])
        umax = ushiro.pop()
        ushiro_tot.append(ushiro_tot[-1]+a[curr]-umax)

    m = -INF
    for mt, ut in zip(mae_tot, reversed(ushiro_tot)):
        m = max(m, mt-ut)
