#[derive(Eq, PartialEq, Clone, Debug)]
pub struct Rev<T>(pub T);
impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

fn solve() {
    let n = get!(usize);
    let mut a = get!([isize]);

    let mut a1 = a.drain(0..n).map(|e| Rev(e)).collect::<BinaryHeap<_>>();
    let a2 = a.drain(0..n).collect::<Vec<_>>();
    let mut a3 = a.into_iter().collect::<BinaryHeap<_>>();

    let mut sum1 = vec![0;n+1];
    let mut sum3 = vec![0;n+1];
    sum1[0] = a1.iter().map(|e| e.0).sum::<isize>();
    sum3[n] = a3.iter().sum::<isize>();

    for i in 0..n {
        a1.push(Rev(a2[i]));
        sum1[i+1] = sum1[i] + a2[i] - a1.pop().unwrap().0;

        a3.push(a2[n-i-1]);
        sum3[n-i-1] = sum3[n-i] + a2[n-i-1] - a3.pop().unwrap();
    }

    let mut mx = std::isize::MIN;
    for i in 0..n+1 {
        mx = max!(mx, sum1[i] - sum3[i]);
    }
    println!("{}", mx);
}

