use std::vec::Vec;
use std::collections::BinaryHeap;
use std::cmp::Reverse;
use std::cmp::max;

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>().split_whitespace().map(|e| e.parse().ok().unwrap()).collect()
}

fn main() {
    let n: usize = read();
    let mut a: Vec<i64> = read_vec();
    let mut dp = vec![(0, 0); 3*n];

    // 一個ずつ仕切りをずらして行き考える
    // 下位n個について,2*nまで行う
    // 下位の和を最大化
    let mut low = BinaryHeap::new();
    let mut low_sum = 0;
    for i in 0..n {
        low.push(Reverse(a[i]));
        low_sum += a[i];
    }

    dp[n-1].0 = low_sum;

    // nから2*nまで
    for i in n..2*n {
        let min = match low.peek() {
            Some(Reverse(x))=> *x,
            _  => panic!(),
        };

        if a[i] > min {
           let _ = low.pop();
           low.push(Reverse(a[i]));
           low_sum += a[i] - min;
        }
        // let mut min = low.peek_mut().unwrap();
        // if a[i] < *max {
        //     low_sum += a[i] - *max;
        //    *max = a[i];
        // }
        dp[i].0 = low_sum;
    }   

    // 上位2*n個について
    let mut high = BinaryHeap::new();
    let mut high_sum = 0;

    for i in 2*n..3*n {
        high.push(a[i]);
        high_sum += a[i];
    }

    dp[2*n].1 = high_sum;

    for i in (n..2*n).rev() {
        let mut max = high.peek_mut().unwrap();
        if a[i] < *max {
           high_sum += a[i] - *max;
           *max = a[i];
        }

        dp[i].1 = high_sum;
    }

    let mut ans = std::i64::MIN;
    for i in n-1..2*n {
        ans = max(ans, dp[i].0 - dp[i+1].1);
    }
    println!("{}", ans);

}

