#[derive(Debug, Copy, Clone, Eq, PartialEq)]
struct Rev(i64);

impl Ord for Rev {
    fn cmp(&self, other: &Rev) -> Ordering {
        other.0.cmp(&self.0)
    }
}

impl PartialOrd for Rev {
    fn partial_cmp(&self, other: &Rev) -> Option<Ordering> {
        Some(other.0.cmp(&self.0))
    }
}

fn main() {
    input!{
      n: usize,
      aa: [i64; 3*n],
    }

    let mut left_heap = BinaryHeap::new();
    let mut left_sum = 0;
    let mut right_sum = 0;

    for i in 0..n {
        left_heap.push(Rev(aa[i]));
        left_sum += aa[i];
    }

    let mut right_used = vec![false; 3*n];
    let mut right_heap = BinaryHeap::new();
    {
        let mut right = vec![];
        for i in n..3*n {
            right.push((aa[i], i));
        }
        right.sort();
        for i in 0..n {
            right_used[right[i].1] = true;
            right_sum += right[i].0;
        }
        for i in n..2*n {
            right_heap.push((Rev(right[i].0), right[i].1));
        }
    }

    let mut ans = left_sum - right_sum;
    for i in n..2*n {
        if let Some(Rev(min_value)) = left_heap.pop() {
            if min_value < aa[i] {
                left_heap.push(Rev(aa[i]));
                left_sum += aa[i] - min_value;
            } else {
                left_heap.push(Rev(min_value));
            }
        }
        if right_used[i] {
            loop {
                let (Rev(value), idx) = right_heap.pop().unwrap();
                if idx <= i {
                    continue;
                }

                right_sum += value - aa[i];
                right_used[i] = false;
                right_used[idx] = true;
                break;
            }
        }
        ans = max(ans, left_sum-right_sum);
    }
    println!("{}", ans);
}

