fn summerize(a: &Vec<i64>) -> i64 {
    a.iter().fold(0, |i, j| i + j)
}
fn maximize(n: i64, a: &Vec<i64>) -> i64 {
    let mut a_ = a.to_vec();
    a_.sort();
    a_.reverse();
    a_.resize(n as usize, 0);
    summerize(&a_)
}
fn minimize(n: i64, a: &Vec<i64>) -> i64 {
    let mut a_ = a.to_vec();
    a_.sort();
    a_.resize(n as usize, 0);
    summerize(&a_)
}

fn search(n: i64, af: &Vec<i64>, ap: &Vec<i64>) -> i64 {
    maximize(n, &af) - minimize(n, &ap)
}

trait Shift<T: Clone> {
    fn shift(&mut self, T);
    fn unshift(&mut self) -> Option<T>;
}
impl<T: Clone> Shift<T> for Vec<T> {
    fn shift(&mut self, e: T) {
        self.insert(0, e);
    }
    fn unshift(&mut self) -> Option<T> {
        let f : Option<T> = match self.first() {
            Some(t) => Some((*t).clone()),
            _ => None
        };
        self.remove(0);
        f
    }
}

