    for i in 0..middle.len(){
        let half1_min = -half1.pop().unwrap();
        half1_sum -= half1_min;

        half1.push(-middle[i]);
        half1_sum += middle[i];
        answers[i+1] = half1_sum;
    }

    let mut half2_sum = half2.iter().sum::<i64>();
    *answers.last_mut().unwrap() -= half2_sum;

    for i in (0..middle.len()).rev(){
        let half2_max = half2.pop().unwrap();
        half2_sum -= half2_max;

        half2.push(middle[i]);
        half2_sum += middle[i];
        answers[i] -= half2_sum;
    }
    let mut ans = std::i64::MIN;
    for tmp in answers{
        ans = cmp::max(ans, tmp);
    }

    println!("{}", ans);
}

