fn sum(a: &Vec<i64>) -> i64 {
    a.iter().fold(0, |i, j| i + j)
}
fn sum_first_n(n: i64, a: &Vec<i64>) -> i64 {
    sum(&a[0..n as usize].to_vec())
}
fn sum_last_n(n: i64, a: &Vec<i64>) -> i64 {
    let l = a.len();
    sum(&a[(l-n as usize)..l].to_vec())
}
fn insert_sorted<T: Ord>(v: T, a: &mut Vec<T>) {
    for i in 0..a.len() {
        if v <= a[i] {
            a.insert(i, v);
            return ()
        }
    }
    a.push(v)
}
fn remove_sorted<T: Ord>(v: T, a: &mut Vec<T>) {
    for i in 0..a.len() {
        if v == a[i] {
            a.remove(i);
            return ()
        }
    }
}

fn score(n: i64, afs: &Vec<i64>, aps: &Vec<i64>) -> i64 {
    sum_last_n(n, afs) - sum_first_n(n, aps)
}

