    let mut pq_1 = std::collections::BinaryHeap::new();
    let mut s_0 = 0_i64;
    let mut s_1 = 0_i64;
    for i in 0..n {
        let a_i = a[i];
        pq_0.push(-a_i);
        s_0 += a_i;

        let a_j = a[3 * n - i - 1];
        pq_1.push(a_j);
        s_1 -= a_j;
    }

    let mut l = n;
    let mut r = 2 * n;
    for _ in 0..n {
        let a_l = a[l];
        let a_r = a[r - 1];
