            pq_0.pop();
            pq_0.push(-a_l);
            s_0 += score_0;
            l += 1;
        } else {
            pq_1.pop();
            pq_1.push(a_r);
            s_1 += score_1;
            r -= 1;
        }
    }

    let ans = s_0 + s_1;
