use std::cmp::max;

fn calc(a: &Vec<i64>) -> Vec<i64> {
    let n = a.len() / 3;
    let mut h = std::collections::BinaryHeap::new();
    let mut sum = 0;
    let mut ans = vec![0; 3 * n];
    for (i, a) in a.into_iter().enumerate() {
        sum += a;
        h.push(-a);
        if h.len() > n {
            sum -= -h.pop().unwrap();
        }
        ans[i] = sum;
    }
    ans
}

fn run(mut sc: scanner::Scanner) {
    let n: usize = sc.read();
    let mut a: Vec<i64> = (0..(3 * n)).map(|_| sc.read()).collect();
    let left = calc(&a);
    a.reverse();
    for a in a.iter_mut() {
        *a = -*a;
    }
    let right = calc(&a);
    let mut ans = -100_000 * 1_000_000_000;
    for i in (n - 1)..(2 * n) {
        ans = max(ans, left[i] + right[3 * n - 2 - i]);
    }
    println!("{}", ans);
}

