}

use std::cmp::Ordering;
#[derive(Eq, PartialEq, Copy, Clone, Debug)]
struct Rev<T>(T) where T : Ord + Copy;
impl<T> PartialOrd for Rev<T> where T : Ord + Copy {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl<T> Ord for Rev<T> where T : Ord + Copy {
    fn cmp(&self, other: &Rev<T>) -> Ordering {
        self.0.cmp(&other.0).reverse()
    }
}
impl<T: Ord + Copy> Rev<T> {
    fn unwrap(&self) -> T {
        self.0
    }
}

