fn calc(a: &Vec<i64>) -> Vec<i64> {
    let n = a.len() / 3;
    let mut h = std::collections::BinaryHeap::new();
    let mut sum = 0i64;
    let mut ans = vec![0; 3 * n];
    for (i, &a) in a.iter().enumerate() {
        sum += a;
        h.push(-a);
        if h.len() > n {
            sum -= -h.pop().unwrap();
        }
        ans[i] = sum;
    }
    ans
}

