fn dfs(i: usize, m: usize, sum: &mut Vec<i64>, n: usize, a: &Vec<i64>) -> i64 {
    if i == 3 * n {
        if m == 2 * n {
            sum[n] - (sum[2 * n] - sum[n])
        } else {
            i64::min_value()
        }
    } else {
        let mut ans = i64::min_value();
        ans = std::cmp::max(ans, dfs(i + 1, m, sum, n, a));

        let last = *sum.last().unwrap();
        sum.push(last + a[i]);
        ans = std::cmp::max(ans, dfs(i + 1, m + 1, sum, n, a));
        sum.pop();

        ans
    }
}

