    let n = sc.parse::<usize>();
    let mut a = vec![0; 3*n];
    for i in 0..(3 * n) {
        a[i] = sc.parse::<i32>();
    }

    let mut heap = BinaryHeap::new();
    let mut prefix_sum = 0;
    let mut prefix_max = vec![0;3*n];
    for i in 0..n {
        heap.push(-a[i]);
        prefix_sum += a[i];
    }
    prefix_max[n - 1] = prefix_sum;
    for i in n..(3 * n) {
        let head = -heap.pop().unwrap();
        if head > a[i] {
            heap.push(-head);
        } else {
            prefix_sum -= head;
            prefix_sum += a[i];
            heap.push(-a[i]);
        }
        prefix_max[i] = prefix_sum;
    }

    heap.clear();
    let mut suffix_sum = 0;
    let mut suffix_min = vec![0;3*n];

    for i in ((2 * n)..(3 * n)).rev() {
        heap.push(a[i]);
        suffix_sum += a[i];
    }
    suffix_min[2 * n] = suffix_sum;
    for i in (0..(2 * n)).rev() {
        let head = heap.pop().unwrap();
        if head < a[i] {
            heap.push(head);
        } else {
            suffix_sum -= head;
            suffix_sum += a[i];
            heap.push(a[i]);
        }
        suffix_min[i] = suffix_sum;
    }

    let mut ans: i64 = -1000000000000000000;
    for i in n..(2 * n + 1) {
        let p = prefix_max[i - 1] as i64;
        let s = suffix_min[i] as i64;
        ans = cmp::max(ans, p - s);
    }
