fn main() {
    let n: usize = read();
    let mut a: Vec<i64> = read_vec();
    let mut dp = vec![(0, 0); 3*n];

    // 一個ずつ仕切りをずらして行き考える
    // 下位n個について,2*nまで行う
    // 下位の和を最大化
    let mut low = BinaryHeap::new();
    let mut low_sum = 0;
    for i in 0..n {
        low.push(-a[i]);
        low_sum += a[i];
    }

    dp[n-1].0 = low_sum;

    // nから2*nまで
    for i in n..2*n {
        let mut min = low.peek_mut().unwrap();
        if a[i] > -*min {
            low_sum += a[i] + *min;
           *min = -a[i];
        }
        dp[i].0 = low_sum;
    }   

    // 上位2*n個について
    let mut high = BinaryHeap::new();
    let mut high_sum = 0;

    for i in 2*n..3*n {
        high.push(a[i]);
        high_sum += a[i];
    }

    dp[2*n].1 = high_sum;

    for i in (n..2*n).rev() {
        let mut max = high.peek_mut().unwrap();
        if a[i] < *max {
           high_sum += a[i] - *max;
           *max = a[i];
        }

        dp[i].1 = high_sum;
    }

    let mut ans = std::i64::MIN;
    for i in n-1..2*n {
        ans = max(ans, dp[i].0 - dp[i+1].1);
    }
    println!("{}", ans);

}

