        if i >= n - 1 {
            forward_max_sums[i] = sum;
        }
    }
    forward_max_sums[2 * n] = forward_max_sums[2 * n - 1];
    let mut backward_min_sums = vec![0; 3 * n];
    let mut sum = 0;
    let mut que = BinaryHeap::<i64>::new();
    for i in (n..3 * n).rev() {
        sum += aseq[i];
        que.push(aseq[i]);
        if i <= 2 * n - 1 {
            sum -= que.pop().unwrap();
        }
        if i <= 2 * n {
            backward_min_sums[i] = sum;
        }
    }
    backward_min_sums[n - 1] = backward_min_sums[n];
    let mut ans = -(1 << 60);
    for i in n - 1..2 * n {
        // println!("{} {} {}", i, forward_max_sums[i], backward_min_sums[i + 1]);
        ans = std::cmp::max(ans, forward_max_sums[i] - backward_min_sums[i + 1]);
    }
    println!("{}", ans);
}
